INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37525, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「利用する」の対象を示す「を」。心理に直接付く助詞として正しい。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「心理へうまく利用」では利用の対象が示されず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示す。「心理とうまく利用」では対象として成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示す。「心理からうまく利用」では利用の対象にならず合わない。"}], "correct_answer": "を", "explanations": {"を": "「利用する」の対象を示す「を」。心理に直接付く助詞として正しい。", "へ": "「へ」は方向を示す。「心理へうまく利用」では利用の対象が示されず不自然。", "と": "「と」は相手や並列を示す。「心理とうまく利用」では対象として成り立たない。", "から": "「から」は起点を示す。「心理からうまく利用」では利用の対象にならず合わない。"}, "error_tags": {"へ": "方向", "と": "相手・並列", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37525, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人間の心の働きや状態。心理学で研究される精神活動。", "primary_collocate": null, "pronunciation": "しんり", "ipa": "ɕiɴɾi", "syllable_count": 3, "sentences": [{"text": "この実験では、人間の心理を数字で測定する。", "target_word": "心理", "complexity_tier": "T4", "furigana": "この実験(じっけん)では、人間(にんげん)の心理(しんり)を数字(すうじ)で測定(そくてい)する。", "sentence_source": "generated"}, {"text": "買い物をするときの消費者の心理を調べる。", "target_word": "心理", "complexity_tier": "T3", "furigana": "買(か)い物(もの)をするときの消費者(しょうひしゃ)の心理(しんり)を調(しら)べる。", "sentence_source": "generated"}, {"text": "人の心理は、周りの意見に大きく左右される。", "target_word": "心理", "complexity_tier": "T3", "furigana": "人(ひと)の心理(しんり)は、周(まわ)りの意見(いけん)に大(おお)きく左右(さゆう)される。", "sentence_source": "generated"}, {"text": "先生は子どもの心理をよく理解して話す。", "target_word": "心理", "complexity_tier": "T3", "furigana": "先生(せんせい)は子(こ)どもの心理(しんり)をよく理解(りかい)して話(はな)す。", "sentence_source": "generated"}, {"text": "値段が安いと買いたくなるのは、自然な心理だ。", "target_word": "心理", "complexity_tier": "T3", "furigana": "値段(ねだん)が安(やす)いと買(か)いたくなるのは、自然(しぜん)な心理(しんり)だ。", "sentence_source": "generated"}, {"text": "この研究では、緊張したときの心理の変化を調べた。", "target_word": "心理", "complexity_tier": "T4", "furigana": "この研究(けんきゅう)では、緊張(きんちょう)したときの心理(しんり)の変化(へんか)を調(しら)べた。", "sentence_source": "generated"}, {"text": "彼は人の心理を見抜くのが得意で、相手の反応をよく観察する。", "target_word": "心理", "complexity_tier": "T3", "furigana": "彼(かれ)は人(ひと)の心理(しんり)を見抜(みぬ)くのが得意(とくい)で、相手(あいて)の反応(はんのう)をよく観察(かんさつ)する。", "sentence_source": "generated"}, {"text": "広告は人の心理をうまく利用している。", "target_word": "心理", "complexity_tier": "T3", "furigana": "広告(こうこく)は人(ひと)の心理(しんり)をうまく利用(りよう)している。", "sentence_source": "generated"}, {"text": "なぜ人は行列に並ぶのか、その心理を説明してください。", "target_word": "心理", "complexity_tier": "T3", "furigana": "なぜ人(ひと)は行列(ぎょうれつ)に並(なら)ぶのか、その心理(しんり)を説明(せつめい)してください。", "sentence_source": "generated"}, {"text": "事故にあった人の心理は、簡単には分からない。", "target_word": "心理", "complexity_tier": "T3", "furigana": "事故(じこ)にあった人(ひと)の心理(しんり)は、簡単(かんたん)には分(わ)からない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "心理", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "心理学で扱う、人間の心の働きや精神活動", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '830f321e-9b60-438b-aad8-359bdfb0dd5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37525, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "心理", "is_correct": true, "explanation": "「人間の心理を数字で測定する」で、心理学が扱う心の働きを指す。文の意味に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「人間の天気を測定する」は文として成り立たない。"}, {"text": "切符", "is_correct": false, "explanation": "「人間の切符を数字で測定する」は意味が通らない。"}, {"text": "靴下", "is_correct": false, "explanation": "「人間の靴下を数字で測定する」は文脈に合わない。"}], "explanations": {"心理": "「人間の心理を数字で測定する」で、心理学が扱う心の働きを指す。文の意味に合う。", "天気": "「人間の天気を測定する」は文として成り立たない。", "切符": "「人間の切符を数字で測定する」は意味が通らない。", "靴下": "「人間の靴下を数字で測定する」は文脈に合わない。"}, "sentence_index": 0, "correct_answer": "心理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この心理は重くて、一人では運べない。", "explanation": "ここは〈机〉のような物の重さを言う文。心理は目に見えない心の働きなので、重くて運べるものとしては使えない。"}, {"text": "この店の心理は高すぎて、買えなかった。", "explanation": "ここは〈値段〉の意味。値段は高い・安いで言うが、心理には値段の概念がないので合わない。"}, {"text": "駅までの心理が遠くて、歩くのがつらい。", "explanation": "ここは〈距離〉の意味。遠い・近いで隔たりを表すのは距離で、心理は場所の隔たりを表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37525, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心理", "is_correct": true, "explanation": "「人の心理を見抜く」で、人の心の動きを指す。文の意味に合う。"}, {"text": "期限", "is_correct": false, "explanation": "期限は締め切りの日時で、人の内面を見抜く対象にはならない。"}, {"text": "予算", "is_correct": false, "explanation": "予算は使えるお金の枠で、人を見抜くという文の対象にはならない。"}, {"text": "単位", "is_correct": false, "explanation": "単位は数量の基準で、人の内面を見抜くという文に入らない。"}], "explanations": {"心理": "「人の心理を見抜く」で、人の心の動きを指す。文の意味に合う。", "期限": "期限は締め切りの日時で、人の内面を見抜く対象にはならない。", "予算": "予算は使えるお金の枠で、人を見抜くという文の対象にはならない。", "単位": "単位は数量の基準で、人の内面を見抜くという文に入らない。"}, "sentence_index": 6, "correct_answer": "心理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は明るい心理で、誰とでもすぐ仲良くなる。", "explanation": "ここは〈性格〉の意味。「明るい」のような人柄は性格で表し、心理は今の心の動きを指すので合わない。"}, {"text": "彼は強い心理で、一度決めたことは必ずやり通す。", "explanation": "ここは〈意志〉の意味。決めたことを貫く力は意志で表し、心理は心の働き全般を指すので強さの評価には合わない。"}, {"text": "指先の心理が鈍くなって、針に糸を通せない。", "explanation": "ここは〈感覚〉の意味。指先の鈍さは感覚が鈍いと言うもので、心理は身体の感じ方には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37525, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新商品を出す前に、顧客の心理が調べた。", "corrected_sentence": "新商品を出す前に、顧客の心理を調べた。", "error_description": "「調べる」は対象を「を」で示す。「心理が」と書くと「心理」が主語になり、「調べた」の目的語がなくなるので誤り。正しくは「心理を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37525, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "交渉では、相手の心理を読みことが大切だ。", "corrected_sentence": "交渉では、相手の心理を読むことが大切だ。", "error_description": "「読む」を名詞にするには、連体形の「読む」に「こと」を付けて「読むこと」とする。「読みこと」は連用形に「こと」を付けた誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37526, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「授業は成立しない」で、成り立つ主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「授業を成立しない」は目的語の「を」になるが、成立は目的語を取らないので誤り。"}, {"text": "と", "is_correct": false, "explanation": "「授業と成立しない」は共同の「と」で、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐ。「授業の成立しない」は名詞に続かず、文が成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「授業は成立しない」で、成り立つ主語を示す。", "を": "「授業を成立しない」は目的語の「を」になるが、成立は目的語を取らないので誤り。", "と": "「授業と成立しない」は共同の「と」で、文が成り立たない。", "の": "「の」は名詞どうしをつなぐ。「授業の成立しない」は名詞に続かず、文が成り立たない。"}, "error_tags": {"を": "目的語", "と": "共同", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
