INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37526, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "契約・取引・会話などが、必要な条件がそろってきちんと成り立つこと。", "primary_collocate": null, "pronunciation": "せいりつ", "ipa": "seːɾitsɯ", "syllable_count": 4, "sentences": [{"text": "二人が合意しなければ、この契約は成立しません。", "target_word": "成立", "complexity_tier": "T3", "furigana": "二人[ふたり]が合意[ごうい]しなければ、この契約[けいやく]は成立[せいりつ]しません。", "sentence_source": "generated"}, {"text": "先生が話を聞かないと、授業は成立しない。", "target_word": "成立", "complexity_tier": "T3", "furigana": "先生[せんせい]が話[はなし]を聞[き]かないと、授業[じゅぎょう]は成立[せいりつ]しない。", "sentence_source": "generated"}, {"text": "ルールを守らなければ、ゲームは成立しない。", "target_word": "成立", "complexity_tier": "T3", "furigana": "ルールを守[まも]らなければ、ゲームは成立[せいりつ]しない。", "sentence_source": "generated"}, {"text": "選手が足りなくて、試合が成立しなかった。", "target_word": "成立", "complexity_tier": "T3", "furigana": "選手[せんしゅ]が足[た]りなくて、試合[しあい]が成立[せいりつ]しなかった。", "sentence_source": "generated"}, {"text": "理由が間違っていると、この説明は成立しない。", "target_word": "成立", "complexity_tier": "T3", "furigana": "理由[りゆう]が間違[まちが]っていると、この説明[せつめい]は成立[せいりつ]しない。", "sentence_source": "generated"}, {"text": "買う人と売る人がいて、初めて取引が成立する。", "target_word": "成立", "complexity_tier": "T3", "furigana": "買[か]う人[ひと]と売[う]る人[ひと]がいて、初[はじ]めて取引[とりひき]が成立[せいりつ]する。", "sentence_source": "generated"}, {"text": "相手の返事がないと、会話が成立しない。", "target_word": "成立", "complexity_tier": "T3", "furigana": "相手[あいて]の返事[へんじ]がないと、会話[かいわ]が成立[せいりつ]しない。", "sentence_source": "generated"}, {"text": "半分以上の人が来て、会議はやっと成立した。", "target_word": "成立", "complexity_tier": "T3", "furigana": "半分[はんぶん]以上[いじょう]の人[ひと]が来[き]て、会議[かいぎ]はやっと成立[せいりつ]した。", "sentence_source": "generated"}, {"text": "投票する人が少なすぎて、選挙が成立しなかった。", "target_word": "成立", "complexity_tier": "T3", "furigana": "投票[とうひょう]する人[ひと]が少[すく]なすぎて、選挙[せんきょ]が成立[せいりつ]しなかった。", "sentence_source": "generated"}, {"text": "お客さんが一人も来ず、その日の商売は成立しなかった。", "target_word": "成立", "complexity_tier": "T3", "furigana": "お客[きゃく]さんが一人[ひとり]も来[こ]ず、その日[ひ]の商売[しょうばい]は成立[せいりつ]しなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "成立する", "label": "終止形"}, {"form": "成立した", "label": "過去形"}, {"form": "成立しない", "label": "否定形"}, {"form": "成立して", "label": "て形"}], "register": "neutral", "sense_fingerprint": "契約・取引・会話・試合などが、必要な条件がそろってきちんと成り立つこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6594844-572f-479f-92a0-dc80fd5f0199') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37526, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "成立", "is_correct": true, "explanation": "「この契約は成立しません」で、必要な条件がそろわず成り立たないという意味になり文脈に合う。"}, {"text": "開催", "is_correct": false, "explanation": "「契約は開催しません」は意味が通らない。契約は催しとして開かれるものではない。"}, {"text": "演奏", "is_correct": false, "explanation": "「契約は演奏しません」は意味が通らない。契約は演奏の対象にならない。"}, {"text": "収穫", "is_correct": false, "explanation": "「契約は収穫しません」は意味が通らない。契約は収穫されるものではない。"}], "explanations": {"成立": "「この契約は成立しません」で、必要な条件がそろわず成り立たないという意味になり文脈に合う。", "開催": "「契約は開催しません」は意味が通らない。契約は催しとして開かれるものではない。", "演奏": "「契約は演奏しません」は意味が通らない。契約は演奏の対象にならない。", "収穫": "「契約は収穫しません」は意味が通らない。契約は収穫されるものではない。"}, "sentence_index": 0, "correct_answer": "成立"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "病院で新しい命が成立した。", "explanation": "ここは〈生まれる〉の意味。成立は条件がそろって成り立つことで、命が生まれる意味では使わない。"}, {"text": "夢が成立した。", "explanation": "ここは〈実現〉の意味。成立は条件がそろって成り立つことで、夢が現実になる意味では使わない。"}, {"text": "ダムが成立した。", "explanation": "ここは〈完成〉の意味。成立は話し合いや条件によって成り立つことで、建造物が出来上がる意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37526, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成立", "is_correct": true, "explanation": "「会話が成立しない」で、やり取りが成り立たないという意味になり文脈に合う。"}, {"text": "撮影", "is_correct": false, "explanation": "「会話が撮影しない」は意味が通らない。会話は撮影の対象にならない。"}, {"text": "採点", "is_correct": false, "explanation": "「会話が採点しない」は意味が通らない。会話は点数をつけるものではない。"}, {"text": "掲載", "is_correct": false, "explanation": "「会話が掲載しない」は意味が通らない。会話は紙面に載せる対象ではない。"}], "explanations": {"成立": "「会話が成立しない」で、やり取りが成り立たないという意味になり文脈に合う。", "撮影": "「会話が撮影しない」は意味が通らない。会話は撮影の対象にならない。", "採点": "「会話が採点しない」は意味が通らない。会話は点数をつけるものではない。", "掲載": "「会話が掲載しない」は意味が通らない。会話は紙面に載せる対象ではない。"}, "sentence_index": 6, "correct_answer": "成立"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "手紙が成立した。", "explanation": "ここは〈届く〉の意味。成立は条件や手続きが整って成り立つことで、手紙が相手に届く意味では使わない。"}, {"text": "風船が大きく成立した。", "explanation": "ここは〈ふくらむ〉の意味。成立は条件や手続きで成り立つことで、物が大きくふくらむ意味では使わない。"}, {"text": "息子が大学に成立した。", "explanation": "ここは〈進学〉の意味。成立は条件や手続きが整って成り立つことで、人が学校に入る意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37526, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "日程が合わず、この約束を成立しなかった。", "corrected_sentence": "日程が合わず、この約束は成立しなかった。", "error_description": "「成立」は自動詞なので目的語の「を」は取らない。「約束は成立する」のように、主語には「は」または「が」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
