INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37527, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「和平が成立した」で、成立するものの主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「和平を成立した」は目的語の「を」になるが、成立は目的語を取らないので誤り。"}, {"text": "と", "is_correct": false, "explanation": "「和平と成立した」は共同の「と」で、文脈に合わない。"}, {"text": "の", "is_correct": false, "explanation": "「和平の成立した」は名詞に付く「の」で、動詞「成立した」とは続かず文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「和平が成立した」で、成立するものの主語を示す。", "を": "「和平を成立した」は目的語の「を」になるが、成立は目的語を取らないので誤り。", "と": "「和平と成立した」は共同の「と」で、文脈に合わない。", "の": "「和平の成立した」は名詞に付く「の」で、動詞「成立した」とは続かず文が成り立たない。"}, "error_tags": {"を": "目的語", "と": "共同", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
