INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37527, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事や状態が新しくでき上がること。また、ある条件や状況が整って、実現すること。", "primary_collocate": null, "pronunciation": "せいりつ", "ipa": "seːɾitsɯ", "syllable_count": 4, "sentences": [{"text": "国会で新しい法律が成立した。", "target_word": "成立", "complexity_tier": "T3", "furigana": "国会[こっかい]で新[あたら]しい法律[ほうりつ]が成立[せいりつ]した。", "sentence_source": "generated"}, {"text": "長い交渉の末、ついに和平が成立した。", "target_word": "成立", "complexity_tier": "T3", "furigana": "長[なが]い交渉[こうしょう]の末[すえ]、ついに和平[わへい]が成立[せいりつ]した。", "sentence_source": "generated"}, {"text": "両チームの条件が合い、トレードが成立した。", "target_word": "成立", "complexity_tier": "T3", "furigana": "両[りょう]チームの条件[じょうけん]が合[あ]い、トレードが成立[せいりつ]した。", "sentence_source": "generated"}, {"text": "予算案は来週、成立する見込みだ。", "target_word": "成立", "complexity_tier": "T3", "furigana": "予算案[よさんあん]は来週[らいしゅう]、成立[せいりつ]する見込[みこ]みだ。", "sentence_source": "generated"}, {"text": "三つの党の連立が成立し、新しい内閣ができた。", "target_word": "成立", "complexity_tier": "T3", "furigana": "三[みっ]つの党[とう]の連立[れんりつ]が成立[せいりつ]し、新[あたら]しい内閣[ないかく]ができた。", "sentence_source": "generated"}, {"text": "売買契約が成立したので、来月引っ越します。", "target_word": "成立", "complexity_tier": "T3", "furigana": "売買[ばいばい]契約[けいやく]が成立[せいりつ]したので、来月[らいげつ]引[ひ]っ越[こ]します。", "sentence_source": "generated"}, {"text": "話し合いの結果、離婚が成立した。", "target_word": "成立", "complexity_tier": "T3", "furigana": "話[はな]し合[あ]いの結果[けっか]、離婚[りこん]が成立[せいりつ]した。", "sentence_source": "generated"}, {"text": "双方の希望が合って、縁談が成立した。", "target_word": "成立", "complexity_tier": "T3", "furigana": "双方[そうほう]の希望[きぼう]が合[あ]って、縁談[えんだん]が成立[せいりつ]した。", "sentence_source": "generated"}, {"text": "賛成する議員が多く、この法案は成立した。", "target_word": "成立", "complexity_tier": "T3", "furigana": "賛成[さんせい]する議員[ぎいん]が多[おお]く、この法案[ほうあん]は成立[せいりつ]した。", "sentence_source": "generated"}, {"text": "条件がそろえば、すぐに取引が成立します。", "target_word": "成立", "complexity_tier": "T3", "furigana": "条件[じょうけん]がそろえば、すぐに取引[とりひき]が成立[せいりつ]します。", "sentence_source": "generated"}], "morphological_forms": [{"form": "成立する", "label": "終止形"}, {"form": "成立した", "label": "過去形"}, {"form": "成立しない", "label": "否定形"}, {"form": "成立して", "label": "て形"}], "register": "formal", "sense_fingerprint": "法律・内閣・和平・縁談などが、話し合いや手続きを経て新しく出来上がり実現すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6594844-572f-479f-92a0-dc80fd5f0199') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37527, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "成立", "is_correct": true, "explanation": "「新しい法律が成立した」で、議会を経て法律が成り立ったという意味になり文脈に合う。"}, {"text": "作曲", "is_correct": false, "explanation": "「法律が作曲した」は意味が通らない。法律は曲を作る対象にならない。"}, {"text": "出版", "is_correct": false, "explanation": "「法律が出版した」は不自然。法律は出版されるものではない。"}, {"text": "収穫", "is_correct": false, "explanation": "「法律が収穫した」は意味が通らない。法律は収穫されるものではない。"}], "explanations": {"成立": "「新しい法律が成立した」で、議会を経て法律が成り立ったという意味になり文脈に合う。", "作曲": "「法律が作曲した」は意味が通らない。法律は曲を作る対象にならない。", "出版": "「法律が出版した」は不自然。法律は出版されるものではない。", "収穫": "「法律が収穫した」は意味が通らない。法律は収穫されるものではない。"}, "sentence_index": 0, "correct_answer": "成立"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ベテランの選手が、ついに成立した。", "explanation": "ここは〈引退〉の意味。成立は条件がそろって成り立つことで、人が現役を退く意味はない。"}, {"text": "リンゴが成立した。", "explanation": "ここは〈熟す〉の意味。成立は条件や手続きが整って成り立つことで、果物が熟す意味では使わない。"}, {"text": "電車が成立した。", "explanation": "ここは〈出発〉の意味。成立は条件や手続きが整って成り立つことで、電車が出発する意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37527, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成立", "is_correct": true, "explanation": "「離婚が成立した」で、話し合いの結果として手続きが整ったという意味になり文脈に合う。"}, {"text": "翻訳", "is_correct": false, "explanation": "「離婚が翻訳した」は意味が通らない。離婚は翻訳の対象にならない。"}, {"text": "採掘", "is_correct": false, "explanation": "「離婚が採掘した」は意味が通らない。離婚は掘り出すものではない。"}, {"text": "暗記", "is_correct": false, "explanation": "「離婚が暗記した」は意味が通らない。離婚は覚える対象ではない。"}], "explanations": {"成立": "「離婚が成立した」で、話し合いの結果として手続きが整ったという意味になり文脈に合う。", "翻訳": "「離婚が翻訳した」は意味が通らない。離婚は翻訳の対象にならない。", "採掘": "「離婚が採掘した」は意味が通らない。離婚は掘り出すものではない。", "暗記": "「離婚が暗記した」は意味が通らない。離婚は覚える対象ではない。"}, "sentence_index": 6, "correct_answer": "成立"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "桜の花が成立した。", "explanation": "ここは〈咲く〉の意味。成立は条件がそろって成り立つことで、花が開く意味では使わない。"}, {"text": "庭の木が成立した。", "explanation": "ここは〈生える〉の意味。成立は条件や手続きが整って成り立つことで、木が生える意味では使わない。"}, {"text": "強い風が成立した。", "explanation": "ここは〈吹く〉の意味。成立は話し合いや条件がそろって成り立つことで、風が吹く意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37527, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "来週、新しい条例が町議会を成立する見込みだ。", "corrected_sentence": "来週、新しい条例が町議会で成立する見込みだ。", "error_description": "「成立」は目的語を取らない。場所を示すなら「で」を使う。「町議会を成立する」の「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37527, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "両社の提携は、先週成立された。", "corrected_sentence": "両社の提携は、先週成立した。", "error_description": "「成立」は自動詞なので受身の「成立された」にはならない。「成立した」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
