INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37528, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「規範に反する」の形で、反する相手を表すので自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を表す。「規範で反した」では反する対象にならない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は比べる文脈がないと使えない。「規範より反した」は文脈に合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐ。「規範の反した行動」は動詞「反した」との関係が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「規範に反する」の形で、反する相手を表すので自然。", "で": "「で」は手段や場所を表す。「規範で反した」では反する対象にならない。", "より": "比較の「より」は比べる文脈がないと使えない。「規範より反した」は文脈に合わない。", "の": "「の」は名詞どうしをつなぐ。「規範の反した行動」は動詞「反した」との関係が成り立たない。"}, "error_tags": {"で": "手段・場所", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37528, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "みんなが守るべき、正しい行動のルールのこと。", "primary_collocate": null, "pronunciation": "きはん", "ipa": "kihaɴ", "syllable_count": 3, "sentences": [{"text": "社会には、みんなが守るべき規範がある。", "target_word": "規範", "complexity_tier": "T3", "furigana": "社会[しゃかい]には、みんなが守[まも]るべき規範[きはん]がある。", "sentence_source": "generated"}, {"text": "子どもは大人の行動を見て、規範を学ぶ。", "target_word": "規範", "complexity_tier": "T3", "furigana": "子[こ]どもは大人[おとな]の行動[こうどう]を見[み]て、規範[きはん]を学[まな]ぶ。", "sentence_source": "generated"}, {"text": "規範を破ると、周りの人から信頼されなくなる。", "target_word": "規範", "complexity_tier": "T3", "furigana": "規範[きはん]を破[やぶ]ると、周[まわ]りの人[ひと]から信頼[しんらい]されなくなる。", "sentence_source": "generated"}, {"text": "静かに並んで待つのは、この国の規範だ。", "target_word": "規範", "complexity_tier": "T3", "furigana": "静[しず]かに並[なら]んで待[ま]つのは、この国[くに]の規範[きはん]だ。", "sentence_source": "generated"}, {"text": "学校では、先生が生徒に規範を教える。", "target_word": "規範", "complexity_tier": "T3", "furigana": "学校[がっこう]では、先生[せんせい]が生徒[せいと]に規範[きはん]を教[おし]える。", "sentence_source": "generated"}, {"text": "規範があるので、みんな安心して暮らせる。", "target_word": "規範", "complexity_tier": "T3", "furigana": "規範[きはん]があるので、みんな安心[あんしん]して暮[く]らせる。", "sentence_source": "generated"}, {"text": "法律になくても、席をゆずるのは大切な規範だ。", "target_word": "規範", "complexity_tier": "T3", "furigana": "法律[ほうりつ]になくても、席[せき]をゆずるのは大切[たいせつ]な規範[きはん]だ。", "sentence_source": "generated"}, {"text": "規範に反した行動をして、彼は注意された。", "target_word": "規範", "complexity_tier": "T3", "furigana": "規範[きはん]に反[はん]した行動[こうどう]をして、彼[かれ]は注意[ちゅうい]された。", "sentence_source": "generated"}, {"text": "この店では、客に丁寧に話すことが規範になっている。", "target_word": "規範", "complexity_tier": "T3", "furigana": "この店[みせ]では、客[きゃく]に丁寧[ていねい]に話[はな]すことが規範[きはん]になっている。", "sentence_source": "generated"}, {"text": "道徳の規範を守る人が多い町は、安全だ。", "target_word": "規範", "complexity_tier": "T3", "furigana": "道徳[どうとく]の規範[きはん]を守[まも]る人[ひと]が多[おお]い町[まち]は、安全[あんぜん]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "規範的", "label": "〜的の形"}], "register": "formal", "sense_fingerprint": "人が守るべき正しい行動のルール。守る・破る・反するの対象になる道徳的な決まり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6594844-572f-479f-92a0-dc80fd5f0199') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37528, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "規範", "is_correct": true, "explanation": "みんなが守るべき正しい行動の決まりという意味で、「守るべき〜がある」に入る。"}, {"text": "温度", "is_correct": false, "explanation": "温度は測るものなので、「守るべき」の対象にならない。"}, {"text": "旋律", "is_correct": false, "explanation": "旋律は音楽の流れを指すので、守るべき決まりとしては合わない。"}, {"text": "感情", "is_correct": false, "explanation": "感情は心の動きで、守るべき決まりという意味では文が成り立たない。"}], "explanations": {"規範": "みんなが守るべき正しい行動の決まりという意味で、「守るべき〜がある」に入る。", "温度": "温度は測るものなので、「守るべき」の対象にならない。", "旋律": "旋律は音楽の流れを指すので、守るべき決まりとしては合わない。", "感情": "感情は心の動きで、守るべき決まりという意味では文が成り立たない。"}, "sentence_index": 0, "correct_answer": "規範"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この部品は、検査の規範をクリアして出荷された。", "explanation": "ここは〈基準〉の意味。数値で決まる検査の合格ラインを指す語で、行動の決まりを表す規範は合わない。"}, {"text": "体温計の規範を見て、熱を測った。", "explanation": "ここは〈目盛り〉の意味。体温計の目盛りを指すので、人が守る行動の決まりとしての規範は合わない。"}, {"text": "工場では、規範の大きさに切る。", "explanation": "ここは〈標準〉の意味。決められた寸法を指すので、行動の決まりである規範は寸法の基準としては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37528, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "規範", "is_correct": true, "explanation": "社会で守るべき行動の基準という意味で、席をゆずることを大切な規範と言える。"}, {"text": "湿度", "is_correct": false, "explanation": "湿度は空気の水分の量なので、道徳的な大切さの説明には合わない。"}, {"text": "面積", "is_correct": false, "explanation": "面積は広さを表す量で、席をゆずる行為の大切さとして使えない。"}, {"text": "速度", "is_correct": false, "explanation": "速度は動きの速さで、席をゆずることの大切さとは結びつかない。"}], "explanations": {"規範": "社会で守るべき行動の基準という意味で、席をゆずることを大切な規範と言える。", "湿度": "湿度は空気の水分の量なので、道徳的な大切さの説明には合わない。", "面積": "面積は広さを表す量で、席をゆずる行為の大切さとして使えない。", "速度": "速度は動きの速さで、席をゆずることの大切さとは結びつかない。"}, "sentence_index": 6, "correct_answer": "規範"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "料理の規範は、一人分の量を見て決める。", "explanation": "ここは〈目安〉の意味。量の見当をつける語で、守るべき行動の決まりを表す規範は合わない。"}, {"text": "テストの規範を確認する。", "explanation": "ここは〈範囲〉の意味。出題される内容の広がりを指すので、行動の決まりである規範は使わない。"}, {"text": "規範を測って、部品を切った。", "explanation": "ここは〈寸法〉の意味。長さや大きさを測る対象を指すので、規範は測るものにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37528, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は、規範を沿って行動する。", "corrected_sentence": "彼は、規範に沿って行動する。", "error_description": "「沿う」は「〜に沿う」の形で使うので、「規範」に続く助詞は「に」が正しい。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37528, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は規範を守れ、仲間に信頼された。", "corrected_sentence": "彼は規範を守って、仲間に信頼された。", "error_description": "「守る」のテ形は「守って」が正しい。「守れ」は命令形で、文のつながりに合わず誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37529, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "も", "options": [{"text": "も", "is_correct": true, "explanation": "「社会の規範も少しずつ変わる」で、ほかのもの（時代など）と並べて加える「も」になり自然。"}, {"text": "を", "is_correct": false, "explanation": "「規範を少しずつ変わる」では、変わる（自動詞）の対象にならず不自然。"}, {"text": "で", "is_correct": false, "explanation": "「規範で少しずつ変わる」は手段の意味になり不自然。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐ。「社会の規範の少しずつ変わる」は動詞に続かず、文が成り立たない。"}], "correct_answer": "も", "explanations": {"も": "「社会の規範も少しずつ変わる」で、ほかのもの（時代など）と並べて加える「も」になり自然。", "を": "「規範を少しずつ変わる」では、変わる（自動詞）の対象にならず不自然。", "で": "「規範で少しずつ変わる」は手段の意味になり不自然。", "の": "「の」は名詞どうしをつなぐ。「社会の規範の少しずつ変わる」は動詞に続かず、文が成り立たない。"}, "error_tags": {"を": "対象", "で": "手段・場所", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37529, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「規範が見直されている」で、見直される主体を表す主語になり自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表す。「規範へ見直されている」は不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を表す。「規範と見直されている」は成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐ。「規範の見直されている」は動詞の主語にならない。"}], "correct_answer": "が", "explanations": {"が": "「規範が見直されている」で、見直される主体を表す主語になり自然。", "へ": "「へ」は方向を表す。「規範へ見直されている」は不自然。", "と": "「と」は並列や相手を表す。「規範と見直されている」は成り立たない。", "の": "「の」は名詞どうしをつなぐ。「規範の見直されている」は動詞の主語にならない。"}, "error_tags": {"へ": "方向", "と": "相手・並列", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37529, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "社会や集団の中で、人々が従うべき行動の基準や決まり。", "primary_collocate": null, "pronunciation": "きはん", "ipa": "kihaɴ", "syllable_count": 3, "sentences": [{"text": "集団の規範に合わない人は、仲間に入りにくい。", "target_word": "規範", "complexity_tier": "T3", "furigana": "集団[しゅうだん]の規範[きはん]に合[あ]わない人[ひと]は、仲間[なかま]に入[はい]りにくい。", "sentence_source": "generated"}, {"text": "時代が変わると、社会の規範も少しずつ変わる。", "target_word": "規範", "complexity_tier": "T3", "furigana": "時代[じだい]が変[か]わると、社会[しゃかい]の規範[きはん]も少[すこ]しずつ変[か]わる。", "sentence_source": "generated"}, {"text": "新しく入った社員は、会社の規範に早く慣れた。", "target_word": "規範", "complexity_tier": "T3", "furigana": "新[あたら]しく入[はい]った社員[しゃいん]は、会社[かいしゃ]の規範[きはん]に早[はや]く慣[な]れた。", "sentence_source": "generated"}, {"text": "研究者には、守るべき倫理の規範がある。", "target_word": "規範", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]には、守[まも]るべき倫理[りんり]の規範[きはん]がある。", "sentence_source": "generated"}, {"text": "村の古い規範が、若い人の生き方を縛っている。", "target_word": "規範", "complexity_tier": "T3", "furigana": "村[むら]の古[ふる]い規範[きはん]が、若[わか]い人[ひと]の生[い]き方[かた]を縛[しば]っている。", "sentence_source": "generated"}, {"text": "国によって、あいさつの規範は大きく違う。", "target_word": "規範", "complexity_tier": "T3", "furigana": "国[くに]によって、あいさつの規範[きはん]は大[おお]きく違[ちが]う。", "sentence_source": "generated"}, {"text": "医者は、職業の規範に従って患者を守る。", "target_word": "規範", "complexity_tier": "T3", "furigana": "医者[いしゃ]は、職業[しょくぎょう]の規範[きはん]に従[したが]って患者[かんじゃ]を守[まも]る。", "sentence_source": "generated"}, {"text": "男女の役割に関する規範が、少しずつ見直されている。", "target_word": "規範", "complexity_tier": "T3", "furigana": "男女[だんじょ]の役割[やくわり]に関[かん]する規範[きはん]が、少[すこ]しずつ見直[みなお]されている。", "sentence_source": "generated"}, {"text": "チームの規範を決めてから、練習の雰囲気が良くなった。", "target_word": "規範", "complexity_tier": "T3", "furigana": "チームの規範[きはん]を決[き]めてから、練習[れんしゅう]の雰囲気[ふんいき]が良[よ]くなった。", "sentence_source": "generated"}, {"text": "その国の文化の規範を知らないと、失礼な行動をしてしまう。", "target_word": "規範", "complexity_tier": "T3", "furigana": "その国[くに]の文化[ぶんか]の規範[きはん]を知[し]らないと、失礼[しつれい]な行動[こうどう]をしてしまう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "規範的", "label": "〜的の形"}], "register": "formal", "sense_fingerprint": "社会・会社・職業・文化などの集団ごとに、人々が従う行動の基準や決まり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6594844-572f-479f-92a0-dc80fd5f0199') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37529, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "規範", "is_correct": true, "explanation": "集団で守るべき行動の基準という意味で、「〜に合わない」の対象になる。"}, {"text": "体重", "is_correct": false, "explanation": "体重は体の重さで、集団の決まりに合う合わないとは結びつかない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空の状態で、集団の決まりに合わないとは言わない。"}, {"text": "地図", "is_correct": false, "explanation": "地図は場所を示すもので、集団の決まりとして合う合わないは言わない。"}], "explanations": {"規範": "集団で守るべき行動の基準という意味で、「〜に合わない」の対象になる。", "体重": "体重は体の重さで、集団の決まりに合う合わないとは結びつかない。", "天気": "天気は空の状態で、集団の決まりに合わないとは言わない。", "地図": "地図は場所を示すもので、集団の決まりとして合う合わないは言わない。"}, "sentence_index": 0, "correct_answer": "規範"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この機械の規範を読んで、操作を覚えた。", "explanation": "ここは〈マニュアル〉の意味。操作の手順を書いた説明書で、人が守る決まりの規範は合わない。"}, {"text": "このパソコンの規範は十分だ。", "explanation": "ここは〈スペック〉の意味。性能の数値を指すので、人の行動の決まりを表す規範は合わない。"}, {"text": "新しい規範で商品を探す。", "explanation": "ここは〈カタログ〉の意味。商品を並べた冊子を指すので、規範は商品を探す道具にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37529, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "規範", "is_correct": true, "explanation": "職業ごとの行動の基準という意味で、「職業の〜に従う」の対象になる。"}, {"text": "気温", "is_correct": false, "explanation": "気温は空気の温度なので、職業の決まりに従うという文には入らない。"}, {"text": "色", "is_correct": false, "explanation": "色は見た目の性質で、従う対象としては不自然。"}, {"text": "体格", "is_correct": false, "explanation": "体格は体の大きさを表すので、職業の決まりに従うとは言わない。"}], "explanations": {"規範": "職業ごとの行動の基準という意味で、「職業の〜に従う」の対象になる。", "気温": "気温は空気の温度なので、職業の決まりに従うという文には入らない。", "色": "色は見た目の性質で、従う対象としては不自然。", "体格": "体格は体の大きさを表すので、職業の決まりに従うとは言わない。"}, "sentence_index": 6, "correct_answer": "規範"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "レストランの規範を見て、注文する。", "explanation": "ここは〈メニュー〉の意味。料理と値段を載せた一覧で、行動の決まりである規範は合わない。"}, {"text": "壁の規範で日付を確認する。", "explanation": "ここは〈カレンダー〉の意味。日付を示す表で、規範は日付を確認する道具にはならない。"}, {"text": "規範で室温を測った。", "explanation": "ここは〈温度計〉の意味。温度を測る器具で、規範は室温を測る道具としては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37529, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会社の規範で従って、新人は動く。", "corrected_sentence": "会社の規範に従って、新人は動く。", "error_description": "「従う」は「〜に従う」の形で使うので、「規範」に続く助詞は「に」が正しい。「で」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37529, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "規範を守っていたば、仲間は安心する。", "corrected_sentence": "規範を守っていれば、仲間は安心する。", "error_description": "「守る」の仮定形は「守っていれば」が正しい。「守っていたば」は活用形として誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37530, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「先生」に続く連体助詞で、「先生のフィードバック」の所属を示し、文が成立する。"}, {"text": "で", "is_correct": false, "explanation": "「先生で」は名詞を結ぶ連体関係を作れず、「先生のフィードバック」の形にならない。"}, {"text": "を", "is_correct": false, "explanation": "「フィードバックをおかげで」は目的語にならず、文が崩れる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、「フィードバック」と「おかげ」をつなげない。"}], "correct_answer": "の", "explanations": {"の": "「先生」に続く連体助詞で、「先生のフィードバック」の所属を示し、文が成立する。", "で": "「先生で」は名詞を結ぶ連体関係を作れず、「先生のフィードバック」の形にならない。", "を": "「フィードバックをおかげで」は目的語にならず、文が崩れる。", "へ": "方向を表す助詞で、「フィードバック」と「おかげ」をつなげない。"}, "error_tags": {"で": "手段・場所", "を": "目的語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37530, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「先輩のフィードバック」を主題として示し、後の「いつも短い」という説明につなぐ。"}, {"text": "に", "is_correct": false, "explanation": "位置や相手を表し、主題を示す役割にはならない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を表し、主題の位置には入らない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表し、主題を示すことができない。"}], "correct_answer": "は", "explanations": {"は": "「先輩のフィードバック」を主題として示し、後の「いつも短い」という説明につなぐ。", "に": "位置や相手を表し、主題を示す役割にはならない。", "で": "手段や場所を表し、主題の位置には入らない。", "から": "起点を表し、主題を示すことができない。"}, "error_tags": {"に": "位置・相手", "で": "手段", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37530, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人からもらった意見や感想のことです。", "primary_collocate": null, "pronunciation": "ふぃーどばっく", "ipa": "ɸiːdobakkɯ", "syllable_count": 7, "sentences": [{"text": "友だちに作文を読んでもらって、フィードバックをもらった。", "target_word": "フィードバック", "complexity_tier": "T3", "furigana": "友[とも]だちに作文[さくぶん]を読[よ]んでもらって、フィードバックをもらった。", "sentence_source": "generated"}, {"text": "先生のフィードバックのおかげで、絵がうまくなった。", "target_word": "フィードバック", "complexity_tier": "T3", "furigana": "先生[せんせい]のフィードバックのおかげで、絵[え]がうまくなった。", "sentence_source": "generated"}, {"text": "発表のあと、みんなからフィードバックをもらってうれしかった。", "target_word": "フィードバック", "complexity_tier": "T3", "furigana": "発表[はっぴょう]のあと、みんなからフィードバックをもらってうれしかった。", "sentence_source": "generated"}, {"text": "料理を食べた家族のフィードバックを聞いて、味を変えてみた。", "target_word": "フィードバック", "complexity_tier": "T3", "furigana": "料理[りょうり]を食[た]べた家族[かぞく]のフィードバックを聞[き]いて、味[あじ]を変[か]えてみた。", "sentence_source": "generated"}, {"text": "フィードバックを読んで、次はもっとがんばろうと思った。", "target_word": "フィードバック", "complexity_tier": "T3", "furigana": "フィードバックを読[よ]んで、次[つぎ]はもっとがんばろうと思[おも]った。", "sentence_source": "generated"}, {"text": "歌を聞いた人が、やさしいフィードバックをくれた。", "target_word": "フィードバック", "complexity_tier": "T3", "furigana": "歌[うた]を聞[き]いた人[ひと]が、やさしいフィードバックをくれた。", "sentence_source": "generated"}, {"text": "新しいゲームを作ったら、友だちからフィードバックが届いた。", "target_word": "フィードバック", "complexity_tier": "T3", "furigana": "新[あたら]しいゲームを作[つく]ったら、友[とも]だちからフィードバックが届[とど]いた。", "sentence_source": "generated"}, {"text": "先輩のフィードバックはいつも短いが、とても役に立つ。", "target_word": "フィードバック", "complexity_tier": "T3", "furigana": "先輩[せんぱい]のフィードバックはいつも短[みじか]いが、とても役[やく]に立[た]つ。", "sentence_source": "generated"}, {"text": "店の人は、お客さんのフィードバックを大切にしている。", "target_word": "フィードバック", "complexity_tier": "T3", "furigana": "店[みせ]の人[ひと]は、お客[きゃく]さんのフィードバックを大切[たいせつ]にしている。", "sentence_source": "generated"}, {"text": "練習の動画を見せて、コーチにフィードバックを頼んだ。", "target_word": "フィードバック", "complexity_tier": "T3", "furigana": "練習[れんしゅう]の動画[どうが]を見[み]せて、コーチにフィードバックを頼[たの]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "フィードバック", "label": "基本形"}, {"form": "フィードバックする", "label": "サ変動詞"}], "register": "中立・丁寧", "sense_fingerprint": "自分の作品や行動に対して人がくれる意見や感想", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20d0fe3a-1868-40a7-a4d9-feac2c45ee0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37530, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "フィードバック", "is_correct": true, "explanation": "「読んでもらって、〜をもらった」と、人からの意見や感想を受け取る文として成り立つ。"}, {"text": "天気", "is_correct": false, "explanation": "「天気をもらった」は意味が通らず、意見をもらう文脈と合わない。"}, {"text": "駅", "is_correct": false, "explanation": "「駅をもらった」は成り立たず、作文を読んでもらう文脈と合わない。"}, {"text": "湿度", "is_correct": false, "explanation": "「湿度をもらった」は意味が通らず、感想を受け取る文と合わない。"}], "explanations": {"フィードバック": "「読んでもらって、〜をもらった」と、人からの意見や感想を受け取る文として成り立つ。", "天気": "「天気をもらった」は意味が通らず、意見をもらう文脈と合わない。", "駅": "「駅をもらった」は成り立たず、作文を読んでもらう文脈と合わない。", "湿度": "「湿度をもらった」は意味が通らず、感想を受け取る文と合わない。"}, "sentence_index": 0, "correct_answer": "フィードバック"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "古くなった看板の、フィードバックを塗り直した。", "explanation": "ここは〈塗装〉の意味。フィードバックは人からもらう意見や感想なので、塗り直す対象にはならない。"}, {"text": "身分の証明として、フィードバックをもらった。", "explanation": "ここは「証明書」の意味。フィードバックは人からもらう意見や感想なので、身分を示す書類には合わない。"}, {"text": "大会で優勝して、フィードバックを飾った。", "explanation": "ここは〈トロフィー〉の意味。フィードバックは人からもらう意見や感想なので、飾られる品物にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37530, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "フィードバック", "is_correct": true, "explanation": "「友だちから〜が届いた」と、人からの意見や感想が届く文として成り立つ。"}, {"text": "地震", "is_correct": false, "explanation": "「友だちから地震が届いた」は意味が通らず、ここでは合わない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "「友だちから夕焼けが届いた」は成り立たず、文脈に合わない。"}, {"text": "雷雨", "is_correct": false, "explanation": "「友だちから雷雨が届いた」は意味が通らず、感想が届く文と合わない。"}], "explanations": {"フィードバック": "「友だちから〜が届いた」と、人からの意見や感想が届く文として成り立つ。", "地震": "「友だちから地震が届いた」は意味が通らず、ここでは合わない。", "夕焼け": "「友だちから夕焼けが届いた」は成り立たず、文脈に合わない。", "雷雨": "「友だちから雷雨が届いた」は意味が通らず、感想が届く文と合わない。"}, "sentence_index": 6, "correct_answer": "フィードバック"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工場の機械を、フィードバックの油で動かした。", "explanation": "ここは〈潤滑剤〉の意味。フィードバックは人からもらう意見や感想なので、機械を動かす材料にはならない。"}, {"text": "スマホの修理を、店にフィードバックとして頼んだ。", "explanation": "ここは故障を直す作業の意味。フィードバックは人からもらう意見や感想なので、直してもらう頼みごとの対象にはならない。"}, {"text": "店員に料理を注文して、フィードバックが運ばれてくるのを待った。", "explanation": "ここは食事を提供される意味。フィードバックは人からもらう意見や感想なので、料理が出てくるのを待つ対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37530, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生からフィードバックを割って、作文を直した。", "corrected_sentence": "先生からフィードバックをもらって、作文を直した。", "error_description": "「フィードバック」は受け取るもので、「割る」とは組み合わない。「もらって」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37530, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先輩に相談して、フィードバックでもらった。", "corrected_sentence": "先輩に相談して、フィードバックをもらった。", "error_description": "「もらう」の対象は「を」で示す。「で」にすると手段の意味になり、「フィードバックでもらった」は不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37531, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「もらう」の対象を示す目的語で、受け取る対象として文が成り立つ。"}, {"text": "に", "is_correct": false, "explanation": "「もらう」は「に」で対象を取らず、ここでは合わない。"}, {"text": "が", "is_correct": false, "explanation": "「フィードバックがもらい」は主格として成り立たず、文が崩れる。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を表し、「もらう」の対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "「もらう」の対象を示す目的語で、受け取る対象として文が成り立つ。", "に": "「もらう」は「に」で対象を取らず、ここでは合わない。", "が": "「フィードバックがもらい」は主格として成り立たず、文が崩れる。", "と": "並列や相手を表し、「もらう」の対象にはならない。"}, "error_tags": {"に": "相手・位置", "が": "主格", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37531, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「良いフィードバック」を主題として示し、後続の説明につなぐ。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、主題を示す位置には入らない。"}, {"text": "に", "is_correct": false, "explanation": "位置や相手を表し、「示してくれる」と結ばれない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「を」が二つ続いて「示す」の対象が立たず、文が崩れる。"}], "correct_answer": "は", "explanations": {"は": "「良いフィードバック」を主題として示し、後続の説明につなぐ。", "へ": "方向を表す助詞で、主題を示す位置には入らない。", "に": "位置や相手を表し、「示してくれる」と結ばれない。", "を": "目的語を示すが、「を」が二つ続いて「示す」の対象が立たず、文が崩れる。"}, "error_tags": {"へ": "方向", "に": "位置・相手", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37531, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かを行った結果に対して、他者から返ってくる評価や意見のこと。", "primary_collocate": null, "pronunciation": "ふぃーどばっく", "ipa": "ɸiːdobakkɯ", "syllable_count": 7, "sentences": [{"text": "作品を見せると、審査員から鋭いフィードバックが返ってきた。", "target_word": "フィードバック", "complexity_tier": "T3", "furigana": "作品[さくひん]を見[み]せると、審査員[しんさいん]から鋭[するど]いフィードバックが返[かえ]ってきた。", "sentence_source": "generated"}, {"text": "発表のあとで先生からフィードバックをもらい、資料の弱い点に気づいた。", "target_word": "フィードバック", "complexity_tier": "T3", "furigana": "発表[はっぴょう]のあとで先生[せんせい]からフィードバックをもらい、資料[しりょう]の弱[よわ]い点[てん]に気[き]づいた。", "sentence_source": "generated"}, {"text": "新商品について、客からのフィードバックを集めて改良した。", "target_word": "フィードバック", "complexity_tier": "T3", "furigana": "新商品[しんしょうひん]について、客[きゃく]からのフィードバックを集[あつ]めて改良[かいりょう]した。", "sentence_source": "generated"}, {"text": "上司は部下の企画に、具体的なフィードバックを丁寧に返した。", "target_word": "フィードバック", "complexity_tier": "T3", "furigana": "上司[じょうし]は部下[ぶか]の企画[きかく]に、具体的[ぐたいてき]なフィードバックを丁寧[ていねい]に返[かえ]した。", "sentence_source": "generated"}, {"text": "試作品を試した人たちのフィードバックが、開発チームの方針を変えた。", "target_word": "フィードバック", "complexity_tier": "T3", "furigana": "試作品[しさくひん]を試[ため]した人[ひと]たちのフィードバックが、開発[かいはつ]チームの方針[ほうしん]を変[か]えた。", "sentence_source": "generated"}, {"text": "フィードバックがなかったので、私の説明が伝わったのか分からなかった。", "target_word": "フィードバック", "complexity_tier": "T3", "furigana": "フィードバックがなかったので、私[わたし]の説明[せつめい]が伝[つた]わったのか分[わ]からなかった。", "sentence_source": "generated"}, {"text": "レポートを出したのに、フィードバックが遅いと学生が不満を言っている。", "target_word": "フィードバック", "complexity_tier": "T3", "furigana": "レポートを出[だ]したのに、フィードバックが遅[おそ]いと学生[がくせい]が不満[ふまん]を言[い]っている。", "sentence_source": "generated"}, {"text": "良いフィードバックは、よかった点と直すべき点の両方を示してくれる。", "target_word": "フィードバック", "complexity_tier": "T3", "furigana": "良[よ]いフィードバックは、よかった点[てん]と直[なお]すべき点[てん]の両方[りょうほう]を示[しめ]してくれる。", "sentence_source": "generated"}, {"text": "会議の最後に、参加者全員がお互いにフィードバックを伝え合った。", "target_word": "フィードバック", "complexity_tier": "T3", "furigana": "会議[かいぎ]の最後[さいご]に、参加者全員[さんかしゃぜんいん]がお互[たが]いにフィードバックを伝[つた]え合[あ]った。", "sentence_source": "generated"}, {"text": "アプリの使いやすさについて、利用者にフィードバックを求めた。", "target_word": "フィードバック", "complexity_tier": "T3", "furigana": "アプリの使[つか]いやすさについて、利用者[りようしゃ]にフィードバックを求[もと]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "フィードバック", "label": "基本形"}, {"form": "フィードバックする", "label": "サ変動詞"}], "register": "ビジネス・書き言葉", "sense_fingerprint": "行動や成果に対して他者から返ってくる評価・意見(改善の手がかり)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20d0fe3a-1868-40a7-a4d9-feac2c45ee0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37531, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "フィードバック", "is_correct": true, "explanation": "「審査員から鋭い〜が返ってきた」と、他者からの評価が返る文として成り立つ。"}, {"text": "湿度", "is_correct": false, "explanation": "「鋭い湿度」は意味が通らず、審査員の評価を述べる文と合わない。"}, {"text": "包装", "is_correct": false, "explanation": "「鋭い包装」は成り立たず、審査員から返ってくるものとして合わない。"}, {"text": "栄養", "is_correct": false, "explanation": "「鋭い栄養」は意味が通らず、評価が返ってくる文脈に合わない。"}], "explanations": {"フィードバック": "「審査員から鋭い〜が返ってきた」と、他者からの評価が返る文として成り立つ。", "湿度": "「鋭い湿度」は意味が通らず、審査員の評価を述べる文と合わない。", "包装": "「鋭い包装」は成り立たず、審査員から返ってくるものとして合わない。", "栄養": "「鋭い栄養」は意味が通らず、評価が返ってくる文脈に合わない。"}, "sentence_index": 0, "correct_answer": "フィードバック"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "手術のあと、医者からフィードバックを処方された。", "explanation": "ここは〈薬〉の意味。フィードバックは他者から返ってくる評価なので、処方される品物にはならない。"}, {"text": "先週の作業について、上司にフィードバックを支払った。", "explanation": "ここは〈代金〉の意味。フィードバックは評価や意見なので、お金として支払う対象にはならない。"}, {"text": "株主は会社の利益から、フィードバックを受け取った。", "explanation": "ここは金銭的な「配当」の意味。フィードバックは評価や意見なので、お金の受け取りには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37531, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "フィードバック", "is_correct": true, "explanation": "「遅い」の主語となり、学生が不満を言う内容として文が成り立つ。"}, {"text": "天気", "is_correct": false, "explanation": "「天気が遅い」は意味が通らず、提出物への不満の文脈と合わない。"}, {"text": "絶景", "is_correct": false, "explanation": "「絶景が遅い」は成り立たず、レポートの文脈と合わない。"}, {"text": "海苔", "is_correct": false, "explanation": "「海苔が遅い」は意味が通らず、評価の遅れを述べる文と合わない。"}], "explanations": {"フィードバック": "「遅い」の主語となり、学生が不満を言う内容として文が成り立つ。", "天気": "「天気が遅い」は意味が通らず、提出物への不満の文脈と合わない。", "絶景": "「絶景が遅い」は成り立たず、レポートの文脈と合わない。", "海苔": "「海苔が遅い」は意味が通らず、評価の遅れを述べる文と合わない。"}, "sentence_index": 6, "correct_answer": "フィードバック"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖父は昔の写真を眺めて、懐かしいフィードバックにひたった。", "explanation": "ここは「感慨」の意味。フィードバックは他者から返ってくる評価なので、個人の感傷には合わない。"}, {"text": "店は客の食べ残しを、フィードバックとして処分した。", "explanation": "ここは〈ごみ〉の意味。フィードバックは他者からの評価や意見なので、捨てる対象にはならない。"}, {"text": "新しい建物を建てるため、フィードバックを購入した。", "explanation": "ここは「資材」の意味。フィードバックは評価や意見なので、建築用に購入する品物には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37531, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生からフィードバックを食べて、論文を直した。", "corrected_sentence": "先生からフィードバックをもらって、論文を直した。", "error_description": "「フィードバック」は受け取るもので、「食べる」とは組み合わない。「もらって」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37531, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "良いフィードバックが受けると、次の改善点が見えてくる。", "corrected_sentence": "良いフィードバックを受けると、次の改善点が見えてくる。", "error_description": "「受ける」の目的語は「を」で示す。「が」は主格で、受ける動作の対象を表せない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9deba143-a18b-4179-b7a2-25ea22261f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37532, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「生かす」は目的語に「を」を取り、「スキルを生かす」となる。"}, {"text": "が", "is_correct": false, "explanation": "「スキルが生かして」は「生かす」の目的語にならず、文が成立しない。"}, {"text": "と", "is_correct": false, "explanation": "「スキルと生かして」は並列にならず、目的語として成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "「スキルへ生かして」は方向の形にならず、生かす対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「生かす」は目的語に「を」を取り、「スキルを生かす」となる。", "が": "「スキルが生かして」は「生かす」の目的語にならず、文が成立しない。", "と": "「スキルと生かして」は並列にならず、目的語として成立しない。", "へ": "「スキルへ生かして」は方向の形にならず、生かす対象を示せない。"}, "error_tags": {"が": "主語", "と": "並列", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
