INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37532, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "じぶんができること、とくいなこと。", "primary_collocate": null, "pronunciation": "すきる", "ipa": "sɯkiɾɯ", "syllable_count": 3, "sentences": [{"text": "私の得意なスキルは、人の話を最後まで聞くことです。", "target_word": "スキル", "complexity_tier": "T3", "furigana": "私(わたし)の得意(とくい)なスキルは、人(ひと)の話(はなし)を最後(さいご)まで聞(き)くことです。", "sentence_source": "generated"}, {"text": "彼女は絵のスキルを生かして、イラストの仕事を始めた。", "target_word": "スキル", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は絵(え)のスキルを生(い)かして、イラストの仕事(しごと)を始(はじ)めた。", "sentence_source": "generated"}, {"text": "自分のスキルを知るために、友達に長所を聞いてみた。", "target_word": "スキル", "complexity_tier": "T3", "furigana": "自分(じぶん)のスキルを知(し)るために、友達(ともだち)に長所(ちょうしょ)を聞(き)いてみた。", "sentence_source": "generated"}, {"text": "弟はゲームのスキルが高く、大会で優勝した。", "target_word": "スキル", "complexity_tier": "T3", "furigana": "弟(おとうと)はゲームのスキルが高(たか)く、大会(たいかい)で優勝(ゆうしょう)した。", "sentence_source": "generated"}, {"text": "面接では、自分のスキルを短く説明してください。", "target_word": "スキル", "complexity_tier": "T3", "furigana": "面接(めんせつ)では、自分(じぶん)のスキルを短(みじか)く説明(せつめい)してください。", "sentence_source": "generated"}, {"text": "サッカーのスキルなら、チームで彼が一番だ。", "target_word": "スキル", "complexity_tier": "T3", "furigana": "サッカーのスキルなら、チームで彼(かれ)が一番(いちばん)だ。", "sentence_source": "generated"}, {"text": "子どもの頃から続けたピアノは、私の大切なスキルだ。", "target_word": "スキル", "complexity_tier": "T3", "furigana": "子(こ)どもの頃(ころ)から続(つづ)けたピアノは、私(わたし)の大切(たいせつ)なスキルだ。", "sentence_source": "generated"}, {"text": "彼にはどんな場所でもすぐ眠れるスキルがある。", "target_word": "スキル", "complexity_tier": "T3", "furigana": "彼(かれ)にはどんな場所(ばしょ)でもすぐ眠(ねむ)れるスキルがある。", "sentence_source": "generated"}, {"text": "このアプリでは、自分のスキルを写真つきで紹介できる。", "target_word": "スキル", "complexity_tier": "T3", "furigana": "このアプリでは、自分(じぶん)のスキルを写真(しゃしん)つきで紹介(しょうかい)できる。", "sentence_source": "generated"}, {"text": "スキルを見せる機会がなくて、彼はずっと悔しかった。", "target_word": "スキル", "complexity_tier": "T3", "furigana": "スキルを見(み)せる機会(きかい)がなくて、彼(かれ)はずっと悔(くや)しかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "スキル", "label": "基本形"}], "register": "標準", "sense_fingerprint": "自分ができること、得意なこと。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dec7f15-7782-4860-bad0-49a54713381d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37532, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "スキル", "is_correct": true, "explanation": "「得意なスキル」は自分ができることを指し、人の話を聞く力の文脈に合う。"}, {"text": "方針", "is_correct": false, "explanation": "「得意な方針」は意味をなさず、人の話を聞く得意さの文脈と合わない。"}, {"text": "締切", "is_correct": false, "explanation": "「得意な締切」は不自然で、人の話を聞く力の説明にならない。"}, {"text": "天気", "is_correct": false, "explanation": "「得意な天気」は意味をなさず、人の話を聞く能力の文脈に合わない。"}], "explanations": {"スキル": "「得意なスキル」は自分ができることを指し、人の話を聞く力の文脈に合う。", "方針": "「得意な方針」は意味をなさず、人の話を聞く得意さの文脈と合わない。", "締切": "「得意な締切」は不自然で、人の話を聞く力の説明にならない。", "天気": "「得意な天気」は意味をなさず、人の話を聞く能力の文脈に合わない。"}, "sentence_index": 0, "correct_answer": "スキル"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "冬休みに家族と雪山へ行き、スキルを楽しんだ。", "explanation": "ここは〈スキー〉の意味。スキルは能力を指し、雪山で滑る競技の名前ではないので合わない。"}, {"text": "休日は山歩きの道具を、スキルとして店に売っている。", "explanation": "ここは〈商品〉の意味。スキルは能力を指し、店で売る品物ではないので合わない。"}, {"text": "彼のスキルは会計士で、税金の相談に乗っている。", "explanation": "ここは〈職業〉の意味。スキルは能力を指し、職種そのものを表す語ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37532, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "スキル", "is_correct": true, "explanation": "「大切なスキル」は自分ができることを指し、ピアノを続けた成果として文脈に合う。"}, {"text": "送料", "is_correct": false, "explanation": "「大切な送料」は意味をなさず、ピアノの話の文脈と合わない。"}, {"text": "渋滞", "is_correct": false, "explanation": "「大切な渋滞」は不自然で、ピアノを続けた成果の説明にならない。"}, {"text": "祝日", "is_correct": false, "explanation": "「大切な祝日」は文脈に合わず、ピアノの話の対象として成立しない。"}], "explanations": {"スキル": "「大切なスキル」は自分ができることを指し、ピアノを続けた成果として文脈に合う。", "送料": "「大切な送料」は意味をなさず、ピアノの話の文脈と合わない。", "渋滞": "「大切な渋滞」は不自然で、ピアノを続けた成果の説明にならない。", "祝日": "「大切な祝日」は文脈に合わず、ピアノの話の対象として成立しない。"}, "sentence_index": 6, "correct_answer": "スキル"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "出かけるときのスキルは、傘と財布だけだ。", "explanation": "ここは〈持ち物〉の意味。スキルは身につけた能力で、傘や財布のように持ち歩く物ではないので合わない。"}, {"text": "彼のスキルはがっしりしていて、柔道選手らしい。", "explanation": "ここは〈体格〉の意味。スキルは体つきを表さないので、体の形容には使えない。"}, {"text": "彼のスキルは穏やかで、誰とでもすぐ仲良くなれる。", "explanation": "ここは〈性格〉の意味。スキルは能力を指し、人柄をあらわす穏やかさには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37532, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は面接で、自分のスキルに具体的に話せた。", "corrected_sentence": "彼は面接で、自分のスキルを具体的に話せた。", "error_description": "誤りは助詞。「話す」は目的語に「を」を取るので、「スキルに」は誤り。正しくは「スキルを」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37532, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "アプリを使うと、料理のスキルが身につける。", "corrected_sentence": "アプリを使うと、料理のスキルが身につく。", "error_description": "誤りは動詞の形。「身につく」は自動詞で「が」と合う。「身につける」は他動詞で「を」を取るため、「スキルが」には「身につく」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37533, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「高める」は他動詞で、目的語「スキル」に「を」が付く。"}, {"text": "が", "is_correct": false, "explanation": "「スキルが高める」は主語と動詞が合わず、高める対象を示せない。"}, {"text": "に", "is_correct": false, "explanation": "「スキルに高める」は「高める」の対象の格として不自然。"}, {"text": "と", "is_correct": false, "explanation": "「スキルと高める」は並列にならず、動詞の目的語として成立しない。"}], "correct_answer": "を", "explanations": {"を": "「高める」は他動詞で、目的語「スキル」に「を」が付く。", "が": "「スキルが高める」は主語と動詞が合わず、高める対象を示せない。", "に": "「スキルに高める」は「高める」の対象の格として不自然。", "と": "「スキルと高める」は並列にならず、動詞の目的語として成立しない。"}, "error_tags": {"が": "主語", "に": "方向", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37533, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「足りない」は主語に「が」を取り、「スキルが」が不足の主語になる。"}, {"text": "を", "is_correct": false, "explanation": "「スキルを足りない」は「足りない」の主語にならず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「スキルへ足りない」は方向の意味にならず成立しない。"}, {"text": "より", "is_correct": false, "explanation": "「スキルより足りない」は比較の形にならず成立しない。"}], "correct_answer": "が", "explanations": {"が": "「足りない」は主語に「が」を取り、「スキルが」が不足の主語になる。", "を": "「スキルを足りない」は「足りない」の主語にならず不自然。", "へ": "「スキルへ足りない」は方向の意味にならず成立しない。", "より": "「スキルより足りない」は比較の形にならず成立しない。"}, "error_tags": {"を": "目的語", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37533, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "あることをうまくおこなうための、みにつけたのうりょくやぎじゅつ。", "primary_collocate": null, "pronunciation": "すきる", "ipa": "sɯkiɾɯ", "syllable_count": 3, "sentences": [{"text": "企業は、単純な作業だけでなく、創造性や対人スキルを求められる役割へ従業員をシフトさせなければならない。", "target_word": "スキル", "complexity_tier": "T4", "furigana": "企業(きぎょう)は、単純(たんじゅん)な作業(さぎょう)だけでなく、創造性(そうぞうせい)や対人(たいじん)スキルを求(もと)められる役割(やくわり)へ従業員(じゅうぎょういん)をシフトさせなければならない。", "sentence_source": "mined"}, {"text": "英語のスキルを高めるために、毎朝ラジオを聞いている。", "target_word": "スキル", "complexity_tier": "T3", "furigana": "英語(えいご)のスキルを高(たか)めるために、毎朝(まいあさ)ラジオを聞(き)いている。", "sentence_source": "generated"}, {"text": "この仕事には、パソコンのスキルが必要です。", "target_word": "スキル", "complexity_tier": "T3", "furigana": "この仕事(しごと)には、パソコンのスキルが必要(ひつよう)です。", "sentence_source": "generated"}, {"text": "経験が少なくても、スキルがあれば転職しやすい。", "target_word": "スキル", "complexity_tier": "T3", "furigana": "経験(けいけん)が少(すく)なくても、スキルがあれば転職(てんしょく)しやすい。", "sentence_source": "generated"}, {"text": "彼は料理のスキルが高く、プロの料理人にも負けない。", "target_word": "スキル", "complexity_tier": "T3", "furigana": "彼(かれ)は料理(りょうり)のスキルが高(たか)く、プロの料理人(りょうりにん)にも負(ま)けない。", "sentence_source": "generated"}, {"text": "新入社員向けに、話し方のスキルを学ぶ研修が開かれた。", "target_word": "スキル", "complexity_tier": "T3", "furigana": "新入社員(しんにゅうしゃいん)向(む)けに、話(はな)し方(かた)のスキルを学(まな)ぶ研修(けんしゅう)が開(ひら)かれた。", "sentence_source": "generated"}, {"text": "スキルを身につけるには、毎日の練習が欠かせない。", "target_word": "スキル", "complexity_tier": "T3", "furigana": "スキルを身(み)につけるには、毎日(まいにち)の練習(れんしゅう)が欠(か)かせない。", "sentence_source": "generated"}, {"text": "山田さんはスキルが足りなかったので、まず基礎から勉強した。", "target_word": "スキル", "complexity_tier": "T3", "furigana": "山田(やまだ)さんはスキルが足(た)りなかったので、まず基礎(きそ)から勉強(べんきょう)した。", "sentence_source": "generated"}, {"text": "会社は、社員のスキルに合わせて仕事を決めている。", "target_word": "スキル", "complexity_tier": "T3", "furigana": "会社(かいしゃ)は、社員(しゃいん)のスキルに合(あ)わせて仕事(しごと)を決(き)めている。", "sentence_source": "generated"}, {"text": "履歴書には、持っているスキルを具体的に書いたほうがいい。", "target_word": "スキル", "complexity_tier": "T3", "furigana": "履歴書(りれきしょ)には、持(も)っているスキルを具体的(ぐたいてき)に書(か)いたほうがいい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "スキル", "label": "基本形"}], "register": "標準", "sense_fingerprint": "仕事や活動をうまく行うために身につけた能力や技術。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dec7f15-7782-4860-bad0-49a54713381d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37533, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "スキル", "is_correct": true, "explanation": "「対人スキル」は人と接する能力を指し、創造性と並べて求められる能力として文脈に合う。"}, {"text": "負担", "is_correct": false, "explanation": "「対人負担」は意味をなさず、求められる能力の文脈に合わない。"}, {"text": "予算", "is_correct": false, "explanation": "「対人予算」は組み合わせとして不自然で、能力を求める文脈に合わない。"}, {"text": "残業", "is_correct": false, "explanation": "「対人残業」は不自然で、創造性と並べて求める対象にはならない。"}], "explanations": {"スキル": "「対人スキル」は人と接する能力を指し、創造性と並べて求められる能力として文脈に合う。", "負担": "「対人負担」は意味をなさず、求められる能力の文脈に合わない。", "予算": "「対人予算」は組み合わせとして不自然で、能力を求める文脈に合わない。", "残業": "「対人残業」は不自然で、創造性と並べて求める対象にはならない。"}, "sentence_index": 0, "correct_answer": "スキル"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は生まれつきのスキルで、毎朝の髪型をすぐ変えてしまう。", "explanation": "ここは〈髪型〉の意味。スキルは能力を指し、髪の形を表す語ではないので合わない。"}, {"text": "運転のスキルは、市役所に申請すれば二週間で交付される。", "explanation": "ここは〈免許〉の意味。免許は役所が交付する資格のことで、身につけた能力であるスキルは申請して交付されるものではないので合わない。"}, {"text": "教科書の内容をスキルとして覚えておくと、テストで役立つ。", "explanation": "ここは〈知識〉の意味。覚える事実は知識であり、実際にできる力を指すスキルとは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37533, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "スキル", "is_correct": true, "explanation": "「身につける」の対象として、能力を表す「スキル」が文脈に合う。"}, {"text": "時間", "is_correct": false, "explanation": "「時間を身につける」とは言わず、練習で得るものの文脈に合わない。"}, {"text": "送料", "is_correct": false, "explanation": "「送料を身につける」は成立せず、練習が必要な文脈と合わない。"}, {"text": "祝日", "is_correct": false, "explanation": "「祝日を身につける」は成立せず、練習で得るものとは関係しない。"}], "explanations": {"スキル": "「身につける」の対象として、能力を表す「スキル」が文脈に合う。", "時間": "「時間を身につける」とは言わず、練習で得るものの文脈に合わない。", "送料": "「送料を身につける」は成立せず、練習が必要な文脈と合わない。", "祝日": "「祝日を身につける」は成立せず、練習で得るものとは関係しない。"}, "sentence_index": 6, "correct_answer": "スキル"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冬は家族と雪山へ行き、毎年スキルを楽しんでいる。", "explanation": "ここは〈スキー〉の意味。スキルは技能であり、雪山で楽しむ競技とは別物なので合わない。"}, {"text": "彼のスキルは穏やかで、誰とでもすぐ仲良くなれる。", "explanation": "ここは〈性格〉の意味。スキルは能力を指し、人柄をあらわす穏やかさには使わない。"}, {"text": "この店のスキルは季節ごとに入れ替わる。", "explanation": "ここは〈在庫〉の意味。スキルは商品ではないので、入れ替わる対象にはならず合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37533, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この仕事には、事務のスキルを必要です。", "corrected_sentence": "この仕事には、事務のスキルが必要です。", "error_description": "誤りは助詞。「必要だ」は「〜が必要だ」と「が」を取るので、「を」は誤り。正しくは「が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37533, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "毎日の練習で、スキルが身につける。", "corrected_sentence": "毎日の練習で、スキルが身につく。", "error_description": "誤りは動詞の形。「身につく」は自動詞で「が」と合う。「身につける」は他動詞で「を」を取るため、「スキルが」には「身につく」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37534, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「解決には時間がかかる」の「には」の「に」。時間や労力を必要とする意味を表す。"}, {"text": "を", "is_correct": false, "explanation": "「解決をは」と続かず、文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「解決がは」と続かず、主語にもならない。"}, {"text": "の", "is_correct": false, "explanation": "「解決のは」と続かず、名詞を結ぶ用法にもならない。"}], "correct_answer": "に", "explanations": {"に": "「解決には時間がかかる」の「には」の「に」。時間や労力を必要とする意味を表す。", "を": "「解決をは」と続かず、文が成り立たない。", "が": "「解決がは」と続かず、主語にもならない。", "の": "「解決のは」と続かず、名詞を結ぶ用法にもならない。"}, "error_tags": {"を": "目的語", "が": "主語", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
