INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37534, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "もんだいをなくすこと", "primary_collocate": null, "pronunciation": "かいけつ", "ipa": "kaiketsɯ", "syllable_count": 4, "sentences": [{"text": "話し合いで、やっと問題が解決した。", "target_word": "解決", "complexity_tier": "T3", "furigana": "話[はな]し合[あ]いで、やっと問題[もんだい]が解決[かいけつ]した。", "sentence_source": "generated"}, {"text": "この問題の解決には、まだ時間がかかる。", "target_word": "解決", "complexity_tier": "T3", "furigana": "この問題[もんだい]の解決[かいけつ]には、まだ時間[じかん]がかかる。", "sentence_source": "generated"}, {"text": "先生に相談したので、悩みは解決した。", "target_word": "解決", "complexity_tier": "T3", "furigana": "先生[せんせい]に相談[そうだん]したので、悩[なや]みは解決[かいけつ]した。", "sentence_source": "generated"}, {"text": "事件が解決して、町はまた静かになった。", "target_word": "解決", "complexity_tier": "T3", "furigana": "事件[じけん]が解決[かいけつ]して、町[まち]はまた静[しず]かになった。", "sentence_source": "generated"}, {"text": "水もれは、修理で解決できるはずだ。", "target_word": "解決", "complexity_tier": "T3", "furigana": "水[みず]もれは、修理[しゅうり]で解決[かいけつ]できるはずだ。", "sentence_source": "generated"}, {"text": "二人のけんかは、あやまって解決した。", "target_word": "解決", "complexity_tier": "T3", "furigana": "二人[ふたり]のけんかは、あやまって解決[かいけつ]した。", "sentence_source": "generated"}, {"text": "問題は解決していないので、会議は続いた。", "target_word": "解決", "complexity_tier": "T3", "furigana": "問題[もんだい]は解決[かいけつ]していないので、会議[かいぎ]は続[つづ]いた。", "sentence_source": "generated"}, {"text": "彼は機械の故障を一人で解決した。", "target_word": "解決", "complexity_tier": "T3", "furigana": "彼[かれ]は機械[きかい]の故障[こしょう]を一人[ひとり]で解決[かいけつ]した。", "sentence_source": "generated"}, {"text": "解決の方法が見つからず、みんなこまっている。", "target_word": "解決", "complexity_tier": "T3", "furigana": "解決[かいけつ]の方法[ほうほう]が見[み]つからず、みんなこまっている。", "sentence_source": "generated"}, {"text": "電話一本で、すべてが解決した。", "target_word": "解決", "complexity_tier": "T3", "furigana": "電話[でんわ]一本[いっぽん]で、すべてが解決[かいけつ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "解決する", "label": "辞書形"}, {"form": "解決した", "label": "過去形"}, {"form": "解決しない", "label": "否定形"}, {"form": "解決できる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "問題・悩み・事件などがなくなること、またはなくすこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '138c9f88-9d7f-429e-8d2c-7d4fc969fc77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37534, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "解決", "is_correct": true, "explanation": "問題がなくなったという意味になり、文が成り立つ。"}, {"text": "反省", "is_correct": false, "explanation": "「問題が反省した」は意味が通らない。反省は人が自分の行いを振り返ること。"}, {"text": "挨拶", "is_correct": false, "explanation": "「問題が挨拶した」は成り立たない。挨拶は人が交わす言葉や礼。"}, {"text": "納得", "is_correct": false, "explanation": "「問題が納得した」は不自然。納得は人が理解して受け入れること。"}], "explanations": {"解決": "問題がなくなったという意味になり、文が成り立つ。", "反省": "「問題が反省した」は意味が通らない。反省は人が自分の行いを振り返ること。", "挨拶": "「問題が挨拶した」は成り立たない。挨拶は人が交わす言葉や礼。", "納得": "「問題が納得した」は不自然。納得は人が理解して受け入れること。"}, "sentence_index": 0, "correct_answer": "解決"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この映画は、来週ついに解決する。", "explanation": "映画は問題ではないので、解決とは言えない。"}, {"text": "彼は来年、留学を解決する。", "explanation": "留学は問題ではないので、解決とは言えない。"}, {"text": "チームは今年の目標を解決した。", "explanation": "目標は問題ではないので、解決とは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37534, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "解決", "is_correct": true, "explanation": "問題がまだ片づいていない状態を表し、文が成り立つ。"}, {"text": "感謝", "is_correct": false, "explanation": "「問題は感謝していない」は意味が通らない。感謝は人が相手に抱く気持ち。"}, {"text": "約束", "is_correct": false, "explanation": "「問題は約束していない」は成り立たない。約束は人同士の取り決め。"}, {"text": "辞退", "is_correct": false, "explanation": "「問題は辞退していない」は成り立たない。辞退は人が申し出を断ること。"}], "explanations": {"解決": "問題がまだ片づいていない状態を表し、文が成り立つ。", "感謝": "「問題は感謝していない」は意味が通らない。感謝は人が相手に抱く気持ち。", "約束": "「問題は約束していない」は成り立たない。約束は人同士の取り決め。", "辞退": "「問題は辞退していない」は成り立たない。辞退は人が申し出を断ること。"}, "sentence_index": 6, "correct_answer": "解決"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会社は新しい計画を、来月ついに解決する。", "explanation": "計画は問題ではないので、解決とは言えない。"}, {"text": "担当者が、届いた申込みを一つずつ解決した。", "explanation": "申込みは問題ではないので、解決とは言えない。"}, {"text": "整備士は毎朝、エンジンを解決している。", "explanation": "エンジンは問題ではないので、解決とは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37534, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "二人はけんかに解決した。", "corrected_sentence": "二人はけんかを解決した。", "error_description": "「解決する」は対象を「を」で取る。「けんかに解決した」は誤りで、正しくは「けんかを解決した」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
