INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37535, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「渋滞を解決するため」の「を」。「解決」の目的語を示す。"}, {"text": "に", "is_correct": false, "explanation": "「渋滞に解決するため」は成り立たない。対象は「を」で示す。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」で、「渋滞へ解決」は不自然。"}, {"text": "の", "is_correct": false, "explanation": "「渋滞の解決するため」は文のつながりが成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「渋滞を解決するため」の「を」。「解決」の目的語を示す。", "に": "「渋滞に解決するため」は成り立たない。対象は「を」で示す。", "へ": "方向を表す「へ」で、「渋滞へ解決」は不自然。", "の": "「渋滞の解決するため」は文のつながりが成り立たない。"}, "error_tags": {"に": "位置・対象", "へ": "方向", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
