INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37535, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "問題や課題を解決すること。困難な状況を好ましい状態に変えること。", "primary_collocate": null, "pronunciation": "かいけつ", "ipa": "kaiketsɯ", "syllable_count": 4, "sentences": [{"text": "会社は人手不足の解決のために、新しい人を入れた。", "target_word": "解決", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は人手不足[ひとでぶそく]の解決[かいけつ]のために、新[あたら]しい人[ひと]を入[い]れた。", "sentence_source": "generated"}, {"text": "市は交通渋滞を解決するため、新しい道路を作った。", "target_word": "解決", "complexity_tier": "T3", "furigana": "市[し]は交通渋滞[こうつうじゅうたい]を解決[かいけつ]するため、新[あたら]しい道路[どうろ]を作[つく]った。", "sentence_source": "generated"}, {"text": "お金の問題が解決して、やっと安心して眠れた。", "target_word": "解決", "complexity_tier": "T3", "furigana": "お金[かね]の問題[もんだい]が解決[かいけつ]して、やっと安心[あんしん]して眠[ねむ]れた。", "sentence_source": "generated"}, {"text": "話し合いを重ねれば、対立も解決できるだろう。", "target_word": "解決", "complexity_tier": "T3", "furigana": "話[はな]し合[あ]いを重[かさ]ねれば、対立[たいりつ]も解決[かいけつ]できるだろう。", "sentence_source": "generated"}, {"text": "長年の争いは、法律の力で解決した。", "target_word": "解決", "complexity_tier": "T3", "furigana": "長年[ながねん]の争[あらそ]いは、法律[ほうりつ]の力[ちから]で解決[かいけつ]した。", "sentence_source": "generated"}, {"text": "解決の糸口が見えたので、チームの空気が明るくなった。", "target_word": "解決", "complexity_tier": "T3", "furigana": "解決[かいけつ]の糸口[いとぐち]が見[み]えたので、チームの空気[くうき]が明[あか]るくなった。", "sentence_source": "generated"}, {"text": "環境問題の解決は、一人の力では難しい。", "target_word": "解決", "complexity_tier": "T3", "furigana": "環境問題[かんきょうもんだい]の解決[かいけつ]は、一人[ひとり]の力[ちから]では難[むずか]しい。", "sentence_source": "generated"}, {"text": "彼女のアイデアが、工場の困難を解決した。", "target_word": "解決", "complexity_tier": "T3", "furigana": "彼女[かのじょ]のアイデアが、工場[こうじょう]の困難[こんなん]を解決[かいけつ]した。", "sentence_source": "generated"}, {"text": "問題を先送りしても、解決にはならない。", "target_word": "解決", "complexity_tier": "T3", "furigana": "問題[もんだい]を先送[さきおく]りしても、解決[かいけつ]にはならない。", "sentence_source": "generated"}, {"text": "専門家の助けで、会社の危機は解決へ向かった。", "target_word": "解決", "complexity_tier": "T3", "furigana": "専門家[せんもんか]の助[たす]けで、会社[かいしゃ]の危機[きき]は解決[かいけつ]へ向[む]かった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "解決する", "label": "辞書形"}, {"form": "解決した", "label": "過去形"}, {"form": "解決しない", "label": "否定形"}, {"form": "解決できる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "社会・組織・人間関係などの困難な状況を良い状態に変えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '138c9f88-9d7f-429e-8d2c-7d4fc969fc77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37535, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "解決", "is_correct": true, "explanation": "人手不足という困った状態を片づける意味で、ここに入る。"}, {"text": "挨拶", "is_correct": false, "explanation": "「人手不足の挨拶のために」は意味が通らない。挨拶は人が交わす言葉や礼。"}, {"text": "納得", "is_correct": false, "explanation": "「人手不足の納得のために」は意味が通らない。納得は理解して受け入れること。"}, {"text": "感謝", "is_correct": false, "explanation": "「人手不足の感謝のために」は意味が通らない。感謝は相手に抱く気持ち。"}], "explanations": {"解決": "人手不足という困った状態を片づける意味で、ここに入る。", "挨拶": "「人手不足の挨拶のために」は意味が通らない。挨拶は人が交わす言葉や礼。", "納得": "「人手不足の納得のために」は意味が通らない。納得は理解して受け入れること。", "感謝": "「人手不足の感謝のために」は意味が通らない。感謝は相手に抱く気持ち。"}, "sentence_index": 0, "correct_answer": "解決"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "担当者は新しい製品を解決した。", "explanation": "ここは〈検査〉の意味。製品は問題ではないので、解決とは言わない。"}, {"text": "町は秋の祭りを解決した。", "explanation": "ここは〈延期〉の意味。祭りは問題ではないので、解決とは言わない。"}, {"text": "選手はついに金メダルを解決した。", "explanation": "ここは〈獲得〉の意味。メダルは問題ではないので、解決とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37535, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "解決", "is_correct": true, "explanation": "環境問題を片づけることを表し、主語として文が成り立つ。"}, {"text": "製造", "is_correct": false, "explanation": "「環境問題の製造は難しい」は成り立たない。製造は物を作ること。"}, {"text": "辞退", "is_correct": false, "explanation": "「環境問題の辞退は難しい」は意味が通らない。辞退は申し出を断ること。"}, {"text": "乗車", "is_correct": false, "explanation": "「環境問題の乗車は難しい」は成り立たない。乗車は乗り物に乗ること。"}], "explanations": {"解決": "環境問題を片づけることを表し、主語として文が成り立つ。", "製造": "「環境問題の製造は難しい」は成り立たない。製造は物を作ること。", "辞退": "「環境問題の辞退は難しい」は意味が通らない。辞退は申し出を断ること。", "乗車": "「環境問題の乗車は難しい」は成り立たない。乗車は乗り物に乗ること。"}, "sentence_index": 6, "correct_answer": "解決"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "カメラマンは花の写真を解決した。", "explanation": "ここは〈撮影〉の意味。写真は問題ではないので、解決とは言わない。"}, {"text": "委員会は新しい候補を解決した。", "explanation": "ここは〈推薦〉の意味。候補は問題ではないので、解決とは言わない。"}, {"text": "市は古い建物を解決した。", "explanation": "ここは〈登録〉の意味。建物は問題ではないので、解決とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37535, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地域の対立に解決するため、話し合いの場が作られた。", "corrected_sentence": "地域の対立を解決するため、話し合いの場が作られた。", "error_description": "「解決する」は対象を「を」で取る。「対立に解決」は誤りで、正しくは「対立を解決するため」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37535, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市の財政難を解決で、新しい計画が必要だ。", "corrected_sentence": "市の財政難を解決するために、新しい計画が必要だ。", "error_description": "「解決する」の後には「ために」が続く。「解決で」では文が成り立たず、目的を表せない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37536, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「経験が豊富」の「が」。豊富だと評価される主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「豊富」は形容詞で目的語の「を」を取らないため、「経験を豊富」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「経験に豊富」は状態の主語を示せず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「経験へ豊富」は方向を示す「へ」で、状態の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「経験が豊富」の「が」。豊富だと評価される主語を示す。", "を": "「豊富」は形容詞で目的語の「を」を取らないため、「経験を豊富」は成り立たない。", "に": "「経験に豊富」は状態の主語を示せず、文が成り立たない。", "へ": "「経験へ豊富」は方向を示す「へ」で、状態の主語にはならない。"}, "error_tags": {"を": "対象", "に": "位置", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37536, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「初めての経験で緊張した」の「で」。緊張の原因や場面を表す。"}, {"text": "の", "is_correct": false, "explanation": "「初めての経験の、とても緊張しました」は文の接続が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「経験と緊張」は並列の関係で、緊張の原因を示せない。"}, {"text": "を", "is_correct": false, "explanation": "「緊張する」は対象の「を」を取らず、「経験を緊張」は成り立たない。"}], "correct_answer": "で", "explanations": {"で": "「初めての経験で緊張した」の「で」。緊張の原因や場面を表す。", "の": "「初めての経験の、とても緊張しました」は文の接続が成り立たない。", "と": "「経験と緊張」は並列の関係で、緊張の原因を示せない。", "を": "「緊張する」は対象の「を」を取らず、「経験を緊張」は成り立たない。"}, "error_tags": {"の": "連体修飾", "と": "並列・相手", "を": "対象"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37536, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをやってみたことがあること。", "primary_collocate": null, "pronunciation": "けいけん", "ipa": "keːkeɴ", "syllable_count": 4, "sentences": [{"text": "外国で働いた経験が、今の仕事に役立っています。", "target_word": "経験", "complexity_tier": "T3", "furigana": "外国[がいこく]で働[はたら]いた経験[けいけん]が、今[いま]の仕事[しごと]に役立[やくだ]っています。", "sentence_source": "generated"}, {"text": "彼は経験が豊富なので、困ったときは相談します。", "target_word": "経験", "complexity_tier": "T3", "furigana": "彼[かれ]は経験[けいけん]が豊富[ほうふ]なので、困[こま]ったときは相談[そうだん]します。", "sentence_source": "generated"}, {"text": "一人で旅行をした経験は、私を強くしました。", "target_word": "経験", "complexity_tier": "T3", "furigana": "一人[ひとり]で旅行[りょこう]をした経験[けいけん]は、私[わたし]を強[つよ]くしました。", "sentence_source": "generated"}, {"text": "若いうちに、いろいろな経験をしておくといいですよ。", "target_word": "経験", "complexity_tier": "T3", "furigana": "若[わか]いうちに、いろいろな経験[けいけん]をしておくといいですよ。", "sentence_source": "generated"}, {"text": "料理の経験がないので、失敗してしまいました。", "target_word": "経験", "complexity_tier": "T3", "furigana": "料理[りょうり]の経験[けいけん]がないので、失敗[しっぱい]してしまいました。", "sentence_source": "generated"}, {"text": "苦しい経験があったから、人の気持ちがわかるようになりました。", "target_word": "経験", "complexity_tier": "T3", "furigana": "苦[くる]しい経験[けいけん]があったから、人[ひと]の気持[きも]ちがわかるようになりました。", "sentence_source": "generated"}, {"text": "この会社では、経験より、やる気を大切にします。", "target_word": "経験", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]では、経験[けいけん]より、やる気[き]を大切[たいせつ]にします。", "sentence_source": "generated"}, {"text": "初めての経験で、とても緊張しました。", "target_word": "経験", "complexity_tier": "T3", "furigana": "初[はじ]めての経験[けいけん]で、とても緊張[きんちょう]しました。", "sentence_source": "generated"}, {"text": "先生は、自分の経験をもとに話してくれました。", "target_word": "経験", "complexity_tier": "T3", "furigana": "先生[せんせい]は、自分[じぶん]の経験[けいけん]をもとに話[はな]してくれました。", "sentence_source": "generated"}, {"text": "運転の経験が少ない私は、雨の日は車に乗りません。", "target_word": "経験", "complexity_tier": "T3", "furigana": "運転[うんてん]の経験[けいけん]が少[すく]ない私[わたし]は、雨[あめ]の日[ひ]は車[くるま]に乗[の]りません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "経験", "label": "基本形"}, {"form": "経験する", "label": "動詞形"}, {"form": "経験した", "label": "過去形"}], "register": "標準", "sense_fingerprint": "実際にやってみたことがある事柄", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b906860-ce3e-49f4-97db-f10691e443cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37536, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "経験", "is_correct": true, "explanation": "「働いた経験」の経験。過去にしたことが今の仕事に役立つという文脈に合う。"}, {"text": "約束", "is_correct": false, "explanation": "約束は人と交わすもので、「働いた約束が役立つ」は文の論理が通らない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は働く対象にならず、「働いた天気が役立つ」は成り立たない。"}, {"text": "体重", "is_correct": false, "explanation": "体重は身体の重さで、仕事の役立ちと結びつかず、文脈に合わない。"}], "explanations": {"経験": "「働いた経験」の経験。過去にしたことが今の仕事に役立つという文脈に合う。", "約束": "約束は人と交わすもので、「働いた約束が役立つ」は文の論理が通らない。", "天気": "天気は働く対象にならず、「働いた天気が役立つ」は成り立たない。", "体重": "体重は身体の重さで、仕事の役立ちと結びつかず、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "経験"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "健康診断で、血液の経験をとった。", "explanation": "ここは〈検査〉（採血）の意味。血液を採るのは検査で、経験は採る対象にならないので合わない。"}, {"text": "図書館で、料理の経験を予約しました。", "explanation": "ここは〈本〉の意味。図書館で予約するのは本や資料で、経験は予約の対象にならないので合わない。"}, {"text": "寒さを感じる経験が鈍くなってきました。", "explanation": "ここは〈感覚〉の意味。寒さを感じ取る働きは感覚で、経験は鈍くなるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37536, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "経験", "is_correct": true, "explanation": "「会社では経験より、やる気を重視する」という対比に入る経験。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は連絡の手段で、「経験より」と比べる対象として文脈に合わない。"}, {"text": "地震", "is_correct": false, "explanation": "地震は自然現象で、会社の評価基準を比べる文脈に入らない。"}, {"text": "電話", "is_correct": false, "explanation": "電話は道具で、やる気と比べられる評価の対象にはならない。"}], "explanations": {"経験": "「会社では経験より、やる気を重視する」という対比に入る経験。", "手紙": "手紙は連絡の手段で、「経験より」と比べる対象として文脈に合わない。", "地震": "地震は自然現象で、会社の評価基準を比べる文脈に入らない。", "電話": "電話は道具で、やる気と比べられる評価の対象にはならない。"}, "sentence_index": 6, "correct_answer": "経験"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "英語を話す経験が高いです。", "explanation": "ここは〈能力〉の意味。高さで表すのは能力で、経験は「豊富」や「多い」で表す語なので合わない。"}, {"text": "アンケートの経験を実施した。", "explanation": "ここは〈調査〉の意味。アンケートを実施するのは調査で、経験は実施するものではないので合わない。"}, {"text": "怒りの経験を抑えました。", "explanation": "ここは〈感情〉の意味。抑えるのは感情で、経験は過去の出来事なので抑える対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37536, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その人は、海外での経験に生かして仕事をしている。", "corrected_sentence": "その人は、海外での経験を生かして仕事をしている。", "error_description": "「生かす」は他動詞で、生かすものを「を」で示す。「経験に」は誤りで、正しくは「経験を生かす」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
