INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37538, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かを思い通りに動かしたり、調整したりすること。", "primary_collocate": null, "pronunciation": "こんとろーる", "ipa": "kontoɾoːɾɯ", "syllable_count": 6, "sentences": [{"text": "温度をコントロールする。", "target_word": "コントロールする", "complexity_tier": "T2", "furigana": "温度[おんど]をコントロールする。", "sentence_source": "generated"}, {"text": "このボタンでコントロールします。", "target_word": "コントロールします", "complexity_tier": "T2", "furigana": "このボタンでコントロールします。", "sentence_source": "generated"}, {"text": "音量のコントロールが難しい。", "target_word": "コントロール", "complexity_tier": "T3", "furigana": "音量[おんりょう]のコントロールが難[むずか]しい。", "sentence_source": "generated"}, {"text": "機械をコントロールしている。", "target_word": "コントロールしている", "complexity_tier": "T3", "furigana": "機械[きかい]をコントロールしている。", "sentence_source": "generated"}, {"text": "リモコンでロボットをコントロールした。", "target_word": "コントロールした", "complexity_tier": "T3", "furigana": "リモコンでロボットをコントロールした。", "sentence_source": "generated"}, {"text": "水の量をコントロールできる装置です。", "target_word": "コントロールできる", "complexity_tier": "T3", "furigana": "水[みず]の量[りょう]をコントロールできる装置[そうち]です。", "sentence_source": "generated"}, {"text": "室内の湿度は、自動でコントロールされている。", "target_word": "コントロールされている", "complexity_tier": "T4", "furigana": "室内[しつない]の湿度[しつど]は、自動[じどう]でコントロールされている。", "sentence_source": "generated"}, {"text": "速度をコントロールしないと、車は曲がれない。", "target_word": "コントロールしない", "complexity_tier": "T4", "furigana": "速度[そくど]をコントロールしないと、車[くるま]は曲[ま]がれない。", "sentence_source": "generated"}, {"text": "この装置は、光の強さをコントロールするために作られた。", "target_word": "コントロールする", "complexity_tier": "T4", "furigana": "この装置[そうち]は、光[ひかり]の強[つよ]さをコントロールするために作[つく]られた。", "sentence_source": "generated"}, {"text": "ボールの動きを思い通りにコントロールするには、練習が必要だ。", "target_word": "コントロールする", "complexity_tier": "T4", "furigana": "ボールの動[うご]きを思[おも]い通[どお]りにコントロールするには、練習[れんしゅう]が必要[ひつよう]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "コントロールする", "label": "活用"}, {"form": "コントロールした", "label": "活用"}, {"form": "コントロールできる", "label": "活用"}, {"form": "コントロールされる", "label": "活用"}], "register": "plain", "sense_fingerprint": "名詞 | 物を思い通りに動かし調整すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T2: contains vocabulary far above tier T2: 曲がれ (Zipf 2.44)']::text[], '2f21d344-fdd8-4556-ab3d-6bddeaf03a3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37538, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "コントロールする", "is_correct": true, "explanation": "温度を調整するという意味が合う。"}, {"text": "食べる", "is_correct": false, "explanation": "形は合うが、温度を食べるという意味が合わない。"}, {"text": "歌う", "is_correct": false, "explanation": "形は合うが、温度を歌うという意味が合わない。"}, {"text": "祝う", "is_correct": false, "explanation": "形は合うが、温度を祝うという意味が合わない。"}], "explanations": {"コントロールする": "温度を調整するという意味が合う。", "食べる": "形は合うが、温度を食べるという意味が合わない。", "歌う": "形は合うが、温度を歌うという意味が合わない。", "祝う": "形は合うが、温度を祝うという意味が合わない。"}, "sentence_index": 0, "correct_answer": "コントロールする"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は毎晩、牛乳をコントロールしてから寝る。", "explanation": "「コントロールする」は「飲む」の意味では使えない。"}, {"text": "私は来月、友達の結婚式にコントロールする予定だ。", "explanation": "「コントロールする」は「出席する」の意味では使えない。"}, {"text": "母は台所で野菜をコントロールしている。", "explanation": "「コントロールする」は「切る」の意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
