INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37539, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「呼吸をコントロールした」で、操作する対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「呼吸がコントロールした」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「呼吸へコントロールした」は文として成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「呼吸からコントロールした」は対象の示し方として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「呼吸をコントロールした」で、操作する対象を示す。", "が": "「呼吸がコントロールした」は文として成り立たない。", "へ": "「呼吸へコントロールした」は文として成り立たない。", "から": "「呼吸からコントロールした」は対象の示し方として成り立たない。"}, "error_tags": {"が": "subject_marker", "へ": "direction", "から": "source"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37539, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事を自分の思い通りに操作したり、管理したりすること。", "primary_collocate": null, "pronunciation": "こんとろーる", "ipa": "kontoɾoːɾɯ", "syllable_count": 6, "sentences": [{"text": "イールドカーブ・コントロールの下では、市場メカニズムを通じた適正なリスクプレミアムの形成が阻害され、結果として財政の持続可能性を担保するべき債務の価格的シグナルが鈍磨する懸念が拭えない。", "target_word": "コントロール", "complexity_tier": "T6", "furigana": "イールドカーブ・コントロールの下[もと]では、市場[しじょう]メカニズムを通[つう]じた適正[てきせい]なリスクプレミアムの形成[けいせい]が阻害[そがい]され、結果[けっか]として財政[ざいせい]の持続[じぞく]可能性[かのうせい]を担保[たんぽ]するべき債務[さいむ]の価格的[かかくてき]シグナルが鈍磨[どんま]する懸念[けねん]が拭[ぬぐ]えない。", "sentence_source": "mined"}, {"text": "感情をコントロールする。", "target_word": "コントロールする", "complexity_tier": "T2", "furigana": "感情[かんじょう]をコントロールする。", "sentence_source": "generated"}, {"text": "コントロールが大切です。", "target_word": "コントロール", "complexity_tier": "T2", "furigana": "コントロールが大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "彼はボールのコントロールがうまい。", "target_word": "コントロール", "complexity_tier": "T3", "furigana": "彼[かれ]はボールのコントロールがうまい。", "sentence_source": "generated"}, {"text": "体重のコントロールを続けている。", "target_word": "コントロール", "complexity_tier": "T3", "furigana": "体重[たいじゅう]のコントロールを続[つづ]けている。", "sentence_source": "generated"}, {"text": "自分ではコントロールできない。", "target_word": "コントロールできない", "complexity_tier": "T3", "furigana": "自分[じぶん]ではコントロールできない。", "sentence_source": "generated"}, {"text": "怒りをコントロールできれば、仕事も楽になる。", "target_word": "コントロールできれば", "complexity_tier": "T4", "furigana": "怒[いか]りをコントロールできれば、仕事[しごと]も楽[らく]になる。", "sentence_source": "generated"}, {"text": "彼女は落ち着くために、呼吸をコントロールした。", "target_word": "コントロールした", "complexity_tier": "T4", "furigana": "彼女[かのじょ]は落[お]ち着[つ]くために、呼吸[こきゅう]をコントロールした。", "sentence_source": "generated"}, {"text": "感情のコントロールを学ぶことは大人にも必要だ。", "target_word": "コントロール", "complexity_tier": "T4", "furigana": "感情[かんじょう]のコントロールを学[まな]ぶことは大人[おとな]にも必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "外からコントロールされていると感じて、彼は不満だった。", "target_word": "コントロールされている", "complexity_tier": "T4", "furigana": "外[そと]からコントロールされていると感[かん]じて、彼[かれ]は不満[ふまん]だった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "コントロールする", "label": "活用"}, {"form": "コントロールした", "label": "活用"}, {"form": "コントロールできる", "label": "活用"}, {"form": "コントロールされる", "label": "活用"}], "register": "plain", "sense_fingerprint": "名詞 | 物事を思い通りに管理し操作すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f21d344-fdd8-4556-ab3d-6bddeaf03a3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37539, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "コントロール", "is_correct": true, "explanation": "金利や利回りを管理・操作する政策名として意味が合う。"}, {"text": "ダンス", "is_correct": false, "explanation": "形は合うが、イールドカーブのダンスという意味が合わない。"}, {"text": "ファッション", "is_correct": false, "explanation": "形は合うが、イールドカーブのファッションという意味が合わない。"}, {"text": "ランニング", "is_correct": false, "explanation": "形は合うが、イールドカーブのランニングという意味が合わない。"}], "explanations": {"コントロール": "金利や利回りを管理・操作する政策名として意味が合う。", "ダンス": "形は合うが、イールドカーブのダンスという意味が合わない。", "ファッション": "形は合うが、イールドカーブのファッションという意味が合わない。", "ランニング": "形は合うが、イールドカーブのランニングという意味が合わない。"}, "sentence_index": 0, "correct_answer": "コントロール"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は毎日コントロールを食べて、元気に学校へ行く。", "explanation": "「コントロール」は食べ物ではなく、食べるものとして使えない。"}, {"text": "昨日は雨だったので、公園へコントロールに行った。", "explanation": "「コントロール」は場所ではなく、行き先として使えない。"}, {"text": "このコントロールは三つの部屋があって、とても広い。", "explanation": "「コントロール」は建物ではなく、部屋があるものとして使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37539, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "コントロールできれば", "is_correct": true, "explanation": "怒りを抑えて管理できれば、という意味が文脈に合う。"}, {"text": "食べられれば", "is_correct": false, "explanation": "形は合うが、怒りを食べるという意味が合わない。"}, {"text": "洗えれば", "is_correct": false, "explanation": "形は合うが、怒りを洗うという意味が合わない。"}, {"text": "売れれば", "is_correct": false, "explanation": "形は合うが、怒りを売るという意味が合わない。"}], "explanations": {"コントロールできれば": "怒りを抑えて管理できれば、という意味が文脈に合う。", "食べられれば": "形は合うが、怒りを食べるという意味が合わない。", "洗えれば": "形は合うが、怒りを洗うという意味が合わない。", "売れれば": "形は合うが、怒りを売るという意味が合わない。"}, "sentence_index": 6, "correct_answer": "コントロールできれば"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "友達に花をコントロールされて、とてもうれしかった。", "explanation": "「コントロールされる」は「贈られる」の意味では使えない。"}, {"text": "今日は月がコントロールされていて、とても明るい。", "explanation": "「コントロールされる」は「出ている」の意味では使えない。"}, {"text": "昨日の夜は、星がたくさんコントロールされていて、きれいだった。", "explanation": "「コントロールされる」は「見える」の意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37539, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は自分の感情にコントロールできない。", "corrected_sentence": "彼は自分の感情をコントロールできない。", "error_description": "コントロールの対象を示す助詞は「に」ではなく「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
