INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37540, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「職場の近く」と場所の所属を表す「の」。職場に直接付く正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「職場を近くに」では目的語が意味をなさず、近さの関係が作れない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」では「近くに食堂がある」の関係が作れず不自然になる。"}, {"text": "で", "is_correct": false, "explanation": "動作の場所を示す「で」だと「職場で近くに」となり、続かない。"}], "correct_answer": "の", "explanations": {"の": "「職場の近く」と場所の所属を表す「の」。職場に直接付く正しい助詞。", "を": "「職場を近くに」では目的語が意味をなさず、近さの関係が作れない。", "へ": "方向を示す「へ」では「近くに食堂がある」の関係が作れず不自然になる。", "で": "動作の場所を示す「で」だと「職場で近くに」となり、続かない。"}, "error_tags": {"を": "目的語の「を」だが、近さの関係とは続かない", "へ": "方向を示すが、近くに食堂があるという関係は表せない", "で": "動作の場所を示すが、「近くに」と続かない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37540, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「職場を見学した」と動作の対象を表す「を」。職場に直接付く正しい助詞。"}, {"text": "に", "is_correct": false, "explanation": "「職場に見学した」と続かず、見学の対象を示せない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」では、職場が見学する主体になってしまい不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」では見学の対象を示せず、「職場より見学した」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「職場を見学した」と動作の対象を表す「を」。職場に直接付く正しい助詞。", "に": "「職場に見学した」と続かず、見学の対象を示せない。", "が": "主語を示す「が」では、職場が見学する主体になってしまい不自然。", "より": "比較の「より」では見学の対象を示せず、「職場より見学した」は意味が通らない。"}, "error_tags": {"に": "移動先や対象の「に」だが、見学の対象は示せない", "が": "主語を示すが、職場が見学する主体にはならない", "より": "比較の「より」で、見学の対象を示せない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37540, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "仕事をする場所のことです。", "primary_collocate": null, "pronunciation": "しょくば", "ipa": "ɕokɯba", "syllable_count": 3, "sentences": [{"text": "兄は駅前のビルにある職場まで、毎日電車で通っている。", "target_word": "職場", "complexity_tier": "T3", "furigana": "兄[あに]は駅前[えきまえ]のビルにある職場[しょくば]まで、毎日[まいにち]電車[でんしゃ]で通[かよ]っている。", "sentence_source": "generated"}, {"text": "職場の近くに安くておいしい食堂があるので、昼はいつもそこで食べる。", "target_word": "職場", "complexity_tier": "T3", "furigana": "職場[しょくば]の近[ちか]くに安[やす]くておいしい食堂[しょくどう]があるので、昼[ひる]はいつもそこで食[た]べる。", "sentence_source": "generated"}, {"text": "母の職場は小学校で、子どもたちに給食を作っている。", "target_word": "職場", "complexity_tier": "T3", "furigana": "母[はは]の職場[しょくば]は小学校[しょうがっこう]で、子[こ]どもたちに給食[きゅうしょく]を作[つく]っている。", "sentence_source": "generated"}, {"text": "雨が強かったため、職場に着いたときには靴までぬれていた。", "target_word": "職場", "complexity_tier": "T3", "furigana": "雨[あめ]が強[つよ]かったため、職場[しょくば]に着[つ]いたときには靴[くつ]までぬれていた。", "sentence_source": "generated"}, {"text": "職場の入り口で名札を受け取り、首にかけた。", "target_word": "職場", "complexity_tier": "T3", "furigana": "職場[しょくば]の入[い]り口[ぐち]で名札[なふだ]を受[う]け取[と]り、首[くび]にかけた。", "sentence_source": "generated"}, {"text": "引っ越しをして、職場まで歩いて行けるようになった。", "target_word": "職場", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しをして、職場[しょくば]まで歩[ある]いて行[い]けるようになった。", "sentence_source": "generated"}, {"text": "父は職場から電話をかけて、帰りが遅くなると伝えた。", "target_word": "職場", "complexity_tier": "T3", "furigana": "父[ちち]は職場[しょくば]から電話[でんわ]をかけて、帰[かえ]りが遅[おそ]くなると伝[つた]えた。", "sentence_source": "generated"}, {"text": "夏休みに、近所の工場へ行って職場を見学した。", "target_word": "職場", "complexity_tier": "T3", "furigana": "夏休[なつやす]みに、近所[きんじょ]の工場[こうじょう]へ行[い]って職場[しょくば]を見学[けんがく]した。", "sentence_source": "generated"}, {"text": "職場の屋上からは、町の花火がよく見える。", "target_word": "職場", "complexity_tier": "T3", "furigana": "職場[しょくば]の屋上[おくじょう]からは、町[まち]の花火[はなび]がよく見[み]える。", "sentence_source": "generated"}, {"text": "私の職場は、古い机と大きな窓がある小さな事務所だ。", "target_word": "職場", "complexity_tier": "T3", "furigana": "私[わたし]の職場[しょくば]は、古[ふる]い机[つくえ]と大[おお]きな窓[まど]がある小[ちい]さな事務所[じむしょ]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "職場", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "毎日仕事をしに行く具体的な場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a842f311-b815-4a39-bf38-8799be70a7cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37540, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "職場", "is_correct": true, "explanation": "「まで毎日電車で通っている」の行き先として、勤め先の職場が自然に入る。"}, {"text": "寝室", "is_correct": false, "explanation": "寝るための部屋で、毎日電車で通う行き先にはならない。"}, {"text": "浴室", "is_correct": false, "explanation": "入浴のための部屋で、電車で通う行き先として成り立たない。"}, {"text": "台所", "is_correct": false, "explanation": "料理をする場所で、毎日電車で通う対象にはならない。"}], "explanations": {"職場": "「まで毎日電車で通っている」の行き先として、勤め先の職場が自然に入る。", "寝室": "寝るための部屋で、毎日電車で通う行き先にはならない。", "浴室": "入浴のための部屋で、電車で通う行き先として成り立たない。", "台所": "料理をする場所で、毎日電車で通う対象にはならない。"}, "sentence_index": 0, "correct_answer": "職場"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今日の職場は一日中晴れだ。", "explanation": "ここは〈天気〉の意味。晴れは空模様を指すので、場所である職場の状態としては使えない。"}, {"text": "父は職場の株を大量に買った。", "explanation": "ここは〈会社〉の意味。株は会社（法人）が発行するもので、仕事をする場所である職場が株を持つ文としては合わない。"}, {"text": "職場を郵便で送った。", "explanation": "ここは〈手紙〉の意味。郵便で送れるのは手紙や荷物で、場所である職場は送れないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37540, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "職場", "is_correct": true, "explanation": "「職場から電話をかけて、帰りが遅くなると伝えた」の起点として、仕事中の場所を指す語が自然に入る。"}, {"text": "墓地", "is_correct": false, "explanation": "墓を並べた場所で、帰りが遅くなると伝える電話をかける場所としては不自然。"}, {"text": "病室", "is_correct": false, "explanation": "入院患者のいる部屋で、帰りが遅くなると会社から伝える文脈に合わない。"}, {"text": "寝台", "is_correct": false, "explanation": "寝るための台で、電話をかける場所としては成り立たない。"}], "explanations": {"職場": "「職場から電話をかけて、帰りが遅くなると伝えた」の起点として、仕事中の場所を指す語が自然に入る。", "墓地": "墓を並べた場所で、帰りが遅くなると伝える電話をかける場所としては不自然。", "病室": "入院患者のいる部屋で、帰りが遅くなると会社から伝える文脈に合わない。", "寝台": "寝るための台で、電話をかける場所としては成り立たない。"}, "sentence_index": 6, "correct_answer": "職場"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "職場を飲んで、早めに寝た。", "explanation": "ここは〈薬〉の意味。薬は飲むものだが、場所である職場は飲めないので合わない。"}, {"text": "この職場は三百ページある。", "explanation": "ここは〈本〉の意味。ページ数で数えるのは本や書類で、仕事をする場所の職場には使えないので合わない。"}, {"text": "この職場は毛並みがよく、人懐っこい。", "explanation": "ここは〈犬〉の意味。毛並みや人懐っこさは生き物の特徴で、職場には当てはまらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37540, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は職場を入ってから、すぐに着替えた。", "corrected_sentence": "彼は職場に入ってから、すぐに着替えた。", "error_description": "「入る」は到達点を表すので「に」が正しい。「を」にすると職場を通り抜けるような不自然な意味になり、誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37540, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父は工場へ行って職場に見学した。", "corrected_sentence": "祖父は工場へ行って職場を見学した。", "error_description": "「見学する」は対象を「を」で示す。「職場に」は対象を表せないので誤りで、「職場を見学した」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37541, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「職場の人間関係」と所属を表す「の」。職場に直接付く正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「職場を人間関係がよくない」となり、目的語として続かず文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「職場に人間関係がよくない」とは続かず、場所を表す「に」では意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」では人間関係の所属を表せず、文が不自然になる。"}], "correct_answer": "の", "explanations": {"の": "「職場の人間関係」と所属を表す「の」。職場に直接付く正しい助詞。", "を": "「職場を人間関係がよくない」となり、目的語として続かず文が成り立たない。", "に": "「職場に人間関係がよくない」とは続かず、場所を表す「に」では意味が通らない。", "へ": "方向を示す「へ」では人間関係の所属を表せず、文が不自然になる。"}, "error_tags": {"を": "目的語を示すが、人間関係との続きが成り立たない", "に": "場所・対象の「に」だが、ここでは続かない", "へ": "方向を示すが、人間関係の所属は表せない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
