INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37541, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "職業上の活動を行うための場所、または組織内の仕事環境を指します。", "primary_collocate": null, "pronunciation": "しょくば", "ipa": "ɕokɯba", "syllable_count": 3, "sentences": [{"text": "変化に適応し、自らの価値を高め続ける姿勢が、これからの職場では強く求められる。", "target_word": "職場", "complexity_tier": "T3", "furigana": "変化[へんか]に適応[てきおう]し、自[みずか]らの価値[かち]を高[たか]め続[つづ]ける姿勢[しせい]が、これからの職場[しょくば]では強[つよ]く求[もと]められる。", "sentence_source": "mined"}, {"text": "職場の人間関係がよくないと、毎日出勤するのがつらくなる。", "target_word": "職場", "complexity_tier": "T3", "furigana": "職場[しょくば]の人間関係[にんげんかんけい]がよくないと、毎日[まいにち]出勤[しゅっきん]するのがつらくなる。", "sentence_source": "generated"}, {"text": "新しい職場の雰囲気に慣れるまで、三か月ほどかかった。", "target_word": "職場", "complexity_tier": "T3", "furigana": "新[あたら]しい職場[しょくば]の雰囲気[ふんいき]に慣[な]れるまで、三[さん]か月[げつ]ほどかかった。", "sentence_source": "generated"}, {"text": "彼女は職場で後輩の相談に乗ることが多く、皆に頼られている。", "target_word": "職場", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は職場[しょくば]で後輩[こうはい]の相談[そうだん]に乗[の]ることが多[おお]く、皆[みな]に頼[たよ]られている。", "sentence_source": "generated"}, {"text": "この会社は、職場の環境を改善するために休憩室を広げた。", "target_word": "職場", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は、職場[しょくば]の環境[かんきょう]を改善[かいぜん]するために休憩室[きゅうけいしつ]を広[ひろ]げた。", "sentence_source": "generated"}, {"text": "職場での悩みを一人で抱え込まず、信頼できる上司に話すべきだ。", "target_word": "職場", "complexity_tier": "T3", "furigana": "職場[しょくば]での悩[なや]みを一人[ひとり]で抱[かか]え込[こ]まず、信頼[しんらい]できる上司[じょうし]に話[はな]すべきだ。", "sentence_source": "generated"}, {"text": "在宅勤務が増えても、職場に集まって話し合う価値は残っている。", "target_word": "職場", "complexity_tier": "T3", "furigana": "在宅勤務[ざいたくきんむ]が増[ふ]えても、職場[しょくば]に集[あつ]まって話[はな]し合[あ]う価値[かち]は残[のこ]っている。", "sentence_source": "generated"}, {"text": "職場の安全を守るため、全員が毎月の点検に参加する。", "target_word": "職場", "complexity_tier": "T3", "furigana": "職場[しょくば]の安全[あんぜん]を守[まも]るため、全員[ぜんいん]が毎月[まいつき]の点検[てんけん]に参加[さんか]する。", "sentence_source": "generated"}, {"text": "前の職場では残業が多かったが、今の職場はほとんど定時で帰れる。", "target_word": "職場", "complexity_tier": "T3", "furigana": "前[まえ]の職場[しょくば]では残業[ざんぎょう]が多[おお]かったが、今[いま]の職場[しょくば]はほとんど定時[ていじ]で帰[かえ]れる。", "sentence_source": "generated"}, {"text": "職場の雰囲気が明るいと、仕事の効率も自然に上がっていく。", "target_word": "職場", "complexity_tier": "T3", "furigana": "職場[しょくば]の雰囲気[ふんいき]が明[あか]るいと、仕事[しごと]の効率[こうりつ]も自然[しぜん]に上[あ]がっていく。", "sentence_source": "generated"}], "morphological_forms": [{"form": "職場", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "組織の中での仕事環境・人間関係の場", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T2: contains vocabulary far above tier T2: 抱え込ま (Zipf 2.29)']::text[], 'a842f311-b815-4a39-bf38-8799be70a7cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37541, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "職場", "is_correct": true, "explanation": "「これからの〜で強く求められる」に入る、仕事をする組織の環境を指す語として自然に当てはまる。"}, {"text": "寝室", "is_correct": false, "explanation": "寝るための部屋で、仕事の環境を表さない。「これからの寝室では強く求められる」は文脈に合わない。"}, {"text": "浴室", "is_correct": false, "explanation": "入浴のための部屋で、価値観や姿勢が求められる場にはならない。"}, {"text": "台所", "is_correct": false, "explanation": "料理をする場所で、仕事の環境を指さないため文が成り立たない。"}], "explanations": {"職場": "「これからの〜で強く求められる」に入る、仕事をする組織の環境を指す語として自然に当てはまる。", "寝室": "寝るための部屋で、仕事の環境を表さない。「これからの寝室では強く求められる」は文脈に合わない。", "浴室": "入浴のための部屋で、価値観や姿勢が求められる場にはならない。", "台所": "料理をする場所で、仕事の環境を指さないため文が成り立たない。"}, "sentence_index": 0, "correct_answer": "職場"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の職場は医師だ。", "explanation": "ここは〈職業〉の意味。職業は仕事の種類を指すので、仕事をする環境の職場とは置き換えられない。"}, {"text": "彼は職場の株を大量に買い増した。", "explanation": "ここは〈会社〉の意味。株は会社（法人）が発行するもので、仕事の環境である職場は株を持てないので合わない。"}, {"text": "彼は職場を達成するため、毎日練習を続けた。", "explanation": "ここは〈目標〉の意味。達成するのは目標などの目的で、職場（仕事の環境）は達成の対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37541, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "職場", "is_correct": true, "explanation": "「職場に集まって話し合う」と場所を表し、在宅勤務と対比される語として自然に入る。"}, {"text": "排水溝", "is_correct": false, "explanation": "水を流す設備で、人が集まって話し合う場所ではないため文が成り立たない。"}, {"text": "下水道", "is_correct": false, "explanation": "地下の排水施設で、話し合いの場にはならず不自然。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "食品を冷やす家電で、人が集まって話し合う場所にはならない。"}], "explanations": {"職場": "「職場に集まって話し合う」と場所を表し、在宅勤務と対比される語として自然に入る。", "排水溝": "水を流す設備で、人が集まって話し合う場所ではないため文が成り立たない。", "下水道": "地下の排水施設で、話し合いの場にはならず不自然。", "冷蔵庫": "食品を冷やす家電で、人が集まって話し合う場所にはならない。"}, "sentence_index": 6, "correct_answer": "職場"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "職場が赤になったので、車が止まった。", "explanation": "ここは〈信号〉の意味。信号は色が変わるが、仕事をする場所の職場は色を持たないので合わない。"}, {"text": "職場は後半に入り、選手たちの動きが激しくなった。", "explanation": "ここは〈試合〉の意味。試合には前半・後半と選手がいるが、職場にはそのような区切りや選手は存在しないので合わない。"}, {"text": "私の職場は読書だ。", "explanation": "ここは〈趣味〉の意味。趣味は好きな活動を指すので、場所である職場を趣味と言い換えることはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37541, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい職場が人間関係に慣れるまで、一か月ほどかかった。", "corrected_sentence": "新しい職場の人間関係に慣れるまで、一か月ほどかかった。", "error_description": "「職場」と「人間関係」をつなぐ助詞は「の」（職場の人間関係）。「が」にすると職場自体が慣れる主語になり、不自然で誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37541, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "仕事を終えて、職場を飲んだ。", "corrected_sentence": "仕事を終えて、職場を後にした。", "error_description": "「職場」に続く動詞は「後にする」「離れる」などで、「飲む」は飲み物に使うので職場とは結びつかない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37542, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「持つ」の対象を示す「を」です。"}, {"text": "に", "is_correct": false, "explanation": "「資産に持っている」は対象を示せず不適切です。"}, {"text": "と", "is_correct": false, "explanation": "「資産と持っている」は意味が成り立ちません。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「資産へ持っている」は不適切です。"}], "correct_answer": "を", "explanations": {"を": "「持つ」の対象を示す「を」です。", "に": "「資産に持っている」は対象を示せず不適切です。", "と": "「資産と持っている」は意味が成り立ちません。", "へ": "「へ」は方向を表すので、「資産へ持っている」は不適切です。"}, "error_tags": {"に": "target", "と": "accompaniment", "へ": "direction"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37542, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「資産の一部」と全体と部分を結ぶ「の」です。"}, {"text": "を", "is_correct": false, "explanation": "「資産を一部を」は「を」が重なり不適切です。"}, {"text": "に", "is_correct": false, "explanation": "「資産に一部を」は名詞をつなげず不適切です。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「資産へ一部を」は不適切です。"}], "correct_answer": "の", "explanations": {"の": "「資産の一部」と全体と部分を結ぶ「の」です。", "を": "「資産を一部を」は「を」が重なり不適切です。", "に": "「資産に一部を」は名詞をつなげず不適切です。", "へ": "「へ」は方向を表すので、「資産へ一部を」は不適切です。"}, "error_tags": {"を": "object", "に": "target", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37542, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "「資産」は、お金や物のように、あとで役に立つもののことです。", "primary_collocate": null, "pronunciation": "しさん", "ipa": "ɕisaɴ", "syllable_count": 3, "sentences": [{"text": "資産がある。", "target_word": "資産", "complexity_tier": "T1", "furigana": "資産[しさん]がある。", "sentence_source": "generated"}, {"text": "大きな資産です。", "target_word": "資産", "complexity_tier": "T2", "furigana": "大[おお]きな資産[しさん]です。", "sentence_source": "generated"}, {"text": "土地は資産です。", "target_word": "資産", "complexity_tier": "T2", "furigana": "土地[とち]は資産[しさん]です。", "sentence_source": "generated"}, {"text": "父は資産を持っている。", "target_word": "資産", "complexity_tier": "T3", "furigana": "父[ちち]は資産[しさん]を持[も]っている。", "sentence_source": "generated"}, {"text": "この家は私たちの大事な資産だ。", "target_word": "資産", "complexity_tier": "T3", "furigana": "この家[いえ]は私[わたし]たちの大事[だいじ]な資産[しさん]だ。", "sentence_source": "generated"}, {"text": "資産を守るために、銀行にお金を預けた。", "target_word": "資産", "complexity_tier": "T3", "furigana": "資産[しさん]を守[まも]るために、銀行[ぎんこう]にお金[かね]を預[あず]けた。", "sentence_source": "generated"}, {"text": "古い絵が高く売れて、彼の資産は増えた。", "target_word": "資産", "complexity_tier": "T3", "furigana": "古[ふる]い絵[え]が高[たか]く売[う]れて、彼[かれ]の資産[しさん]は増[ふ]えた。", "sentence_source": "generated"}, {"text": "資産の一部を、学校のために使うことにした。", "target_word": "資産", "complexity_tier": "T4", "furigana": "資産[しさん]の一部[いちぶ]を、学校[がっこう]のために使[つか]うことにした。", "sentence_source": "generated"}, {"text": "祖父が残した資産で、孫たちは大学に通えた。", "target_word": "資産", "complexity_tier": "T4", "furigana": "祖父[そふ]が残[のこ]した資産[しさん]で、孫[まご]たちは大学[だいがく]に通[かよ]えた。", "sentence_source": "generated"}, {"text": "使わない資産をそのままにするのはもったいないと思う。", "target_word": "資産", "complexity_tier": "T4", "furigana": "使[つか]わない資産[しさん]をそのままにするのはもったいないと思[おも]う。", "sentence_source": "generated"}], "morphological_forms": [{"form": "資産家", "label": "派