INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37542, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "資産", "is_correct": true, "explanation": "見出し語そのものです。"}, {"text": "持参", "is_correct": false, "explanation": "「じさん」で、「し」が「じ」に変わった別の語です。"}, {"text": "師団", "is_correct": false, "explanation": "「しだん」で、「さ」が「だ」に変わった別の語です。"}, {"text": "士官", "is_correct": false, "explanation": "「しかん」で、「さ」が「か」に変わった別の語です。"}, {"text": "指南", "is_correct": false, "explanation": "「しなん」で、「さ」が「な」に変わった別の語です。"}, {"text": "視察", "is_correct": false, "explanation": "「しさつ」で、語末の「ん」が「つ」に変わった別の語です。"}], "explanations": {"資産": "見出し語そのものです。", "持参": "「じさん」で、「し」が「じ」に変わった別の語です。", "師団": "「しだん」で、「さ」が「だ」に変わった別の語です。", "士官": "「しかん」で、「さ」が「か」に変わった別の語です。", "指南": "「しなん」で、「さ」が「な」に変わった別の語です。", "視察": "「しさつ」で、語末の「ん」が「つ」に変わった別の語です。"}, "sentence_index": null, "correct_answer": "資産"}, "level_3": {"options": [{"text": "資産", "is_correct": true, "explanation": "お金や物を持っているという意味で「ある」に合います。"}, {"text": "昨日", "is_correct": false, "explanation": "形は合うが、「昨日がある」では意味が合わない。"}, {"text": "左", "is_correct": false, "explanation": "形は合うが、「左がある」では意味が合わない。"}, {"text": "午前", "is_correct": false, "explanation": "形は合うが、「午前がある」では意味が合わない。"}], "explanations": {"資産": "お金や物を持っているという意味で「ある」に合います。", "昨日": "形は合うが、「昨日がある」では意味が合わない。", "左": "形は合うが、「左がある」では意味が合わない。", "午前": "形は合うが、「午前がある」では意味が合わない。"}, "sentence_index": 0, "correct_answer": "資産"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "資産に水を入れて、お茶をいれた。", "explanation": "資産は水を入れる容器ではないので誤りです。"}, {"text": "資産が走って、駅に行った。", "explanation": "資産は走る主体ではないので誤りです。"}, {"text": "この資産はとても甘くておいしい。", "explanation": "資産は味のある食べ物ではないので誤りです。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_vers