たいせつ]にしてきた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "資産家", "label": "派生"}, {"form": "資産価値", "label": "派生"}, {"form": "資産運用", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 将来の価値を生む財産や無形のもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f21d344-fdd8-4556-ab3d-6bddeaf03a3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37543, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "資産", "is_correct": true, "explanation": "見出し語そのものです。"}, {"text": "持参", "is_correct": false, "explanation": "「じさん」で、「し」が「じ」に変わった別の語です。"}, {"text": "師団", "is_correct": false, "explanation": "「しだん」で、「さ」が「だ」に変わった別の語です。"}, {"text": "士官", "is_correct": false, "explanation": "「しかん」で、「さ」が「か」に変わった別の語です。"}, {"text": "指南", "is_correct": false, "explanation": "「しなん」で、「さ」が「な」に変わった別の語です。"}, {"text": "視察", "is_correct": false, "explanation": "「しさつ」で、語末の「ん」が「つ」に変わった別の語です。"}], "explanations": {"資産": "見出し語そのものです。", "持参": "「じさん」で、「し」が「じ」に変わった別の語です。", "師団": "「しだん」で、「さ」が「だ」に変わった別の語です。", "士官": "「しかん」で、「さ」が「か」に変わった別の語です。", "指南": "「しなん」で、「さ」が「な」に変わった別の語です。", "視察": "「しさつ」で、語末の「ん」が「つ」に変わった別の語です。"}, "sentence_index": null, "correct_answer": "資産"}, "level_3": {"options": [{"text": "資産", "is_correct": true, "explanation": "健康が将来にも役立つ大切なものだという意味に合います。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、「健康は何よりの天気だ」では意味が合わない。"}, {"text": "机", "is_correct": false, "explanation": "形は合うが、「健康は何よりの机だ」では意味が合わない。"}, {"text": "宿題", "is_correct": false, "explanation": "形は合うが、「健康は何よりの宿題だ」では意味が合わない。"}], "explanations": {"資産": "健康が将来にも役立つ大切なものだという意味に合います。", "天気": "形は合うが、「健康は何よりの天気だ」では意味が合わない。", "机": "形は合うが、「健康は何よりの机だ」では意味が合わない。", "宿題": "形は合うが、「健康は何よりの宿題だ」では意味が合わない。"}, "sentence_index": 0, "correct_answer": "資産"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "資産を飲んで、のどのかわきをいやした。", "explanation": "資産は飲み物ではないので、意味の使い方が誤りです。"}, {"text": "彼は資産が高くて、天井に頭をぶつけた。", "explanation": "資産は身長を表す語ではないので、使い方が誤りです。"}, {"text": "私の資産は毎朝六時に起きる。", "explanation": "資産は人のように起きる主体ではないので誤りです。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37543, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "資産", "is_correct": true, "explanation": "見出し語そのものです。"}, {"text": "悲惨", "is_correct": false, "explanation": "「ひさん」で、「し」が「ひ」に変わった別の語です。"}, {"text": "子細", "is_correct": false, "explanation": "「しさい」で、語末の「ん」が「い」に変わった別の語です。"}, {"text": "指針", "is_correct": false, "explanation": "「ししん」で、「さ」が「し」に変わった別の語です。"}, {"text": "施策", "is_correct": false, "explanation": "「しさく」で、語末の「ん」が「く」に変わった別の語です。"}], "explanations": {"資産": "見出し語そのものです。", "悲惨": "「ひさん」で、「し」が「ひ」に変わった別の語です。", "子細": "「しさい」で、語末の「ん」が「い」に変わった別の語です。", "指針": "「ししん」で、「さ」が「し」に変わった別の語です。", "施策": "「しさく」で、語末の「ん」が「く」に変わった別の語です。"}, "sentence_index": null, "correct_answer": "資産"}, "level_3": {"options": [{"text": "資産", "is_correct": true, "explanation": "若い時の経験が一生の財産になるという意味に合います。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、経験が一生の天気になるのは意味が合わない。"}, {"text": "机", "is_correct": false, "explanation": "形は合うが、経験が机になるのは意味が合わない。"}, {"text": "昼食", "is_correct": false, "explanation": "形は合うが、経験が一生の昼食になるのは意味が合わない。"}], "explanations": {"資産": "若い時の経験が一生の財産になるという意味に合います。", "天気": "形は合うが、経験が一生の天気になるのは意味が合わない。", "机": "形は合うが、経験が机になるのは意味が合わない。", "昼食": "形は合うが、経験が一生の昼食になるのは意味が合わない。"}, "sentence_index": 6, "correct_answer": "資産"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "資産が降って、道がぬれた。", "explanation": "資産は雨のように降る物ではないので誤りです。"}, {"text": "彼は資産を着て、会社へ出かけた。", "explanation": "資産は着る物ではないので誤りです。"}, {"text": "資産が鳴いて、朝早く目が覚めた。", "explanation": "資産は鳴く生き物ではないので誤りです。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37543, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は多くの資産に持っている。", "corrected_sentence": "彼は多くの資産を持っている。", "error_description": "「持つ」の対象を示す助詞は「に」ではなく「を」です。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37543, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "親から資産が受け継ぐ人もいる。", "corrected_sentence": "親から資産を受け継ぐ人もいる。", "error_description": "受け継ぐのは人で、資産はその対象なので、「が」ではなく「を」を使います。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13322750-3a4e-4704-999d-63599f3d62c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
