INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37544, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "自分で見たり聞いたりして、知ったり感じたりすること。", "primary_collocate": null, "pronunciation": "たいけん", "ipa": "taikeɴ", "syllable_count": 4, "sentences": [{"text": "週末に、陶芸教室で粘土を使った体験をした。", "target_word": "体験", "complexity_tier": "T3", "furigana": "週末[しゅうまつ]に、陶芸[とうげい]教室[きょうしつ]で粘土[ねんど]を使[つか]った体験[たいけん]をした。", "sentence_source": "generated"}, {"text": "子どもたちは、牧場で牛の乳しぼりを体験した。", "target_word": "体験", "complexity_tier": "T3", "furigana": "子[こ]どもたちは、牧場[ぼくじょう]で牛[うし]の乳[ちち]しぼりを体験[たいけん]した。", "sentence_source": "generated"}, {"text": "この博物館では、昔の暮らしを体験できる。", "target_word": "体験", "complexity_tier": "T3", "furigana": "この博物館[はくぶつかん]では、昔[むかし]の暮[く]らしを体験[たいけん]できる。", "sentence_source": "generated"}, {"text": "自分の目で見た体験は、本で読んだ知識より強く心に残る。", "target_word": "体験", "complexity_tier": "T3", "furigana": "自分[じぶん]の目[め]で見[み]た体験[たいけん]は、本[ほん]で読[よ]んだ知識[ちしき]より強[つよ]く心[こころ]に残[のこ]る。", "sentence_source": "generated"}, {"text": "初めてオーロラを見た体験を、今でもはっきり覚えている。", "target_word": "体験", "complexity_tier": "T3", "furigana": "初[はじ]めてオーロラを見[み]た体験[たいけん]を、今[いま]でもはっきり覚[おぼ]えている。", "sentence_source": "generated"}, {"text": "留学生は、日本の夏祭りを体験して、とても喜んでいた。", "target_word": "体験", "complexity_tier": "T3", "furigana": "留学生[りゅうがくせい]は、日本[にほん]の夏祭[なつまつ]りを体験[たいけん]して、とても喜[よろこ]んでいた。", "sentence_source": "generated"}, {"text": "無料で参加できる体験の時間が、午前と午後に一回ずつある。", "target_word": "体験", "complexity_tier": "T3", "furigana": "無料[むりょう]で参加[さんか]できる体験[たいけん]の時間[じかん]が、午前[ごぜん]と午後[ごご]に一回[いっかい]ずつある。", "sentence_source": "generated"}, {"text": "実際に雪の中を歩く体験をして、寒さの厳しさを知った。", "target_word": "体験", "complexity_tier": "T3", "furigana": "実際[じっさい]に雪[ゆき]の中[なか]を歩[ある]く体験[たいけん]をして、寒[さむ]さの厳[きび]しさを知[し]った。", "sentence_source": "generated"}, {"text": "友人の話を聞くだけでなく、自分でも体験してみたい。", "target_word": "体験", "complexity_tier": "T3", "furigana": "友人[ゆうじん]の話[はなし]を聞[き]くだけでなく、自分[じぶん]でも体験[たいけん]してみたい。", "sentence_source": "generated"}, {"text": "初めての船旅は、新鮮な体験の連続だった。", "target_word": "体験", "complexity_tier": "T3", "furigana": "初[はじ]めての船旅[ふなたび]は、新鮮[しんせん]な体験[たいけん]の連続[れんぞく]だった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "体験", "label": "基本形"}, {"form": "体験する", "label": "辞書形"}, {"form": "体験した", "label": "過去形"}, {"form": "体験できる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "自分で見聞きして直接知り、感じること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e79adc-4d42-49ba-a89a-201c237b3d59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37544, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体験", "is_correct": true, "explanation": "「粘土を使った体験」は実際に自分でやってみた経験の意味で合う。"}, {"text": "体重", "is_correct": false, "explanation": "体重は身体の重さを表すので、作業の経験には合わない。"}, {"text": "体温", "is_correct": false, "explanation": "体温は体の温度を指し、粘土作業の話には入らない。"}, {"text": "体制", "is_correct": false, "explanation": "体制は組織や仕組みの意味で、ここでは意味が合わない。"}], "explanations": {"体験": "「粘土を使った体験」は実際に自分でやってみた経験の意味で合う。", "体重": "体重は身体の重さを表すので、作業の経験には合わない。", "体温": "体温は体の温度を指し、粘土作業の話には入らない。", "体制": "体制は組織や仕組みの意味で、ここでは意味が合わない。"}, "sentence_index": 0, "correct_answer": "体験"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寒さで手の体験が鈍くなった。", "explanation": "ここは〈感覚〉の意味。手の感覚が鈍くなるとは言うが、体験が鈍くなるとは言わない。"}, {"text": "久しぶりに故郷の駅に立ち、体験にふけった。", "explanation": "ここは〈感慨〉の意味。感慨にふけるとは言うが、体験にふけるとは言わない。"}, {"text": "この夏は体験温度が高く、外を歩くとつらい。", "explanation": "ここは〈体感〉の意味。体感温度とは言うが、体験温度とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37544, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体験", "is_correct": true, "explanation": "「参加できる体験の時間」は催しに参加して経験する意味で合う。"}, {"text": "体質", "is_correct": false, "explanation": "体質は生まれつきの体の性質で、時間の説明には入らない。"}, {"text": "体系", "is_correct": false, "explanation": "体系は組織だった仕組みを指し、ここでは意味が合わない。"}, {"text": "体型", "is_correct": false, "explanation": "体型は体つきを指すので、催しの時間の話とは結びつかない。"}], "explanations": {"体験": "「参加できる体験の時間」は催しに参加して経験する意味で合う。", "体質": "体質は生まれつきの体の性質で、時間の説明には入らない。", "体系": "体系は組織だった仕組みを指し、ここでは意味が合わない。", "体型": "体型は体つきを指すので、催しの時間の話とは結びつかない。"}, "sentence_index": 6, "correct_answer": "体験"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "熱で体験が上がって、寝込んでしまった。", "explanation": "ここは〈体温〉の意味。体温が上がるとは言うが、体験が上がるとは言わない。"}, {"text": "森の中で体験を研ぎ澄ませて、鳥の声を聞いた。", "explanation": "ここは〈五感〉の意味。五感を研ぎ澄ますとは言うが、体験を研ぎ澄ますとは言わない。"}, {"text": "彼は鋭い体験眼で、小さな変化にも気づく。", "explanation": "ここは〈観察眼〉の意味。観察眼を持つとは言うが、体験眼とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37544, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は夏休みに、祖父の畑で野菜作りに体験した。", "corrected_sentence": "私は夏休みに、祖父の畑で野菜作りを体験した。", "error_description": "体験の対象は「を」で示す。「に」は誤りで、正しくは「野菜作りを体験した」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37544, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この施設では、宇宙食を体験られる。", "corrected_sentence": "この施設では、宇宙食を体験できる。", "error_description": "体験は「する」を付けるサ変動詞なので、可能の形は「体験できる」。「体験られる」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
