INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37545, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "実際に自分が経験すること。また、その経験によって得られた知識や感じ方。", "primary_collocate": null, "pronunciation": "たいけん", "ipa": "taikeɴ", "syllable_count": 4, "sentences": [{"text": "この祭りでは、地域の伝統料理を体験できる。", "target_word": "体験", "complexity_tier": "T3", "furigana": "この祭[まつ]りでは、地域[ちいき]の伝統[でんとう]料理[りょうり]を体験[たいけん]できる。", "sentence_source": "generated"}, {"text": "初めての海外生活は、私にとって貴重な体験だった。", "target_word": "体験", "complexity_tier": "T3", "furigana": "初[はじ]めての海外[かいがい]生活[せいかつ]は、私[わたし]にとって貴重[きちょう]な体験[たいけん]だった。", "sentence_source": "generated"}, {"text": "彼は災害の体験を、子どもたちに語り続けている。", "target_word": "体験", "complexity_tier": "T3", "furigana": "彼[かれ]は災害[さいがい]の体験[たいけん]を、子[こ]どもたちに語[かた]り続[つづ]けている。", "sentence_source": "generated"}, {"text": "実際に体験しなければ、この仕事の大変さは分からない。", "target_word": "体験", "complexity_tier": "T3", "furigana": "実際[じっさい]に体験[たいけん]しなければ、この仕事[しごと]の大変[たいへん]さは分[わ]からない。", "sentence_source": "generated"}, {"text": "農家での体験を通じて、食べ物への感謝が深まった。", "target_word": "体験", "complexity_tier": "T3", "furigana": "農家[のうか]での体験[たいけん]を通[つう]じて、食[た]べ物[もの]への感謝[かんしゃ]が深[ふか]まった。", "sentence_source": "generated"}, {"text": "彼女は苦い体験から、人を簡単に信じなくなった。", "target_word": "体験", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は苦[にが]い体験[たいけん]から、人[ひと]を簡単[かんたん]に信[しん]じなくなった。", "sentence_source": "generated"}, {"text": "先生は自分の体験をもとに、失敗の大切さを話した。", "target_word": "体験", "complexity_tier": "T3", "furigana": "先生[せんせい]は自分[じぶん]の体験[たいけん]をもとに、失敗[しっぱい]の大切[たいせつ]さを話[はな]した。", "sentence_source": "generated"}, {"text": "小学生のとき、田植えを体験して、米作りの苦労を知った。", "target_word": "体験", "complexity_tier": "T3", "furigana": "小学生[しょうがくせい]のとき、田植[たう]えを体験[たいけん]して、米作[こめづく]りの苦労[くろう]を知[し]った。", "sentence_source": "generated"}, {"text": "若いうちに、いろいろな体験を積んでおくほうがいい。", "target_word": "体験", "complexity_tier": "T3", "furigana": "若[わか]いうちに、いろいろな体験[たいけん]を積[つ]んでおくほうがいい。", "sentence_source": "generated"}, {"text": "彼にとって、戦争の体験は一生忘れられない記憶だ。", "target_word": "体験", "complexity_tier": "T3", "furigana": "彼[かれ]にとって、戦争[せんそう]の体験[たいけん]は一生[いっしょう]忘[わす]れられない記憶[きおく]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "体験", "label": "基本形"}, {"form": "体験する", "label": "辞書形"}, {"form": "体験した", "label": "過去形"}, {"form": "体験しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "自分が実際に経験すること、またその経験から得た知識や感じ方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e79adc-4d42-49ba-a89a-201c237b3d59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37545, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体験", "is_correct": true, "explanation": "「豊かな食体験」は食べることを実際に経験する意味で、体験が入る。"}, {"text": "体重", "is_correct": false, "explanation": "体重は身体の重さを表すので、食べることの経験の文脈には合わない。"}, {"text": "体温", "is_correct": false, "explanation": "体温は体の温度を指し、食の経験の話には入らない。"}, {"text": "体制", "is_correct": false, "explanation": "体制は組織や仕組みの意味で、食文化の経験には当てはまらない。"}], "explanations": {"体験": "「豊かな食体験」は食べることを実際に経験する意味で、体験が入る。", "体重": "体重は身体の重さを表すので、食べることの経験の文脈には合わない。", "体温": "体温は体の温度を指し、食の経験の話には入らない。", "体制": "体制は組織や仕組みの意味で、食文化の経験には当てはまらない。"}, "sentence_index": 0, "correct_answer": "体験"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この夏は体験温度がとても高く、外を歩くとつらい。", "explanation": "ここは〈体感〉（体で感じる暑さ）の意味。体感温度とは言うが、体験温度とは言わない。"}, {"text": "風邪で体験が落ちて、階段を上るのもつらい。", "explanation": "ここは〈体力〉の意味。体力が落ちるとは言うが、体験は実際に経験することなので落ちるものではない。"}, {"text": "子どもが生まれて、親になった体験がわいた。", "explanation": "ここは〈実感〉の意味。実感がわくとは言うが、体験はわくものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37545, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体験", "is_correct": true, "explanation": "「自分の体験をもとに」は自分が実際にした経験の意味で合う。"}, {"text": "体質", "is_correct": false, "explanation": "体質は生まれつきの体の性質で、話の根拠となる経験には入らない。"}, {"text": "体系", "is_correct": false, "explanation": "体系は組織だった仕組みを指し、ここでは意味が合わない。"}, {"text": "体型", "is_correct": false, "explanation": "体型は体つきを指すので、失敗の大切さを話す根拠とは結びつかない。"}], "explanations": {"体験": "「自分の体験をもとに」は自分が実際にした経験の意味で合う。", "体質": "体質は生まれつきの体の性質で、話の根拠となる経験には入らない。", "体系": "体系は組織だった仕組みを指し、ここでは意味が合わない。", "体型": "体型は体つきを指すので、失敗の大切さを話す根拠とは結びつかない。"}, "sentence_index": 6, "correct_answer": "体験"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寝不足で体験が崩れて、仕事を休んだ。", "explanation": "ここは〈体調〉の意味。体調が崩れるとは言うが、体験は崩れるものではない。"}, {"text": "彼は体験ががっしりしていて、力仕事に向いている。", "explanation": "ここは〈体格〉の意味。体格がしっかりしていると言うが、体験の様子には使わない。"}, {"text": "毎朝歩いて、体験を保っている。", "explanation": "ここは〈健康〉の意味。健康を保つとは言うが、体験は保つものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37545, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "田舎で農作業を体験に、食べ物の大切さを知った。", "corrected_sentence": "田舎で農作業を体験して、食べ物の大切さを知った。", "error_description": "体験は「体験する」のサ変名詞なので、動詞の形で続ける。「体験に」は誤りで、正しくは「体験して」（て形で「知った」に続く）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37545, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この村では、昔の生活を体験られる。", "corrected_sentence": "この村では、昔の生活を体験できる。", "error_description": "体験は「する」を付けるサ変動詞なので、可能の形は「体験できる」。「体験られる」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37546, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "架空", "is_correct": true, "explanation": "想像で作られ、実際には存在しないこと。「実在」の対義語として辞書に載る。"}, {"text": "真実", "is_correct": false, "explanation": "本当のこと。「実在」と近い意味で、反対語ではない。"}, {"text": "現実", "is_correct": false, "explanation": "今ある状況。反対語ではない。"}, {"text": "本物", "is_correct": false, "explanation": "偽物ではないもの。反対語ではない。"}], "correct_answer": "架空", "explanations": {"架空": "想像で作られ、実際には存在しないこと。「実在」の対義語として辞書に載る。", "真実": "本当のこと。「実在」と近い意味で、反対語ではない。", "現実": "今ある状況。反対語ではない。", "本物": "偽物ではないもの。反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37546, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「実在の人物」で、実在を人物の修飾に変える助詞。"}, {"text": "に", "is_correct": false, "explanation": "「実在に人物」は名詞を修飾できず、「に」は相手や時点を示すので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「実在で人物」は手段や場所を示すので、名詞の修飾にならない。"}, {"text": "から", "is_correct": false, "explanation": "「実在から人物」は起点を示すため、名詞を修飾できない。"}], "correct_answer": "の", "explanations": {"の": "「実在の人物」で、実在を人物の修飾に変える助詞。", "に": "「実在に人物」は名詞を修飾できず、「に」は相手や時点を示すので合わない。", "で": "「実在で人物」は手段や場所を示すので、名詞の修飾にならない。", "から": "「実在から人物」は起点を示すため、名詞を修飾できない。"}, "error_tags": {"に": "相手・時点", "で": "場所・手段", "から": "起点"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "架空", "is_correct": true, "explanation": "想像で作られ、実際には存在しないこと。「実在」の対義語として辞書に載る。"}, {"text": "事実", "is_correct": false, "explanation": "本当に起きたこと。反対語ではない。"}, {"text": "存在", "is_correct": false, "explanation": "そこにあること。近い意味で、反対語ではない。"}, {"text": "真相", "is_correct": false, "explanation": "隠れていた本当の事情。反対語ではない。"}], "correct_answer": "架空", "explanations": {"架空": "想像で作られ、実際には存在しないこと。「実在」の対義語として辞書に載る。", "事実": "本当に起きたこと。反対語ではない。", "存在": "そこにあること。近い意味で、反対語ではない。", "真相": "隠れていた本当の事情。反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37546, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "本当にあって、うそではないこと。", "primary_collocate": null, "pronunciation": "じつざい", "ipa": "dʑitsɯzai", "syllable_count": 4, "sentences": [{"text": "この物語の主人公は、実在した人です。", "target_word": "実在", "complexity_tier": "T3", "furigana": "この物語[ものがたり]の主人公[しゅじんこう]は、実在[じつざい]した人[ひと]です。", "sentence_source": "generated"}, {"text": "実在する会社の名前は使えない。", "target_word": "実在", "complexity_tier": "T3", "furigana": "実在[じつざい]する会社[かいしゃ]の名前[なまえ]は使[つか]えない。", "sentence_source": "generated"}, {"text": "幽霊が実在するかどうか、友だちと議論した。", "target_word": "実在", "complexity_tier": "T4", "furigana": "幽霊[ゆうれい]が実在[じつざい]するかどうか、友[とも]だちと議論[ぎろん]した。", "sentence_source": "generated"}, {"text": "これは実在の事件をもとにした映画だ。", "target_word": "実在", "complexity_tier": "T3", "furigana": "これは実在[じつざい]の事件[じけん]をもとにした映画[えいが]だ。", "sentence_source": "generated"}, {"text": "地図にある島は、本当に実在している。", "target_word": "実在", "complexity_tier": "T3", "furigana": "地図[ちず]にある島[しま]は、本当[ほんとう]に実在[じつざい]している。", "sentence_source": "generated"}, {"text": "彼が実在しない人だと知って、驚いた。", "target_word": "実在", "complexity_tier": "T3", "furigana": "彼[かれ]が実在[じつざい]しない人[ひと]だと知[し]って、驚[おどろ]いた。", "sentence_source": "generated"}, {"text": "その動物は、昔から実在すると信じられてきた。", "target_word": "実在", "complexity_tier": "T4", "furigana": "その動物[どうぶつ]は、昔[むかし]から実在[じつざい]すると信[しん]じられてきた。", "sentence_source": "generated"}, {"text": "実在の人物なので、写真も残っている。", "target_word": "実在", "complexity_tier": "T3", "furigana": "実在[じつざい]の人物[じんぶつ]なので、写真[しゃしん]も残[のこ]っている。", "sentence_source": "generated"}, {"text": "絵の中の町は、実在しない想像の場所だ。", "target_word": "実在", "complexity_tier": "T3", "furigana": "絵[え]の中[なか]の町[まち]は、実在[じつざい]しない想像[そうぞう]の場所[ばしょ]だ。", "sentence_source": "generated"}, {"text": "本に出てくる店は実在するので、行ってみた。", "target_word": "実在", "complexity_tier": "T3", "furigana": "本[ほん]に出[で]てくる店[みせ]は実在[じつざい]するので、行[い]ってみた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "実在", "label": "基本形"}, {"form": "実在する", "label": "サ変動詞・終止形"}, {"form": "実在した", "label": "過去形"}, {"form": "実在の", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "本当に存在していて、作り話ではないこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf6ee224-92d2-4127-abed-56d8891d40e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37546, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "実在", "is_correct": true, "explanation": "「実在した人」で、本当にいた人を表す。"}, {"text": "確率", "is_correct": false, "explanation": "「確率した人」は意味が成り立たず、この空所には合わない。"}, {"text": "必然", "is_correct": false, "explanation": "「必然した人」は不自然で、この空所には合わない。"}, {"text": "習慣", "is_correct": false, "explanation": "「習慣した人」は文の内容として成り立たない。"}], "explanations": {"実在": "「実在した人」で、本当にいた人を表す。", "確率": "「確率した人」は意味が成り立たず、この空所には合わない。", "必然": "「必然した人」は不自然で、この空所には合わない。", "習慣": "「習慣した人」は文の内容として成り立たない。"}, "sentence_index": 0, "correct_answer": "実在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夢から覚めて、実在に戻った。", "explanation": "ここは〈現実〉の意味。夢と比べて今いる世界は「現実に戻る」と言い、「実在」は存在しているという意味なので合わない。"}, {"text": "彼は試合で、実在を見せつけた。", "explanation": "ここは〈実力〉（能力）の意味。試合で力を示す時は「実力を見せつける」と言い、「実在」は存在の意味なので、能力は表せない。"}, {"text": "その本の実在を読んで、感動した。", "explanation": "ここは〈内容〉の意味。本の中身は「内容を読む」と言い、「実在」は本当にあることを表すので、本の中身には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37546, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "実在", "is_correct": true, "explanation": "「昔から実在すると信じられてきた」で、本当にいたと信じられることを表す。"}, {"text": "偶然", "is_correct": false, "explanation": "「偶然すると」は文の内容として成り立たない。"}, {"text": "誤解", "is_correct": false, "explanation": "「誤解する」は取り違えることで、「誤解すると信じられてきた」は内容が通らない。"}, {"text": "連想", "is_correct": false, "explanation": "「連想すると信じられてきた」は文の内容に合わない。"}], "explanations": {"実在": "「昔から実在すると信じられてきた」で、本当にいたと信じられることを表す。", "偶然": "「偶然すると」は文の内容として成り立たない。", "誤解": "「誤解する」は取り違えることで、「誤解すると信じられてきた」は内容が通らない。", "連想": "「連想すると信じられてきた」は文の内容に合わない。"}, "sentence_index": 6, "correct_answer": "実在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "展示会で、名画の実在を見た。", "explanation": "ここは〈実物〉の意味。目の前の本物を見る時は「実物を見る」と言い、「実在」は存在の意味なので見る対象にはならない。"}, {"text": "テストの実在がよくて、先生にほめられた。", "explanation": "ここは〈成績〉の意味。出来の良さは「成績がよい」と言い、「実在」は存在の意味なので成績には使わない。"}, {"text": "その店の実在が人気だ。", "explanation": "ここは〈人気〉の意味。店の評判は「人気がある」と言い、「実在」は本当にあることなので、人気の度合いには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37546, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この映画は実在を事件に基づいている。", "corrected_sentence": "この映画は実在の事件に基づいている。", "error_description": "誤: 実在を事件に → 正: 実在の事件に。「実在」は名詞で、後の名詞を修飾するには「の」が必要。「を」は目的語を示すので、ここでは使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37546, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その店は実在たので、行ってみた。", "corrected_sentence": "その店は実在するので、行ってみた。", "error_description": "誤: 実在た → 正: 実在する。「実在」は「実在する」の形で文中の動詞として使う。「た」を続けると語形が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37547, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "架空", "is_correct": true, "explanation": "想像で作られ、実際には存在しないこと。「実在」の対義語として辞書に載る。"}, {"text": "真実", "is_correct": false, "explanation": "本当のこと。「実在」と近い意味で、反対語ではない。"}, {"text": "現実", "is_correct": false, "explanation": "今ある状況。反対語ではない。"}, {"text": "本物", "is_correct": false, "explanation": "偽物ではないもの。反対語ではない。"}], "correct_answer": "架空", "explanations": {"架空": "想像で作られ、実際には存在しないこと。「実在」の対義語として辞書に載る。", "真実": "本当のこと。「実在」と近い意味で、反対語ではない。", "現実": "今ある状況。反対語ではない。", "本物": "偽物ではないもの。反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37547, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「宇宙人が実在する」で、実在の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「宇宙人を実在する」は目的語を示す「を」になり、実在の主語にはならない。"}, {"text": "に", "is_correct": false, "explanation": "「宇宙人に実在する」は相手を示し、主語にならない。"}, {"text": "で", "is_correct": false, "explanation": "「宇宙人で実在する」は手段や場所を示し、主語にならない。"}], "correct_answer": "が", "explanations": {"が": "「宇宙人が実在する」で、実在の主語を示す。", "を": "「宇宙人を実在する」は目的語を示す「を」になり、実在の主語にはならない。", "に": "「宇宙人に実在する」は相手を示し、主語にならない。", "で": "「宇宙人で実在する」は手段や場所を示し、主語にならない。"}, "error_tags": {"を": "目的語", "に": "相手", "で": "手段・場所"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "架空", "is_correct": true, "explanation": "想像で作られ、実際には存在しないこと。「実在」の対義語として辞書に載る。"}, {"text": "事実", "is_correct": false, "explanation": "本当に起きたこと。反対語ではない。"}, {"text": "存在", "is_correct": false, "explanation": "そこにあること。近い意味で、反対語ではない。"}, {"text": "真相", "is_correct": false, "explanation": "隠れていた本当の事情。反対語ではない。"}], "correct_answer": "架空", "explanations": {"架空": "想像で作られ、実際には存在しないこと。「実在」の対義語として辞書に載る。", "事実": "本当に起きたこと。反対語ではない。", "存在": "そこにあること。近い意味で、反対語ではない。", "真相": "隠れていた本当の事情。反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37547, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "実際に存在すること。想像や仮定ではなく、現実にあること。", "primary_collocate": null, "pronunciation": "じつざい", "ipa": "dʑitsɯzai", "syllable_count": 4, "sentences": [{"text": "神話の英雄が実在したかは、わからない。", "target_word": "実在", "complexity_tier": "T4", "furigana": "神話[しんわ]の英雄[えいゆう]が実在[じつざい]したかは、わからない。", "sentence_source": "generated"}, {"text": "実在しない町を舞台にした小説を読んだ。", "target_word": "実在", "complexity_tier": "T3", "furigana": "実在[じつざい]しない町[まち]を舞台[ぶたい]にした小説[しょうせつ]を読[よ]んだ。", "sentence_source": "generated"}, {"text": "子どもは、サンタクロースが実在すると信じている。", "target_word": "実在", "complexity_tier": "T3", "furigana": "子[こ]どもは、サンタクロースが実在[じつざい]すると信[しん]じている。", "sentence_source": "generated"}, {"text": "彼は実在の画家をモデルに絵を描いた。", "target_word": "実在", "complexity_tier": "T3", "furigana": "彼[かれ]は実在[じつざい]の画家[がか]をモデルに絵[え]を描[か]いた。", "sentence_source": "generated"}, {"text": "証拠が出て、その人物の実在が確かめられた。", "target_word": "実在", "complexity_tier": "T4", "furigana": "証拠[しょうこ]が出[で]て、その人物[じんぶつ]の実在[じつざい]が確[たし]かめられた。", "sentence_source": "generated"}, {"text": "その話は作り話ではなく、実在する人物の体験にもとづいている。", "target_word": "実在", "complexity_tier": "T3", "furigana": "作り話[つくりばなし]ではなく、実在[じつざい]する人物[じんぶつ]の体験[たいけん]にもとづいている。", "sentence_source": "generated"}, {"text": "実在する人にしか、この賞は贈られない。", "target_word": "実在", "complexity_tier": "T4", "furigana": "実在[じつざい]する人[ひと]にしか、この賞[しょう]は贈[おく]られない。", "sentence_source": "generated"}, {"text": "宇宙人が実在するなら、いつか会ってみたい。", "target_word": "実在", "complexity_tier": "T3", "furigana": "宇宙人[うちゅうじん]が実在[じつざい]するなら、いつか会[あ]ってみたい。", "sentence_source": "generated"}, {"text": "その村は昔話ではなく、実在した場所だ。", "target_word": "実在", "complexity_tier": "T3", "furigana": "その村[むら]は昔話[むかしばなし]ではなく、実在[じつざい]した場所[ばしょ]だ。", "sentence_source": "generated"}, {"text": "空想のキャラクターと違い、彼女は実在する人だ。", "target_word": "実在", "complexity_tier": "T3", "furigana": "空想[くうそう]のキャラクターと違[ちが]い、彼女[かのじょ]は実在[じつざい]する人[ひと]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "実在", "label": "基本形"}, {"form": "実在する", "label": "サ変動詞・終止形"}, {"form": "実在した", "label": "過去形"}, {"form": "実在しない", "label": "否定形"}], "register": "formal", "sense_fingerprint": "想像や仮定ではなく現実に存在すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf6ee224-92d2-4127-abed-56d8891d40e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37547, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "実在", "is_correct": true, "explanation": "「実在したかは、わからない」で、英雄が本当にいたかを表す。"}, {"text": "確率", "is_correct": false, "explanation": "「確率したか」は意味が成り立たず、この空所には合わない。"}, {"text": "必然", "is_correct": false, "explanation": "「必然したか」は不自然で、この空所には合わない。"}, {"text": "偶然", "is_correct": false, "explanation": "「偶然したか」は文の内容に合わない。"}], "explanations": {"実在": "「実在したかは、わからない」で、英雄が本当にいたかを表す。", "確率": "「確率したか」は意味が成り立たず、この空所には合わない。", "必然": "「必然したか」は不自然で、この空所には合わない。", "偶然": "「偶然したか」は文の内容に合わない。"}, "sentence_index": 0, "correct_answer": "実在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は実在の腕前を見せた。", "explanation": "ここは〈本物〉（偽物でないこと）の意味。腕前の確かさは「本物の腕前」と言い、「実在」は存在の意味なので腕前には使わない。"}, {"text": "ゲームの世界から、実在へ戻った。", "explanation": "ここは〈現実〉の意味。ゲームや夢と比べた今の世界は「現実」で、「実在」は存在の意味なので合わない。"}, {"text": "彼女の実在がよくて、表彰された。", "explanation": "ここは〈成績〉の意味。結果の良さは「成績がよい」と言い、「実在」は存在の意味なので、成績には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37547, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "実在", "is_correct": true, "explanation": "「実在する人」で、本当にいる人を表す。"}, {"text": "習慣", "is_correct": false, "explanation": "「習慣する人」は意味が成り立たず、この空所には合わない。"}, {"text": "余裕", "is_correct": false, "explanation": "「余裕する人」は文の内容に合わない。"}, {"text": "体重", "is_correct": false, "explanation": "「体重する人」は意味が通らない。"}], "explanations": {"実在": "「実在する人」で、本当にいる人を表す。", "習慣": "「習慣する人」は意味が成り立たず、この空所には合わない。", "余裕": "「余裕する人」は文の内容に合わない。", "体重": "「体重する人」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "実在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その服の実在を試着した。", "explanation": "ここは〈実物〉の意味。店で試着するのは「実物」で、「実在」は存在の意味なので服の試着には使わない。"}, {"text": "試験の実在がよくて、先生にほめられた。", "explanation": "ここは〈成績〉の意味。出来の良さは「成績がよい」と言い、「実在」は存在の意味なので成績には使わない。"}, {"text": "彼女の実力は、試合で実在を示した。", "explanation": "ここは〈実力〉の意味。能力を見せる時は「実力を示す」と言い、「実在」は存在の意味なので能力には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37547, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その話は作り話ではなく、実在を人物の体験にもとづいている。", "corrected_sentence": "その話は作り話ではなく、実在の人物の体験にもとづいている。", "error_description": "誤: 実在を人物 → 正: 実在の人物。「実在」は名詞で、後ろの「人物」を修飾するには「の」が必要。「を」は目的語を示すので、ここでは使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37547, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その村は昔話ではなく、実在を場所だ。", "corrected_sentence": "その村は昔話ではなく、実在する場所だ。", "error_description": "誤: 実在を場所 → 正: 実在する場所。「実在」は「する」を付けて動詞として使う。「を」は目的語の助詞で、「実在を」では後ろの名詞を修飾できない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
