INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37548, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "その人の考え方や感じ方の、いつものようす。", "primary_collocate": null, "pronunciation": "せいかく", "ipa": "seːkaku", "syllable_count": 4, "sentences": [{"text": "兄は明るい性格で、だれとでもすぐ友だちになる。", "target_word": "性格", "complexity_tier": "T3", "furigana": "兄[あに]は明[あか]るい性格[せいかく]で、だれとでもすぐ友[とも]だちになる。", "sentence_source": "generated"}, {"text": "彼女は性格がやさしいので、みんなに好かれている。", "target_word": "性格", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は性格[せいかく]がやさしいので、みんなに好[す]かれている。", "sentence_source": "generated"}, {"text": "双子でも、性格はまったく違う。", "target_word": "性格", "complexity_tier": "T3", "furigana": "双子[ふたご]でも、性格[せいかく]はまったく違[ちが]う。", "sentence_source": "generated"}, {"text": "私は性格がのんびりしていて、急ぐのが苦手だ。", "target_word": "性格", "complexity_tier": "T3", "furigana": "私[わたし]は性格[せいかく]がのんびりしていて、急[いそ]ぐのが苦手[にがて]だ。", "sentence_source": "generated"}, {"text": "祖父は頑固な性格だが、孫にはいつもやさしい。", "target_word": "性格", "complexity_tier": "T3", "furigana": "祖父[そふ]は頑固[がんこ]な性格[せいかく]だが、孫[まご]にはいつもやさしい。", "sentence_source": "generated"}, {"text": "性格が合わなくて、二人は長く続かなかった。", "target_word": "性格", "complexity_tier": "T3", "furigana": "性格[せいかく]が合[あ]わなくて、二人[ふたり]は長[なが]く続[つづ]かなかった。", "sentence_source": "generated"}, {"text": "この子は性格がおとなしく、友だちにもすぐ慣れる。", "target_word": "性格", "complexity_tier": "T3", "furigana": "この子[こ]は性格[せいかく]がおとなしく、友[とも]だちにもすぐ慣[な]れる。", "sentence_source": "generated"}, {"text": "先生は、生徒の性格を見て話し方を変える。", "target_word": "性格", "complexity_tier": "T3", "furigana": "先生[せんせい]は、生徒[せいと]の性格[せいかく]を見[み]て話[はな]し方[かた]を変[か]える。", "sentence_source": "generated"}, {"text": "人の性格は、話し方にも出ると言われる。", "target_word": "性格", "complexity_tier": "T3", "furigana": "人[ひと]の性格[せいかく]は、話[はな]し方[かた]にも出[で]ると言[い]われる。", "sentence_source": "generated"}, {"text": "弟は負けず嫌いの性格で、練習をやめなかった。", "target_word": "性格", "complexity_tier": "T3", "furigana": "弟[おとうと]は負[ま]けず嫌[ぎら]いの性格[せいかく]で、練習[れんしゅう]をやめなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "性格", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人の考え方・感じ方に見られるふだんのようす（明るい、やさしいなど）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '138c9f88-9d7f-429e-8d2c-7d4fc969fc77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37548, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "性格", "is_correct": true, "explanation": "人の考え方や感じ方の傾向を表し、「明るい性格」と言える。"}, {"text": "身長", "is_correct": false, "explanation": "「明るい身長」は意味が通らない。身長は体の高さ。"}, {"text": "年齢", "is_correct": false, "explanation": "「明るい年齢」は意味が通らない。年齢は生きてきた年数。"}, {"text": "出身", "is_correct": false, "explanation": "「明るい出身」は意味が通らない。出身は生まれや育った場所。"}], "explanations": {"性格": "人の考え方や感じ方の傾向を表し、「明るい性格」と言える。", "身長": "「明るい身長」は意味が通らない。身長は体の高さ。", "年齢": "「明るい年齢」は意味が通らない。年齢は生きてきた年数。", "出身": "「明るい出身」は意味が通らない。出身は生まれや育った場所。"}, "sentence_index": 0, "correct_answer": "性格"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この布は性格が丈夫で、長く使える。", "explanation": "ここは〈性質〉の意味。性格は人について言うもので、布の丈夫さには使わない。"}, {"text": "私は性格が弱くて、すぐかぜをひく。", "explanation": "ここは〈体質〉の意味。かぜをひきやすさは体質で、性格とは言わない。"}, {"text": "彼は性格が整っていて、雑誌のモデルに選ばれた。", "explanation": "ここは〈外見〉の意味。顔立ちや姿は外見で、性格とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37548, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "性格", "is_correct": true, "explanation": "おとなしいのは人の性格を表す。文が成り立つ。"}, {"text": "性別", "is_correct": false, "explanation": "「性別がおとなしい」は成り立たない。性別は男女などの区別。"}, {"text": "体重", "is_correct": false, "explanation": "「体重がおとなしい」は成り立たない。体重は体の重さ。"}, {"text": "毛色", "is_correct": false, "explanation": "「毛色がおとなしい」は成り立たない。毛色は毛の色。"}], "explanations": {"性格": "おとなしいのは人の性格を表す。文が成り立つ。", "性別": "「性別がおとなしい」は成り立たない。性別は男女などの区別。", "体重": "「体重がおとなしい」は成り立たない。体重は体の重さ。", "毛色": "「毛色がおとなしい」は成り立たない。毛色は毛の色。"}, "sentence_index": 6, "correct_answer": "性格"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妹は性格がすらりとしている。", "explanation": "ここは〈体型〉の意味。すらりとした形は体型で、性格とは言わない。"}, {"text": "今日は性格が悪く、熱がある。", "explanation": "ここは〈体調〉の意味。熱や具合は体調で、性格とは言わない。"}, {"text": "先生の性格は低くて、教室によく響く。", "explanation": "ここは〈声〉の意味。声の高さや響きは声で、性格とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37548, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "あの子は性格を明るくて、すぐ友だちができる。", "corrected_sentence": "あの子は性格が明るくて、すぐ友だちができる。", "error_description": "「性格が明るい」と主語を「が」で示す。「性格を明るい」は誤りで、正しくは「性格が明るい」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37548, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼とは性格がよく似合う。", "corrected_sentence": "彼とは性格がよく合う。", "error_description": "「性格が合う」が正しい。「似合う」は服や外見に合うことを表し、性格には使わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
