INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37549, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "人の心の持ち方や行動の傾向。その人らしさを表す特徴。", "primary_collocate": null, "pronunciation": "せいかく", "ipa": "seːkaku", "syllable_count": 4, "sentences": [{"text": "彼の性格は、仕事のしかたによく表れている。", "target_word": "性格", "complexity_tier": "T3", "furigana": "彼[かれ]の性格[せいかく]は、仕事[しごと]のしかたによく表[あらわ]れている。", "sentence_source": "generated"}, {"text": "慎重な性格なので、彼は決めるまでに時間がかかる。", "target_word": "性格", "complexity_tier": "T3", "furigana": "慎重[しんちょう]な性格[せいかく]なので、彼[かれ]は決[き]めるまでに時間[じかん]がかかる。", "sentence_source": "generated"}, {"text": "彼女は思ったことをはっきり言う性格だ。", "target_word": "性格", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は思[おも]ったことをはっきり言[い]う性格[せいかく]だ。", "sentence_source": "generated"}, {"text": "面接では、応募者の性格も大切に見られる。", "target_word": "性格", "complexity_tier": "T3", "furigana": "面接[めんせつ]では、応募者[おうぼしゃ]の性格[せいかく]も大切[たいせつ]に見[み]られる。", "sentence_source": "generated"}, {"text": "性格を変えるのは難しいが、行動は変えられる。", "target_word": "性格", "complexity_tier": "T3", "furigana": "性格[せいかく]を変[か]えるのは難[むずか]しいが、行動[こうどう]は変[か]えられる。", "sentence_source": "generated"}, {"text": "母は用心深い性格で、出かける前に必ず戸締まりを確かめる。", "target_word": "性格", "complexity_tier": "T3", "furigana": "母[はは]は用心深[ようじんぶか]い性格[せいかく]で、出[で]かける前[まえ]に必[かなら]ず戸締[とじ]まりを確[たし]かめる。", "sentence_source": "generated"}, {"text": "彼は性格がまっすぐで、うそをつくことができない。", "target_word": "性格", "complexity_tier": "T3", "furigana": "彼[かれ]は性格[せいかく]がまっすぐで、うそをつくことができない。", "sentence_source": "generated"}, {"text": "性格の違いが原因で、意見がよくぶつかる。", "target_word": "性格", "complexity_tier": "T3", "furigana": "性格[せいかく]の違[ちが]いが原因[げんいん]で、意見[いけん]がよくぶつかる。", "sentence_source": "generated"}, {"text": "子どもの性格は、育つ環境にも影響される。", "target_word": "性格", "complexity_tier": "T3", "furigana": "子[こ]どもの性格[せいかく]は、育[そだ]つ環境[かんきょう]にも影響[えいきょう]される。", "sentence_source": "generated"}, {"text": "好奇心が強い性格のおかげで、彼は多くのことを学んだ。", "target_word": "性格", "complexity_tier": "T3", "furigana": "好奇心[こうきしん]が強[つよ]い性格[せいかく]のおかげで、彼[かれ]は多[おお]くのことを学[まな]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "性格", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "心の持ち方や行動の傾向として表れる、その人らしい特徴", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T2: contains vocabulary far above tier T2: 用心深い (Zipf 2.19), 戸締まり (Zipf 2.22)']::text[], '138c9f88-9d7f-429e-8d2c-7d4fc969fc77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37549, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "性格", "is_correct": true, "explanation": "行動の傾向として仕事のしかたに表れる、という意味で文が成り立つ。"}, {"text": "身長", "is_correct": false, "explanation": "身長は仕事のしかたに表れるものではないので、文が成り立たない。"}, {"text": "天気", "is_correct": false, "explanation": "「彼の天気は、仕事のしかたに表れる」は成り立たない。天気は空模様。"}, {"text": "体重", "is_correct": false, "explanation": "体重は仕事のしかたに表れるものではないので、文が成り立たない。"}], "explanations": {"性格": "行動の傾向として仕事のしかたに表れる、という意味で文が成り立つ。", "身長": "身長は仕事のしかたに表れるものではないので、文が成り立たない。", "天気": "「彼の天気は、仕事のしかたに表れる」は成り立たない。天気は空模様。", "体重": "体重は仕事のしかたに表れるものではないので、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "性格"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の性格は高くて、転職で有利になった。", "explanation": "ここは〈年収〉の意味。収入の多さは年収で、性格を高いとは言わない。"}, {"text": "午後は性格が晴れて、洗濯日和になった。", "explanation": "ここは〈天気〉の意味。晴れるのは天気で、性格には使わない。"}, {"text": "このアパートは性格が高くて、学生には無理だ。", "explanation": "ここは〈家賃〉の意味。料金の高さは家賃で、性格とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37549, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "性格", "is_correct": true, "explanation": "心の持ち方が素直で、まっすぐであることを表し、文が成り立つ。"}, {"text": "年収", "is_correct": false, "explanation": "「年収がまっすぐ」は意味が通らない。年収は一年の収入。"}, {"text": "答案", "is_correct": false, "explanation": "「答案がまっすぐ」は意味が通らない。答案は試験の答え。"}, {"text": "誕生日", "is_correct": false, "explanation": "「誕生日がまっすぐ」は意味が通らない。誕生日は生まれた日。"}], "explanations": {"性格": "心の持ち方が素直で、まっすぐであることを表し、文が成り立つ。", "年収": "「年収がまっすぐ」は意味が通らない。年収は一年の収入。", "答案": "「答案がまっすぐ」は意味が通らない。答案は試験の答え。", "誕生日": "「誕生日がまっすぐ」は意味が通らない。誕生日は生まれた日。"}, "sentence_index": 6, "correct_answer": "性格"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新しい機械の性格が、ようやく正常に作動した。", "explanation": "ここは〈機械〉の意味。作動するのは機械で、性格とは言わない。"}, {"text": "ランナーは性格が速くて、記録を次々に更新した。", "explanation": "ここは〈足〉の意味。速いのは足や走力で、性格を速いとは言わない。"}, {"text": "彼の性格は上手で、先生に褒められた。", "explanation": "ここは〈字〉の意味。上手さは字や技術で、性格には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37549, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は性格を落ち着いていて、相談しやすい。", "corrected_sentence": "彼女は性格が落ち着いていて、相談しやすい。", "error_description": "「性格が落ち着いている」と主語を「が」で示す。「性格を落ち着いていて」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37549, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "性格は、ある程度生まれつき決めている。", "corrected_sentence": "性格は、ある程度生まれつき決まっている。", "error_description": "「性格」は「決まる」が正しい。「決める」は人が意図して決める動作に使い、性格には合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
