INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37554, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「上を」の「を」。飛んでいく経路の場所を示し、動詞「飛ぶ」の前に入る。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」。ドローンがすでに主語なので、二つ目の「が」では文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。動詞の前に入ると文の構造が崩れ、合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示す「と」。経路を示す位置では合わない。"}], "correct_answer": "を", "explanations": {"を": "「上を」の「を」。飛んでいく経路の場所を示し、動詞「飛ぶ」の前に入る。", "が": "主語を示す「が」。ドローンがすでに主語なので、二つ目の「が」では文が成り立たない。", "の": "連体修飾の「の」。動詞の前に入ると文の構造が崩れ、合わない。", "と": "並列や相手を示す「と」。経路を示す位置では合わない。"}, "error_tags": {"が": "主語", "の": "連体修飾", "と": "並列・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab34d665-f01a-4eba-b5e8-9aab20d6c140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37554, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "とぶは、そらをうごくことです。", "primary_collocate": null, "pronunciation": "とぶ", "ipa": "tobɯ", "syllable_count": 2, "sentences": [{"text": "鳥が空を飛んでいます。", "target_word": "飛んで", "complexity_tier": "T3", "furigana": "鳥[とり]が空[そら]を飛[と]んでいます。", "sentence_source": "generated"}, {"text": "風船が風で高く飛んでいった。", "target_word": "飛んで", "complexity_tier": "T3", "furigana": "風船[ふうせん]が風[かぜ]で高[たか]く飛[と]んでいった。", "sentence_source": "generated"}, {"text": "飛行機は明日の朝、東京へ飛びます。", "target_word": "飛びます", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]は明日[あした]の朝[あさ]、東京[とうきょう]へ飛[と]びます。", "sentence_source": "generated"}, {"text": "私は鳥のように空を飛びたい。", "target_word": "飛びたい", "complexity_tier": "T3", "furigana": "私[わたし]は鳥[とり]のように空[そら]を飛[と]びたい。", "sentence_source": "generated"}, {"text": "紙飛行機が遠くまで飛んだ。", "target_word": "飛んだ", "complexity_tier": "T3", "furigana": "紙飛行機[かみひこうき]が遠[とお]くまで飛[と]んだ。", "sentence_source": "generated"}, {"text": "ペンギンは鳥なのに、空を飛べません。", "target_word": "飛べません", "complexity_tier": "T3", "furigana": "ペンギンは鳥[とり]なのに、空[そら]を飛[と]べません。", "sentence_source": "generated"}, {"text": "蝶が花の上を飛んでいる。", "target_word": "飛んで", "complexity_tier": "T3", "furigana": "蝶[ちょう]が花[はな]の上[うえ]を飛[と]んでいる。", "sentence_source": "generated"}, {"text": "ドローンが公園の上を飛んでいた。", "target_word": "飛んで", "complexity_tier": "T3", "furigana": "ドローンが公園[こうえん]の上[うえ]を飛[と]んでいた。", "sentence_source": "generated"}, {"text": "雨の日は、虫があまり飛ばない。", "target_word": "飛ばない", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、虫[むし]があまり飛[と]ばない。", "sentence_source": "generated"}, {"text": "ヘリコプターが海の近くを飛んでいる。", "target_word": "飛んで", "complexity_tier": "T3", "furigana": "ヘリコプターが海[うみ]の近[ちか]くを飛[と]んでいる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "飛ぶ", "label": "辞書形"}, {"form": "飛びます", "label": "丁寧形"}, {"form": "飛んで", "label": "て形"}, {"form": "飛んだ", "label": "た形"}, {"form": "飛ばない", "label": "ない形"}, {"form": "飛べる", "label": "可能形"}, {"form": "飛びたい", "label": "たい形"}], "register": "neutral", "sense_fingerprint": "空中を移動する(飛ぶ・とぶ)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d21cf5d-f729-4c5e-b9cd-2c0746b4a406') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37554, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "飛んで", "is_correct": true, "explanation": "「空を飛んでいます」の形。鳥が空中を移動する動きを表し、文が成り立つ。"}, {"text": "歩いて", "is_correct": false, "explanation": "歩くは地面を進む動きなので、「空を歩いて」では空中の移動を表せず合わない。"}, {"text": "跳ねて", "is_correct": false, "explanation": "跳ねるは弾む動きで、「空を跳ねて」は空中を進む意味にならず不自然。"}, {"text": "落ちて", "is_correct": false, "explanation": "落ちるは上から下へ下がる動きで、「空を落ちて」は空中を進む意味にならない。"}], "explanations": {"飛んで": "「空を飛んでいます」の形。鳥が空中を移動する動きを表し、文が成り立つ。", "歩いて": "歩くは地面を進む動きなので、「空を歩いて」では空中の移動を表せず合わない。", "跳ねて": "跳ねるは弾む動きで、「空を跳ねて」は空中を進む意味にならず不自然。", "落ちて": "落ちるは上から下へ下がる動きで、「空を落ちて」は空中を進む意味にならない。"}, "sentence_index": 0, "correct_answer": "飛んで"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明日は車で飛んで、海まで行きます。", "explanation": "ここは〈車で移動する〉の意味。〈飛ぶ〉は空中を進むことなので、車での移動には合わない。"}, {"text": "犬は飼い主を見るなり、飛んで寝た。", "explanation": "ここは〈眠り込む〉の意味。〈飛ぶ〉は空中を進むことなので、横になって眠る動作には合わない。"}, {"text": "救命胴衣のおかげで、おぼれずに水に飛んでいられる。", "explanation": "ここは〈水に浮く〉の意味。水面に留まる様子で、空中を進む〈飛ぶ〉とは違うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab34d665-f01a-4eba-b5e8-9aab20d6c140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37554, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "飛んで", "is_correct": true, "explanation": "「花の上を飛んでいる」の形。蝶が空中を移動する動きとして文が成り立つ。"}, {"text": "転がって", "is_correct": false, "explanation": "転がるは地面などを回る動きで、空中を飛ぶ蝶には合わず不自然。"}, {"text": "駆けて", "is_correct": false, "explanation": "駆けるは地上を速く走る動きで、「花の上を駆けて」は空中の移動を表せない。"}, {"text": "叩いて", "is_correct": false, "explanation": "叩くは何かを打つ動作で、「花の上を叩いて」は移動の意味にならない。"}], "explanations": {"飛んで": "「花の上を飛んでいる」の形。蝶が空中を移動する動きとして文が成り立つ。", "転がって": "転がるは地面などを回る動きで、空中を飛ぶ蝶には合わず不自然。", "駆けて": "駆けるは地上を速く走る動きで、「花の上を駆けて」は空中の移動を表せない。", "叩いて": "叩くは何かを打つ動作で、「花の上を叩いて」は移動の意味にならない。"}, "sentence_index": 6, "correct_answer": "飛んで"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この古い時計は、針が飛んで正確に動く。", "explanation": "ここは〈なめらかに回る〉の意味。〈飛ぶ〉は空中を移動することなので、針の動きには合わない。"}, {"text": "コーヒーを飲んだら、手の震えが飛んだ。", "explanation": "ここは〈止まる〉の意味。〈飛ぶ〉は空中を移動することなので、震えが消える様子には合わない。"}, {"text": "先生は黒板に、チョークで飛んで字を書いた。", "explanation": "ここは〈速く記す〉の意味。〈飛ぶ〉は空中を移動することなので、素早く書き付ける動きには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab34d665-f01a-4eba-b5e8-9aab20d6c140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37554, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ツバメが空を飛ぶでいます。", "corrected_sentence": "ツバメが空を飛んでいます。", "error_description": "「飛んでいます」の「飛んで」（て形）が正しい。「飛ぶで」は活用が誤りで、〈飛ぶ〉の形に〈で〉は続かない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "飛んで", "is_correct": true, "explanation": "「飛んでいった」の形（て形）。後ろの動詞につながる形で文に合う。"}, {"text": "飛ばない", "is_correct": false, "explanation": "ない形。否定の意味になるので、「飛んでいった」の形ではない。"}, {"text": "飛べる", "is_correct": false, "explanation": "可能形。「できる」の意味になり、ここの文の形と合わない。"}, {"text": "飛びます", "is_correct": false, "explanation": "丁寧形。「飛びます」は「飛んでいった」の形ではなく、ここでは続かない。"}], "correct_form": "飛んで", "base_form": "飛ぶ", "form_label": "て形", "sentence_index": 1, "explanations": {"飛んで": "「飛んでいった」の形（て形）。後ろの動詞につながる形で文に合う。", "飛ばない": "ない形。否定の意味になるので、「飛んでいった」の形ではない。", "飛べる": "可能形。「できる」の意味になり、ここの文の形と合わない。", "飛びます": "丁寧形。「飛びます」は「飛んでいった」の形ではなく、ここでは続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab34d665-f01a-4eba-b5e8-9aab20d6c140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37554, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "カラスが公園の上を飛んだでいた。", "corrected_sentence": "カラスが公園の上を飛んでいた。", "error_description": "「飛んでいた」の「飛んで」（て形）が正しい。「飛んだで」は〈た形＋で〉の並びで、「飛んでいた」の形にならないため誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "飛んで", "is_correct": true, "explanation": "「飛んでいた」の形（て形）。後ろの「いた」に続く形で文に合う。"}, {"text": "飛びたい", "is_correct": false, "explanation": "たい形。「〜したい」の意味になり、「飛んでいた」の形ではない。"}, {"text": "飛べない", "is_correct": false, "explanation": "ない形（可能の否定）。飛ぶ動作の進行を表せず、文の形と合わない。"}, {"text": "飛んだ", "is_correct": false, "explanation": "た形。過去の完了を表すが、「いた」と続く進行の形にはならない。"}], "correct_form": "飛んで", "base_form": "飛ぶ", "form_label": "て形", "sentence_index": 7, "explanations": {"飛んで": "「飛んでいた」の形（て形）。後ろの「いた」に続く形で文に合う。", "飛びたい": "たい形。「〜したい」の意味になり、「飛んでいた」の形ではない。", "飛べない": "ない形（可能の否定）。飛ぶ動作の進行を表せず、文の形と合わない。", "飛んだ": "た形。過去の完了を表すが、「いた」と続く進行の形にはならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab34d665-f01a-4eba-b5e8-9aab20d6c140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37555, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "まで", "options": [{"text": "まで", "is_correct": true, "explanation": "「遠くまで」の「まで」。移動の到達点、つまり距離の終わりを示す。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。名詞を修飾する形になり、「遠くの飛べる」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」。比べる対象がなく、「遠くより飛べる」は成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」。遠くを起点とする意味になり、到達点を表す「遠くまで」とは合わない。"}], "correct_answer": "まで", "explanations": {"まで": "「遠くまで」の「まで」。移動の到達点、つまり距離の終わりを示す。", "の": "連体修飾の「の」。名詞を修飾する形になり、「遠くの飛べる」は成り立たない。", "より": "比較の「より」。比べる対象がなく、「遠くより飛べる」は成り立たない。", "から": "起点の「から」。遠くを起点とする意味になり、到達点を表す「遠くまで」とは合わない。"}, "error_tags": {"の": "連体修飾", "より": "比較", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab34d665-f01a-4eba-b5e8-9aab20d6c140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37555, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「まわりを」の「を」。飛んでいる経路の場所を示し、動詞の前に入る。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」。カモメがすでに主語なので、二つ目の「が」では文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。動詞の前に入ると文の構造が崩れ、合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示す「と」。経路を示す位置では合わない。"}], "correct_answer": "を", "explanations": {"を": "「まわりを」の「を」。飛んでいる経路の場所を示し、動詞の前に入る。", "が": "主語を示す「が」。カモメがすでに主語なので、二つ目の「が」では文が成り立たない。", "の": "連体修飾の「の」。動詞の前に入ると文の構造が崩れ、合わない。", "と": "並列や相手を示す「と」。経路を示す位置では合わない。"}, "error_tags": {"が": "主語", "の": "連体修飾", "と": "並列・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab34d665-f01a-4eba-b5e8-9aab20d6c140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37555, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "空中を移動する。鳥や飛行機などが、翼を使って空を進む。", "primary_collocate": null, "pronunciation": "とぶ", "ipa": "tobɯ", "syllable_count": 2, "sentences": [{"text": "白鳥は大きな翼を広げて、空高く飛ぶ。", "target_word": "飛ぶ", "complexity_tier": "T3", "furigana": "白鳥[はくちょう]は大[おお]きな翼[つばさ]を広[ひろ]げて、空高[そらたか]く飛[と]ぶ。", "sentence_source": "generated"}, {"text": "鳥は翼があるから、遠くまで飛べる。", "target_word": "飛べる", "complexity_tier": "T3", "furigana": "鳥[とり]は翼[つばさ]があるから、遠[とお]くまで飛[と]べる。", "sentence_source": "generated"}, {"text": "この飛行機は、太平洋の上を十時間飛びます。", "target_word": "飛びます", "complexity_tier": "T3", "furigana": "この飛行機[ひこうき]は、太平洋[たいへいよう]の上[うえ]を十時間[じゅうじかん]飛[と]びます。", "sentence_source": "generated"}, {"text": "渡り鳥は、冬になると南へ飛んでいく。", "target_word": "飛んで", "complexity_tier": "T3", "furigana": "渡[わた]り鳥[どり]は、冬[ふゆ]になると南[みなみ]へ飛[と]んでいく。", "sentence_source": "generated"}, {"text": "ツバメが低いところを飛んでいるので、もうすぐ雨が降りそうだ。", "target_word": "飛んで", "complexity_tier": "T3", "furigana": "ツバメが低[ひく]いところを飛[と]んでいるので、もうすぐ雨[あめ]が降[ふ]りそうだ。", "sentence_source": "generated"}, {"text": "ひな鳥はまだ小さいので、うまく飛べない。", "target_word": "飛べない", "complexity_tier": "T3", "furigana": "ひな鳥[どり]はまだ小[ちい]さいので、うまく飛[と]べない。", "sentence_source": "generated"}, {"text": "戦闘機が大きな音を立てて飛んでいった。", "target_word": "飛んで", "complexity_tier": "T3", "furigana": "戦闘機[せんとうき]が大[おお]きな音[おと]を立[た]てて飛[と]んでいった。", "sentence_source": "generated"}, {"text": "カモメが船のまわりを飛んでいる。", "target_word": "飛んで", "complexity_tier": "T3", "furigana": "カモメが船[ふね]のまわりを飛[と]んでいる。", "sentence_source": "generated"}, {"text": "台風のため、今日は飛行機が飛びません。", "target_word": "飛びません", "complexity_tier": "T3", "furigana": "台風[たいふう]のため、今日[きょう]は飛行機[ひこうき]が飛[と]びません。", "sentence_source": "generated"}, {"text": "鷲は山の上を飛びながら、えさを探す。", "target_word": "飛びながら", "complexity_tier": "T3", "furigana": "鷲[わし]は山[やま]の上[うえ]を飛[と]びながら、えさを探[さが]す。", "sentence_source": "generated"}], "morphological_forms": [{"form": "飛ぶ", "label": "辞書形"}, {"form": "飛びます", "label": "丁寧形"}, {"form": "飛んで", "label": "て形"}, {"form": "飛んだ", "label": "た形"}, {"form": "飛ばない", "label": "ない形"}, {"form": "飛べる", "label": "可能形"}, {"form": "飛びながら", "label": "ながら形"}], "register": "neutral", "sense_fingerprint": "鳥や飛行機が翼で空を進む(飛ぶ・とぶ)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d21cf5d-f729-4c5e-b9cd-2c0746b4a406') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37555, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "飛ぶ", "is_correct": true, "explanation": "辞書形。翼で空中を進む意味で、「空高く飛ぶ」として文末に合う。"}, {"text": "歩く", "is_correct": false, "explanation": "地面を足で進む動き。「空高く歩く」では空中の移動にならず合わない。"}, {"text": "眠る", "is_correct": false, "explanation": "寝ている状態を表す。「空高く眠る」は空中を進む意味にならず合わない。"}, {"text": "落ちる", "is_correct": false, "explanation": "上から下へ下がる動き。「空高く落ちる」は空中を進む意味にならない。"}], "explanations": {"飛ぶ": "辞書形。翼で空中を進む意味で、「空高く飛ぶ」として文末に合う。", "歩く": "地面を足で進む動き。「空高く歩く」では空中の移動にならず合わない。", "眠る": "寝ている状態を表す。「空高く眠る」は空中を進む意味にならず合わない。", "落ちる": "上から下へ下がる動き。「空高く落ちる」は空中を進む意味にならない。"}, "sentence_index": 0, "correct_answer": "飛ぶ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "仕事のストレスが一晩で飛んで、体が軽くなった。", "explanation": "ここは〈消える〉の意味。ストレスがなくなる様子で、空中を進む〈飛ぶ〉とは違うので合わない。"}, {"text": "原材料費の高騰で、商品が一気に店の奥へ飛んだ。", "explanation": "ここは〈運ばれる〉の意味。〈飛ぶ〉は空中を進むことなので、商品を運ぶ動きには合わない。"}, {"text": "眠気が一気に飛んで、目がさえた。", "explanation": "ここは〈消える〉の意味。眠気がなくなる様子で、空中を進む〈飛ぶ〉とは違うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab34d665-f01a-4eba-b5e8-9aab20d6c140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37555, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "飛んで", "is_correct": true, "explanation": "「大きな音を立てて飛んでいった」の形。戦闘機が空中を進んだ動きを表す。"}, {"text": "笑って", "is_correct": false, "explanation": "笑うは表情や声を出す動作で、「戦闘機が笑っていった」は意味が通らない。"}, {"text": "叫んで", "is_correct": false, "explanation": "叫ぶは声を上げる動作で、移動の意味にならず不自然。"}, {"text": "泣いて", "is_correct": false, "explanation": "泣くは涙を流す動作で、戦闘機の移動の文には合わない。"}], "explanations": {"飛んで": "「大きな音を立てて飛んでいった」の形。戦闘機が空中を進んだ動きを表す。", "笑って": "笑うは表情や声を出す動作で、「戦闘機が笑っていった」は意味が通らない。", "叫んで": "叫ぶは声を上げる動作で、移動の意味にならず不自然。", "泣いて": "泣くは涙を流す動作で、戦闘機の移動の文には合わない。"}, "sentence_index": 6, "correct_answer": "飛んで"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "面接で緊張が一気に飛んで、すらすら答えられた。", "explanation": "ここは〈消える〉の意味。緊張がなくなる様子で、空中を進む〈飛ぶ〉とは違うので合わない。"}, {"text": "雷の日、家の鍵が飛んで、扉が開いた。", "explanation": "ここは〈解錠する〉の意味。〈飛ぶ〉は空中を移動することなので、鍵を回す動作には合わない。"}, {"text": "猫が窓辺でじっと飛んで、日なたを楽しんだ。", "explanation": "ここは〈座る〉の意味。〈飛ぶ〉は空中を進むことなので、じっと腰を下ろす様子には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab34d665-f01a-4eba-b5e8-9aab20d6c140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37555, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "コウノトリは大きな翼を広げて、空高く飛ぶている。", "corrected_sentence": "コウノトリは大きな翼を広げて、空高く飛んでいる。", "error_description": "「飛んでいる」の「飛んで」（て形）が正しい。「飛ぶている」は〈飛ぶ＋ている〉の活用ミスで、「飛んでいる」の形にならない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "飛べる", "is_correct": true, "explanation": "可能形。「〜できる」の意味で、「遠くまで飛べる」の形に合う。"}, {"text": "飛んで", "is_correct": false, "explanation": "て形。後ろに続く形で、文末の可能の意味は表せない。"}, {"text": "飛ぼう", "is_correct": false, "explanation": "意向形。「〜しよう」の意志を表し、事実を述べる文には合わない。"}, {"text": "飛ばない", "is_correct": false, "explanation": "ない形。否定になり、可能の意味を表せない。"}], "correct_form": "飛べる", "base_form": "飛ぶ", "form_label": "可能形", "sentence_index": 1, "explanations": {"飛べる": "可能形。「〜できる」の意味で、「遠くまで飛べる」の形に合う。", "飛んで": "て形。後ろに続く形で、文末の可能の意味は表せない。", "飛ぼう": "意向形。「〜しよう」の意志を表し、事実を述べる文には合わない。", "飛ばない": "ない形。否定になり、可能の意味を表せない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab34d665-f01a-4eba-b5e8-9aab20d6c140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37555, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "トンビは山の上を飛ぶながら、えさを探す。", "corrected_sentence": "トンビは山の上を飛びながら、えさを探す。", "error_description": "「飛びながら」の「飛び」（連用形）が正しい。「飛ぶながら」は〈ながら〉の前に連用形が来ないため誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "飛んで", "is_correct": true, "explanation": "「飛んでいる」の形（て形）。後ろの「いる」に続く形で文に合う。"}, {"text": "飛びたい", "is_correct": false, "explanation": "たい形。「〜したい」の意味になり、「飛んでいる」の形ではない。"}, {"text": "飛びながら", "is_correct": false, "explanation": "ながら形。同時動作を表すが、「飛んでいる」の形にはならない。"}, {"text": "飛べない", "is_correct": false, "explanation": "ない形（可能の否定）。飛んでいる状態を表せず、文の形と合わない。"}], "correct_form": "飛んで", "base_form": "飛ぶ", "form_label": "て形", "sentence_index": 7, "explanations": {"飛んで": "「飛んでいる」の形（て形）。後ろの「いる」に続く形で文に合う。", "飛びたい": "たい形。「〜したい」の意味になり、「飛んでいる」の形ではない。", "飛びながら": "ながら形。同時動作を表すが、「飛んでいる」の形にはならない。", "飛べない": "ない形（可能の否定）。飛んでいる状態を表せず、文の形と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab34d665-f01a-4eba-b5e8-9aab20d6c140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37556, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「翼に」の「に」。雪が付いている場所を示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」。「ついている」は目的語を取らないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段を示す「で」。付着の場所を表す文の形にはならず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」。付着の場所としては合わない。"}], "correct_answer": "に", "explanations": {"に": "「翼に」の「に」。雪が付いている場所を示す。", "を": "目的語の「を」。「ついている」は目的語を取らないので合わない。", "で": "手段を示す「で」。付着の場所を表す文の形にはならず、不自然。", "へ": "方向を示す「へ」。付着の場所としては合わない。"}, "error_tags": {"を": "目的語", "で": "手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab34d665-f01a-4eba-b5e8-9aab20d6c140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37556, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語の「を」。「翼を休めて」で、休める動作の対象を示す。"}, {"text": "に", "is_correct": false, "explanation": "場所や相手を示す「に」。「翼に休める」では動作の対象にならず合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示す「と」。「翼と休める」では成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」。「翼から休める」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "目的語の「を」。「翼を休めて」で、休める動作の対象を示す。", "に": "場所や相手を示す「に」。「翼に休める」では動作の対象にならず合わない。", "と": "並列や相手を示す「と」。「翼と休める」では成り立たない。", "から": "起点を示す「から」。「翼から休める」は意味が通らない。"}, "error_tags": {"に": "場所・相手", "と": "並列・相手", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab34d665-f01a-4eba-b5e8-9aab20d6c140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37556, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "とりや　ひこうきの　からだの　りょうがわに　ある　はねのことです。", "primary_collocate": null, "pronunciation": "つばさ", "ipa": "tsɯbasa", "syllable_count": 3, "sentences": [{"text": "鳥の翼は大きくてきれいです。", "target_word": "翼", "complexity_tier": "T3", "furigana": "鳥[とり]の翼[つばさ]は大[おお]きくてきれいです。", "sentence_source": "generated"}, {"text": "飛行機の翼に雪がついています。", "target_word": "翼", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]の翼[つばさ]に雪[ゆき]がついています。", "sentence_source": "generated"}, {"text": "ひな鳥は小さな翼を動かしました。", "target_word": "翼", "complexity_tier": "T3", "furigana": "ひな鳥[どり]は小[ちい]さな翼[つばさ]を動[うご]かしました。", "sentence_source": "generated"}, {"text": "鳥は翼を広げて、空へ飛んでいきました。", "target_word": "翼", "complexity_tier": "T3", "furigana": "鳥[とり]は翼[つばさ]を広[ひろ]げて、空[そら]へ飛[と]んでいきました。", "sentence_source": "generated"}, {"text": "白い翼をもつ鳥が池にいます。", "target_word": "翼", "complexity_tier": "T3", "furigana": "白[しろ]い翼[つばさ]をもつ鳥[とり]が池[いけ]にいます。", "sentence_source": "generated"}, {"text": "雨にぬれて、鳥の翼が重くなりました。", "target_word": "翼", "complexity_tier": "T3", "furigana": "雨[あめ]にぬれて、鳥[とり]の翼[つばさ]が重[おも]くなりました。", "sentence_source": "generated"}, {"text": "この模型の飛行機は、翼が青いです。", "target_word": "翼", "complexity_tier": "T3", "furigana": "この模型[もけい]の飛行機[ひこうき]は、翼[つばさ]が青[あお]いです。", "sentence_source": "generated"}, {"text": "鳥は翼を休めて、木の上でじっとしています。", "target_word": "翼", "complexity_tier": "T3", "furigana": "鳥[とり]は翼[つばさ]を休[やす]めて、木[き]の上[うえ]でじっとしています。", "sentence_source": "generated"}, {"text": "けがをした鳥は、翼がうまく動きませんでした。", "target_word": "翼", "complexity_tier": "T3", "furigana": "けがをした鳥[とり]は、翼[つばさ]がうまく動[うご]きませんでした。", "sentence_source": "generated"}, {"text": "窓から飛行機の翼が見えます。", "target_word": "翼", "complexity_tier": "T3", "furigana": "窓[まど]から飛行機[ひこうき]の翼[つばさ]が見[み]えます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "翼", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "鳥や飛行機の体の両側にある羽(翼・つばさ)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T2: contains vocabulary far above tier T2: ひな鳥 (Zipf 2.0)']::text[], '6d21cf5d-f729-4c5e-b9cd-2c0746b4a406') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37556, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "翼", "is_correct": true, "explanation": "鳥の体の左右にある部分を指し、「鳥の翼は大きくてきれいです」が成り立つ。"}, {"text": "空", "is_correct": false, "explanation": "空は鳥の体の部分ではないため、「鳥の空は大きくて」では意味が通らない。"}, {"text": "池", "is_correct": false, "explanation": "池は鳥の体の部分ではないため、「鳥の池は大きくて」は合わない。"}, {"text": "風", "is_correct": false, "explanation": "風は体の部分ではないため、「鳥の風は大きくて」は成り立たない。"}], "explanations": {"翼": "鳥の体の左右にある部分を指し、「鳥の翼は大きくてきれいです」が成り立つ。", "空": "空は鳥の体の部分ではないため、「鳥の空は大きくて」では意味が通らない。", "池": "池は鳥の体の部分ではないため、「鳥の池は大きくて」は合わない。", "風": "風は体の部分ではないため、「鳥の風は大きくて」は成り立たない。"}, "sentence_index": 0, "correct_answer": "翼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "魚が翼を動かして、ゆっくり泳いだ。", "explanation": "ここは〈ひれ〉の意味。魚の体の部分は〈翼〉とは言わないので合わない。"}, {"text": "子どもが帰ってくると、犬は翼を振って迎えた。", "explanation": "ここは〈尾〉（しっぽ）の意味。犬の体の部分には〈翼〉を使わないので合わない。"}, {"text": "寒かったので、彼は首に翼を巻いた。", "explanation": "ここは〈マフラー〉（首に巻く布）の意味。体の左右の部分である〈翼〉とは違うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab34d665-f01a-4eba-b5e8-9aab20d6c140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37556, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "翼", "is_correct": true, "explanation": "「翼が青いです」の主語になる部分で、模型の飛行機の一部として文が成り立つ。"}, {"text": "名前", "is_correct": false, "explanation": "名前は色を表せないため、「名前が青いです」は意味が通らない。"}, {"text": "値段", "is_correct": false, "explanation": "値段は色を持たないので、「値段が青いです」は成り立たない。"}, {"text": "形", "is_correct": false, "explanation": "形は色の主語にならず、「形が青いです」は不自然。"}], "explanations": {"翼": "「翼が青いです」の主語になる部分で、模型の飛行機の一部として文が成り立つ。", "名前": "名前は色を表せないため、「名前が青いです」は意味が通らない。", "値段": "値段は色を持たないので、「値段が青いです」は成り立たない。", "形": "形は色の主語にならず、「形が青いです」は不自然。"}, "sentence_index": 6, "correct_answer": "翼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朝になって、彼は玄関の翼を開けた。", "explanation": "ここは〈扉〉の意味。体の左右の部分である〈翼〉とは違うので合わない。"}, {"text": "船は翼に風を受けて進んだ。", "explanation": "ここは〈帆〉（船の布の部分）の意味。船の布を〈翼〉と言うと合わない。"}, {"text": "庭に一枚の翼が落ちていた。", "explanation": "ここは〈羽〉（鳥の体から抜けた一枚のもの）の意味。翼は体の左右にある大きな部分なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab34d665-f01a-4eba-b5e8-9aab20d6c140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37556, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ワシの翼を大きくてきれいです。", "corrected_sentence": "ワシの翼は大きくてきれいです。", "error_description": "「翼は大きくてきれいです」の「は」（主題）が正しい。「翼を」は目的語を示すため、形容詞の主題にはならず文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab34d665-f01a-4eba-b5e8-9aab20d6c140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37556, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どもが模型の飛行機の翼を塗るた。", "corrected_sentence": "子どもが模型の飛行機の翼を塗った。", "error_description": "「塗った」が正しい。「塗るた」は〈塗る〉に〈た〉を直接続けた誤りで、過去の形「塗った」になっていない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab34d665-f01a-4eba-b5e8-9aab20d6c140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37557, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題の「は」。「飛行機の翼は」と話題を示し、機体の左右にあると述べる。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」。「ついている」は目的語を取らないので、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」。主題を示す位置では意味が合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」。翼を起点とする意味にならず、文が通らない。"}], "correct_answer": "は", "explanations": {"は": "主題の「は」。「飛行機の翼は」と話題を示し、機体の左右にあると述べる。", "を": "目的語の「を」。「ついている」は目的語を取らないので、文が成り立たない。", "へ": "方向の「へ」。主題を示す位置では意味が合わない。", "から": "起点の「から」。翼を起点とする意味にならず、文が通らない。"}, "error_tags": {"を": "目的語", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab34d665-f01a-4eba-b5e8-9aab20d6c140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37557, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "比較の相手を示す「と」。「鳥の翼とは」で比べる相手を示す。"}, {"text": "に", "is_correct": false, "explanation": "場所や相手を示す「に」。比べる相手としては文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す「で」。比べる相手にはならず、文が通らない。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」。二つ目の主語になり、「形がちがう」の文構造が崩れる。"}], "correct_answer": "と", "explanations": {"と": "比較の相手を示す「と」。「鳥の翼とは」で比べる相手を示す。", "に": "場所や相手を示す「に」。比べる相手としては文が成り立たない。", "で": "手段や場所を示す「で」。比べる相手にはならず、文が通らない。", "が": "主語の「が」。二つ目の主語になり、「形がちがう」の文構造が崩れる。"}, "error_tags": {"に": "場所・相手", "で": "手段・場所", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab34d665-f01a-4eba-b5e8-9aab20d6c140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37557, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "鳥や飛行機などの体の左右にあり、空を飛ぶために使う部分。", "primary_collocate": null, "pronunciation": "つばさ", "ipa": "tsɯbasa", "syllable_count": 3, "sentences": [{"text": "鳥は翼を使って、空を飛ぶ。", "target_word": "翼", "complexity_tier": "T3", "furigana": "鳥[とり]は翼[つばさ]を使[つか]って、空[そら]を飛[と]ぶ。", "sentence_source": "generated"}, {"text": "飛行機の翼は、機体の左右についている。", "target_word": "翼", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]の翼[つばさ]は、機体[きたい]の左右[さゆう]についている。", "sentence_source": "generated"}, {"text": "片方の翼を痛めた鳥は、飛ぶことができない。", "target_word": "翼", "complexity_tier": "T3", "furigana": "片方[かたほう]の翼[つばさ]を痛[いた]めた鳥[とり]は、飛[と]ぶことができない。", "sentence_source": "generated"}, {"text": "翼が大きい鳥ほど、長い時間飛べる。", "target_word": "翼", "complexity_tier": "T3", "furigana": "翼[つばさ]が大[おお]きい鳥[とり]ほど、長[なが]い時間[じかん]飛[と]べる。", "sentence_source": "generated"}, {"text": "ハヤブサは翼を折りたたんで、一気に降りてきた。", "target_word": "翼", "complexity_tier": "T3", "furigana": "ハヤブサは翼[つばさ]を折[お]りたたんで、一気[いっき]に降[お]りてきた。", "sentence_source": "generated"}, {"text": "飛行機は翼で風を受けて、空に浮かぶ。", "target_word": "翼", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]は翼[つばさ]で風[かぜ]を受[う]けて、空[そら]に浮[う]かぶ。", "sentence_source": "generated"}, {"text": "ペンギンの翼は短く、空を飛ぶには向かない。", "target_word": "翼", "complexity_tier": "T3", "furigana": "ペンギンの翼[つばさ]は短[みじか]く、空[そら]を飛[と]ぶには向[む]かない。", "sentence_source": "generated"}, {"text": "コウモリの翼は、鳥の翼とは形がちがう。", "target_word": "翼", "complexity_tier": "T3", "furigana": "コウモリの翼[つばさ]は、鳥[とり]の翼[つばさ]とは形[かたち]がちがう。", "sentence_source": "generated"}, {"text": "翼を広げると三メートルもある鳥がいる。", "target_word": "翼", "complexity_tier": "T3", "furigana": "翼[つばさ]を広[ひろ]げると三[さん]メートルもある鳥[とり]がいる。", "sentence_source": "generated"}, {"text": "整備士が、飛行機の翼を丁寧に点検している。", "target_word": "翼", "complexity_tier": "T3", "furigana": "整備士[せいびし]が、飛行機[ひこうき]の翼[つばさ]を丁寧[ていねい]に点検[てんけん]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "翼", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "空を飛ぶために使う、体の左右にある部分(翼・つばさ)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T2: contains vocabulary far above tier T2: 折りたたん (Zipf 2.39)']::text[], '6d21cf5d-f729-4c5e-b9cd-2c0746b4a406') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37557, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "翼", "is_correct": true, "explanation": "空を飛ぶために使う体の部分。「翼を使って、空を飛ぶ」が成り立つ。"}, {"text": "地図", "is_correct": false, "explanation": "地図を使って空を飛ぶという文は、飛ぶための体の部分の意味にならず合わない。"}, {"text": "歌", "is_correct": false, "explanation": "歌は飛ぶための手段にならず、「歌を使って」は文の意味が通らない。"}, {"text": "雑誌", "is_correct": false, "explanation": "雑誌は飛ぶための手段にならず、「雑誌を使って」は意味が通らない。"}], "explanations": {"翼": "空を飛ぶために使う体の部分。「翼を使って、空を飛ぶ」が成り立つ。", "地図": "地図を使って空を飛ぶという文は、飛ぶための体の部分の意味にならず合わない。", "歌": "歌は飛ぶための手段にならず、「歌を使って」は文の意味が通らない。", "雑誌": "雑誌は飛ぶための手段にならず、「雑誌を使って」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "翼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は飛んできた石を、翼で受け止めた。", "explanation": "ここは〈手〉の意味。人の体の部分は〈翼〉とは言わないので合わない。"}, {"text": "山道を登るために、翼を使った。", "explanation": "ここは〈足〉の意味。山道を登る動きに〈翼〉を使うのは合わない。"}, {"text": "この病院は、患者のために翼を用意した。", "explanation": "ここは〈建物の別棟〉（建物の左右に張り出した部分）の意味。体の左右の部分である〈翼〉の義項とは違うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab34d665-f01a-4eba-b5e8-9aab20d6c140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37557, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "翼", "is_correct": true, "explanation": "ペンギンの体の左右にある部分。「ペンギンの翼は短く」が成り立つ。"}, {"text": "色", "is_correct": false, "explanation": "色は短いという状態の主語にならず、「ペンギンの色は短く」は意味が通らない。"}, {"text": "値段", "is_correct": false, "explanation": "値段は長さや短さを持たないので、「ペンギンの値段は短く」は合わない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は体の部分ではなく、「ペンギンの天気は短く」は成り立たない。"}], "explanations": {"翼": "ペンギンの体の左右にある部分。「ペンギンの翼は短く」が成り立つ。", "色": "色は短いという状態の主語にならず、「ペンギンの色は短く」は意味が通らない。", "値段": "値段は長さや短さを持たないので、「ペンギンの値段は短く」は合わない。", "天気": "天気は体の部分ではなく、「ペンギンの天気は短く」は成り立たない。"}, "sentence_index": 6, "correct_answer": "翼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女はドレスの翼を揺らして、舞台に出た。", "explanation": "ここは〈フリル〉（服の飾り）の意味。体の左右の部分である〈翼〉は服の飾りには使わないので合わない。"}, {"text": "犬が嬉しそうに翼を振っている。", "explanation": "ここは〈尾〉（しっぽ）の意味。犬の体の部分には〈翼〉を使わないので合わない。"}, {"text": "羽根つきの翼が風で飛ばされた。", "explanation": "ここは〈シャトルコック〉（打ち合う球）の意味。翼は体の左右にある大きな部分なので、球には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab34d665-f01a-4eba-b5e8-9aab20d6c140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37557, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ワシは翼で使って、空を飛ぶ。", "corrected_sentence": "ワシは翼を使って、空を飛ぶ。", "error_description": "「使う」の目的語には「を」が必要。「翼で使う」は「で」が誤りで、「翼を使って」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab34d665-f01a-4eba-b5e8-9aab20d6c140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37557, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ペンギンの翼を短いが、空を飛ぶには向かない。", "corrected_sentence": "ペンギンの翼は短いが、空を飛ぶには向かない。", "error_description": "「翼は」の「は」が正しい。「翼を」は目的語を示すため、「短い」の主題にはならず文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab34d665-f01a-4eba-b5e8-9aab20d6c140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37558, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「寝る」の場所を示す「で」なので、屋根の上で寝ているは自然。"}, {"text": "を", "is_correct": false, "explanation": "「寝る」は場所を「を」で取らない。屋根の上を寝ているは不自然。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す格。屋根の上が寝ているでは意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や共同を示す。屋根の上と寝ているでは文が成り立たない。"}], "correct_answer": "で", "explanations": {"で": "「寝る」の場所を示す「で」なので、屋根の上で寝ているは自然。", "を": "「寝る」は場所を「を」で取らない。屋根の上を寝ているは不自然。", "が": "「が」は主語を示す格。屋根の上が寝ているでは意味が通らない。", "と": "「と」は相手や共同を示す。屋根の上と寝ているでは文が成り立たない。"}, "error_tags": {"を": "目的語", "が": "主語", "と": "相手・共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37558, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「歩く」は通る場所を「を」で示すので、塀の上を歩いては自然。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す格。塀の上が歩いてでは意味が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ。塀の上の歩いてでは文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示す。塀の上より歩いてでは意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「歩く」は通る場所を「を」で示すので、塀の上を歩いては自然。", "が": "「が」は主語を示す格。塀の上が歩いてでは意味が成り立たない。", "の": "「の」は名詞をつなぐ。塀の上の歩いてでは文が成り立たない。", "より": "「より」は比較を示す。塀の上より歩いてでは意味が通らない。"}, "error_tags": {"が": "主語", "の": "連体修飾", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37558, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "うえは、たかいところのことです。", "primary_collocate": null, "pronunciation": "うえ", "ipa": "ɯe", "syllable_count": 2, "sentences": [{"text": "本は机の上にあります。", "target_word": "上", "complexity_tier": "T2", "furigana": "本[ほん]は机[つくえ]の上[うえ]にあります。", "sentence_source": "generated"}, {"text": "猫が屋根の上で寝ている。", "target_word": "上", "complexity_tier": "T2", "furigana": "猫[ねこ]が屋根[やね]の上[うえ]で寝[ね]ている。", "sentence_source": "generated"}, {"text": "山の上から町が見える。", "target_word": "上", "complexity_tier": "T2", "furigana": "山[やま]の上[うえ]から町[まち]が見[み]える。", "sentence_source": "generated"}, {"text": "鳥は木の上に巣を作った。", "target_word": "上", "complexity_tier": "T2", "furigana": "鳥[とり]は木[き]の上[うえ]に巣[す]を作[つく]った。", "sentence_source": "generated"}, {"text": "かばんを棚の上に置いてください。", "target_word": "上", "complexity_tier": "T2", "furigana": "かばんを棚[たな]の上[うえ]に置[お]いてください。", "sentence_source": "generated"}, {"text": "二階の部屋は、一階の部屋の上にある。", "target_word": "上", "complexity_tier": "T3", "furigana": "二階[にかい]の部屋[へや]は、一階[いっかい]の部屋[へや]の上[うえ]にある。", "sentence_source": "generated"}, {"text": "雲の上は、いつも晴れている。", "target_word": "上", "complexity_tier": "T2", "furigana": "雲[くも]の上[うえ]は、いつも晴[は]れている。", "sentence_source": "generated"}, {"text": "子どもが高い塀の上を歩いて、母は心配した。", "target_word": "上", "complexity_tier": "T3", "furigana": "子[こ]どもが高[たか]い塀[へい]の上[うえ]を歩[ある]いて、母[はは]は心配[しんぱい]した。", "sentence_source": "generated"}, {"text": "橋の上から、川の魚がよく見えた。", "target_word": "上", "complexity_tier": "T3", "furigana": "橋[はし]の上[うえ]から、川[かわ]の魚[さかな]がよく見[み]えた。", "sentence_source": "generated"}, {"text": "机の上が散らかっていたので、先に片づけた。", "target_word": "上", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]が散[ち]らかっていたので、先[さき]に片[かた]づけた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "上", "label": "基本形"}, {"form": "上に", "label": "に格"}, {"form": "上の", "label": "連体形"}, {"form": "上から", "label": "から格"}], "register": "neutral", "sense_fingerprint": "高いところ、物の上の方の位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf6ee224-92d2-4127-abed-56d8891d40e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37558, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上", "is_correct": true, "explanation": "「机の上」は机の表面の位置を表し、本の場所として文が自然に通る。"}, {"text": "歌", "is_correct": false, "explanation": "「机の歌」は場所を表せず、本の位置を述べる文が成り立たない。"}, {"text": "夢", "is_correct": false, "explanation": "「机の夢」は場所にならず、文の意味が通らない。"}, {"text": "色", "is_correct": false, "explanation": "「机の色」は場所を表さず、本がある位置の説明にならない。"}], "explanations": {"上": "「机の上」は机の表面の位置を表し、本の場所として文が自然に通る。", "歌": "「机の歌」は場所を表せず、本の位置を述べる文が成り立たない。", "夢": "「机の夢」は場所にならず、文の意味が通らない。", "色": "「机の色」は場所を表さず、本がある位置の説明にならない。"}, "sentence_index": 0, "correct_answer": "上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "三日の上で、彼は戻ってきた。", "explanation": "ここは〈〜後〉の意味。「三日後」の後を上に替えたもので、期間のあとを「三日の上」とは言わない。"}, {"text": "仕事の上が早い。", "explanation": "ここは〈上手〉の意味。「仕事が上手だ」の上手を上に替えたもので、「仕事の上が早い」とは言わない。"}, {"text": "一時間の上を待った。", "explanation": "ここは〈以上〉の意味。「一時間以上」の以上を上に替えたもので、「一時間の上」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37558, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上", "is_correct": true, "explanation": "「雲の上」は雲より上の空を指し、いつも晴れているという文と合う。"}, {"text": "音", "is_correct": false, "explanation": "「雲の音」は場所を表せず、いつも晴れているとも結びつかない。"}, {"text": "名前", "is_correct": false, "explanation": "「雲の名前は、いつも晴れている」は主語として成り立たず不自然。"}, {"text": "辞書", "is_correct": false, "explanation": "「雲の辞書」は意味をなさず、晴れている天気の話にならない。"}], "explanations": {"上": "「雲の上」は雲より上の空を指し、いつも晴れているという文と合う。", "音": "「雲の音」は場所を表せず、いつも晴れているとも結びつかない。", "名前": "「雲の名前は、いつも晴れている」は主語として成り立たず不自然。", "辞書": "「雲の辞書」は意味をなさず、晴れている天気の話にならない。"}, "sentence_index": 6, "correct_answer": "上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ピアノの上がうまくなった。", "explanation": "ここは〈上達〉の意味。「ピアノが上達した」の上達を上に替えたもので、「ピアノの上がうまくなった」とは言わない。"}, {"text": "この料理は上の味だ。", "explanation": "ここは〈上品〉の意味。「上品な味だ」の上品を上に替えたもので、「上の味」は料理の品質を表さない。"}, {"text": "猫が箱の上に入って寝ている。", "explanation": "ここは〈中〉の意味。「猫が箱の中に入って寝ている」の中を上に替えたもので、「入る」は内側に入る動作なので、物の上の位置とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37558, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ペンは机の上を置いてあります。", "corrected_sentence": "ペンは机の上に置いてあります。", "error_description": "「置く」は場所を「に」で示す。「上を」の「を」は誤りで、正しくは「上に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37558, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窓ガラスの上を、雨粒がいくつも残っていた。", "corrected_sentence": "窓ガラスの上に、雨粒がいくつも残っていた。", "error_description": "「残る」は場所を「に」で示す。「上を」の「を」は誤りで、正しくは「上に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
