INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37559, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物の位置が、下よりも高い方にあること。また、その方向や場所。", "primary_collocate": null, "pronunciation": "うえ", "ipa": "ɯe", "syllable_count": 2, "sentences": [{"text": "気候変動という地球的危機の緩和に向け、産業セクターにおける排出量の抑制は、持続可能性を担保する上で不可避の責務である。", "target_word": "上", "complexity_tier": "T5", "furigana": "気候変動(きこうへんどう)という地球的(ちきゅうてき)危機(きき)の緩和(かんわ)に向(む)け、産業(さんぎょう)セクターにおける排出量(はいしゅつりょう)の抑制(よくせい)は、持続可能性(じぞくかのうせい)を担保(たんぽ)する上(うえ)で不可避(ふかひ)の責務(せきむ)である。", "sentence_source": "mined"}, {"text": "再生可能エネルギーの導入加速にもかかわらず、製造プロセスの性質上、炭素発生をゼロ化し得ない領域において、CCUSは極めて重要な役割を担う。", "target_word": "上", "complexity_tier": "T5", "furigana": "再生可能(さいせいかのう)エネルギーの導入加速(どうにゅうかそく)にもかかわらず、製造(せいぞう)プロセスの性質上(せいしつじょう)、炭素発生(たんそはっせい)をゼロ化(か)し得(え)ない領域(りょういき)において、CCUSは極(きわ)めて重要(じゅうよう)な役割(やくわり)を担(にな)う。", "sentence_source": "mined"}, {"text": "力強く円を描くことで、言葉にできない思春期の焦燥感が、少しずつ紙の上へ溶け出していくようだった。", "target_word": "上", "complexity_tier": "T4", "furigana": "力強(ちからづよ)く円(えん)を描(えが)くことで、言葉(ことば)にできない思春期(ししゅんき)の焦燥感(しょうそうかん)が、少(すこ)しずつ紙(かみ)の上(うえ)へ溶(と)け出(だ)していくようだった。", "sentence_source": "mined"}, {"text": "この製作の全工程は、まさに宇宙の理を机の上に縮図として描き出す、崇高な知的探究なのである。", "target_word": "上", "complexity_tier": "T5", "furigana": "この製作(せいさく)の全工程(ぜんこうてい)は、まさに宇宙(うちゅう)の理(ことわり)を机(つくえ)の上(うえ)に縮図(しゅくず)として描(えが)き出(だ)す、崇高(すうこう)な知的探究(ちてきたんきゅう)なのである。", "sentence_source": "mined"}, {"text": "机の上に古い地図が広げてあったので、旅の計画がすぐに分かった。", "target_word": "上", "complexity_tier": "T2", "furigana": "机(つくえ)の上(うえ)に古(ふる)い地図(ちず)が広(ひろ)げてあったので、旅(たび)の計画(けいかく)がすぐに分(わ)かった。", "sentence_source": "generated"}, {"text": "猫は棚の上で丸くなって、午後の日差しを浴びていた。", "target_word": "上", "complexity_tier": "T2", "furigana": "猫(ねこ)は棚(たな)の上(うえ)で丸(まる)くなって、午後(ごご)の日差(ひざ)しを浴(あ)びていた。", "sentence_source": "generated"}, {"text": "屋根の上に雪が積もっていたため、父は朝早くからはしごで雪下ろしをした。", "target_word": "上", "complexity_tier": "T3", "furigana": "屋根(やね)の上(うえ)に雪(ゆき)が積(つ)もっていたため、父(ちち)は朝早(あさはや)くからはしごで雪下(ゆきお)ろしをした。", "sentence_source": "generated"}, {"text": "地図では、北が上、南が下になっていることが多い。", "target_word": "上", "complexity_tier": "T2", "furigana": "地図(ちず)では、北(きた)が上(うえ)、南(みなみ)が下(した)になっていることが多(おお)い。", "sentence_source": "generated"}, {"text": "山の上は空気が冷たいので、夏でも厚いセーターが必要だ。", "target_word": "上", "complexity_tier": "T3", "furigana": "山(やま)の上(うえ)は空気(くうき)が冷(つめ)たいので、夏(なつ)でも厚(あつ)いセーターが必要(ひつよう)だ。", "sentence_source": "generated"}, {"text": "彼は本をいちばん上の段に置いたが、背の低い妹には届かなかった。", "target_word": "上", "complexity_tier": "T3", "furigana": "彼(かれ)は本(ほん)をいちばん上(うえ)の段(だん)に置(お)いたが、背(せ)の低(ひく)い妹(いもうと)には届(とど)かなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "上", "label": "基本形"}, {"form": "上に", "label": "に格"}, {"form": "上の", "label": "連体修飾(の)"}], "register": "neutral", "sense_fingerprint": "位置が高い方・上方の場所を表す名詞(うえ)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 6 words above tier T1 (max 2): セクター (Zipf 3.53), 排出 (Zipf 3.98), 持続 (Zipf 3.94), 担保 (Zipf 3.83), 不可避 (Zipf 3.57), 責務 (Zipf 3.42)','sentence 2 above tier T1: 3 words above tier T1 (max 2): 力強く (Zipf 3.37), 思春 (Zipf 3.69), 焦燥 (Zipf 2.87)','sentence 3 above tier T1: contains vocabulary far above tier T1: 描き出す (Zipf 2.48)','sentence 6 above tier T1: contains vocabulary far above tier T1: 雪下ろし (Zipf 1.97)']::text[], '08e7e9f6-0f05-455b-afc5-ee87762d7379') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37559, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上", "is_correct": true, "explanation": "「机の上に」の「上」。机の表面という場所を表し、「古い地図が広げてあった」と自然につながる。"}, {"text": "窓", "is_correct": false, "explanation": "「机の窓に古い地図が広げてあった」は場所として成り立たず、意味が通らない。"}, {"text": "色", "is_correct": false, "explanation": "「机の色に…」は場所を表さず、文が成り立たない。"}, {"text": "数", "is_correct": false, "explanation": "「机の数に…」は場所を表さず、意味が通らない。"}], "explanations": {"上": "「机の上に」の「上」。机の表面という場所を表し、「古い地図が広げてあった」と自然につながる。", "窓": "「机の窓に古い地図が広げてあった」は場所として成り立たず、意味が通らない。", "色": "「机の色に…」は場所を表さず、文が成り立たない。", "数": "「机の数に…」は場所を表さず、意味が通らない。"}, "sentence_index": 0, "correct_answer": "上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "箱の上に、古い手紙が入っている。", "explanation": "〈中〉の意味。容器の内側は「中」で、「上」は上方を指すので内部の位置には使えない。"}, {"text": "会議の上に、食事をします。", "explanation": "〈後〉の意味。会議の後を表すには「後」を使い、「上」では合わない。"}, {"text": "明日の上に会議がある。", "explanation": "〈前〉の意味。時間の前後には「前」を使い、「上」は時間には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64e7d4f9-aee5-437b-a6be-eb6c0a13dc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37559, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上", "is_correct": true, "explanation": "「屋根の上」の「上」。屋根の上方を示し、雪が積もる場所として合う。"}, {"text": "本", "is_correct": false, "explanation": "「屋根の本に雪が積もる」は場所を示さず、意味が通らない。"}, {"text": "音", "is_correct": false, "explanation": "「屋根の音に雪が積もる」は場所を示さず、文として成り立たない。"}, {"text": "歌", "is_correct": false, "explanation": "「屋根の歌に雪が積もる」は場所を表さず、文として成り立たない。"}], "explanations": {"上": "「屋根の上」の「上」。屋根の上方を示し、雪が積もる場所として合う。", "本": "「屋根の本に雪が積もる」は場所を示さず、意味が通らない。", "音": "「屋根の音に雪が積もる」は場所を示さず、文として成り立たない。", "歌": "「屋根の歌に雪が積もる」は場所を表さず、文として成り立たない。"}, "sentence_index": 6, "correct_answer": "上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地下室は、一階の上にある。", "explanation": "〈下〉の意味。地下は一階より下にあるので、「上」では位置が逆になる。"}, {"text": "ポストは、建物の上の裏に置いてある。", "explanation": "〈裏〉の意味。建物の背面は「裏」と言い、「上」では位置が合わない。"}, {"text": "向かいの家は、私の家の上にある。", "explanation": "〈隣〉の意味。並んだ家は「隣」と言い、同じ高さの家を「上」で言うと位置が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64e7d4f9-aee5-437b-a6be-eb6c0a13dc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37559, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この地域は大雨の後に川の水位が上げるので注意が必要だ。", "corrected_sentence": "この地域は大雨の後に川の水位が上がるので注意が必要だ。", "error_description": "動詞の誤り。「水位が」に続くのは自動詞の「上がる」が正しく、他動詞の「上げる」は「水位を上げる」の形で使う。", "correct_sentence_indices": [2, 4, 5]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64e7d4f9-aee5-437b-a6be-eb6c0a13dc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37559, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "机の上を本が置いてある。", "corrected_sentence": "机の上に本が置いてある。", "error_description": "格助詞の誤り。「上」に続けて場所を示すには「に」が正しく、「を」は目的語になるので「置いてある」の場所を示せない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64e7d4f9-aee5-437b-a6be-eb6c0a13dc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37560, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「手を上げる」の「を」で、上げる対象の手を示す。"}, {"text": "が", "is_correct": false, "explanation": "「手が」は主語を示すため、手を持ち上げる対象にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「手へ」は方向を示すが、「手へ上げる」は不自然で対象を示せない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すが、「手から上げる」は手が出発点になり意味が合わない。"}], "correct_answer": "を", "explanations": {"を": "「手を上げる」の「を」で、上げる対象の手を示す。", "が": "「手が」は主語を示すため、手を持ち上げる対象にはならない。", "へ": "「手へ」は方向を示すが、「手へ上げる」は不自然で対象を示せない。", "から": "「から」は起点を示すが、「手から上げる」は手が出発点になり意味が合わない。"}, "error_tags": {"が": "主語", "へ": "方向", "から": "起点"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下げる", "is_correct": true, "explanation": "「上げる」の対義語。物を低い方へ移すこと。"}, {"text": "押す", "is_correct": false, "explanation": "「押す」は力を加えて動かす意味で、上下の対義語ではない。"}, {"text": "置く", "is_correct": false, "explanation": "「置く」は物を一定の場所に据える意味で、上げるの対義語ではない。"}, {"text": "寄せる", "is_correct": false, "explanation": "「寄せる」は近くへ移す意味で、上下の対義語ではない。"}], "correct_answer": "下げる", "explanations": {"下げる": "「上げる」の対義語。物を低い方へ移すこと。", "押す": "「押す」は力を加えて動かす意味で、上下の対義語ではない。", "置く": "「置く」は物を一定の場所に据える意味で、上げるの対義語ではない。", "寄せる": "「寄せる」は近くへ移す意味で、上下の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37560, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「上げると」の「と」で、条件を表す。"}, {"text": "に", "is_correct": false, "explanation": "「上げるに」は接続せず、条件を表す「と」が必要。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段を示すが、「上げるで」は条件節にならない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、動詞の終止形に直接続かない。"}], "correct_answer": "と", "explanations": {"と": "「上げると」の「と」で、条件を表す。", "に": "「上げるに」は接続せず、条件を表す「と」が必要。", "で": "「で」は手段を示すが、「上げるで」は条件節にならない。", "を": "「を」は目的語を示すが、動詞の終止形に直接続かない。"}, "error_tags": {"に": "接続", "で": "手段", "を": "目的語"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下げる", "is_correct": true, "explanation": "「上げる」の対義語。釣り竿などを低い方へ移すこと。"}, {"text": "引く", "is_correct": false, "explanation": "「引く」は手前へ力を加えて動かす意味で、上下の対義語ではない。"}, {"text": "広げる", "is_correct": false, "explanation": "「広げる」は範囲や面積を大きくする意味で、上下の対義語ではない。"}, {"text": "運ぶ", "is_correct": false, "explanation": "「運ぶ」は場所を移す意味で、上下の対義語ではない。"}], "correct_answer": "下げる", "explanations": {"下げる": "「上げる」の対義語。釣り竿などを低い方へ移すこと。", "引く": "「引く」は手前へ力を加えて動かす意味で、上下の対義語ではない。", "広げる": "「広げる」は範囲や面積を大きくする意味で、上下の対義語ではない。", "運ぶ": "「運ぶ」は場所を移す意味で、上下の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37560, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものを上に動かすこと。", "primary_collocate": null, "pronunciation": "あげる", "ipa": "aɡeɾɯ", "syllable_count": 3, "sentences": [{"text": "重い箱を棚の上に上げるのは大変だ。", "target_word": "上げる", "complexity_tier": "T3", "furigana": "重[おも]い箱[はこ]を棚[たな]の上[うえ]に上[あ]げるのは大変[たいへん]だ。", "sentence_source": "generated"}, {"text": "質問があるときは、手を上げてください。", "target_word": "上げて", "complexity_tier": "T3", "furigana": "質問[しつもん]があるときは、手[て]を上[あ]げてください。", "sentence_source": "generated"}, {"text": "運動会の朝、校庭で旗を上げた。", "target_word": "上げた", "complexity_tier": "T3", "furigana": "運動会[うんどうかい]の朝[あさ]、校庭[こうてい]で旗[はた]を上[あ]げた。", "sentence_source": "generated"}, {"text": "暑いので、ブラインドを上げて風を入れた。", "target_word": "上げて", "complexity_tier": "T3", "furigana": "暑[あつ]いので、ブラインドを上[あ]げて風[かぜ]を入[い]れた。", "sentence_source": "generated"}, {"text": "後ろの人にも見えるように、看板を高く上げた。", "target_word": "上げた", "complexity_tier": "T3", "furigana": "後[うし]ろの人[ひと]にも見[み]えるように、看板[かんばん]を高[たか]く上[あ]げた。", "sentence_source": "generated"}, {"text": "彼は顔を上げて、空を見た。", "target_word": "上げて", "complexity_tier": "T3", "furigana": "彼[かれ]は顔[かお]を上[あ]げて、空[そら]を見[み]た。", "sentence_source": "generated"}, {"text": "車の下を調べるため、車をジャッキで上げます。", "target_word": "上げます", "complexity_tier": "T3", "furigana": "車[くるま]の下[した]を調[しら]べるため、車[くるま]をジャッキで上[あ]げます。", "sentence_source": "generated"}, {"text": "幕を上げると、舞台には花が飾ってあった。", "target_word": "上げる", "complexity_tier": "T3", "furigana": "幕[まく]を上[あ]げると、舞台[ぶたい]には花[はな]が飾[かざ]ってあった。", "sentence_source": "generated"}, {"text": "足を上げて、道の段差をまたいだ。", "target_word": "上げて", "complexity_tier": "T3", "furigana": "足[あし]を上[あ]げて、道[みち]の段差[だんさ]をまたいだ。", "sentence_source": "generated"}, {"text": "釣り竿を上げたら、大きな魚がかかっていた。", "target_word": "上げた", "complexity_tier": "T3", "furigana": "釣[つ]り竿[ざお]を上[あ]げたら、大[おお]きな魚[さかな]がかかっていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "上げる", "label": "終止形"}, {"form": "上げます", "label": "丁寧形"}, {"form": "上げた", "label": "過去形"}, {"form": "上げて", "label": "て形"}, {"form": "上げない", "label": "否定形"}, {"form": "上げれば", "label": "仮定形"}, {"form": "上げよう", "label": "意志形"}], "register": "中立", "sense_fingerprint": "手・旗・幕・顔など具体的なものを上の方へ動かす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68b8a0b9-d581-49d2-8aa6-b2f3d6bfbb8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37560, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上げる", "is_correct": true, "explanation": "「棚の上に物を移す」意味で、「棚の上に〜のは大変だ」と自然につながる。"}, {"text": "浴びる", "is_correct": false, "explanation": "「浴びる」は液体や光を体に受ける意味で、箱を棚に移す文には入らない。"}, {"text": "割る", "is_correct": false, "explanation": "「割る」は物を壊して分ける意味で、箱を棚に移す動作とは合わない。"}, {"text": "眠る", "is_correct": false, "explanation": "「眠る」は寝る動作を表し、物を棚へ移す文の空所には続かない。"}], "explanations": {"上げる": "「棚の上に物を移す」意味で、「棚の上に〜のは大変だ」と自然につながる。", "浴びる": "「浴びる」は液体や光を体に受ける意味で、箱を棚に移す文には入らない。", "割る": "「割る」は物を壊して分ける意味で、箱を棚に移す動作とは合わない。", "眠る": "「眠る」は寝る動作を表し、物を棚へ移す文の空所には続かない。"}, "sentence_index": 0, "correct_answer": "上げる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "カップに紅茶を上げた。", "explanation": "ここは〈注ぐ〉の意味。液体を容器に入れる動作は〈上げる〉では言わない。"}, {"text": "壁に絵を上げた。", "explanation": "ここは〈掛ける〉の意味。壁に物を引っかけて留める動作は〈上げる〉では表せない。"}, {"text": "コンセントにプラグを上げた。", "explanation": "ここは〈差し込む〉の意味。穴に差し入れる動作は〈上げる〉では言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37560, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上げます", "is_correct": true, "explanation": "ジャッキで車を持ち上げる意味で、丁寧形が文末に合う。"}, {"text": "咲きます", "is_correct": false, "explanation": "「咲く」は花などが開く意味で、ジャッキで車を扱う文には合わない。"}, {"text": "凍ります", "is_correct": false, "explanation": "「凍る」は冷えて固まる意味で、車を持ち上げる文には入らない。"}, {"text": "叫びます", "is_correct": false, "explanation": "「叫ぶ」は大声を出す意味で、物を対象に取る文には続かない。"}], "explanations": {"上げます": "ジャッキで車を持ち上げる意味で、丁寧形が文末に合う。", "咲きます": "「咲く」は花などが開く意味で、ジャッキで車を扱う文には合わない。", "凍ります": "「凍る」は冷えて固まる意味で、車を持ち上げる文には入らない。", "叫びます": "「叫ぶ」は大声を出す意味で、物を対象に取る文には続かない。"}, "sentence_index": 6, "correct_answer": "上げます"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "玄関のドアの鍵を上げた。", "explanation": "ここは〈鍵をかける（施錠する）〉の意味。鍵を閉める動作は〈上げる〉では言わない。"}, {"text": "天井から風鈴を上げた。", "explanation": "ここは〈吊るす〉の意味。天井からぶら下げる動作は〈上げる〉では表せない。"}, {"text": "本のページに栞を上げた。", "explanation": "ここは〈挟む〉の意味。ページの間に差し入れる動作は〈上げる〉では言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37560, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窓のブラインドを上げれて、部屋に光を入れた。", "corrected_sentence": "窓のブラインドを上げて、部屋に光を入れた。", "error_description": "正しくは「上げて」（て形）。「上げれて」は「上げる」の活用として存在せず、「れ」が余分に入っている誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "上げて", "is_correct": true, "explanation": "て形で、「手を上げてください」と依頼の文につながる。"}, {"text": "上げない", "is_correct": false, "explanation": "「上げないください」は依頼の形として成り立たず、否定の依頼には「上げないでください」が必要。"}, {"text": "上げます", "is_correct": false, "explanation": "丁寧形は「ください」と直接続かず、「上げますください」は不自然。"}, {"text": "上げよう", "is_correct": false, "explanation": "意志形は依頼の文に入らず、「上げようください」は成り立たない。"}], "correct_form": "上げて", "base_form": "上げる", "form_label": "て形", "sentence_index": 1, "explanations": {"上げて": "て形で、「手を上げてください」と依頼の文につながる。", "上げない": "「上げないください」は依頼の形として成り立たず、否定の依頼には「上げないでください」が必要。", "上げます": "丁寧形は「ください」と直接続かず、「上げますください」は不自然。", "上げよう": "意志形は依頼の文に入らず、「上げようください」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37560, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ブラインドを上げるで、部屋が明るくなった。", "corrected_sentence": "ブラインドを上げると、部屋が明るくなった。", "error_description": "正しくは「上げると」（条件の「と」）。「上げるで」は「で」が誤りで、動詞に続けて条件を表すには「と」が必要。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "上げる", "is_correct": true, "explanation": "「幕を上げると」の辞書形で、条件の「と」に直接続く。"}, {"text": "上げて", "is_correct": false, "explanation": "て形は「と」に続かず、「上げてと」は文が成り立たない。"}, {"text": "上げた", "is_correct": false, "explanation": "「上げたと」は条件の表現として不自然で、「上げたら」などが必要。"}, {"text": "上げれば", "is_correct": false, "explanation": "ば形は「と」と重ならず、「上げればと」は成り立たない。"}], "correct_form": "上げる", "base_form": "上げる", "form_label": "辞書形", "sentence_index": 7, "explanations": {"上げる": "「幕を上げると」の辞書形で、条件の「と」に直接続く。", "上げて": "て形は「と」に続かず、「上げてと」は文が成り立たない。", "上げた": "「上げたと」は条件の表現として不自然で、「上げたら」などが必要。", "上げれば": "ば形は「と」と重ならず、「上げればと」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37561, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「上げると」の「と」で、発表の内容（引き上げること）を示す。"}, {"text": "が", "is_correct": false, "explanation": "「上げるが」は逆接の接続になり、「と」の位置に入らず文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「上げへ」は方向を示すが、発表の文には合わない。"}, {"text": "を", "is_correct": false, "explanation": "「上げるを」は動詞に直接続かず、目的語としても成り立たない。"}], "correct_answer": "と", "explanations": {"と": "「上げると」の「と」で、発表の内容（引き上げること）を示す。", "が": "「上げるが」は逆接の接続になり、「と」の位置に入らず文が成り立たない。", "へ": "「上げへ」は方向を示すが、発表の文には合わない。", "を": "「上げるを」は動詞に直接続かず、目的語としても成り立たない。"}, "error_tags": {"が": "逆接", "へ": "方向", "を": "目的語"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下げる", "is_correct": true, "explanation": "「上げる」（程度を高くする）の対義語。速度などを低くすること。"}, {"text": "支える", "is_correct": false, "explanation": "「支える」は下から支持する意味で、上下の対義語ではない。"}, {"text": "止める", "is_correct": false, "explanation": "「止める」は動きを終わらせる意味で、程度を上下させる対義語ではない。"}, {"text": "倒す", "is_correct": false, "explanation": "「倒す」は横に傾けて動かす意味で、上下の対義語ではない。"}], "correct_answer": "下げる", "explanations": {"下げる": "「上げる」（程度を高くする）の対義語。速度などを低くすること。", "支える": "「支える」は下から支持する意味で、上下の対義語ではない。", "止める": "「止める」は動きを終わらせる意味で、程度を上下させる対義語ではない。", "倒す": "「倒す」は横に傾けて動かす意味で、上下の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37561, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「上げるの」で動作を名詞化し、「上げること」を表す。"}, {"text": "を", "is_correct": false, "explanation": "「上げるを」は目的語を示すが、動詞に直接続かない。"}, {"text": "に", "is_correct": false, "explanation": "「上げるに」は位置や時点を示すが、名詞化の位置には入らない。"}, {"text": "で", "is_correct": false, "explanation": "「上げるで」は手段を示すが、名詞化の位置には入らない。"}], "correct_answer": "の", "explanations": {"の": "「上げるの」で動作を名詞化し、「上げること」を表す。", "を": "「上げるを」は目的語を示すが、動詞に直接続かない。", "に": "「上げるに」は位置や時点を示すが、名詞化の位置には入らない。", "で": "「上げるで」は手段を示すが、名詞化の位置には入らない。"}, "error_tags": {"を": "目的語", "に": "位置", "で": "手段"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下げる", "is_correct": true, "explanation": "「上げる」（程度を高くする）の対義語。家賃などを低くすること。"}, {"text": "引く", "is_correct": false, "explanation": "「引く」は手前へ力を加えて動かす意味で、上下の対義語ではない。"}, {"text": "広げる", "is_correct": false, "explanation": "「広げる」は範囲や面積を大きくする意味で、上下の対義語ではない。"}, {"text": "運ぶ", "is_correct": false, "explanation": "「運ぶ」は場所を移す意味で、程度の上下の対義語ではない。"}], "correct_answer": "下げる", "explanations": {"下げる": "「上げる」（程度を高くする）の対義語。家賃などを低くすること。", "引く": "「引く」は手前へ力を加えて動かす意味で、上下の対義語ではない。", "広げる": "「広げる」は範囲や面積を大きくする意味で、上下の対義語ではない。", "運ぶ": "「運ぶ」は場所を移す意味で、程度の上下の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37561, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "成績・給料・値段・温度・速度などの程度や、地位を高くする。", "primary_collocate": null, "pronunciation": "あげる", "ipa": "aɡeɾɯ", "syllable_count": 3, "sentences": [{"text": "成績を上げるために、毎日二時間勉強している。", "target_word": "上げる", "complexity_tier": "T3", "furigana": "成績[せいせき]を上[あ]げるために、毎日[まいにち]二時間[にじかん]勉強[べんきょう]している。", "sentence_source": "generated"}, {"text": "会社は来月から社員の給料を上げると発表した。", "target_word": "上げる", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は来月[らいげつ]から社員[しゃいん]の給料[きゅうりょう]を上[あ]げると発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "部屋が寒いので、エアコンの温度を上げた。", "target_word": "上げた", "complexity_tier": "T3", "furigana": "部屋[へや]が寒[さむ]いので、エアコンの温度[おんど]を上[あ]げた。", "sentence_source": "generated"}, {"text": "車の速度を上げると、エンジンの音が大きくなった。", "target_word": "上げる", "complexity_tier": "T3", "furigana": "車[くるま]の速度[そくど]を上[あ]げると、エンジンの音[おと]が大[おお]きくなった。", "sentence_source": "generated"}, {"text": "彼は努力して、チームの順位を三位から一位に上げた。", "target_word": "上げた", "complexity_tier": "T3", "furigana": "彼[かれ]は努力[どりょく]して、チームの順位[じゅんい]を三位[さんい]から一位[いちい]に上[あ]げた。", "sentence_source": "generated"}, {"text": "人気が出たので、店は商品の値段を上げた。", "target_word": "上げた", "complexity_tier": "T3", "furigana": "人気[にんき]が出[で]たので、店[みせ]は商品[しょうひん]の値段[ねだん]を上[あ]げた。", "sentence_source": "generated"}, {"text": "音が小さくて聞こえないので、ラジオの音量を上げてください。", "target_word": "上げて", "complexity_tier": "T3", "furigana": "音[おと]が小[ちい]さくて聞[き]こえないので、ラジオの音量[おんりょう]を上[あ]げてください。", "sentence_source": "generated"}, {"text": "荷物を二階に上げるのを手伝ってくれませんか。", "target_word": "上げる", "complexity_tier": "T3", "furigana": "荷物[にもつ]を二階[にかい]に上[あ]げるのを手伝[てつだ]ってくれませんか。", "sentence_source": "generated"}, {"text": "社長は、働きぶりのよい彼の地位を上げた。", "target_word": "上げた", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は、働[はたら]きぶりのよい彼[かれ]の地位[ちい]を上[あ]げた。", "sentence_source": "generated"}, {"text": "物価が上がったので、大家さんは来年から家賃を上げるそうだ。", "target_word": "上げる", "complexity_tier": "T3", "furigana": "物価[ぶっか]が上[あ]がったので、大家[おおや]さんは来年[らいねん]から家賃[やちん]を上[あ]げるそうだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "上げる", "label": "終止形"}, {"form": "上げます", "label": "丁寧形"}, {"form": "上げた", "label": "過去形"}, {"form": "上げて", "label": "て形"}, {"form": "上げない", "label": "否定形"}, {"form": "上げれば", "label": "仮定形"}, {"form": "上げよう", "label": "意志形"}], "register": "中立", "sense_fingerprint": "成績・給料・値段・温度・速度・地位などの程度を高くする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68b8a0b9-d581-49d2-8aa6-b2f3d6bfbb8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37561, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上げる", "is_correct": true, "explanation": "「成績を高くする」意味で、「ために」に自然につながる。"}, {"text": "眠る", "is_correct": false, "explanation": "「眠る」は寝る動作で、成績を対象にする文には合わない。"}, {"text": "割る", "is_correct": false, "explanation": "「割る」は壊す意味で、成績には使わない。"}, {"text": "凍る", "is_correct": false, "explanation": "「凍る」は固まる意味で、成績の文には続かない。"}], "explanations": {"上げる": "「成績を高くする」意味で、「ために」に自然につながる。", "眠る": "「眠る」は寝る動作で、成績を対象にする文には合わない。", "割る": "「割る」は壊す意味で、成績には使わない。", "凍る": "「凍る」は固まる意味で、成績の文には続かない。"}, "sentence_index": 0, "correct_answer": "上げる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ノートに名前を上げた。", "explanation": "ここは〈書く〉の意味。紙に名前を記す動作は〈上げる〉では言わない。"}, {"text": "毎日運動して身長を上げた。", "explanation": "ここは〈伸ばす〉の意味。身長が伸びる場合は〈上げる〉を使わず、〈伸ばす〉が正しい。"}, {"text": "毎月少しずつ貯金を上げた。", "explanation": "ここは〈増やす〉の意味。金額を増やす場合でも〈上げる〉とは言わず、〈増やす〉が正しい。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37561, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上げて", "is_correct": true, "explanation": "「ラジオの音量を上げてください」の形。て形が依頼の文につながる。"}, {"text": "咲いて", "is_correct": false, "explanation": "「咲く」は花が開く意味で、音量には使わない。"}, {"text": "噛んで", "is_correct": false, "explanation": "「噛む」は歯で食べる動作で、音量の文には入らない。"}, {"text": "焦がして", "is_correct": false, "explanation": "「焦がす」は焦げさせる意味で、音量の文には続かない。"}], "explanations": {"上げて": "「ラジオの音量を上げてください」の形。て形が依頼の文につながる。", "咲いて": "「咲く」は花が開く意味で、音量には使わない。", "噛んで": "「噛む」は歯で食べる動作で、音量の文には入らない。", "焦がして": "「焦がす」は焦げさせる意味で、音量の文には続かない。"}, "sentence_index": 6, "correct_answer": "上げて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "電波の届く範囲を上げた。", "explanation": "ここは〈広げる〉の意味。範囲を大きくする場合は〈上げる〉を使わないので、この文は不自然。"}, {"text": "相手の理解を上げた。", "explanation": "ここは〈深める〉の意味。理解を深める場合は〈上げる〉ではなく〈深める〉を使う。"}, {"text": "タンクにガソリンを上げた。", "explanation": "ここは〈注ぐ〉の意味。液体を容器に入れる動作は〈上げる〉では表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37561, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "給料を上がるため、会社は新しい制度を作った。", "corrected_sentence": "給料を上げるため、会社は新しい制度を作った。", "error_description": "正しくは「上げる」（他動詞）。「上がる」は自動詞なので「給料を」と続けられず、「給料が上がる」の形になる。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "上げる", "is_correct": true, "explanation": "「給料を上げると」の辞書形で、条件の「と」に直接続く。"}, {"text": "上げれば", "is_correct": false, "explanation": "ば形は「と発表した」の前に置けず、文が成り立たない。"}, {"text": "上げない", "is_correct": false, "explanation": "否定形だと引き上げないという内容になり、発表の内容が反対になる。"}, {"text": "上げます", "is_correct": false, "explanation": "丁寧形は「と」の前に続けにくく、「上げますと発表した」は不自然。"}], "correct_form": "上げる", "base_form": "上げる", "form_label": "辞書形", "sentence_index": 1, "explanations": {"上げる": "「給料を上げると」の辞書形で、条件の「と」に直接続く。", "上げれば": "ば形は「と発表した」の前に置けず、文が成り立たない。", "上げない": "否定形だと引き上げないという内容になり、発表の内容が反対になる。", "上げます": "丁寧形は「と」の前に続けにくく、「上げますと発表した」は不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37561, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "来年の家賃を上げ予定だと聞いた。", "corrected_sentence": "来年の家賃を上げる予定だと聞いた。", "error_description": "正しくは「上げる予定」（辞書形＋予定）。「上げ」だけでは「予定」に続かず、動詞の辞書形が必要。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "上げる", "is_correct": true, "explanation": "「のを」の前は辞書形で、名詞化した「上げること」を作れる。"}, {"text": "上げて", "is_correct": false, "explanation": "て形は「のを」に続けられず、文が成り立たない。"}, {"text": "上げれば", "is_correct": false, "explanation": "ば形は「のを」と続かず、文が成り立たない。"}, {"text": "上げよう", "is_correct": false, "explanation": "意志形は「のを」と続かず、「上げようのを」は成り立たない。"}], "correct_form": "上げる", "base_form": "上げる", "form_label": "辞書形", "sentence_index": 7, "explanations": {"上げる": "「のを」の前は辞書形で、名詞化した「上げること」を作れる。", "上げて": "て形は「のを」に続けられず、文が成り立たない。", "上げれば": "ば形は「のを」と続かず、文が成り立たない。", "上げよう": "意志形は「のを」と続かず、「上げようのを」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37562, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「窓に当たって」の「に」で、ぶつかる場所を示す。"}, {"text": "が", "is_correct": false, "explanation": "「窓が当たって」は主語を示すが、ぶつかる場所にはならない。"}, {"text": "を", "is_correct": false, "explanation": "「窓を当たって」は目的語を示すが、自動詞の「当たる」には続かない。"}, {"text": "で", "is_correct": false, "explanation": "「窓で当たって」は手段や場所を示すが、ぶつかる場所は「に」で示す。"}], "correct_answer": "に", "explanations": {"に": "「窓に当たって」の「に」で、ぶつかる場所を示す。", "が": "「窓が当たって」は主語を示すが、ぶつかる場所にはならない。", "を": "「窓を当たって」は目的語を示すが、自動詞の「当たる」には続かない。", "で": "「窓で当たって」は手段や場所を示すが、ぶつかる場所は「に」で示す。"}, "error_tags": {"が": "主語", "を": "目的語", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37562, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「耳に当たって」の「に」で、ぶつかる場所を示す。"}, {"text": "と", "is_correct": false, "explanation": "「耳と当たって」は相手を並べる意味になり、ぶつかる場所にはならない。"}, {"text": "の", "is_correct": false, "explanation": "「耳の当たって」は連体修飾としても成り立たず、文が続かない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すが、「耳より当たって」はぶつかる場所とは合わない。"}], "correct_answer": "に", "explanations": {"に": "「耳に当たって」の「に」で、ぶつかる場所を示す。", "と": "「耳と当たって」は相手を並べる意味になり、ぶつかる場所にはならない。", "の": "「耳の当たって」は連体修飾としても成り立たず、文が続かない。", "より": "「より」は比較を示すが、「耳より当たって」はぶつかる場所とは合わない。"}, "error_tags": {"と": "相手", "の": "所属", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37562, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "風や空気が人の体や物にぶつかること。", "primary_collocate": null, "pronunciation": "あたる", "ipa": "atarɯ", "syllable_count": 3, "sentences": [{"text": "窓を開けると、冷たい風が顔に当たった。", "target_word": "当たった", "complexity_tier": "T3", "furigana": "窓[まど]を開[あ]けると、冷[つめ]たい風[かぜ]が顔[かお]に当[あ]たった。", "sentence_source": "generated"}, {"text": "強い風が窓に当たって、ガラスが鳴っている。", "target_word": "当たって", "complexity_tier": "T3", "furigana": "強[つよ]い風[かぜ]が窓[まど]に当[あ]たって、ガラスが鳴[な]っている。", "sentence_source": "generated"}, {"text": "扇風機の風が体に当たると、すずしい。", "target_word": "当たる", "complexity_tier": "T3", "furigana": "扇風機[せんぷうき]の風[かぜ]が体[からだ]に当[あ]たると、すずしい。", "sentence_source": "generated"}, {"text": "海からの風が顔に当たって、気持ちがよかった。", "target_word": "当たって", "complexity_tier": "T3", "furigana": "海[うみ]からの風[かぜ]が顔[かお]に当[あ]たって、気持[きも]ちがよかった。", "sentence_source": "generated"}, {"text": "風が直接当たらないように、エアコンの向きを変えた。", "target_word": "当たらない", "complexity_tier": "T3", "furigana": "風[かぜ]が直接[ちょくせつ]当[あ]たらないように、エアコンの向[む]きを変[か]えた。", "sentence_source": "generated"}, {"text": "冷たい空気が首に当たって、思わず身ぶるいした。", "target_word": "当たって", "complexity_tier": "T3", "furigana": "冷[つめ]たい空気[くうき]が首[くび]に当[あ]たって、思[おも]わず身[み]ぶるいした。", "sentence_source": "generated"}, {"text": "山の上では、強い風が体に当たって歩きにくい。", "target_word": "当たって", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]では、強[つよ]い風[かぜ]が体[からだ]に当[あ]たって歩[ある]きにくい。", "sentence_source": "generated"}, {"text": "ドライヤーの熱い風が耳に当たって、少し痛かった。", "target_word": "当たって", "complexity_tier": "T3", "furigana": "ドライヤーの熱[あつ]い風[かぜ]が耳[みみ]に当[あ]たって、少[すこ]し痛[いた]かった。", "sentence_source": "generated"}, {"text": "走ると、風が頬に当たるのがよくわかる。", "target_word": "当たる", "complexity_tier": "T3", "furigana": "走[はし]ると、風[かぜ]が頬[ほお]に当[あ]たるのがよくわかる。", "sentence_source": "generated"}, {"text": "風が旗に当たって、大きくはためいている。", "target_word": "当たって", "complexity_tier": "T3", "furigana": "風[かぜ]が旗[はた]に当[あ]たって、大[おお]きくはためいている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "当たる", "label": "終止形"}, {"form": "当たります", "label": "丁寧形"}, {"form": "当たった", "label": "過去形"}, {"form": "当たって", "label": "て形"}, {"form": "当たらない", "label": "否定形"}, {"form": "当たれば", "label": "仮定形"}, {"form": "当たろう", "label": "意志形"}], "register": "中立", "sense_fingerprint": "風や空気が人の体や物にぶつかる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T2: contains vocabulary far above tier T2: すずしい (Zipf 2.04)','sentence 9 above tier T2: contains vocabulary far above tier T2: はためい (Zipf 1.8)']::text[], '68b8a0b9-d581-49d2-8aa6-b2f3d6bfbb8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37562, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当たった", "is_correct": true, "explanation": "「風が顔にぶつかる」意味で、過去形として文末に合う。"}, {"text": "割った", "is_correct": false, "explanation": "「割る」は壊す意味で、風が顔に当たる文には使わない。"}, {"text": "眠った", "is_correct": false, "explanation": "「眠る」は寝る動作で、風が顔に当たる文には入らない。"}, {"text": "咲いた", "is_correct": false, "explanation": "「咲く」は花が開く意味で、風の文には合わない。"}], "explanations": {"当たった": "「風が顔にぶつかる」意味で、過去形として文末に合う。", "割った": "「割る」は壊す意味で、風が顔に当たる文には使わない。", "眠った": "「眠る」は寝る動作で、風が顔に当たる文には入らない。", "咲いた": "「咲く」は花が開く意味で、風の文には合わない。"}, "sentence_index": 0, "correct_answer": "当たった"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "風が夜空に当たって、星が消えた。", "explanation": "ここは〈照らす〉（光が届く）の意味。空に光が差す場合は〈照らす〉を使い、風が空に当たるとは言わない。"}, {"text": "風がノートに当たって、字を書いた。", "explanation": "ここは〈書く〉の意味。紙に字を書く動作は〈当たる〉では表せない。"}, {"text": "風が鍵穴に当たって、鍵を回した。", "explanation": "ここは〈差し込む〉の意味。鍵穴に差し込んで回す動作は〈当たる〉では言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37562, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当たって", "is_correct": true, "explanation": "「風が体にぶつかる」意味で、て形が「歩きにくい」に続く。"}, {"text": "叫んで", "is_correct": false, "explanation": "「叫ぶ」は大声を出す意味で、風の文には入らない。"}, {"text": "磨いて", "is_correct": false, "explanation": "「磨く」は表面をこする意味で、風が体に当たる文には合わない。"}, {"text": "噛んで", "is_correct": false, "explanation": "「噛む」は歯で食べる動作で、風の文には入らない。"}], "explanations": {"当たって": "「風が体にぶつかる」意味で、て形が「歩きにくい」に続く。", "叫んで": "「叫ぶ」は大声を出す意味で、風の文には入らない。", "磨いて": "「磨く」は表面をこする意味で、風が体に当たる文には合わない。", "噛んで": "「噛む」は歯で食べる動作で、風の文には入らない。"}, "sentence_index": 6, "correct_answer": "当たって"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "授業で先生に当たった。", "explanation": "ここは〈指名される〉の意味。風や空気が物にぶつかる意味では、人を指名する用法は合わない。"}, {"text": "答案に当たって、点数をつけた。", "explanation": "ここは〈採点する〉の意味。答案に点数をつける動作は〈当たる〉では表せない。"}, {"text": "大事な書類に当たって、印鑑を押した。", "explanation": "ここは〈押す〉の意味。印鑑を押す動作は〈当たる〉では言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37562, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窓から入った冷たい風が顔に当てた。", "corrected_sentence": "窓から入った冷たい風が顔に当たった。", "error_description": "正しくは「当たった」（自動詞）。「当てた」は他動詞で、人が物を押し当てる意味になり、「風が」が主語では合わない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "当たって", "is_correct": true, "explanation": "「窓に当たって」のて形で、後ろの「ガラスが鳴っている」へ続く。"}, {"text": "当たります", "is_correct": false, "explanation": "丁寧形は文の途中の接続に使えず、後ろの「ガラスが鳴っている」とつながらない。"}, {"text": "当たらない", "is_correct": false, "explanation": "否定形だと窓に風が当たらないという内容になり、ガラスが鳴る原因と矛盾する。"}, {"text": "当たろう", "is_correct": false, "explanation": "意志形は風には意志がないので、「当たろう、ガラスが鳴っている」は成り立たない。"}], "correct_form": "当たって", "base_form": "当たる", "form_label": "て形", "sentence_index": 1, "explanations": {"当たって": "「窓に当たって」のて形で、後ろの「ガラスが鳴っている」へ続く。", "当たります": "丁寧形は文の途中の接続に使えず、後ろの「ガラスが鳴っている」とつながらない。", "当たらない": "否定形だと窓に風が当たらないという内容になり、ガラスが鳴る原因と矛盾する。", "当たろう": "意志形は風には意志がないので、「当たろう、ガラスが鳴っている」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37562, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "強い風が体に当たれて、足がふらついた。", "corrected_sentence": "強い風が体に当たって、足がふらついた。", "error_description": "正しくは「当たって」（て形）。「当たれて」は「当たる」の活用として存在せず、「れ」が余分に入っている誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "当たって", "is_correct": true, "explanation": "「耳に当たって」のて形で、後ろの「少し痛かった」へ続く。"}, {"text": "当たった", "is_correct": false, "explanation": "過去形で言い切ると、後ろの「少し痛かった」と原因と結果でつながらない。"}, {"text": "当たる", "is_correct": false, "explanation": "辞書形で文を切ると、後ろの「少し痛かった」と原因と結果でつながらない。"}, {"text": "当たらなかった", "is_correct": false, "explanation": "否定の過去形だと耳に当たらなかったという内容になり、「少し痛かった」の原因と矛盾する。"}], "correct_form": "当たって", "base_form": "当たる", "form_label": "て形", "sentence_index": 7, "explanations": {"当たって": "「耳に当たって」のて形で、後ろの「少し痛かった」へ続く。", "当たった": "過去形で言い切ると、後ろの「少し痛かった」と原因と結果でつながらない。", "当たる": "辞書形で文を切ると、後ろの「少し痛かった」と原因と結果でつながらない。", "当たらなかった": "否定の過去形だと耳に当たらなかったという内容になり、「少し痛かった」の原因と矛盾する。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37564, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "道は落とした場所を表す。「道に落とす」は道の上へ落とした意味になり、ここに合う。"}, {"text": "を", "is_correct": false, "explanation": "「道を落とす」は道そのものを目的語にすることになり、文の意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「道の落としてしまった」は名詞を修飾する形にならず、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は場所を示す文脈に合わず、意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "道は落とした場所を表す。「道に落とす」は道の上へ落とした意味になり、ここに合う。", "を": "「道を落とす」は道そのものを目的語にすることになり、文の意味が通らない。", "の": "「道の落としてしまった」は名詞を修飾する形にならず、文が成り立たない。", "より": "比較の「より」は場所を示す文脈に合わず、意味が通らない。"}, "error_tags": {"を": "目的語の格", "の": "連体修飾", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37564, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37564, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものを　したに　うごかす。", "primary_collocate": null, "pronunciation": "おとす", "ipa": "otosɯ", "syllable_count": 3, "sentences": [{"text": "手がすべって、皿を床に落とした。", "target_word": "落とした", "complexity_tier": "T3", "furigana": "手[て]がすべって、皿[さら]を床[ゆか]に落[お]とした。", "sentence_source": "generated"}, {"text": "歩きながら携帯電話を見ていて、道に落としてしまった。", "target_word": "落として", "complexity_tier": "T3", "furigana": "歩[ある]きながら携帯電話[けいたいでんわ]を見[み]ていて、道[みち]に落[お]としてしまった。", "sentence_source": "generated"}, {"text": "木をゆすって、実を地面に落とした。", "target_word": "落とした", "complexity_tier": "T3", "furigana": "木[き]をゆすって、実[み]を地面[じめん]に落[お]とした。", "sentence_source": "generated"}, {"text": "机の上のコップを落とさないように、気をつけてください。", "target_word": "落とさない", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]のコップを落[お]とさないように、気[き]をつけてください。", "sentence_source": "generated"}, {"text": "子どもがおもちゃを階段から落としてしまった。", "target_word": "落として", "complexity_tier": "T3", "furigana": "子[こ]どもがおもちゃを階段[かいだん]から落[お]としてしまった。", "sentence_source": "generated"}, {"text": "重い荷物を足の上に落とすと、とても痛い。", "target_word": "落とす", "complexity_tier": "T3", "furigana": "重[おも]い荷物[にもつ]を足[あし]の上[うえ]に落[お]とすと、とても痛[いた]い。", "sentence_source": "generated"}, {"text": "彼はびっくりして、持っていたかばんを落とした。", "target_word": "落とした", "complexity_tier": "T3", "furigana": "彼[かれ]はびっくりして、持[も]っていたかばんを落[お]とした。", "sentence_source": "generated"}, {"text": "猫がテーブルの花びんを落として、割ってしまった。", "target_word": "落として", "complexity_tier": "T3", "furigana": "猫[ねこ]がテーブルの花[か]びんを落[お]として、割[わ]ってしまった。", "sentence_source": "generated"}, {"text": "橋の上から、小さな石を川に落とした。", "target_word": "落とした", "complexity_tier": "T3", "furigana": "橋[はし]の上[うえ]から、小[ちい]さな石[いし]を川[かわ]に落[お]とした。", "sentence_source": "generated"}, {"text": "弟は、ポケットから鍵を落としたことに気づかなかった。", "target_word": "落とした", "complexity_tier": "T3", "furigana": "弟[おとうと]は、ポケットから鍵[かぎ]を落[お]としたことに気[き]づかなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "落とす", "label": "終止形"}, {"form": "落とします", "label": "丁寧形"}, {"form": "落とした", "label": "過去形"}, {"form": "落として", "label": "て形"}, {"form": "落とさない", "label": "否定形"}, {"form": "落とせば", "label": "仮定形"}, {"form": "落とそう", "label": "意志形"}], "register": "中立", "sense_fingerprint": "手に持っていたものなどを誤って、または意図して下へ落下させる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T3: contains vocabulary far above tier T3: 花びん (Zipf 1.51)']::text[], '68b8a0b9-d581-49d2-8aa6-b2f3d6bfbb8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37564, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "落とした", "is_correct": true, "explanation": "手から離して床へ落下させた意味で、「手がすべって」という文脈に合う。"}, {"text": "食べた", "is_correct": false, "explanation": "皿は食べられないので、「皿を床に食べた」は文として成り立たない。"}, {"text": "弾いた", "is_correct": false, "explanation": "皿を弾くという動作は、手がすべって皿を床に置いてしまう文脈に合わない。"}, {"text": "飲んだ", "is_correct": false, "explanation": "皿は飲めないので、「皿を床に飲んだ」は意味が通らない。"}], "explanations": {"落とした": "手から離して床へ落下させた意味で、「手がすべって」という文脈に合う。", "食べた": "皿は食べられないので、「皿を床に食べた」は文として成り立たない。", "弾いた": "皿を弾くという動作は、手がすべって皿を床に置いてしまう文脈に合わない。", "飲んだ": "皿は飲めないので、「皿を床に飲んだ」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "落とした"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "鳥かごの扉を開けて、鳥を空へ落とした。", "explanation": "ここは〈放す〉の場面。〈放す〉は捕まえていたものを自由にする動作で、〈落とす〉は下へ動かす意味なので、空へ向けて放つ文脈には合わない。"}, {"text": "仕事の締め切りを一週間早く落とした。", "explanation": "ここは〈繰り上げる〉の場面。期限を前倒しにする文脈で、〈落とす〉は物を下へ動かす意味なので、期限を早める文脈には合わない。"}, {"text": "ガラスの置物を、音を立てないように机の上に落とした。", "explanation": "ここは〈置く〉の場面。〈置く〉は静かに据える動作だが、〈落とす〉は手から離して下へ動かすので、音を立てずに置く文脈とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37564, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "落とした", "is_correct": true, "explanation": "手に持っていたかばんを下へ落とした意味で、びっくりした流れに合う。"}, {"text": "歌った", "is_correct": false, "explanation": "かばんは歌えないので、「かばんを歌った」は文の内容が成り立たない。"}, {"text": "味わった", "is_correct": false, "explanation": "かばんは味わうものではないので、文の意味に合わない。"}, {"text": "踊った", "is_correct": false, "explanation": "かばんは踊らないので、「かばんを踊った」は意味が通らない。"}], "explanations": {"落とした": "手に持っていたかばんを下へ落とした意味で、びっくりした流れに合う。", "歌った": "かばんは歌えないので、「かばんを歌った」は文の内容が成り立たない。", "味わった": "かばんは味わうものではないので、文の意味に合わない。", "踊った": "かばんは踊らないので、「かばんを踊った」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "落とした"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議の時間を三十分落として、早めに終わらせた。", "explanation": "ここは〈縮める〉の場面。時間を短くする文脈で、〈落とす〉は物を下へ動かす意味なので、時間には使えず、〈縮める〉の代わりにはならない。"}, {"text": "ダイエットで、身長を三センチ落とした。", "explanation": "ここは〈縮む〉の場面。〈落とす〉は体重のように自分で減らせるものに使うが、身長は落とせないので、身長が低くなる文脈には合わない。"}, {"text": "彼はボールを遠くのゴールへ落とした。", "explanation": "ここは〈投げる〉の場面。〈投げる〉は遠くへ飛ばす動作だが、〈落とす〉は重力で下へ動かすので、水平に遠くへ飛ばす意味には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37564, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "駅のホームに財布を落ちた。", "corrected_sentence": "駅のホームに財布を落とした。", "error_description": "「落ちる」は自動詞で、目的語の「財布を」と組み合わさない。他動詞の「落とした」が正しい形。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "落として", "is_correct": true, "explanation": "て形で、「〜してしまった」に続けて道に落としてしまったという文を完成させる。"}, {"text": "落とす", "is_correct": false, "explanation": "終止形なので「〜してしまった」につながらず、文の途中に置けない。"}, {"text": "落とさない", "is_correct": false, "explanation": "否定形になり、落としてしまったという出来事を表せない。"}, {"text": "落とした", "is_correct": false, "explanation": "過去形は「〜てしまった」の前に続かず、「落としたしまった」となって文が壊れる。"}], "correct_form": "落として", "base_form": "落とす", "form_label": "て形", "sentence_index": 1, "explanations": {"落として": "て形で、「〜してしまった」に続けて道に落としてしまったという文を完成させる。", "落とす": "終止形なので「〜してしまった」につながらず、文の途中に置けない。", "落とさない": "否定形になり、落としてしまったという出来事を表せない。", "落とした": "過去形は「〜てしまった」の前に続かず、「落としたしまった」となって文が壊れる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37564, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ベランダから鉢植えが落とした。", "corrected_sentence": "ベランダから鉢植えを落とした。", "error_description": "「が」は主語を示すが、他動詞「落とした」の目的語は「を」で示す。「鉢植えが」は誤りで、正しくは「鉢植えを」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "落として", "is_correct": true, "explanation": "て形で、「割ってしまった」に続けて猫が花びんを落として割ったという文を完成させる。"}, {"text": "落とそう", "is_correct": false, "explanation": "意志形になり、猫の出来事を描写する文に合わない。"}, {"text": "落とさ", "is_correct": false, "explanation": "未然形のままでは文が途中で切れ、「〜てしまった」にも続かず成り立たない。"}, {"text": "落とします", "is_correct": false, "explanation": "丁寧形は「〜て、割ってしまった」と続かず、文の途中に丁寧語が入って崩れる。"}], "correct_form": "落として", "base_form": "落とす", "form_label": "て形", "sentence_index": 7, "explanations": {"落として": "て形で、「割ってしまった」に続けて猫が花びんを落として割ったという文を完成させる。", "落とそう": "意志形になり、猫の出来事を描写する文に合わない。", "落とさ": "未然形のままでは文が途中で切れ、「〜てしまった」にも続かず成り立たない。", "落とします": "丁寧形は「〜て、割ってしまった」と続かず、文の途中に丁寧語が入って崩れる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
