INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37565, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "空中や空間にあるものを、重力などで下の方へ移動させること。", "primary_collocate": null, "pronunciation": "おとす", "ipa": "otosɯ", "syllable_count": 3, "sentences": [{"text": "飛行機は、山の村に食べ物の箱を落とした。", "target_word": "落とした", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]は、山[やま]の村[むら]に食[た]べ物[もの]の箱[はこ]を落[お]とした。", "sentence_source": "generated"}, {"text": "木の枝をゆらして、積もった雪を落とした。", "target_word": "落とした", "complexity_tier": "T3", "furigana": "木[き]の枝[えだ]をゆらして、積[つ]もった雪[ゆき]を落[お]とした。", "sentence_source": "generated"}, {"text": "強い風が、木からたくさんの葉を落とした。", "target_word": "落とした", "complexity_tier": "T3", "furigana": "強[つよ]い風[かぜ]が、木[き]からたくさんの葉[は]を落[お]とした。", "sentence_source": "generated"}, {"text": "高い塔の上からボールを落とす実験をした。", "target_word": "落とす", "complexity_tier": "T3", "furigana": "高[たか]い塔[とう]の上[うえ]からボールを落[お]とす実験[じっけん]をした。", "sentence_source": "generated"}, {"text": "屋根の上の雪を落とす作業をしている。", "target_word": "落とす", "complexity_tier": "T3", "furigana": "屋根[やね]の上[うえ]の雪[ゆき]を落[お]とす作業[さぎょう]をしている。", "sentence_source": "generated"}, {"text": "ベランダから物を落とすと危ないので、やめてください。", "target_word": "落とす", "complexity_tier": "T3", "furigana": "ベランダから物[もの]を落[お]とすと危[あぶ]ないので、やめてください。", "sentence_source": "generated"}, {"text": "ヘリコプターが、海にいる人へ浮き輪を落とした。", "target_word": "落とした", "complexity_tier": "T3", "furigana": "ヘリコプターが、海[うみ]にいる人[ひと]へ浮[う]き輪[わ]を落[お]とした。", "sentence_source": "generated"}, {"text": "台風の強い風が、木の実を地面に落とした。", "target_word": "落とした", "complexity_tier": "T3", "furigana": "台風[たいふう]の強[つよ]い風[かぜ]が、木[き]の実[み]を地面[じめん]に落[お]とした。", "sentence_source": "generated"}, {"text": "鳥は空高くから貝を岩の上に落として、割って食べる。", "target_word": "落として", "complexity_tier": "T3", "furigana": "鳥[とり]は空高[そらたか]くから貝[かい]を岩[いわ]の上[うえ]に落[お]として、割[わ]って食[た]べる。", "sentence_source": "generated"}, {"text": "木にのぼって、熟した柿を落とした。", "target_word": "落とした", "complexity_tier": "T3", "furigana": "木[き]にのぼって、熟[じゅく]した柿[かき]を落[お]とした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "落とす", "label": "終止形"}, {"form": "落とします", "label": "丁寧形"}, {"form": "落とした", "label": "過去形"}, {"form": "落として", "label": "て形"}, {"form": "落とさない", "label": "否定形"}, {"form": "落とせば", "label": "仮定形"}, {"form": "落とそう", "label": "意志形"}], "register": "中立", "sense_fingerprint": "高い所にあるものを重力で下へ落下させる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T3: contains vocabulary far above tier T3: ゆらし (Zipf 1.73)']::text[], '68b8a0b9-d581-49d2-8aa6-b2f3d6bfbb8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37565, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "落とした", "is_correct": true, "explanation": "空から下へ落下させた意味で、飛行機が箱を投下した文脈に合う。"}, {"text": "歌った", "is_correct": false, "explanation": "箱は歌えないので、「箱を歌った」は文が成り立たない。"}, {"text": "弾いた", "is_correct": false, "explanation": "箱は弾けないので、「箱を弾いた」は意味が通らない。"}, {"text": "飲んだ", "is_correct": false, "explanation": "箱は飲めないので、「箱を飲んだ」は文の内容に合わない。"}], "explanations": {"落とした": "空から下へ落下させた意味で、飛行機が箱を投下した文脈に合う。", "歌った": "箱は歌えないので、「箱を歌った」は文が成り立たない。", "弾いた": "箱は弾けないので、「箱を弾いた」は意味が通らない。", "飲んだ": "箱は飲めないので、「箱を飲んだ」は文の内容に合わない。"}, "sentence_index": 0, "correct_answer": "落とした"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ふたを開けたら、小鳥を空へ落として飛ばした。", "explanation": "ここは〈放す〉の場面。〈放す〉は解放する動作で、〈落とす〉は下へ動かす意味なので、空へ向けて放つ文脈には合わない。"}, {"text": "プロジェクトの期限を一週間早く落とした。", "explanation": "ここは〈前倒しにする〉の場面。期限を早める文脈で、〈落とす〉は物を下へ動かす意味なので、期限の変更には合わない。"}, {"text": "彼は野球のボールを一塁へ落とした。", "explanation": "ここは〈投げる〉の場面。〈投げる〉は遠くへ飛ばす動きだが、〈落とす〉は重力で下へ移すので、一塁へ水平に飛ばす意味には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37565, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "落とした", "is_correct": true, "explanation": "空から海上の人へ浮き輪を下へ落とした意味で、文脈に合う。"}, {"text": "味わった", "is_correct": false, "explanation": "浮き輪は味わえないので、「浮き輪を味わった」は文が成り立たない。"}, {"text": "踊った", "is_correct": false, "explanation": "浮き輪は踊らないので、「浮き輪を踊った」は意味が通らない。"}, {"text": "食べた", "is_correct": false, "explanation": "浮き輪は食べられないので、「浮き輪を食べた」は文の内容に合わない。"}], "explanations": {"落とした": "空から海上の人へ浮き輪を下へ落とした意味で、文脈に合う。", "味わった": "浮き輪は味わえないので、「浮き輪を味わった」は文が成り立たない。", "踊った": "浮き輪は踊らないので、「浮き輪を踊った」は意味が通らない。", "食べた": "浮き輪は食べられないので、「浮き輪を食べた」は文の内容に合わない。"}, "sentence_index": 6, "correct_answer": "落とした"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大人になってから、身長を三センチ落とした。", "explanation": "ここは〈縮む〉の場面。〈落とす〉は体重のように自分で減らせるものに使うが、身長は落とせないので、身長が低くなる文脈には合わない。"}, {"text": "外したコートを、壁の釘に落としてかけた。", "explanation": "ここは〈掛ける〉の場面。〈落とす〉は物を下へ動かす意味で、釘やフックに引っかけて留める動作には使えないので、掛ける文脈には合わない。"}, {"text": "重い荷物を、そっと棚から落とした。", "explanation": "ここは〈下ろす〉の場面。〈落とす〉は下へ勢いよく移す動きなので、そっと静かに下ろす場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37565, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ベランダから物を落としないでください。", "corrected_sentence": "ベランダから物を落とさないでください。", "error_description": "否定形は「落とさない」が正しい。「落としない」は活用が誤っている。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "落とした", "is_correct": true, "explanation": "過去形で、「ゆらして」から続く過去の出来事を述べている。"}, {"text": "落とし", "is_correct": false, "explanation": "連用形で文が終わらず、この文の文末として成り立たない。"}, {"text": "落とさ", "is_correct": false, "explanation": "未然形のままでは文が終わらず、否定の文にも過去の文にもならない。"}, {"text": "落として", "is_correct": false, "explanation": "て形は文を終えられず、この文では文末が成り立たない。"}], "correct_form": "落とした", "base_form": "落とす", "form_label": "過去形", "sentence_index": 1, "explanations": {"落とした": "過去形で、「ゆらして」から続く過去の出来事を述べている。", "落とし": "連用形で文が終わらず、この文の文末として成り立たない。", "落とさ": "未然形のままでは文が終わらず、否定の文にも過去の文にもならない。", "落として": "て形は文を終えられず、この文では文末が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37565, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋根から雪が落とした。", "corrected_sentence": "屋根から雪を落とした。", "error_description": "「雪が」は主語を示すが、他動詞「落とした」の目的語は「雪を」で示す。格助詞「が」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "落とした", "is_correct": true, "explanation": "過去形で、台風が木の実を地面に落とした出来事を述べている。"}, {"text": "落とさない", "is_correct": false, "explanation": "否定形になり、落ちたという出来事の文と合わない。"}, {"text": "落とせば", "is_correct": false, "explanation": "仮定形になり、「〜すると」という条件の文になって、実際の出来事を述べられない。"}, {"text": "落とそう", "is_correct": false, "explanation": "意志形になり、「台風が〜落とそう」では実際に起きた出来事を述べられない。"}], "correct_form": "落とした", "base_form": "落とす", "form_label": "過去形", "sentence_index": 7, "explanations": {"落とした": "過去形で、台風が木の実を地面に落とした出来事を述べている。", "落とさない": "否定形になり、落ちたという出来事の文と合わない。", "落とせば": "仮定形になり、「〜すると」という条件の文になって、実際の出来事を述べられない。", "落とそう": "意志形になり、「台風が〜落とそう」では実際に起きた出来事を述べられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37566, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示す「は」で、「祖父の行李は」と話題を立てて、古いが丈夫だと続ける。"}, {"text": "で", "is_correct": false, "explanation": "「行李で古いが」は形容詞「古い」につながらず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「行李へ古いが」は方向を表すが、形容詞の文には合わず、文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「行李から古いが」は起点を示すが、形容詞の文に合わず、文が成り立たない。"}], "correct_answer": "は", "explanations": {"は": "主題を示す「は」で、「祖父の行李は」と話題を立てて、古いが丈夫だと続ける。", "で": "「行李で古いが」は形容詞「古い」につながらず、文が成り立たない。", "へ": "「行李へ古いが」は方向を表すが、形容詞の文には合わず、文が成り立たない。", "から": "「行李から古いが」は起点を示すが、形容詞の文に合わず、文が成り立たない。"}, "error_tags": {"で": "手段・場所", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37566, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37566, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "りょこうの　ときに　もって　いく　ふくろや　はこ。", "primary_collocate": null, "pronunciation": "こうり", "ipa": "koːɾi", "syllable_count": 3, "sentences": [{"text": "旅行の前の日に、行李に着替えを入れた。", "target_word": "行李", "complexity_tier": "T3", "furigana": "旅行[りょこう]の前[まえ]の日[ひ]に、行李[こうり]に着替[きが]えを入[い]れた。", "sentence_source": "generated"}, {"text": "祖父の行李は古いが、とても丈夫だ。", "target_word": "行李", "complexity_tier": "T3", "furigana": "祖父[そふ]の行李[こうり]は古[ふる]いが、とても丈夫[じょうぶ]だ。", "sentence_source": "generated"}, {"text": "駅まで行李を運ぶのは、思ったより大変だった。", "target_word": "行李", "complexity_tier": "T3", "furigana": "駅[えき]まで行李[こうり]を運[はこ]ぶのは、思[おも]ったより大変[たいへん]だった。", "sentence_source": "generated"}, {"text": "行李が重すぎて、一人では持ち上げられなかった。", "target_word": "行李", "complexity_tier": "T3", "furigana": "行李[こうり]が重[おも]すぎて、一人[ひとり]では持[も]ち上[あ]げられなかった。", "sentence_source": "generated"}, {"text": "母は行李から、古い着物を出してくれた。", "target_word": "行李", "complexity_tier": "T3", "furigana": "母[はは]は行李[こうり]から、古[ふる]い着物[きもの]を出[だ]してくれた。", "sentence_source": "generated"}, {"text": "兄は大きな行李を持って、遠い町へ出かけた。", "target_word": "行李", "complexity_tier": "T3", "furigana": "兄[あに]は大[おお]きな行李[こうり]を持[も]って、遠[とお]い町[まち]へ出[で]かけた。", "sentence_source": "generated"}, {"text": "行李のふたを開けると、なつかしい匂いがした。", "target_word": "行李", "complexity_tier": "T3", "furigana": "行李[こうり]のふたを開[あ]けると、なつかしい匂[にお]いがした。", "sentence_source": "generated"}, {"text": "雨が降ってきたので、行李をぬれない場所に置いた。", "target_word": "行李", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]ってきたので、行李[こうり]をぬれない場所[ばしょ]に置[お]いた。", "sentence_source": "generated"}, {"text": "昔の旅人は、行李を肩にかけて歩いたそうだ。", "target_word": "行李", "complexity_tier": "T3", "furigana": "昔[むかし]の旅人[たびびと]は、行李[こうり]を肩[かた]にかけて歩[ある]いたそうだ。", "sentence_source": "generated"}, {"text": "出発の朝、父は行李の中身をもう一度確かめた。", "target_word": "行李", "complexity_tier": "T3", "furigana": "出発[しゅっぱつ]の朝[あさ]、父[ちち]は行李[こうり]の中身[なかみ]をもう一度[いちど]確[たし]かめた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "行李", "label": "基本形"}], "register": "やや古風", "sense_fingerprint": "旅に持って行く袋や箱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68b8a0b9-d581-49d2-8aa6-b2f3d6bfbb8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37566, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "行李", "is_correct": true, "explanation": "旅行用の入れ物として、着替えを入れる文脈に合う。"}, {"text": "鍋", "is_correct": false, "explanation": "鍋に着替えを入れる場面は不自然で、文の内容に合わない。"}, {"text": "瓶", "is_correct": false, "explanation": "瓶は口が狭く、着替えを入れる用途に合わないので文が成り立たない。"}, {"text": "鉢", "is_correct": false, "explanation": "鉢は着替えを入れるものではなく、「鉢に着替えを入れた」は意味が通らない。"}], "explanations": {"行李": "旅行用の入れ物として、着替えを入れる文脈に合う。", "鍋": "鍋に着替えを入れる場面は不自然で、文の内容に合わない。", "瓶": "瓶は口が狭く、着替えを入れる用途に合わないので文が成り立たない。", "鉢": "鉢は着替えを入れるものではなく、「鉢に着替えを入れた」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "行李"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "スーパーで野菜を行李に入れて、レジまで運んだ。", "explanation": "ここは〈買い物かご〉の場面。行李は旅行用の大きな入れ物で、店で使う買い物かごとは用途が違うので合わない。"}, {"text": "彼は行李を頭にのせて、帽子の代わりにした。", "explanation": "ここは〈帽子〉の場面。行李は旅の荷物を入れる入れ物で、頭にかぶるものではないので、帽子の代わりにはならない。"}, {"text": "台所で出た紙くずを、行李に捨てた。", "explanation": "ここは〈ゴミ箱〉の場面。ゴミ箱はごみを捨てる入れ物で、行李は衣服や旅の荷物を運ぶためのものなので、紙くずには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37566, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "行李", "is_correct": true, "explanation": "ふたのついた旅行用の入れ物で、ふたを開けると匂いがする文脈に合う。"}, {"text": "箸", "is_correct": false, "explanation": "箸にはふたがないので、「箸のふたを開けると」は文が成り立たない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "鉛筆にはふたのような部分がないので、文の内容に合わない。"}, {"text": "栞", "is_correct": false, "explanation": "栞にはふたがなく、「栞のふたを開けると」は意味が通らない。"}], "explanations": {"行李": "ふたのついた旅行用の入れ物で、ふたを開けると匂いがする文脈に合う。", "箸": "箸にはふたがないので、「箸のふたを開けると」は文が成り立たない。", "鉛筆": "鉛筆にはふたのような部分がないので、文の内容に合わない。", "栞": "栞にはふたがなく、「栞のふたを開けると」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "行李"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一年生の息子は、行李を背負って学校へ行った。", "explanation": "ここは〈ランドセル〉の場面。ランドセルは小学生の通学用かばんで、旅行用の行李を子どもが通学に背負うことはないので合わない。"}, {"text": "買ったパンを、行李に入れて持ち帰った。", "explanation": "ここは〈紙袋〉の場面。紙袋は買った品物を入れて持ち帰る袋で、行李は旅の大きな荷物を運ぶ入れ物なので、パン一つには合わない。"}, {"text": "ペンは、行李にきちんと並べて入れた。", "explanation": "ここは〈筆箱〉の場面。筆箱は文房具を入れる小物入れで、旅の荷物を入れる行李とは大きさも用途も違うので、ペンには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37566, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "空港で行李が係の人に預けた。", "corrected_sentence": "空港で行李を係の人に預けた。", "error_description": "「行李が」は主語を示すが、他動詞「預けた」の目的語は「行李を」で示す。「が」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37566, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父は一人で行李を持ち上げらなかった。", "corrected_sentence": "父は一人で行李を持ち上げられなかった。", "error_description": "可能形の「られ」が抜けている。「持ち上げらなかった」は活用が誤りで、正しくは「持ち上げられなかった」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37567, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「行李の中」と、行李の内側を指す連体修飾の「の」で、服がしまってある場所を示す。"}, {"text": "が", "is_correct": false, "explanation": "「行李が中には」は主語と主題の組み立てが合わず、文として不自然で成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「行李へ中には」は方向を表すが、中にある服の状態を述べる文に合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は文脈に合わず、「行李より中には」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「行李の中」と、行李の内側を指す連体修飾の「の」で、服がしまってある場所を示す。", "が": "「行李が中には」は主語と主題の組み立てが合わず、文として不自然で成り立たない。", "へ": "「行李へ中には」は方向を表すが、中にある服の状態を述べる文に合わない。", "より": "比較の「より」は文脈に合わず、「行李より中には」は意味が通らない。"}, "error_tags": {"が": "主語の格", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37567, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「行李を係の人にあずけた」で、あずける対象の行李を目的語として示す。"}, {"text": "で", "is_correct": false, "explanation": "「行李で係の人にあずけた」は手段のように読めて、あずける対象が示せず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「行李と係の人にあずけた」は並列になり、あずける対象が明確にならない。"}, {"text": "に", "is_correct": false, "explanation": "「行李に係の人にあずけた」は「に」が重なって文が崩れる。"}], "correct_answer": "を", "explanations": {"を": "「行李を係の人にあずけた」で、あずける対象の行李を目的語として示す。", "で": "「行李で係の人にあずけた」は手段のように読めて、あずける対象が示せず不自然。", "と": "「行李と係の人にあずけた」は並列になり、あずける対象が明確にならない。", "に": "「行李に係の人にあずけた」は「に」が重なって文が崩れる。"}, "error_tags": {"で": "手段・場所", "と": "並列", "に": "重複した格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37567, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "旅行や出かけるときに、衣服や品物を入れて運ぶための入れ物。", "primary_collocate": null, "pronunciation": "こうり", "ipa": "koːɾi", "syllable_count": 3, "sentences": [{"text": "彼は行李に衣服をていねいにたたんで入れた。", "target_word": "行李", "complexity_tier": "T3", "furigana": "彼[かれ]は行李[こうり]に衣服[いふく]をていねいにたたんで入[い]れた。", "sentence_source": "generated"}, {"text": "行李の中には、季節ごとの服がしまってある。", "target_word": "行李", "complexity_tier": "T3", "furigana": "行李[こうり]の中[なか]には、季節[きせつ]ごとの服[ふく]がしまってある。", "sentence_source": "generated"}, {"text": "古い行李は、竹で編まれていて軽い。", "target_word": "行李", "complexity_tier": "T3", "furigana": "古[ふる]い行李[こうり]は、竹[たけ]で編[あ]まれていて軽[かる]い。", "sentence_source": "generated"}, {"text": "旅先で買った品物が多くて、行李がいっぱいになった。", "target_word": "行李", "complexity_tier": "T3", "furigana": "旅先[たびさき]で買[か]った品物[しなもの]が多[おお]くて、行李[こうり]がいっぱいになった。", "sentence_source": "generated"}, {"text": "母は新しい行李を買って、私の荷物をまとめてくれた。", "target_word": "行李", "complexity_tier": "T3", "furigana": "母[はは]は新[あたら]しい行李[こうり]を買[か]って、私[わたし]の荷物[にもつ]をまとめてくれた。", "sentence_source": "generated"}, {"text": "行李を開けたら、おみやげが全部こわれていた。", "target_word": "行李", "complexity_tier": "T3", "furigana": "行李[こうり]を開[あ]けたら、おみやげが全部[ぜんぶ]こわれていた。", "sentence_source": "generated"}, {"text": "この行李なら、着物も毛布も入れることができる。", "target_word": "行李", "complexity_tier": "T3", "furigana": "この行李[こうり]なら、着物[きもの]も毛布[もうふ]も入[い]れることができる。", "sentence_source": "generated"}, {"text": "船に乗る前に、行李を係の人にあずけた。", "target_word": "行李", "complexity_tier": "T3", "furigana": "船[ふね]に乗[の]る前[まえ]に、行李[こうり]を係[かかり]の人[ひと]にあずけた。", "sentence_source": "generated"}, {"text": "押し入れの奥から、祖母の行李が出てきた。", "target_word": "行李", "complexity_tier": "T3", "furigana": "押[お]し入[い]れの奥[おく]から、祖母[そぼ]の行李[こうり]が出[で]てきた。", "sentence_source": "generated"}, {"text": "行李のひもがほどけて、中の服が外にこぼれた。", "target_word": "行李", "complexity_tier": "T3", "furigana": "行李[こうり]のひもがほどけて、中[なか]の服[ふく]が外[そと]にこぼれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "行李", "label": "基本形"}], "register": "やや古風", "sense_fingerprint": "衣服や品物を入れて運ぶ入れ物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68b8a0b9-d581-49d2-8aa6-b2f3d6bfbb8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37567, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "行李", "is_correct": true, "explanation": "衣服を入れて運ぶ入れ物で、衣服をたたんで入れる文脈に合う。"}, {"text": "鍋", "is_correct": false, "explanation": "鍋に衣服をたたんで入れるのは不自然で、文の内容に合わない。"}, {"text": "瓶", "is_correct": false, "explanation": "瓶は口が狭く、衣服をたたんで入れる用途に合わないので文が成り立たない。"}, {"text": "皿", "is_correct": false, "explanation": "皿は衣服を入れる容器ではないので、「皿に衣服を入れた」は文の内容に合わない。"}], "explanations": {"行李": "衣服を入れて運ぶ入れ物で、衣服をたたんで入れる文脈に合う。", "鍋": "鍋に衣服をたたんで入れるのは不自然で、文の内容に合わない。", "瓶": "瓶は口が狭く、衣服をたたんで入れる用途に合わないので文が成り立たない。", "皿": "皿は衣服を入れる容器ではないので、「皿に衣服を入れた」は文の内容に合わない。"}, "sentence_index": 0, "correct_answer": "行李"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "冷たいお茶を、行李に入れて持ち歩いた。", "explanation": "ここは〈水筒〉の場面。水筒は液体を入れて運ぶ容器だが、行李は衣服などを運ぶ入れ物で、液体は入れられない。"}, {"text": "牛乳を、行李に入れて冷やしておいた。", "explanation": "ここは〈冷蔵庫〉の場面。冷蔵庫は食品を冷やして保存する器具で、行李には冷やす機能がないので合わない。"}, {"text": "小銭を、行李に入れて財布代わりにした。", "explanation": "ここは〈財布〉の場面。財布は小銭やお札を入れる小物入れで、行李は衣服や大きな荷物を運ぶ入れ物なので、小銭には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37567, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "行李", "is_correct": true, "explanation": "着物や毛布を入れられる大きな入れ物で、この文脈に合う。"}, {"text": "栞", "is_correct": false, "explanation": "栞は本に挟む紙片で、着物や毛布を入れられないので文が成り立たない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "鉛筆は着物や毛布を入れる用途がなく、文の内容に合わない。"}, {"text": "歯ブラシ", "is_correct": false, "explanation": "歯ブラシは着物や毛布を入れられないので、「歯ブラシなら」は文として成り立たない。"}], "explanations": {"行李": "着物や毛布を入れられる大きな入れ物で、この文脈に合う。", "栞": "栞は本に挟む紙片で、着物や毛布を入れられないので文が成り立たない。", "鉛筆": "鉛筆は着物や毛布を入れる用途がなく、文の内容に合わない。", "歯ブラシ": "歯ブラシは着物や毛布を入れられないので、「歯ブラシなら」は文として成り立たない。"}, "sentence_index": 6, "correct_answer": "行李"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ご飯を行李で炊いた。", "explanation": "ここは〈炊飯器〉の場面。行李は衣服や品物を運ぶ入れ物で、ご飯を炊く機能はないので、炊く文脈には合わない。"}, {"text": "出した手紙を、行李に投函した。", "explanation": "ここは〈ポスト〉の場面。投函は郵便を投入口へ入れる行為で、行李は衣服や旅の品物を運ぶ入れ物なので、郵便物の投函には使わない。"}, {"text": "行李に土を入れて、花を植えた。", "explanation": "ここは〈植木鉢〉の場面。植木鉢は植物を植えて育てる容器で、行李は土を入れて植物を育てる用途ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37567, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "母は行李を布団をしまった。", "corrected_sentence": "母は行李に布団をしまった。", "error_description": "「しまう」は入れ物に「に」で収める場所を示す。「行李を」は誤りで、正しくは「行李に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37567, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父行李を納戸から出した。", "corrected_sentence": "父の行李を納戸から出した。", "error_description": "「父の行李」の連体修飾の「の」が抜けている。「父行李」は名詞を並べただけで、正しい日本語にならない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37568, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「好き」の対象を示す「が」で、物理が好きという文になる。"}, {"text": "を", "is_correct": false, "explanation": "「好き」は「を」を目的語に取らないので不自然。"}, {"text": "に", "is_correct": false, "explanation": "「好き」の対象は「に」で示さないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を表し、好きの対象を示さない。"}], "correct_answer": "が", "explanations": {"が": "「好き」の対象を示す「が」で、物理が好きという文になる。", "を": "「好き」は「を」を目的語に取らないので不自然。", "に": "「好き」の対象は「に」で示さないので合わない。", "で": "「で」は手段や場所を表し、好きの対象を示さない。"}, "error_tags": {"を": "好きの対象", "に": "方向・相手", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37568, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「物理の知識」と名詞をつなぎ、知識の分野を示す。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」で、物理へ知識を向ける不自然な文になる。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」で、物理が知識を使うという不自然な文になる。"}, {"text": "を", "is_correct": false, "explanation": "目的語が重なる「を」で、「物理を知識を」と不自然になる。"}], "correct_answer": "の", "explanations": {"の": "「物理の知識」と名詞をつなぎ、知識の分野を示す。", "へ": "方向を表す「へ」で、物理へ知識を向ける不自然な文になる。", "が": "主語の「が」で、物理が知識を使うという不自然な文になる。", "を": "目的語が重なる「を」で、「物理を知識を」と不自然になる。"}, "error_tags": {"へ": "方向", "が": "主語", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37568, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "もののしくみや、ものどうしのせいしつについて、考えること。", "primary_collocate": null, "pronunciation": "ぶつり", "ipa": "bɯtsɯɾi", "syllable_count": 3, "sentences": [{"text": "物理の授業で、ボールが落ちる理由を考えた。", "target_word": "物理", "complexity_tier": "T3", "furigana": "物理[ぶつり]の授業[じゅぎょう]で、ボールが落[お]ちる理由[りゆう]を考[かんが]えた。", "sentence_source": "generated"}, {"text": "兄は物理が好きで、ものの動きを調べている。", "target_word": "物理", "complexity_tier": "T3", "furigana": "兄[あに]は物理[ぶつり]が好[す]きで、ものの動[うご]きを調[しら]べている。", "sentence_source": "generated"}, {"text": "物理を学ぶと、なぜ氷が水にうくのかが分かる。", "target_word": "物理", "complexity_tier": "T3", "furigana": "物理[ぶつり]を学[まな]ぶと、なぜ氷[こおり]が水[みず]にうくのかが分[わ]かる。", "sentence_source": "generated"}, {"text": "物理の宿題が難しくて、夜までかかった。", "target_word": "物理", "complexity_tier": "T3", "furigana": "物理[ぶつり]の宿題[しゅくだい]が難[むずか]しくて、夜[よる]までかかった。", "sentence_source": "generated"}, {"text": "橋がこわれない理由は、物理で説明できる。", "target_word": "物理", "complexity_tier": "T3", "furigana": "橋[はし]がこわれない理由[りゆう]は、物理[ぶつり]で説明[せつめい]できる。", "sentence_source": "generated"}, {"text": "先生は物理の考え方で、ブランコの動きを教えてくれた。", "target_word": "物理", "complexity_tier": "T3", "furigana": "先生[せんせい]は物理[ぶつり]の考[かんが]え方[かた]で、ブランコの動[うご]きを教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "物理が苦手なので、公式を何度も書いて覚えた。", "target_word": "物理", "complexity_tier": "T3", "furigana": "物理[ぶつり]が苦手[にがて]なので、公式[こうしき]を何度[なんど]も書[か]いて覚[おぼ]えた。", "sentence_source": "generated"}, {"text": "物理の知識を使えば、ボールが飛ぶ距離を計算できる。", "target_word": "物理", "complexity_tier": "T3", "furigana": "物理[ぶつり]の知識[ちしき]を使[つか]えば、ボールが飛[と]ぶ距離[きょり]を計算[けいさん]できる。", "sentence_source": "generated"}, {"text": "弟は物理の本を読んで、星の動きに興味を持った。", "target_word": "物理", "complexity_tier": "T3", "furigana": "弟[おとうと]は物理[ぶつり]の本[ほん]を読[よ]んで、星[ほし]の動[うご]きに興味[きょうみ]を持[も]った。", "sentence_source": "generated"}, {"text": "物理の実験で、鉄が熱でのびることを確かめた。", "target_word": "物理", "complexity_tier": "T3", "furigana": "物理[ぶつり]の実験[じっけん]で、鉄[てつ]が熱[ねつ]でのびることを確[たし]かめた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "物理", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "物の動きやしくみ、性質について考える科目としての物理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '138c9f88-9d7f-429e-8d2c-7d4fc969fc77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37568, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "物理", "is_correct": true, "explanation": "科目名として、ボールが落ちる理由を考える内容に合い、空欄に入る。"}, {"text": "失恋", "is_correct": false, "explanation": "出来事を表す語で、授業の科目にはならず文が成り立たない。"}, {"text": "寂しさ", "is_correct": false, "explanation": "感情を表す語で、「の授業」の科目名として使えない。"}, {"text": "友情", "is_correct": false, "explanation": "人間関係を表す語で、授業の科目として文脈に合わない。"}], "explanations": {"物理": "科目名として、ボールが落ちる理由を考える内容に合い、空欄に入る。", "失恋": "出来事を表す語で、授業の科目にはならず文が成り立たない。", "寂しさ": "感情を表す語で、「の授業」の科目名として使えない。", "友情": "人間関係を表す語で、授業の科目として文脈に合わない。"}, "sentence_index": 0, "correct_answer": "物理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この物理は熱に強く、ガラスより丈夫だ。", "explanation": "ここでは物理を材料の名前として使っており、学問名の物理とは合わない。"}, {"text": "酸と金属をまぜると泡が出るので、物理の実験で確かめた。", "explanation": "ここは〈化学〉の意味。薬品の反応は化学の範囲で、物の動きや性質を扱う物理とは合わない。"}, {"text": "物理の宿題で、人が生きる意味を考えた。", "explanation": "ここは〈哲学〉の意味。人の生き方を考える学問で、自然のしくみを扱う物理とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37568, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "物理", "is_correct": true, "explanation": "苦手な科目として、公式を何度も書いて覚えた文脈に合う。"}, {"text": "信頼", "is_correct": false, "explanation": "関係を表す語で、苦手の対象にも科目にもならず文が成り立たない。"}, {"text": "料理", "is_correct": false, "explanation": "料理は公式を覚える対象ではなく、文が成り立たない。"}, {"text": "希望", "is_correct": false, "explanation": "気持ちを表す語で、公式を覚える行為の対象として合わない。"}], "explanations": {"物理": "苦手な科目として、公式を何度も書いて覚えた文脈に合う。", "信頼": "関係を表す語で、苦手の対象にも科目にもならず文が成り立たない。", "料理": "料理は公式を覚える対象ではなく、文が成り立たない。", "希望": "気持ちを表す語で、公式を覚える行為の対象として合わない。"}, "sentence_index": 6, "correct_answer": "物理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "物理の授業で、地層から化石を集めた。", "explanation": "ここは〈地学〉の意味。化石や地層を調べる学問で、物の動きを考える物理の内容ではない。"}, {"text": "物理の授業で、ミドリムシを観察した。", "explanation": "ここは〈生物〉の意味。生き物を観察する内容で、物の動きや性質を扱う物理とは合わない。"}, {"text": "物理の授業で、お金の流れを学んだ。", "explanation": "ここは〈経済学〉の意味。お金の動きを扱う学問で、自然のきまりを扱う物理とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37568, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "物理を授業で、ボールの動きを計算した。", "corrected_sentence": "物理の授業で、ボールの動きを計算した。", "error_description": "「物理」の後は「の授業」と続ける。「を」は誤りで、正しくは「の」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37568, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "物理を学ぶると、ボールが落ちる理由が分かる。", "corrected_sentence": "物理を学ぶと、ボールが落ちる理由が分かる。", "error_description": "動詞「学ぶ」に「と」を続けるので「学ぶと」が正しい。「学ぶると」は余計な「る」が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37569, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示す「は」で、物理について説明する文になる。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」では主題にならず、文が不自然になる。"}, {"text": "に", "is_correct": false, "explanation": "方向や対象の「に」は、主題を示す文に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」で、物理へ向かう不自然な文になる。"}], "correct_answer": "は", "explanations": {"は": "主題を示す「は」で、物理について説明する文になる。", "を": "目的語の「を」では主題にならず、文が不自然になる。", "に": "方向や対象の「に」は、主題を示す文に合わない。", "へ": "方向の「へ」で、物理へ向かう不自然な文になる。"}, "error_tags": {"を": "目的語", "に": "方向・対象", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37569, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「物理の教科書」と名詞をつなぎ、所属を示す。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」で、教科書に続かない。"}, {"text": "を", "is_correct": false, "explanation": "二つ目の目的語を重ねる「を」で、「物理を教科書には」と不自然になる。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」で、物理が教科書に載るという不自然な文になる。"}], "correct_answer": "の", "explanations": {"の": "「物理の教科書」と名詞をつなぎ、所属を示す。", "へ": "方向を表す「へ」で、教科書に続かない。", "を": "二つ目の目的語を重ねる「を」で、「物理を教科書には」と不自然になる。", "が": "主語の「が」で、物理が教科書に載るという不自然な文になる。"}, "error_tags": {"へ": "方向", "を": "目的語", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37569, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物の性質や、物と物との関係についてのきまり。物事のしくみを研究する学問の分野。", "primary_collocate": null, "pronunciation": "ぶつり", "ipa": "bɯtsɯɾi", "syllable_count": 3, "sentences": [{"text": "大学では物理を専攻して、研究者になりたい。", "target_word": "物理", "complexity_tier": "T3", "furigana": "大学[だいがく]では物理[ぶつり]を専攻[せんこう]して、研究者[けんきゅうしゃ]になりたい。", "sentence_source": "generated"}, {"text": "物理は、自然のきまりを研究する学問だ。", "target_word": "物理", "complexity_tier": "T3", "furigana": "物理[ぶつり]は、自然[しぜん]のきまりを研究[けんきゅう]する学問[がくもん]だ。", "sentence_source": "generated"}, {"text": "この法則は、物理の基本として世界中で教えられている。", "target_word": "物理", "complexity_tier": "T3", "furigana": "この法則[ほうそく]は、物理[ぶつり]の基本[きほん]として世界中[せかいじゅう]で教[おし]えられている。", "sentence_source": "generated"}, {"text": "姉は物理の先生で、高校で毎日授業をしている。", "target_word": "物理", "complexity_tier": "T3", "furigana": "姉[あね]は物理[ぶつり]の先生[せんせい]で、高校[こうこう]で毎日[まいにち]授業[じゅぎょう]をしている。", "sentence_source": "generated"}, {"text": "物理の試験に、重力についての問題が出た。", "target_word": "物理", "complexity_tier": "T3", "furigana": "物理[ぶつり]の試験[しけん]に、重力[じゅうりょく]についての問題[もんだい]が出[で]た。", "sentence_source": "generated"}, {"text": "物理を研究する人は、実験と計算の両方を行う。", "target_word": "物理", "complexity_tier": "T3", "furigana": "物理[ぶつり]を研究[けんきゅう]する人[ひと]は、実験[じっけん]と計算[けいさん]の両方[りょうほう]を行[おこな]う。", "sentence_source": "generated"}, {"text": "ニュートンは、物理の歴史を変えた科学者だ。", "target_word": "物理", "complexity_tier": "T3", "furigana": "ニュートンは、物理[ぶつり]の歴史[れきし]を変[か]えた科学者[かがくしゃ]だ。", "sentence_source": "generated"}, {"text": "物理の教科書には、力と運動のきまりがのっている。", "target_word": "物理", "complexity_tier": "T3", "furigana": "物理[ぶつり]の教科書[きょうかしょ]には、力[ちから]と運動[うんどう]のきまりがのっている。", "sentence_source": "generated"}, {"text": "彼は物理に強いので、友だちがよく質問に来る。", "target_word": "物理", "complexity_tier": "T3", "furigana": "彼[かれ]は物理[ぶつり]に強[つよ]いので、友[とも]だちがよく質問[しつもん]に来[く]る。", "sentence_source": "generated"}, {"text": "物理の法則によって、光は真空の中を進むことができる。", "target_word": "物理", "complexity_tier": "T3", "furigana": "物理[ぶつり]の法則[ほうそく]によって、光[ひかり]は真空[しんくう]の中[なか]を進[すす]むことができる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "物理", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "自然の法則を研究する学問分野としての物理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '138c9f88-9d7f-429e-8d2c-7d4fc969fc77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37569, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "物理", "is_correct": true, "explanation": "専攻する学問の名前で、研究者になりたいという文に合う。"}, {"text": "嫉妬", "is_correct": false, "explanation": "感情の語で、専攻の対象にはならず文が成り立たない。"}, {"text": "後悔", "is_correct": false, "explanation": "感情の語で、大学で専攻するものとして不自然。"}, {"text": "不安", "is_correct": false, "explanation": "気持ちを表す語で、専攻する分野にはならない。"}], "explanations": {"物理": "専攻する学問の名前で、研究者になりたいという文に合う。", "嫉妬": "感情の語で、専攻の対象にはならず文が成り立たない。", "後悔": "感情の語で、大学で専攻するものとして不自然。", "不安": "気持ちを表す語で、専攻する分野にはならない。"}, "sentence_index": 0, "correct_answer": "物理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "姉は物理の研究者で、山で化石を集めている。", "explanation": "ここは〈地学〉の意味。化石や地層を調べる学問で、物の動きや性質を扱う物理とは合わない。"}, {"text": "姉は物理の先生で、高校で命の大切さを教えている。", "explanation": "ここは〈倫理〉の意味。命の大切さを教える内容で、自然のきまりを扱う物理とは合わない。"}, {"text": "姉は物理の歌手で、毎晩ステージで歌っている。", "explanation": "ここは〈音楽〉の意味。歌をうたう活動は音楽の範囲で、自然のきまりを研究する物理とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37569, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "物理", "is_correct": true, "explanation": "学問の名前で、ニュートンが歴史を変えた科学者という文に合う。"}, {"text": "謙遜", "is_correct": false, "explanation": "態度を表す語で、学問の歴史の対象にはならない。"}, {"text": "恋愛", "is_correct": false, "explanation": "感情や関係を表す語で、科学者が歴史を変えた対象として不自然。"}, {"text": "感激", "is_correct": false, "explanation": "気持ちを表す語で、歴史の対象として文が成り立たない。"}], "explanations": {"物理": "学問の名前で、ニュートンが歴史を変えた科学者という文に合う。", "謙遜": "態度を表す語で、学問の歴史の対象にはならない。", "恋愛": "感情や関係を表す語で、科学者が歴史を変えた対象として不自然。", "感激": "気持ちを表す語で、歴史の対象として文が成り立たない。"}, "sentence_index": 6, "correct_answer": "物理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "友人は物理の研究で、人の心の仕組みを調べている。", "explanation": "ここは〈心理学〉の意味。人の心を扱う学問で、自然のきまりを扱う物理とは合わない。"}, {"text": "物理の授業で、昔の戦争の原因を学んだ。", "explanation": "ここは〈歴史学〉の意味。過去の出来事を扱うので、自然の法則を扱う物理とは合わない。"}, {"text": "物理の研究で、物価の変動を調べた。", "explanation": "ここは〈経済学〉の意味。お金や物価を扱う学問で、物理の対象とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37569, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大学では物理に専攻して、宇宙の研究をしたい。", "corrected_sentence": "大学では物理を専攻して、宇宙の研究をしたい。", "error_description": "「専攻する」は目的語に「を」を取る。「に」は誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37569, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "物理を研究すった人は、実験を重ねる。", "corrected_sentence": "物理を研究する人は、実験を重ねる。", "error_description": "動詞「研究する」の連体形は「研究する人」。「研究すった」は活用が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
