INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37570, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「研究するエンジニアが」は主語で、「考えている」の主語として正しい。"}, {"text": "を", "is_correct": false, "explanation": "「を」にすると「エンジニアを、形を考えている」となり、考える人が主語になれず不自然。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所・相手などを示し、ここでは主語を作れない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、主語の位置には合わない。"}], "correct_answer": "が", "explanations": {"が": "「研究するエンジニアが」は主語で、「考えている」の主語として正しい。", "を": "「を」にすると「エンジニアを、形を考えている」となり、考える人が主語になれず不自然。", "に": "「に」は場所・相手などを示し、ここでは主語を作れない。", "へ": "「へ」は方向を示すので、主語の位置には合わない。"}, "error_tags": {"を": "object", "に": "location_or_dative", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37570, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "飛行機や車などの乗り物を作る技術者。", "primary_collocate": null, "pronunciation": "えんじにあ", "ipa": "endʑinia", "syllable_count": 5, "sentences": [{"text": "兄は飛行機のエンジニアとして、空港の近くで働いている。", "target_word": "エンジニア", "complexity_tier": "T3", "furigana": "兄[あに]は飛行機[ひこうき]のエンジニアとして、空港[くうこう]の近[ちか]くで働[はたら]いている。", "sentence_source": "generated"}, {"text": "あのエンジニアは、新しい車のエンジンを作っている。", "target_word": "エンジニア", "complexity_tier": "T3", "furigana": "あのエンジニアは、新[あたら]しい車[くるま]のエンジンを作[つく]っている。", "sentence_source": "generated"}, {"text": "エンジニアが機体を調べて、小さな問題を見つけた。", "target_word": "エンジニア", "complexity_tier": "T3", "furigana": "エンジニアが機体[きたい]を調[しら]べて、小[ちい]さな問題[もんだい]を見[み]つけた。", "sentence_source": "generated"}, {"text": "将来はエンジニアになって、空を飛ぶ乗り物を作りたい。", "target_word": "エンジニア", "complexity_tier": "T3", "furigana": "将来[しょうらい]はエンジニアになって、空[そら]を飛[と]ぶ乗[の]り物[もの]を作[つく]りたい。", "sentence_source": "generated"}, {"text": "車の会社で働くエンジニアは、毎日試験を行う。", "target_word": "エンジニア", "complexity_tier": "T3", "furigana": "車[くるま]の会社[かいしゃ]で働[はたら]くエンジニアは、毎日[まいにち]試験[しけん]を行[おこな]う。", "sentence_source": "generated"}, {"text": "ヘリコプターを設計したエンジニアが、学校で話をした。", "target_word": "エンジニア", "complexity_tier": "T3", "furigana": "ヘリコプターを設計[せっけい]したエンジニアが、学校[がっこう]で話[はなし]をした。", "sentence_source": "generated"}, {"text": "エンジニアの仕事は、安全な乗り物を作ることだ。", "target_word": "エンジニア", "complexity_tier": "T3", "furigana": "エンジニアの仕事[しごと]は、安全[あんぜん]な乗[の]り物[もの]を作[つく]ることだ。", "sentence_source": "generated"}, {"text": "空気の力を研究するエンジニアが、新しい飛行機の形を考えている。", "target_word": "エンジニア", "complexity_tier": "T3", "furigana": "空気[くうき]の力[ちから]を研究[けんきゅう]するエンジニアが、新[あたら]しい飛行機[ひこうき]の形[かたち]を考[かんが]えている。", "sentence_source": "generated"}, {"text": "父は電車のエンジニアで、新しい車両の部品を考えている。", "target_word": "エンジニア", "complexity_tier": "T3", "furigana": "父[ちち]は電車[でんしゃ]のエンジニアで、新[あたら]しい車両[しゃりょう]の部品[ぶひん]を考[かんが]えている。", "sentence_source": "generated"}, {"text": "エンジニアたちは、軽くて丈夫な翼を作るために何度も実験した。", "target_word": "エンジニア", "complexity_tier": "T3", "furigana": "エンジニアたちは、軽[かる]くて丈夫[じょうぶ]な翼[つばさ]を作[つく]るために何度[なんど]も実験[じっけん]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "エンジニア", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "飛行機や車などの乗り物を作る技術者", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07c94323-d2a7-4136-9285-064b10d13ae7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37570, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "座席", "is_correct": false, "explanation": "座席は座るための設備で、「飛行機の座席として働く」は意味が通らない。"}, {"text": "エンジニア", "is_correct": true, "explanation": "飛行機を作る技術者で、兄が空港の近くで働くという文に合う。"}, {"text": "翼", "is_correct": false, "explanation": "翼は機体の一部で、人の職業として「翼として働く」とは言えない。"}, {"text": "滑走路", "is_correct": false, "explanation": "滑走路は空港の施設で、人が立場として働くものではない。"}], "explanations": {"座席": "座席は座るための設備で、「飛行機の座席として働く」は意味が通らない。", "エンジニア": "飛行機を作る技術者で、兄が空港の近くで働くという文に合う。", "翼": "翼は機体の一部で、人の職業として「翼として働く」とは言えない。", "滑走路": "滑走路は空港の施設で、人が立場として働くものではない。"}, "sentence_index": 0, "correct_answer": "エンジニア"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "あの店のエンジニアは、三十年間同じ器を手で作り続けている。", "explanation": "ここは〈職人〉の意味。エンジニアは機械や乗り物を設計・開発する技術者で、手仕事で器を作る人には使わない。"}, {"text": "兄は毎朝、エンジニアとしてバスを運転して、乗客を駅まで送る。", "explanation": "ここは〈運転手〉の意味。エンジニアは乗り物を作る技術者で、乗り物を運転して客を運ぶ人には使わない。"}, {"text": "兄は毎日、エンジニアとして店でパンを焼いて売っている。", "explanation": "ここは〈パン屋〉の意味。エンジニアは乗り物を作る技術者で、パンを焼いて売る人には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37570, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乗客", "is_correct": false, "explanation": "乗客は乗る人で、「乗客の仕事は安全な乗り物を作ることだ」は成り立たない。"}, {"text": "切符", "is_correct": false, "explanation": "切符は乗車券で、仕事の内容として「乗り物を作る」とは結びつかない。"}, {"text": "エンジニア", "is_correct": true, "explanation": "乗り物を作る技術者で、仕事の内容と合う。"}, {"text": "車庫", "is_correct": false, "explanation": "車庫は車を停める場所で、「車庫の仕事は乗り物を作ること」は不自然。"}], "explanations": {"乗客": "乗客は乗る人で、「乗客の仕事は安全な乗り物を作ることだ」は成り立たない。", "切符": "切符は乗車券で、仕事の内容として「乗り物を作る」とは結びつかない。", "エンジニア": "乗り物を作る技術者で、仕事の内容と合う。", "車庫": "車庫は車を停める場所で、「車庫の仕事は乗り物を作ること」は不自然。"}, "sentence_index": 6, "correct_answer": "エンジニア"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "エンジニアたちは、新しい薬の効果を確かめるために何度も実験した。", "explanation": "ここは〈研究者〉の意味。エンジニアは機械や乗り物を作る技術者で、薬の効果を研究する人には使わない。"}, {"text": "エンジニアたちは、朝早く市場へ行き、新鮮な野菜を一つずつ選んで買った。", "explanation": "ここは〈仕入れ業者〉の意味。エンジニアは機械や技術を開発する専門家で、市場で食材を買い付ける人には使わない。"}, {"text": "エンジニアたちは、会議で英語を日本語に何度も通訳した。", "explanation": "ここは〈通訳〉の意味。エンジニアは技術を作る専門家で、言葉を訳す人には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37570, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姉は将来、電車のエンジニアをなりたいと言っている。", "corrected_sentence": "姉は将来、電車のエンジニアになりたいと言っている。", "error_description": "「なる」は「に」を取る。「エンジニアを」は誤りで、正しくは「エンジニアに」（〜になりたい）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37570, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この工場では、エンジニアで三人働いている。", "corrected_sentence": "この工場では、エンジニアが三人働いている。", "error_description": "「三人が働く」の主語は「が」。「で」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37571, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「エンジニアが」は主語で、開発する人として文に合う。"}, {"text": "を", "is_correct": false, "explanation": "「を」にすると「エンジニアを開発し」となり、開発する人が主語にならず不自然。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や場所を示し、ここでは主語を作れない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、主語の位置には合わない。"}], "correct_answer": "が", "explanations": {"が": "「エンジニアが」は主語で、開発する人として文に合う。", "を": "「を」にすると「エンジニアを開発し」となり、開発する人が主語にならず不自然。", "に": "「に」は相手や場所を示し、ここでは主語を作れない。", "へ": "「へ」は方向を示すので、主語の位置には合わない。"}, "error_tags": {"を": "object", "に": "location_or_dative", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37571, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37571, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "機械や装置を設計・開発する専門家。特に、飛行機などの乗り物やコンピューターなどの技術を扱う仕事。", "primary_collocate": null, "pronunciation": "えんじにあ", "ipa": "endʑinia", "syllable_count": 5, "sentences": [{"text": "彼はコンピューターを設計するエンジニアとして、会社で働いている。", "target_word": "エンジニア", "complexity_tier": "T3", "furigana": "彼[かれ]はコンピューターを設計[せっけい]するエンジニアとして、会社[かいしゃ]で働[はたら]いている。", "sentence_source": "generated"}, {"text": "エンジニアが新しい機械を開発し、工場で使われ始めた。", "target_word": "エンジニア", "complexity_tier": "T3", "furigana": "エンジニアが新[あたら]しい機械[きかい]を開発[かいはつ]し、工場[こうじょう]で使[つか]われ始[はじ]めた。", "sentence_source": "generated"}, {"text": "システムに問題が出たので、エンジニアが夜中に呼ばれた。", "target_word": "エンジニア", "complexity_tier": "T3", "furigana": "システムに問題[もんだい]が出[で]たので、エンジニアが夜中[よなか]に呼[よ]ばれた。", "sentence_source": "generated"}, {"text": "エンジニアになるために、大学で技術を学んだ。", "target_word": "エンジニア", "complexity_tier": "T3", "furigana": "エンジニアになるために、大学[だいがく]で技術[ぎじゅつ]を学[まな]んだ。", "sentence_source": "generated"}, {"text": "ソフトウェアのエンジニアは、画面の裏で動くしくみを作る。", "target_word": "エンジニア", "complexity_tier": "T3", "furigana": "ソフトウェアのエンジニアは、画面[がめん]の裏[うら]で動[うご]くしくみを作[つく]る。", "sentence_source": "generated"}, {"text": "装置の設計を担当するエンジニアが、図面を直している。", "target_word": "エンジニア", "complexity_tier": "T3", "furigana": "装置[そうち]の設計[せっけい]を担当[たんとう]するエンジニアが、図面[ずめん]を直[なお]している。", "sentence_source": "generated"}, {"text": "優秀なエンジニアは、難しい問題を分かりやすく説明できる。", "target_word": "エンジニア", "complexity_tier": "T3", "furigana": "優秀[ゆうしゅう]なエンジニアは、難[むずか]しい問題[もんだい]を分[わ]かりやすく説明[せつめい]できる。", "sentence_source": "generated"}, {"text": "彼女は医療機器を開発するエンジニアだ。", "target_word": "エンジニア", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は医療機器[いりょうきき]を開発[かいはつ]するエンジニアだ。", "sentence_source": "generated"}, {"text": "エンジニアの募集を見て、私はその会社に応募した。", "target_word": "エンジニア", "complexity_tier": "T3", "furigana": "エンジニアの募集[ぼしゅう]を見[み]て、私[わたし]はその会社[かいしゃ]に応募[おうぼ]した。", "sentence_source": "generated"}, {"text": "専門のエンジニアがいなければ、この大きな機械は動かせない。", "target_word": "エンジニア", "complexity_tier": "T3", "furigana": "専門[せんもん]のエンジニアがいなければ、この大[おお]きな機械[きかい]は動[うご]かせない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "エンジニア", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "機械や装置、コンピューターを設計・開発する専門家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07c94323-d2a7-4136-9285-064b10d13ae7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37571, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "図面", "is_correct": false, "explanation": "図面は設計を示す紙で、「設計する図面として働く」は成り立たない。"}, {"text": "エンジニア", "is_correct": true, "explanation": "コンピューターを設計する専門家で、会社で働くという文に合う。"}, {"text": "部品", "is_correct": false, "explanation": "部品は機械の一部で、人の立場として「部品として働く」とは言わない。"}, {"text": "工具", "is_correct": false, "explanation": "工具は作業に使う道具で、「工具として会社で働く」は意味が通らない。"}], "explanations": {"図面": "図面は設計を示す紙で、「設計する図面として働く」は成り立たない。", "エンジニア": "コンピューターを設計する専門家で、会社で働くという文に合う。", "部品": "部品は機械の一部で、人の立場として「部品として働く」とは言わない。", "工具": "工具は作業に使う道具で、「工具として会社で働く」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "エンジニア"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼はエンジニアとして、夜勤の後も病院で患者の手術を続けている。", "explanation": "ここは〈医師〉の意味。エンジニアは機械やシステムを開発する人で、患者の手術をする人には使わない。"}, {"text": "彼女はエンジニアとして、英語の小説を毎晩日本語に訳している。", "explanation": "ここは〈翻訳家〉の意味。エンジニアは機械や技術を作る専門家で、小説を訳す人には使わない。"}, {"text": "父はエンジニアとして、毎朝畑で米と野菜を育てている。", "explanation": "ここは〈農家〉の意味。エンジニアは機械や装置を開発する専門家で、畑で作物を育てる人には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37571, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "座布団", "is_correct": false, "explanation": "座布団は座る物で、「優秀な座布団は難しい問題を説明できる」は成り立たない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様で、人のように問題を説明することはできない。"}, {"text": "エンジニア", "is_correct": true, "explanation": "専門的な技術を持つ人で、難しい問題を説明できるという文に合う。"}, {"text": "切手", "is_correct": false, "explanation": "切手は郵便に使う物で、問題を説明する主体にはならない。"}], "explanations": {"座布団": "座布団は座る物で、「優秀な座布団は難しい問題を説明できる」は成り立たない。", "天気": "天気は空模様で、人のように問題を説明することはできない。", "エンジニア": "専門的な技術を持つ人で、難しい問題を説明できるという文に合う。", "切手": "切手は郵便に使う物で、問題を説明する主体にはならない。"}, "sentence_index": 6, "correct_answer": "エンジニア"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "専門のエンジニアがいなければ、彼女の髪は美しく切れない。", "explanation": "ここは〈美容師〉の意味。エンジニアは機械や装置を設計・開発する専門家で、髪を切る人には使わない。"}, {"text": "専門のエンジニアがいなければ、この大きな絵は描けない。", "explanation": "ここは〈画家〉の意味。エンジニアは機械や装置を開発する専門家で、絵を描く人には使わない。"}, {"text": "専門のエンジニアがいなければ、このむずかしい歌は歌えない。", "explanation": "ここは〈歌手〉の意味。エンジニアは機械や装置を開発する専門家で、歌を歌う人には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37571, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姉は去年から大きな会社でエンジニアに働いている。", "corrected_sentence": "姉は去年から大きな会社でエンジニアとして働いている。", "error_description": "「働く」の資格は「として」で示す。「エンジニアに」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37571, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "あの会社のエンジニアを一人が、新しいソフトを開発している。", "corrected_sentence": "あの会社のエンジニアの一人が、新しいソフトを開発している。", "error_description": "「エンジニアの一人」の「の」が正しい。「を」は目的語になり、「一人が」と合わず誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37572, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下手", "is_correct": true, "explanation": "〈上手〉（うまくできる）の対義語。「先生は教えるのが上手」に対して「下手」が反対の意味になる。"}, {"text": "静か", "is_correct": false, "explanation": "形状詞だが、〈上手〉の反対の意味を持たない。"}, {"text": "丁寧", "is_correct": false, "explanation": "注意深くていねいなさまで、〈上手〉の類義語とも対義語とも言えない。"}, {"text": "派手", "is_correct": false, "explanation": "はなやかで目立つさまを表し、腕前の反対語ではない。"}], "correct_answer": "下手", "explanations": {"下手": "〈上手〉（うまくできる）の対義語。「先生は教えるのが上手」に対して「下手」が反対の意味になる。", "静か": "形状詞だが、〈上手〉の反対の意味を持たない。", "丁寧": "注意深くていねいなさまで、〈上手〉の類義語とも対義語とも言えない。", "派手": "はなやかで目立つさまを表し、腕前の反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37572, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下手", "is_correct": true, "explanation": "〈上手〉（うまくできる）の対義語。「友達は写真をとるのが上手」に対して反対の意味になる。"}, {"text": "穏やか", "is_correct": false, "explanation": "おだやかなさまで、腕前の反対語ではない。"}, {"text": "無邪気", "is_correct": false, "explanation": "かざりのない素直さを表し、腕前の反対語ではない。"}, {"text": "地味", "is_correct": false, "explanation": "はで派手でないさまで、〈上手〉の反対語ではない。"}], "correct_answer": "下手", "explanations": {"下手": "〈上手〉（うまくできる）の対義語。「友達は写真をとるのが上手」に対して反対の意味になる。", "穏やか": "おだやかなさまで、腕前の反対語ではない。", "無邪気": "かざりのない素直さを表し、腕前の反対語ではない。", "地味": "はで派手でないさまで、〈上手〉の反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37572, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "じょうずは、うまくできることです。", "primary_collocate": null, "pronunciation": "じょうず", "ipa": "dʑoːzɯ", "syllable_count": 2, "sentences": [{"text": "姉は料理が上手で、毎日おいしい晩ご飯を作る。", "target_word": "上手", "complexity_tier": "T3", "furigana": "姉[あね]は料理[りょうり]が上手[じょうず]で、毎日[まいにち]おいしい晩[ばん]ご飯[はん]を作[つく]る。", "sentence_source": "generated"}, {"text": "私は絵が下手だが、弟は上手だ。", "target_word": "上手", "complexity_tier": "T3", "furigana": "私[わたし]は絵[え]が下手[へた]だが、弟[おとうと]は上手[じょうず]だ。", "sentence_source": "generated"}, {"text": "彼は人の話を聞くのが上手なので、みんなに好かれている。", "target_word": "上手", "complexity_tier": "T3", "furigana": "彼[かれ]は人[ひと]の話[はなし]を聞[き]くのが上手[じょうず]なので、みんなに好[す]かれている。", "sentence_source": "generated"}, {"text": "先生は教えるのが上手で、むずかしい問題もよくわかった。", "target_word": "上手", "complexity_tier": "T3", "furigana": "先生[せんせい]は教[おし]えるのが上手[じょうず]で、むずかしい問題[もんだい]もよくわかった。", "sentence_source": "generated"}, {"text": "田中さんは日本語が上手になったね。", "target_word": "上手", "complexity_tier": "T3", "furigana": "田中[たなか]さんは日本語[にほんご]が上手[じょうず]になったね。", "sentence_source": "generated"}, {"text": "上手に字を書くために、毎日練習している。", "target_word": "上手", "complexity_tier": "T3", "furigana": "上手[じょうず]に字[じ]を書[か]くために、毎日[まいにち]練習[れんしゅう]している。", "sentence_source": "generated"}, {"text": "妹はピアノが上手なので、発表会で弾くことになった。", "target_word": "上手", "complexity_tier": "T3", "furigana": "妹[いもうと]はピアノが上手[じょうず]なので、発表会[はっぴょうかい]で弾[ひ]くことになった。", "sentence_source": "generated"}, {"text": "母は買い物が上手で、安くていい物をよく見つける。", "target_word": "上手", "complexity_tier": "T3", "furigana": "母[はは]は買[か]い物[もの]が上手[じょうず]で、安[やす]くていい物[もの]をよく見[み]つける。", "sentence_source": "generated"}, {"text": "あの人は泳ぐのが上手だから、海でも安心だ。", "target_word": "上手", "complexity_tier": "T3", "furigana": "あの人[ひと]は泳[およ]ぐのが上手[じょうず]だから、海[うみ]でも安心[あんしん]だ。", "sentence_source": "generated"}, {"text": "友達は写真をとるのが上手で、私の顔もきれいにうつる。", "target_word": "上手", "complexity_tier": "T3", "furigana": "友達[ともだち]は写真[しゃしん]をとるのが上手[じょうず]で、私[わたし]の顔[かお]もきれいにうつる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "上手だ", "label": "終止形"}, {"form": "上手な", "label": "連体形"}, {"form": "上手に", "label": "連用形"}, {"form": "上手で", "label": "連用形（で）"}], "register": "中立（日常会話）", "sense_fingerprint": "物事をうまくできる様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68b8a0b9-d581-49d2-8aa6-b2f3d6bfbb8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37572, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上手", "is_correct": true, "explanation": "〈上手〉は料理の腕前がよいことを表し、「料理が〜で」の述語として文に合う。"}, {"text": "乱暴", "is_correct": false, "explanation": "荒っぽい態度や性質を表すので、料理の出来ばえを述べる文には合わない。"}, {"text": "不思議", "is_correct": false, "explanation": "ふしぎなさまを表す語で、料理の腕前を述べる語ではない。"}, {"text": "静か", "is_correct": false, "explanation": "音や様子が穏やかなことを表し、料理の腕前には使わない。"}], "explanations": {"上手": "〈上手〉は料理の腕前がよいことを表し、「料理が〜で」の述語として文に合う。", "乱暴": "荒っぽい態度や性質を表すので、料理の出来ばえを述べる文には合わない。", "不思議": "ふしぎなさまを表す語で、料理の腕前を述べる語ではない。", "静か": "音や様子が穏やかなことを表し、料理の腕前には使わない。"}, "sentence_index": 0, "correct_answer": "上手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "業績が上手で、来期も期待できる。", "explanation": "ここは〈好調〉（物事の調子がよいさま）の意味。〈上手〉は技術や能力のすぐれた様子を表し、業績の調子には使わない。"}, {"text": "テストで満点を取って、彼は上手な顔をした。", "explanation": "ここは〈得意〉（誇らしげ）の意味。〈上手〉は腕前がすぐれることで、表情の誇らしさには使わない。"}, {"text": "祖父は八十歳でも上手で、毎朝散歩をする。", "explanation": "ここは〈達者〉（元気で丈夫）の意味。〈上手〉は技術の確かさを表し、体の丈夫さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37572, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上手", "is_correct": true, "explanation": "〈上手〉はピアノの腕前がよいことを表し、「ピアノが〜なので」に入る。"}, {"text": "窮屈", "is_correct": false, "explanation": "せまくて動きにくいさまを表し、ピアノの腕前には使わない。"}, {"text": "寂しい", "is_correct": false, "explanation": "心細さや静けさを表す語で、演奏の腕前とは結びつかない。"}, {"text": "陰気", "is_correct": false, "explanation": "暗くしずんだ雰囲気を表し、ピアノの腕前を述べる語ではない。"}], "explanations": {"上手": "〈上手〉はピアノの腕前がよいことを表し、「ピアノが〜なので」に入る。", "窮屈": "せまくて動きにくいさまを表し、ピアノの腕前には使わない。", "寂しい": "心細さや静けさを表す語で、演奏の腕前とは結びつかない。", "陰気": "暗くしずんだ雰囲気を表し、ピアノの腕前を述べる語ではない。"}, "sentence_index": 6, "correct_answer": "上手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は上手な服装で、パーティーに来た。", "explanation": "ここは〈上品〉（品がよいさま）の意味。〈上手〉は技術のすぐれていることで、服装の品格には使わない。"}, {"text": "彼は上手で、ほとんど話さない。", "explanation": "ここは〈無口〉（口数が少ないさま）の意味。〈上手〉は腕前の高さを表し、話す量には使わない。"}, {"text": "部屋が上手で、片付けに時間がかかった。", "explanation": "ここは〈乱雑〉（散らかっているさま）の意味。〈上手〉は腕前がよいことで、部屋の様子には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37572, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "母は洗濯が上手に、いつもきれいに畳む。", "corrected_sentence": "母は洗濯が上手で、いつもきれいに畳む。", "error_description": "形の誤り。「上手」を述語にして後ろへ続けるには連用形の「で」が必要。「上手に」は副詞なので、「洗濯が」の述語にはならない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "上手", "is_correct": true, "explanation": "語幹。「〜だ」を付けて「弟は上手だ」と述語になる。"}, {"text": "上手な", "is_correct": false, "explanation": "連体形で名詞を修飾する形。「上手なだ」とは続かない。"}, {"text": "上手に", "is_correct": false, "explanation": "連用形の副詞。「上手にだ」という形は成り立たない。"}, {"text": "上手で", "is_correct": false, "explanation": "接続の「で」が付いた形。「上手でだ」とは続かない。"}], "correct_form": "上手", "base_form": "上手だ", "form_label": "語幹＋だ（終止形）", "sentence_index": 1, "explanations": {"上手": "語幹。「〜だ」を付けて「弟は上手だ」と述語になる。", "上手な": "連体形で名詞を修飾する形。「上手なだ」とは続かない。", "上手に": "連用形の副詞。「上手にだ」という形は成り立たない。", "上手で": "接続の「で」が付いた形。「上手でだ」とは続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37572, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は上手の絵を描く。", "corrected_sentence": "彼女は上手な絵を描く。", "error_description": "形の誤り。「上手」は名詞を修飾するとき「上手な」になる。「上手の」は文法的に成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "上手", "is_correct": true, "explanation": "語幹。ここでは「で」が続き、「買い物が上手で」と述語になる。"}, {"text": "上手だった", "is_correct": false, "explanation": "過去の形。「買い物が上手だったで」とは続かない。"}, {"text": "上手でない", "is_correct": false, "explanation": "否定の形。「買い物が上手でないで」とは続かない。"}, {"text": "上手だ", "is_correct": false, "explanation": "終止形。「上手だで」とは接続できない。"}], "correct_form": "上手", "base_form": "上手だ", "form_label": "語幹＋で（連用形）", "sentence_index": 7, "explanations": {"上手": "語幹。ここでは「で」が続き、「買い物が上手で」と述語になる。", "上手だった": "過去の形。「買い物が上手だったで」とは続かない。", "上手でない": "否定の形。「買い物が上手でないで」とは続かない。", "上手だ": "終止形。「上手だで」とは接続できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0963b36e-e2ca-4a1e-93fe-9a42d5c5b09b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37574, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "へ", "options": [{"text": "へ", "is_correct": true, "explanation": "移動の向かう先を表す「へ」で、空へ上がっていく文になる。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」で、空が上がるという不自然な文になる。"}, {"text": "で", "is_correct": false, "explanation": "場所を示す「で」は移動の向かう先を表さない。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」で、動きの向きを示さないので文が合わない。"}], "correct_answer": "へ", "explanations": {"へ": "移動の向かう先を表す「へ」で、空へ上がっていく文になる。", "が": "主語の「が」で、空が上がるという不自然な文になる。", "で": "場所を示す「で」は移動の向かう先を表さない。", "と": "並列の「と」で、動きの向きを示さないので文が合わない。"}, "error_tags": {"が": "主語", "で": "場所", "と": "並列"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下がる", "is_correct": true, "explanation": "「上がる」の対義語で、物が下へ動くことを表す。"}, {"text": "止まる", "is_correct": false, "explanation": "動きが止まる意味で、上へ動くことの反対語ではない。"}, {"text": "残る", "is_correct": false, "explanation": "その場に留まる意味で、上がるの対義語ではない。"}, {"text": "運ぶ", "is_correct": false, "explanation": "物を移動させる意味で、上がるの対義語ではない。"}], "correct_answer": "下がる", "explanations": {"下がる": "「上がる」の対義語で、物が下へ動くことを表す。", "止まる": "動きが止まる意味で、上へ動くことの反対語ではない。", "残る": "その場に留まる意味で、上がるの対義語ではない。", "運ぶ": "物を移動させる意味で、上がるの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37574, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下がる", "is_correct": true, "explanation": "「上がる」の対義語で、ボールが下へ動くことを表す。"}, {"text": "通る", "is_correct": false, "explanation": "通過する意味で、上がるの対義語ではない。"}, {"text": "並ぶ", "is_correct": false, "explanation": "横に並ぶ意味で、上がるの対義語ではない。"}, {"text": "寄る", "is_correct": false, "explanation": "近づく意味で、上がるの対義語ではない。"}], "correct_answer": "下がる", "explanations": {"下がる": "「上がる」の対義語で、ボールが下へ動くことを表す。", "通る": "通過する意味で、上がるの対義語ではない。", "並ぶ": "横に並ぶ意味で、上がるの対義語ではない。", "寄る": "近づく意味で、上がるの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37574, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "うえに うごく こと。", "primary_collocate": null, "pronunciation": "あがる", "ipa": "aɡaɾɯ", "syllable_count": 3, "sentences": [{"text": "ロケットが勢いよく上がって、青空に消えた。", "target_word": "上がって", "complexity_tier": "T3", "furigana": "ロケットが勢[いきお]いよく上[あ]がって、青空[あおぞら]に消[き]えた。", "sentence_source": "generated"}, {"text": "風船が空へ上がっていくのを、子どもたちが見ていた。", "target_word": "上がって", "complexity_tier": "T3", "furigana": "風船[ふうせん]が空[そら]へ上[あ]がっていくのを、子[こ]どもたちが見[み]ていた。", "sentence_source": "generated"}, {"text": "大きな音とともに、花火が夜空に上がった。", "target_word": "上がった", "complexity_tier": "T3", "furigana": "大[おお]きな音[おと]とともに、花火[はなび]が夜空[よぞら]に上[あ]がった。", "sentence_source": "generated"}, {"text": "ヘリコプターがゆっくり上がって、山の上を飛んでいった。", "target_word": "上がって", "complexity_tier": "T3", "furigana": "ヘリコプターがゆっくり上[あ]がって、山[やま]の上[うえ]を飛[と]んでいった。", "sentence_source": "generated"}, {"text": "風がないので、煙がまっすぐ上がっている。", "target_word": "上がって", "complexity_tier": "T3", "furigana": "風[かぜ]がないので、煙[けむり]がまっすぐ上[あ]がっている。", "sentence_source": "generated"}, {"text": "大雨で水かさが上がって、川があふれそうだ。", "target_word": "上がって", "complexity_tier": "T3", "furigana": "大雨[おおあめ]で水[みず]かさが上[あ]がって、川[かわ]があふれそうだ。", "sentence_source": "generated"}, {"text": "幕が上がると、劇が始まった。", "target_word": "上がる", "complexity_tier": "T3", "furigana": "幕[まく]が上[あ]がると、劇[げき]が始[はじ]まった。", "sentence_source": "generated"}, {"text": "ゴンドラが少しずつ上がって、景色が広がった。", "target_word": "上がって", "complexity_tier": "T3", "furigana": "ゴンドラが少[すこ]しずつ上[あ]がって、景色[けしき]が広[ひろ]がった。", "sentence_source": "generated"}, {"text": "湯気が上がるあたたかいスープを、ゆっくり飲んだ。", "target_word": "上がる", "complexity_tier": "T3", "furigana": "湯気[ゆげ]が上[あ]がるあたたかいスープを、ゆっくり飲[の]んだ。", "sentence_source": "generated"}, {"text": "ボールが高く上がって、みんなが空を見た。", "target_word": "上がって", "complexity_tier": "T3", "furigana": "ボールが高[たか]く上[あ]がって、みんなが空[そら]を見[み]た。", "sentence_source": "generated"}], "morphological_forms": [{"form": "上がる", "label": "辞書形"}, {"form": "上がります", "label": "ます形"}, {"form": "上がって", "label": "て形"}, {"form": "上がった", "label": "た形"}, {"form": "上がらない", "label": "ない形"}, {"form": "上がれば", "label": "仮定形"}], "register": "標準", "sense_fingerprint": "ものや数値が下から上へ動く、上昇する意味の上がる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T2: contains vocabulary far above tier T2: 水かさ (Zipf 1.84)']::text[], '138c9f88-9d7f-429e-8d2c-7d4fc969fc77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37574, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上がって", "is_correct": true, "explanation": "上へ動くロケットの動きを表し、青空に消えたという文に合う。"}, {"text": "眠って", "is_correct": false, "explanation": "ロケットが眠るという動きは成り立たず、文が不自然になる。"}, {"text": "拾って", "is_correct": false, "explanation": "ロケットを拾うという動作は文脈に合わない。"}, {"text": "眺めて", "is_correct": false, "explanation": "ロケットが眺めるという主語と動作の組み合わせが不自然。"}], "explanations": {"上がって": "上へ動くロケットの動きを表し、青空に消えたという文に合う。", "眠って": "ロケットが眠るという動きは成り立たず、文が不自然になる。", "拾って": "ロケットを拾うという動作は文脈に合わない。", "眺めて": "ロケットが眺めるという主語と動作の組み合わせが不自然。"}, "sentence_index": 0, "correct_answer": "上がって"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "洗濯したら、セーターが上がった。", "explanation": "ここは〈縮む〉の意味。布が小さくなる変化は縮むと言い、上へ動く意味の上がるとは合わない。"}, {"text": "夕日が上がって、景色が暗くなった。", "explanation": "ここは〈沈む〉の意味。太陽が地平線の下へ入ることは沈むと言い、上がるは合わない。"}, {"text": "花が上がって、庭が寂しくなった。", "explanation": "ここは〈枯れる〉の意味。花がしおれて衰えることは枯れると言い、上へ動く意味の上がるは使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37574, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上がる", "is_correct": true, "explanation": "幕が上へ動くという意味で、劇が始まった文に合う。"}, {"text": "包む", "is_correct": false, "explanation": "物を包む動作で、幕が包むという文は成り立たない。"}, {"text": "転ぶ", "is_correct": false, "explanation": "人が転ぶ動作で、幕が転ぶという文は不自然。"}, {"text": "叫ぶ", "is_correct": false, "explanation": "声を出す動作で、幕が叫ぶという文は成り立たない。"}], "explanations": {"上がる": "幕が上へ動くという意味で、劇が始まった文に合う。", "包む": "物を包む動作で、幕が包むという文は成り立たない。", "転ぶ": "人が転ぶ動作で、幕が転ぶという文は不自然。", "叫ぶ": "声を出す動作で、幕が叫ぶという文は成り立たない。"}, "sentence_index": 6, "correct_answer": "上がる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "機械が上がって、動かなくなった。", "explanation": "ここは〈止まる〉の意味。機械の動きが止まることは止まると言い、上へ動く上がるは使えない。"}, {"text": "庭の雑草が上がって、きれいになった。", "explanation": "ここは〈抜く〉の意味。雑草を地面から取り去ることは抜くと言い、上がるは合わない。"}, {"text": "重い荷物が上がって、トラックに積んだ。", "explanation": "ここは〈持ち上げる〉の意味。「上げる」は他動詞で、荷物を持ち上げる動作は「上がる」では表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37574, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "花火が夜空に上がらって、みんなが歓声をあげた。", "corrected_sentence": "花火が夜空に上がって、みんなが歓声をあげた。", "error_description": "「上がる」のて形は「上がって」。「上がらって」は『ない形』に『って』を付けた誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "上がって", "is_correct": true, "explanation": "て形で、「上がっていく」と続けて動きを表す形。"}, {"text": "上がった", "is_correct": false, "explanation": "過去形で、後ろの「いく」と続けると時制が合わない。"}, {"text": "上がらない", "is_correct": false, "explanation": "否定形で、風船が上がるという動きを打ち消してしまう。"}, {"text": "上がれば", "is_correct": false, "explanation": "仮定形で、文の流れに合わず「見ていた」と続かない。"}], "correct_form": "上がって", "base_form": "上がる", "form_label": "て形", "sentence_index": 1, "explanations": {"上がって": "て形で、「上がっていく」と続けて動きを表す形。", "上がった": "過去形で、後ろの「いく」と続けると時制が合わない。", "上がらない": "否定形で、風船が上がるという動きを打ち消してしまう。", "上がれば": "仮定形で、文の流れに合わず「見ていた」と続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37574, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "湯気が上げて、部屋があたたかくなった。", "corrected_sentence": "湯気が上がって、部屋があたたかくなった。", "error_description": "「湯気」は自分で上へ動くので自動詞「上がる」を使う。「上げる」は他動詞で、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "上がって", "is_correct": true, "explanation": "て形で、「景色が広がった」と続けて動きの流れを表す形。"}, {"text": "上がります", "is_correct": false, "explanation": "丁寧な形で、普通体の文の中では浮いてしまう。"}, {"text": "上がろう", "is_correct": false, "explanation": "意志を表す形で、ゴンドラの動きを述べる文に合わない。"}, {"text": "上がらず", "is_correct": false, "explanation": "打ち消しの形で、ゴンドラが上がる動きを否定してしまう。"}], "correct_form": "上がって", "base_form": "上がる", "form_label": "て形", "sentence_index": 7, "explanations": {"上がって": "て形で、「景色が広がった」と続けて動きの流れを表す形。", "上がります": "丁寧な形で、普通体の文の中では浮いてしまう。", "上がろう": "意志を表す形で、ゴンドラの動きを述べる文に合わない。", "上がらず": "打ち消しの形で、ゴンドラが上がる動きを否定してしまう。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37575, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "移動先の「に」で、座敷に上がるという文になる。"}, {"text": "を", "is_correct": false, "explanation": "「上がる」の移動先を「を」で示すと不自然になる。"}, {"text": "で", "is_correct": false, "explanation": "場所の「で」は移動先を示さないので文が合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」では、座敷へ上がる文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "移動先の「に」で、座敷に上がるという文になる。", "を": "「上がる」の移動先を「を」で示すと不自然になる。", "で": "場所の「で」は移動先を示さないので文が合わない。", "と": "並列の「と」では、座敷へ上がる文が成り立たない。"}, "error_tags": {"を": "目的語", "で": "場所", "と": "並列"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下りる", "is_correct": true, "explanation": "「上がる」の対義語で、階段などを下へ移動する意味を表す。"}, {"text": "歩く", "is_correct": false, "explanation": "移動の仕方を表す語で、上がるの対義語ではない。"}, {"text": "座る", "is_correct": false, "explanation": "体の姿勢を表す語で、上がるの対義語ではない。"}, {"text": "走る", "is_correct": false, "explanation": "速く移動する意味で、上がるの対義語ではない。"}], "correct_answer": "下りる", "explanations": {"下りる": "「上がる」の対義語で、階段などを下へ移動する意味を表す。", "歩く": "移動の仕方を表す語で、上がるの対義語ではない。", "座る": "体の姿勢を表す語で、上がるの対義語ではない。", "走る": "速く移動する意味で、上がるの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37575, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "移動先の「に」で、土手に上がるという文になる。"}, {"text": "の", "is_correct": false, "explanation": "所有や所属の「の」では、土手の上がるという意味になり不自然。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」で、土手が上がるという不自然な文になる。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」で、土手と上がるという不自然な文になる。"}], "correct_answer": "に", "explanations": {"に": "移動先の「に」で、土手に上がるという文になる。", "の": "所有や所属の「の」では、土手の上がるという意味になり不自然。", "が": "主語の「が」で、土手が上がるという不自然な文になる。", "と": "並列の「と」で、土手と上がるという不自然な文になる。"}, "error_tags": {"の": "所属", "が": "主語", "と": "並列"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下りる", "is_correct": true, "explanation": "「上がる」の対義語で、縁側などから下へ移動する意味を表す。"}, {"text": "飛ぶ", "is_correct": false, "explanation": "空を移動する意味で、上がるの対義語ではない。"}, {"text": "寝る", "is_correct": false, "explanation": "横になる意味で、上がるの対義語ではない。"}, {"text": "乗る", "is_correct": false, "explanation": "上に載る意味で、上へ動くことの反対語ではない。"}], "correct_answer": "下りる", "explanations": {"下りる": "「上がる」の対義語で、縁側などから下へ移動する意味を表す。", "飛ぶ": "空を移動する意味で、上がるの対義語ではない。", "寝る": "横になる意味で、上がるの対義語ではない。", "乗る": "上に載る意味で、上へ動くことの反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37575, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "位置が低いところから高いところへ移る。", "primary_collocate": null, "pronunciation": "あがる", "ipa": "aɡaɾɯ", "syllable_count": 3, "sentences": [{"text": "階段を上がって、二階の部屋に入った。", "target_word": "上がって", "complexity_tier": "T3", "furigana": "階段[かいだん]を上[あ]がって、二階[にかい]の部屋[へや]に入[はい]った。", "sentence_source": "generated"}, {"text": "靴をぬいで、座敷に上がってください。", "target_word": "上がって", "complexity_tier": "T3", "furigana": "靴[くつ]をぬいで、座敷[ざしき]に上[あ]がってください。", "sentence_source": "generated"}, {"text": "坂を上がると、小さな神社がある。", "target_word": "上がる", "complexity_tier": "T3", "furigana": "坂[さか]を上[あ]がると、小[ちい]さな神社[じんじゃ]がある。", "sentence_source": "generated"}, {"text": "彼は舞台に上がって、あいさつをした。", "target_word": "上がって", "complexity_tier": "T3", "furigana": "彼[かれ]は舞台[ぶたい]に上[あ]がって、あいさつをした。", "sentence_source": "generated"}, {"text": "屋根に上がるときは、はしごを使います。", "target_word": "上がる", "complexity_tier": "T3", "furigana": "屋根[やね]に上[あ]がるときは、はしごを使[つか]います。", "sentence_source": "generated"}, {"text": "山道を上がって、頂上まで三時間かかった。", "target_word": "上がって", "complexity_tier": "T3", "furigana": "山道[やまみち]を上[あ]がって、頂上[ちょうじょう]まで三時間[さんじかん]かかった。", "sentence_source": "generated"}, {"text": "荷物を置くために、二階に上がった。", "target_word": "上がった", "complexity_tier": "T3", "furigana": "荷物[にもつ]を置[お]くために、二階[にかい]に上[あ]がった。", "sentence_source": "generated"}, {"text": "川の土手に上がって、夕日を見た。", "target_word": "上がって", "complexity_tier": "T3", "furigana": "川[かわ]の土手[どて]に上[あ]がって、夕日[ゆうひ]を見[み]た。", "sentence_source": "generated"}, {"text": "エレベーターが使えないので、五階まで階段で上がった。", "target_word": "上がった", "complexity_tier": "T3", "furigana": "エレベーターが使[つか]えないので、五階[ごかい]まで階段[かいだん]で上[あ]がった。", "sentence_source": "generated"}, {"text": "縁側に上がって、お茶をいただいた。", "target_word": "上がって", "complexity_tier": "T3", "furigana": "縁側[えんがわ]に上[あ]がって、お茶[ちゃ]をいただいた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "上がる", "label": "辞書形"}, {"form": "上がります", "label": "ます形"}, {"form": "上がって", "label": "て形"}, {"form": "上がった", "label": "た形"}, {"form": "上がらない", "label": "ない形"}, {"form": "上がれば", "label": "仮定形"}], "register": "標準", "sense_fingerprint": "人が階段や坂などを使って低い所から高い所へ移動する意味の上がる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '138c9f88-9d7f-429e-8d2c-7d4fc969fc77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37575, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上がって", "is_correct": true, "explanation": "階段を上へ移動する意味で、二階の部屋に入った文に合う。"}, {"text": "投げて", "is_correct": false, "explanation": "物を投げる動作で、階段を投げるという文は成り立たない。"}, {"text": "謝って", "is_correct": false, "explanation": "謝る動作で、階段を対象にする文は不自然。"}, {"text": "叫んで", "is_correct": false, "explanation": "声を出す動作で、階段を叫ぶという文は成り立たない。"}], "explanations": {"上がって": "階段を上へ移動する意味で、二階の部屋に入った文に合う。", "投げて": "物を投げる動作で、階段を投げるという文は成り立たない。", "謝って": "謝る動作で、階段を対象にする文は不自然。", "叫んで": "声を出す動作で、階段を叫ぶという文は成り立たない。"}, "sentence_index": 0, "correct_answer": "上がって"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "地下室に上がって、ワインを取ってきた。", "explanation": "ここは〈下りる〉の意味。低い所へ移ることは下りると言い、上がるは高い所へ移る意味なので合わない。"}, {"text": "ボールが机の下に上がった。", "explanation": "ここは〈落ちる〉の意味。下へ落ちることは落ちると言い、上がるは使えない。"}, {"text": "船が上がって、港の底に消えた。", "explanation": "ここは〈沈む〉の意味。水の中へ下がっていくことは沈むと言い、上がるは使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37575, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上がった", "is_correct": true, "explanation": "二階へ移動した意味で、荷物を置くために上がった文に合う。"}, {"text": "包んだ", "is_correct": false, "explanation": "物を包む動作で、二階に包んだという文は成り立たない。"}, {"text": "踊った", "is_correct": false, "explanation": "踊る動作で、二階に踊ったという文は不自然。"}, {"text": "咲いた", "is_correct": false, "explanation": "花が咲く意味で、人が二階に移動する文には合わない。"}], "explanations": {"上がった": "二階へ移動した意味で、荷物を置くために上がった文に合う。", "包んだ": "物を包む動作で、二階に包んだという文は成り立たない。", "踊った": "踊る動作で、二階に踊ったという文は不自然。", "咲いた": "花が咲く意味で、人が二階に移動する文には合わない。"}, "sentence_index": 6, "correct_answer": "上がった"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夕方、川底に上がって、魚を探した。", "explanation": "ここは〈もぐる〉の意味。水の中へ入っていくことはもぐると言い、上へ動く上がるは合わない。"}, {"text": "夕日が上がって、景色が明るくなった。", "explanation": "ここは〈沈む〉と混同しやすい語。夕日は沈むので、上へ移動する意味とは合わない。"}, {"text": "重い荷物が上がって、トラックに積んだ。", "explanation": "ここは〈持ち上げる〉の意味。「上がる」は自分で上へ動くことで、荷物を持ち上げる動作は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37575, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "はしごで屋根に上がた、雨漏りを直した。", "corrected_sentence": "はしごで屋根に上がって、雨漏りを直した。", "error_description": "「上がる」の過去形は「上がった」。「上がた」は「っ」が抜けた誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "上がって", "is_correct": true, "explanation": "て形で、「ください」と続けて座敷へ上がるよう頼む形。"}, {"text": "上がった", "is_correct": false, "explanation": "過去形で、命令や依頼の文「ください」と続かない。"}, {"text": "上がらない", "is_correct": false, "explanation": "否定形で、上がらないよう指示する意味になってしまう。"}, {"text": "上がれば", "is_correct": false, "explanation": "仮定形で、「ください」と続けると文が不自然になる。"}], "correct_form": "上がって", "base_form": "上がる", "form_label": "て形", "sentence_index": 1, "explanations": {"上がって": "て形で、「ください」と続けて座敷へ上がるよう頼む形。", "上がった": "過去形で、命令や依頼の文「ください」と続かない。", "上がらない": "否定形で、上がらないよう指示する意味になってしまう。", "上がれば": "仮定形で、「ください」と続けると文が不自然になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37575, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "玄関に上がりて、靴をそろえた。", "corrected_sentence": "玄関に上がって、靴をそろえた。", "error_description": "動詞「上がる」のて形は「上がって」。「上がりて」は誤った活用。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "上がって", "is_correct": true, "explanation": "て形で、「夕日を見た」と続けて動作の流れを表す形。"}, {"text": "上がります", "is_correct": false, "explanation": "丁寧な形で、普通体の文の中では不自然になる。"}, {"text": "上がろう", "is_correct": false, "explanation": "意志を表す形で、動作を述べる文に合わない。"}, {"text": "上がれ", "is_correct": false, "explanation": "命令の形で、「夕日を見た」と続く過去の出来事に合わない。"}], "correct_form": "上がって", "base_form": "上がる", "form_label": "て形", "sentence_index": 7, "explanations": {"上がって": "て形で、「夕日を見た」と続けて動作の流れを表す形。", "上がります": "丁寧な形で、普通体の文の中では不自然になる。", "上がろう": "意志を表す形で、動作を述べる文に合わない。", "上がれ": "命令の形で、「夕日を見た」と続く過去の出来事に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
