INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37576, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「板が折れてしまった」で、板が折れる主体（主語）を示す。"}, {"text": "と", "is_correct": false, "explanation": "「板と折れてしまった」は共同を表すが、折れる主体を示せず不自然。"}, {"text": "の", "is_correct": false, "explanation": "「板の折れてしまった」は連体修飾にならず、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「板より折れてしまった」は比較になり、意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「板が折れてしまった」で、板が折れる主体（主語）を示す。", "と": "「板と折れてしまった」は共同を表すが、折れる主体を示せず不自然。", "の": "「板の折れてしまった」は連体修飾にならず、文が成り立たない。", "より": "「板より折れてしまった」は比較になり、意味が通らない。"}, "error_tags": {"と": "共同・相手", "の": "連体修飾", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37576, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものの形が、たおれるようにまがること。", "primary_collocate": null, "pronunciation": "おれる", "ipa": "oɾeɾɯ", "syllable_count": 3, "sentences": [{"text": "強い風で、木の枝が折れた。", "target_word": "折れた", "complexity_tier": "T3", "furigana": "強[つよ]い風[かぜ]で、木[き]の枝[えだ]が折[お]れた。", "sentence_source": "generated"}, {"text": "雪が重くて、竹が折れそうだ。", "target_word": "折れそう", "complexity_tier": "T3", "furigana": "雪[ゆき]が重[おも]くて、竹[たけ]が折[お]れそうだ。", "sentence_source": "generated"}, {"text": "傘の骨が折れて、使えなくなった。", "target_word": "折れて", "complexity_tier": "T3", "furigana": "傘[かさ]の骨[ほね]が折[お]れて、使[つか]えなくなった。", "sentence_source": "generated"}, {"text": "鉛筆の芯が折れたので、けずり直した。", "target_word": "折れた", "complexity_tier": "T3", "furigana": "鉛筆[えんぴつ]の芯[しん]が折[お]れたので、けずり直[なお]した。", "sentence_source": "generated"}, {"text": "台風で電柱が折れて、停電になった。", "target_word": "折れて", "complexity_tier": "T3", "furigana": "台風[たいふう]で電柱[でんちゅう]が折[お]れて、停電[ていでん]になった。", "sentence_source": "generated"}, {"text": "転んだとき、足の骨が折れた。", "target_word": "折れた", "complexity_tier": "T3", "furigana": "転[ころ]んだとき、足[あし]の骨[ほね]が折[お]れた。", "sentence_source": "generated"}, {"text": "釣りざおが折れるほど、大きな魚がかかった。", "target_word": "折れる", "complexity_tier": "T3", "furigana": "釣[つ]りざおが折[お]れるほど、大[おお]きな魚[さかな]がかかった。", "sentence_source": "generated"}, {"text": "スキーで転んで、板が折れてしまった。", "target_word": "折れて", "complexity_tier": "T3", "furigana": "スキーで転[ころ]んで、板[いた]が折[お]れてしまった。", "sentence_source": "generated"}, {"text": "チョークが折れて、黒板の下に落ちた。", "target_word": "折れて", "complexity_tier": "T3", "furigana": "チョークが折[お]れて、黒板[こくばん]の下[した]に落[お]ちた。", "sentence_source": "generated"}, {"text": "古い橋の柱が折れないか、心配している。", "target_word": "折れない", "complexity_tier": "T3", "furigana": "古[ふる]い橋[はし]の柱[はしら]が折[お]れないか、心配[しんぱい]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "折れる", "label": "辞書形"}, {"form": "折れます", "label": "ます形"}, {"form": "折れて", "label": "て形"}, {"form": "折れた", "label": "た形"}, {"form": "折れない", "label": "ない形"}, {"form": "折れれば", "label": "仮定形"}], "register": "標準", "sense_fingerprint": "枝・骨・芯など細長いものが力でぽきっと曲がったり割れたりする意味の折れる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '138c9f88-9d7f-429e-8d2c-7d4fc969fc77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37576, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "折れた", "is_correct": true, "explanation": "「強い風で、木の枝が折れた」と完了した出来事を述べる文末に合う。"}, {"text": "折れて", "is_correct": false, "explanation": "て形は途中の形で、文末に置くと文が終わらない。"}, {"text": "折れれば", "is_correct": false, "explanation": "仮定形は「〜ば」に続く形で、この文末では成り立たない。"}, {"text": "折れろ", "is_correct": false, "explanation": "命令形で、すでに起きた事実を述べる文には合わない。"}], "explanations": {"折れた": "「強い風で、木の枝が折れた」と完了した出来事を述べる文末に合う。", "折れて": "て形は途中の形で、文末に置くと文が終わらない。", "折れれば": "仮定形は「〜ば」に続く形で、この文末では成り立たない。", "折れろ": "命令形で、すでに起きた事実を述べる文には合わない。"}, "sentence_index": 0, "correct_answer": "折れた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "たんすが折れて、引き出しが飛び出した。", "explanation": "ここは〈倒れる〉の意味。たんすのように大きな家具がたおれるのは倒れるで、折れるとは言わない。"}, {"text": "お皿が折れて、台所の床に散らばった。", "explanation": "ここは〈割れる〉の意味。平たい皿が砕けるのは割れるで、折れるとは言わない。"}, {"text": "糸が折れて、風船が飛んでいった。", "explanation": "ここは〈切れる〉の意味。糸がちぎれるのは切れるで、折れるとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37576, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "折れる", "is_correct": true, "explanation": "辞書形で「釣りざおが折れるほど」と程度を表す「〜ほど」に続き、文に合う。"}, {"text": "折れなくて", "is_correct": false, "explanation": "て形の途中形で、「〜ほど」に続けると文が成り立たない。"}, {"text": "折れよう", "is_correct": false, "explanation": "意向形で、「〜ほど」の程度表現に続かない。"}, {"text": "折れません", "is_correct": false, "explanation": "丁寧な否定形で、「〜ほど」の前では文法的に続かない。"}], "explanations": {"折れる": "辞書形で「釣りざおが折れるほど」と程度を表す「〜ほど」に続き、文に合う。", "折れなくて": "て形の途中形で、「〜ほど」に続けると文が成り立たない。", "折れよう": "意向形で、「〜ほど」の程度表現に続かない。", "折れません": "丁寧な否定形で、「〜ほど」の前では文法的に続かない。"}, "sentence_index": 6, "correct_answer": "折れる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "砂の城が折れて、波にさらわれた。", "explanation": "ここは〈崩れる〉の意味。砂の城のように積んだものが形を保てずくずれるのは崩れるで、折れるとは言わない。"}, {"text": "機械が折れて、動かなくなった。", "explanation": "ここは〈壊れる〉の意味。機械の故障は壊れるで言い、折れるは細長いものが曲がる場合に使う。"}, {"text": "ガラス瓶が折れて、中身が飛び散った。", "explanation": "ここは〈砕ける〉の意味。ガラスが細かく砕けるのは砕けるで、折れるとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37576, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "庭の木の枝を折れて、道をふさいだ。", "corrected_sentence": "庭の木の枝が折れて、道をふさいだ。", "error_description": "助詞の誤り。「折れる」は自動詞なので、折れる主体の枝は「が」で示す。「を」は目的語に使うため、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "折れそう", "is_correct": true, "explanation": "様態の「〜そうだ」で、今にも折れそうな竹の状態を表し、文に合う。"}, {"text": "折れろ", "is_correct": false, "explanation": "命令形で、「〜そうだ」に続かず文が成り立たない。"}, {"text": "折れれば", "is_correct": false, "explanation": "仮定形で、「〜そうだ」に続かず文が成り立たない。"}, {"text": "折れず", "is_correct": false, "explanation": "「〜ずに」の連用形で、「〜そうだ」と続かず文が成り立たない。"}], "correct_form": "折れそう", "base_form": "折れる", "form_label": "様態（〜そうだ）", "sentence_index": 1, "explanations": {"折れそう": "様態の「〜そうだ」で、今にも折れそうな竹の状態を表し、文に合う。", "折れろ": "命令形で、「〜そうだ」に続かず文が成り立たない。", "折れれば": "仮定形で、「〜そうだ」に続かず文が成り立たない。", "折れず": "「〜ずに」の連用形で、「〜そうだ」と続かず文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37576, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "強い雨で、ハウスの柱が折れるて、屋根が落ちた。", "corrected_sentence": "強い雨で、ハウスの柱が折れて、屋根が落ちた。", "error_description": "て形の誤り。「折れる」は一段動詞なので、て形は「折れて」になる。「折れるて」は語形として成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "折れて", "is_correct": true, "explanation": "て形で、「折れてしまった」と完了した結果を表す「〜てしまう」に続き、文に合う。"}, {"text": "折れます", "is_correct": false, "explanation": "丁寧な終止形で、「〜てしまった」とつながらない。"}, {"text": "折れない", "is_correct": false, "explanation": "否定形で、「〜てしまった」と続かず、板が折れた事実とも逆になる。"}, {"text": "折れませんでした", "is_correct": false, "explanation": "丁寧な否定過去で、「〜てしまった」と続かず事実とも逆になる。"}], "correct_form": "折れて", "base_form": "折れる", "form_label": "て形（〜てしまう）", "sentence_index": 7, "explanations": {"折れて": "て形で、「折れてしまった」と完了した結果を表す「〜てしまう」に続き、文に合う。", "折れます": "丁寧な終止形で、「〜てしまった」とつながらない。", "折れない": "否定形で、「〜てしまった」と続かず、板が折れた事実とも逆になる。", "折れませんでした": "丁寧な否定過去で、「〜てしまった」と続かず事実とも逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37577, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「針金が折れて」で、針金が折れる主体（主語）を示す。"}, {"text": "を", "is_correct": false, "explanation": "「針金を折れて」は目的語の形になるが、折れるは自動詞なので不自然。"}, {"text": "の", "is_correct": false, "explanation": "「針金の折れて」は連体修飾にならず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「針金へ折れて」は方向を示すが、折れる主体を表せない。"}], "correct_answer": "が", "explanations": {"が": "「針金が折れて」で、針金が折れる主体（主語）を示す。", "を": "「針金を折れて」は目的語の形になるが、折れるは自動詞なので不自然。", "の": "「針金の折れて」は連体修飾にならず、文が成り立たない。", "へ": "「針金へ折れて」は方向を示すが、折れる主体を表せない。"}, "error_tags": {"を": "目的語", "の": "連体修飾", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37577, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「柄が折れて」で、柄が折れる主体（主語）を示す。"}, {"text": "に", "is_correct": false, "explanation": "「柄に折れて」は位置や方向を示し、折れる主体を表せない。"}, {"text": "と", "is_correct": false, "explanation": "「柄と折れて」は共同を表すが、文の主語にならず不自然。"}, {"text": "より", "is_correct": false, "explanation": "「柄より折れて」は比較になり、意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「柄が折れて」で、柄が折れる主体（主語）を示す。", "に": "「柄に折れて」は位置や方向を示し、折れる主体を表せない。", "と": "「柄と折れて」は共同を表すが、文の主語にならず不自然。", "より": "「柄より折れて」は比較になり、意味が通らない。"}, "error_tags": {"に": "位置・方向", "と": "共同・相手", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37577, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある物が、折れ曲がること。", "primary_collocate": null, "pronunciation": "おれる", "ipa": "oɾeɾɯ", "syllable_count": 3, "sentences": [{"text": "本のページの角が折れていた。", "target_word": "折れて", "complexity_tier": "T3", "furigana": "本[ほん]のページの角[かど]が折[お]れていた。", "sentence_source": "generated"}, {"text": "針金が折れて、変な形になった。", "target_word": "折れて", "complexity_tier": "T3", "furigana": "針金[はりがね]が折[お]れて、変[へん]な形[かたち]になった。", "sentence_source": "generated"}, {"text": "かばんの中で、ポスターが折れてしまった。", "target_word": "折れて", "complexity_tier": "T3", "furigana": "かばんの中[なか]で、ポスターが折[お]れてしまった。", "sentence_source": "generated"}, {"text": "満員電車で、カードが折れてしまった。", "target_word": "折れて", "complexity_tier": "T3", "furigana": "満員電車[まんいんでんしゃ]で、カードが折[お]れてしまった。", "sentence_source": "generated"}, {"text": "写真が折れないように、かたい板ではさんだ。", "target_word": "折れない", "complexity_tier": "T3", "furigana": "写真[しゃしん]が折[お]れないように、かたい板[いた]ではさんだ。", "sentence_source": "generated"}, {"text": "くぎが折れて、先が横を向いている。", "target_word": "折れて", "complexity_tier": "T3", "furigana": "くぎが折[お]れて、先[さき]が横[よこ]を向[む]いている。", "sentence_source": "generated"}, {"text": "手紙が折れたまま、ポストに入っていた。", "target_word": "折れた", "complexity_tier": "T3", "furigana": "手紙[てがみ]が折[お]れたまま、ポストに入[はい]っていた。", "sentence_source": "generated"}, {"text": "古い傘の柄が折れて、くの字になっている。", "target_word": "折れて", "complexity_tier": "T3", "furigana": "古[ふる]い傘[かさ]の柄[え]が折[お]れて、くの字[じ]になっている。", "sentence_source": "generated"}, {"text": "賞状が折れないように、筒に入れて持ち帰った。", "target_word": "折れない", "complexity_tier": "T3", "furigana": "賞状[しょうじょう]が折[お]れないように、筒[つつ]に入[い]れて持[も]ち帰[かえ]った。", "sentence_source": "generated"}, {"text": "新聞のはしが折れているので、のばしてください。", "target_word": "折れて", "complexity_tier": "T3", "furigana": "新聞[しんぶん]のはしが折[お]れているので、のばしてください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "折れる", "label": "辞書形"}, {"form": "折れます", "label": "ます形"}, {"form": "折れて", "label": "て形"}, {"form": "折れた", "label": "た形"}, {"form": "折れない", "label": "ない形"}, {"form": "折れれば", "label": "仮定形"}], "register": "標準", "sense_fingerprint": "紙・針金・角などが意図せず折り目がついたり曲がったりする意味の折れる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '138c9f88-9d7f-429e-8d2c-7d4fc969fc77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37577, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "折れて", "is_correct": true, "explanation": "て形に「いた」が続き、「角が折れていた」と折れた状態を表す。"}, {"text": "折れた", "is_correct": false, "explanation": "「折れたいた」は続かず、文として成り立たない。"}, {"text": "折れない", "is_correct": false, "explanation": "否定形で「いた」と続かず、折れた状態の説明に合わない。"}, {"text": "折れます", "is_correct": false, "explanation": "丁寧形で「いた」と続かず、常体の文に合わない。"}], "explanations": {"折れて": "て形に「いた」が続き、「角が折れていた」と折れた状態を表す。", "折れた": "「折れたいた」は続かず、文として成り立たない。", "折れない": "否定形で「いた」と続かず、折れた状態の説明に合わない。", "折れます": "丁寧形で「いた」と続かず、常体の文に合わない。"}, "sentence_index": 0, "correct_answer": "折れて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "本棚が折れて、本が床に散らばった。", "explanation": "ここは〈倒れる〉の意味。本棚のように大きな家具が横にたおれるのは倒れるで、折れるとは言わない。"}, {"text": "ポットが折れて、お湯がもれた。", "explanation": "ここは〈壊れる〉の意味。機械の故障は壊れるで言い、折れるは細長いものが曲がる場合に使う。"}, {"text": "糸が折れて、ビーズが散らばった。", "explanation": "ここは〈切れる〉の意味。糸がちぎれるのは切れるで、折れるとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37577, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "折れた", "is_correct": true, "explanation": "た形に「まま」が続き、「手紙が折れたまま」と折れた状態のままを表す。"}, {"text": "折れて", "is_correct": false, "explanation": "て形は「〜まま」に続かず、文が成り立たない。"}, {"text": "折れれば", "is_correct": false, "explanation": "仮定形は「〜まま」に続かず、文が成り立たない。"}, {"text": "折れろ", "is_correct": false, "explanation": "命令形は「〜まま」に続かず、文が成り立たない。"}], "explanations": {"折れた": "た形に「まま」が続き、「手紙が折れたまま」と折れた状態のままを表す。", "折れて": "て形は「〜まま」に続かず、文が成り立たない。", "折れれば": "仮定形は「〜まま」に続かず、文が成り立たない。", "折れろ": "命令形は「〜まま」に続かず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "折れた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雪だるまが折れて、庭に崩れ落ちた。", "explanation": "ここは〈崩れる〉の意味。雪だるまのように積んだものが形を保てずくずれるのは崩れるで、折れるとは言わない。"}, {"text": "ガラスのコップが折れた。", "explanation": "ここは〈割れる〉の意味。ガラスが割れるのは割れるで、折れるとは言わない。"}, {"text": "空き缶が折れて、ぺしゃんこになった。", "explanation": "ここは〈潰れる〉の意味。押されて平たくなるのは潰れるで、折れるとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37577, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ゆうびんの封筒が折れたて、中の書類が見えていた。", "corrected_sentence": "ゆうびんの封筒が折れて、中の書類が見えていた。", "error_description": "活用の誤り。接続の「て」が「たて」になっている。「折れて」が正しい形。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "折れて", "is_correct": true, "explanation": "て形で、「針金が折れて、変な形になった」と結果へ続く文に合う。"}, {"text": "折れろ", "is_correct": false, "explanation": "命令形で、「針金が〜、変な形になった」と続かず文が成り立たない。"}, {"text": "折れよう", "is_correct": false, "explanation": "意向形で、「針金が〜、変な形になった」と続かず文が成り立たない。"}, {"text": "折れます", "is_correct": false, "explanation": "丁寧な終止形で、「〜て、〜になった」と続かない。"}], "correct_form": "折れて", "base_form": "折れる", "form_label": "て形（継続・結果）", "sentence_index": 1, "explanations": {"折れて": "て形で、「針金が折れて、変な形になった」と結果へ続く文に合う。", "折れろ": "命令形で、「針金が〜、変な形になった」と続かず文が成り立たない。", "折れよう": "意向形で、「針金が〜、変な形になった」と続かず文が成り立たない。", "折れます": "丁寧な終止形で、「〜て、〜になった」と続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37577, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "お気に入りのしおりを折れてしまった。", "corrected_sentence": "お気に入りのしおりが折れてしまった。", "error_description": "助詞の誤り。「しおりが折れる」の主語には「が」を使う。「を」は目的語用で、「折れる」には合わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "折れて", "is_correct": true, "explanation": "て形で、「くの字になっている」と結果の状態へ続く文に合う。"}, {"text": "折れよう", "is_correct": false, "explanation": "意向形で、「柄が〜、くの字になっている」と続かず文が成り立たない。"}, {"text": "折れません", "is_correct": false, "explanation": "丁寧な否定形で、文の流れに合わない。"}, {"text": "折れませんでした", "is_correct": false, "explanation": "丁寧な否定過去で、くの字になった結果の説明と意味が逆になる。"}], "correct_form": "折れて", "base_form": "折れる", "form_label": "て形（結果の状態）", "sentence_index": 7, "explanations": {"折れて": "て形で、「くの字になっている」と結果の状態へ続く文に合う。", "折れよう": "意向形で、「柄が〜、くの字になっている」と続かず文が成り立たない。", "折れません": "丁寧な否定形で、文の流れに合わない。", "折れませんでした": "丁寧な否定過去で、くの字になった結果の説明と意味が逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37578, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「塩の加減が難しい」で、加減が難しいの主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「塩の加減を難しい」は形容詞に目的語が付かず、不自然。"}, {"text": "に", "is_correct": false, "explanation": "「塩の加減に難しい」は難しさの相手を示せず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「塩の加減へ難しい」は方向を示し、難しいの主語にならない。"}], "correct_answer": "が", "explanations": {"が": "「塩の加減が難しい」で、加減が難しいの主語を示す。", "を": "「塩の加減を難しい」は形容詞に目的語が付かず、不自然。", "に": "「塩の加減に難しい」は難しさの相手を示せず、不自然。", "へ": "「塩の加減へ難しい」は方向を示し、難しいの主語にならない。"}, "error_tags": {"を": "目的語", "に": "位置・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37578, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「酢と油の加減」で、酢と油の割合の調整具合を表す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「酢と油を加減が難しい」は述語と結びつかず文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「酢と油から加減が難しい」は起点を示し、意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や位置を示すが、「酢と油に加減が難しい」は難しいの主語にならず不自然。"}], "correct_answer": "の", "explanations": {"の": "「酢と油の加減」で、酢と油の割合の調整具合を表す。", "を": "「を」は目的語を示すが、「酢と油を加減が難しい」は述語と結びつかず文が成り立たない。", "から": "「酢と油から加減が難しい」は起点を示し、意味が通らない。", "に": "「に」は相手や位置を示すが、「酢と油に加減が難しい」は難しいの主語にならず不自然。"}, "error_tags": {"を": "目的語", "に": "位置・相手", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37578, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものごとが ちょうど よい ぐあいに なる こと。", "primary_collocate": null, "pronunciation": "かげん", "ipa": "kaɡeɴ", "syllable_count": 3, "sentences": [{"text": "お湯の加減がちょうどよくて、ゆっくり入れた。", "target_word": "加減", "complexity_tier": "T3", "furigana": "お湯[ゆ]の加減[かげん]がちょうどよくて、ゆっくり入[はい]れた。", "sentence_source": "generated"}, {"text": "塩の加減が難しくて、何度も味見をした。", "target_word": "加減", "complexity_tier": "T3", "furigana": "塩[しお]の加減[かげん]が難[むずか]しくて、何度[なんど]も味見[あじみ]をした。", "sentence_source": "generated"}, {"text": "火にかけすぎないよう、加減を見ながら煮る。", "target_word": "加減", "complexity_tier": "T3", "furigana": "火[ひ]にかけすぎないよう、加減[かげん]を見[み]ながら煮[に]る。", "sentence_source": "generated"}, {"text": "このスープは味の加減が絶妙で、何杯でも飲める。", "target_word": "加減", "complexity_tier": "T3", "furigana": "このスープは味[あじ]の加減[かげん]が絶妙[ぜつみょう]で、何杯[なんばい]でも飲[の]める。", "sentence_source": "generated"}, {"text": "煮物の味は、しょうゆの加減しだいでよくも悪くもなる。", "target_word": "加減", "complexity_tier": "T3", "furigana": "煮物[にもの]の味[あじ]は、しょうゆの加減[かげん]しだいでよくも悪くもなる。", "sentence_source": "generated"}, {"text": "力の加減を覚えると、字がきれいに書ける。", "target_word": "加減", "complexity_tier": "T3", "furigana": "力[ちから]の加減[かげん]を覚[おぼ]えると、字[じ]がきれいに書[か]ける。", "sentence_source": "generated"}, {"text": "おふろの加減はいかがですか。", "target_word": "加減", "complexity_tier": "T3", "furigana": "おふろの加減[かげん]はいかがですか。", "sentence_source": "generated"}, {"text": "ドレッシングは、酢と油の加減が難しい。", "target_word": "加減", "complexity_tier": "T3", "furigana": "ドレッシングは、酢[す]と油[あぶら]の加減[かげん]が難しい。", "sentence_source": "generated"}, {"text": "水の加減を間違えて、ご飯がかたくなった。", "target_word": "加減", "complexity_tier": "T3", "furigana": "水[みず]の加減[かげん]を間違[まちが]えて、ご飯[はん]がかたくなった。", "sentence_source": "generated"}, {"text": "このカレーは、スパイスの加減がちょうどいい。", "target_word": "加減", "complexity_tier": "T3", "furigana": "このカレーは、スパイスの加減[かげん]がちょうどいい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "加減", "label": "基本形"}], "register": "標準", "sense_fingerprint": "味・温度・力などをちょうどよい具合に調整すること、またその塩梅", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '138c9f88-9d7f-429e-8d2c-7d4fc969fc77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37578, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "加減", "is_correct": true, "explanation": "「お湯の加減」は湯の熱さの調整具合を表し、ちょうどよくて入ったという文に合う。"}, {"text": "湯気", "is_correct": false, "explanation": "湯から立つ蒸気で、熱さの具合を表さないので、ちょうどよい調整の文には合わない。"}, {"text": "沸騰", "is_correct": false, "explanation": "お湯が沸く現象で、ちょうどよい具合を述べる文には合わない。"}, {"text": "渦", "is_correct": false, "explanation": "かき混ぜたときの流れで、湯の熱さを言う文には合わない。"}], "explanations": {"加減": "「お湯の加減」は湯の熱さの調整具合を表し、ちょうどよくて入ったという文に合う。", "湯気": "湯から立つ蒸気で、熱さの具合を表さないので、ちょうどよい調整の文には合わない。", "沸騰": "お湯が沸く現象で、ちょうどよい具合を述べる文には合わない。", "渦": "かき混ぜたときの流れで、湯の熱さを言う文には合わない。"}, "sentence_index": 0, "correct_answer": "加減"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この部屋は加減が広くて、家具が置きやすい。", "explanation": "ここは〈広さ〉の意味。部屋の広さは広さで言い、加減は調整の具合を表すので合わない。"}, {"text": "この箱は加減が四角くて、積みやすい。", "explanation": "ここは〈形〉の意味。箱の形は形で言い、加減は調整の具合を表すので合わない。"}, {"text": "漬物の加減がきれいな赤色で、食欲がわいた。", "explanation": "ここは〈色〉の意味。漬物の色は色で言い、加減は調整の具合を表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37578, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "加減", "is_correct": true, "explanation": "「おふろの加減はいかがですか」は湯の温度など、ちょうどよい具合を尋ねる言い方で、文に合う。"}, {"text": "排水", "is_correct": false, "explanation": "水を流す仕組みで、湯の具合を尋ねる文には合わない。"}, {"text": "蛇口", "is_correct": false, "explanation": "水や湯を出す器具で、湯の具合を尋ねる文には合わない。"}, {"text": "脱衣所", "is_correct": false, "explanation": "着替えをする場所で、湯の具合を尋ねる文には合わない。"}], "explanations": {"加減": "「おふろの加減はいかがですか」は湯の温度など、ちょうどよい具合を尋ねる言い方で、文に合う。", "排水": "水を流す仕組みで、湯の具合を尋ねる文には合わない。", "蛇口": "水や湯を出す器具で、湯の具合を尋ねる文には合わない。", "脱衣所": "着替えをする場所で、湯の具合を尋ねる文には合わない。"}, "sentence_index": 6, "correct_answer": "加減"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "けがの加減は軽かった。", "explanation": "ここは〈程度〉の意味。けがの重さは程度で言い、加減はちょうどよい具合の調整を表すので合わない。"}, {"text": "このカレーは加減が豊かで、香りが立つ。", "explanation": "ここは〈香り〉の意味。香りの豊かさは香りで言い、加減は調整の具合を表すので合わない。"}, {"text": "スープに加減を入れすぎて、しょっぱくなった。", "explanation": "ここは〈調味料〉の意味。調味料は入れられるが、加減は物ではないので入れられない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37578, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "野菜を炒めるときは、火に加減をこまめに見る。", "corrected_sentence": "野菜を炒めるときは、火の加減をこまめに見る。", "error_description": "助詞の誤り。「火の加減」（火力の調整具合）の「の」が「に」になっている。「火に加減」では意味が通らない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37578, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "鍋の火を強めたり弱めたりして、加減を刻む。", "corrected_sentence": "鍋の火を強めたり弱めたりして、加減を調える。", "error_description": "連語の誤り。「加減を調える」が正しい。「刻む」は材料を細かく切る動詞で、加減とは組み合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37579, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「角度の加減で」と続き、角度の調整具合を表す。"}, {"text": "を", "is_correct": false, "explanation": "「角度を加減で」は目的語を示すが、後に述語がなく文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「角度へ加減で」は方向を示し、意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「角度で加減で」は手段の「で」が重なり、文として成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「角度の加減で」と続き、角度の調整具合を表す。", "を": "「角度を加減で」は目的語を示すが、後に述語がなく文が成り立たない。", "へ": "「角度へ加減で」は方向を示し、意味が通らない。", "で": "「角度で加減で」は手段の「で」が重なり、文として成り立たない。"}, "error_tags": {"を": "目的語", "へ": "方向", "で": "手段・原因"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37579, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「ボリュームの加減を、部屋の広さに合わせる」で、加減が合わせる対象（目的語）になる。"}, {"text": "に", "is_correct": false, "explanation": "「加減に、部屋の広さに合わせる」は「に」が二つ続き、文として不自然。"}, {"text": "から", "is_correct": false, "explanation": "「加減から」は起点を示し、合わせる対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「加減へ、部屋の広さに合わせる」は方向を示し、合わせる対象にならず不自然。"}], "correct_answer": "を", "explanations": {"を": "「ボリュームの加減を、部屋の広さに合わせる」で、加減が合わせる対象（目的語）になる。", "に": "「加減に、部屋の広さに合わせる」は「に」が二つ続き、文として不自然。", "から": "「加減から」は起点を示し、合わせる対象を示せない。", "へ": "「加減へ、部屋の広さに合わせる」は方向を示し、合わせる対象にならず不自然。"}, "error_tags": {"に": "位置・相手", "から": "起点", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37579, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の程度や状態が、ちょうどよい具合であること。また、その度合い。", "primary_collocate": null, "pronunciation": "かげん", "ipa": "kaɡeɴ", "syllable_count": 3, "sentences": [{"text": "体の加減が悪くて、会社を休んだ。", "target_word": "加減", "complexity_tier": "T3", "furigana": "体[からだ]の加減[かげん]が悪[わる]くて、会社[かいしゃ]を休[やす]んだ。", "sentence_source": "generated"}, {"text": "角度の加減で、写真に光が映りこんだ。", "target_word": "加減", "complexity_tier": "T3", "furigana": "角度[かくど]の加減[かげん]で、写真[しゃしん]に光[ひかり]が映[うつ]りこんだ。", "sentence_source": "generated"}, {"text": "照明の加減で、顔色が悪く見える。", "target_word": "加減", "complexity_tier": "T3", "furigana": "照明[しょうめい]の加減[かげん]で、顔色[かおいろ]が悪[わる]く見[み]える。", "sentence_source": "generated"}, {"text": "彼は酒を飲む加減を知っているので、酔いつぶれたことがない。", "target_word": "加減", "complexity_tier": "T3", "furigana": "彼[かれ]は酒[さけ]を飲[の]む加減[かげん]を知[し]っているので、酔[よ]いつぶれたことがない。", "sentence_source": "generated"}, {"text": "運動の加減を考えて、無理のない計画を立てた。", "target_word": "加減", "complexity_tier": "T3", "furigana": "運動[うんどう]の加減[かげん]を考[かんが]えて、無理[むり]のない計画[けいかく]を立[た]てた。", "sentence_source": "generated"}, {"text": "季節の変わり目は、気候の加減で体調をくずしやすい。", "target_word": "加減", "complexity_tier": "T3", "furigana": "季節[きせつ]の変[か]わり目[め]は、気候[きこう]の加減[かげん]で体調[たいちょう]をくずしやすい。", "sentence_source": "generated"}, {"text": "冷房の加減が強すぎて、寒くなった。", "target_word": "加減", "complexity_tier": "T3", "furigana": "冷房[れいぼう]の加減[かげん]が強[つよ]すぎて、寒[さむ]くなった。", "sentence_source": "generated"}, {"text": "ボリュームの加減を、部屋の広さに合わせる。", "target_word": "加減", "complexity_tier": "T3", "furigana": "ボリュームの加減[かげん]を、部屋[へや]の広[ひろ]さに合[あ]わせる。", "sentence_source": "generated"}, {"text": "勉強の量の加減を、先生と相談した。", "target_word": "加減", "complexity_tier": "T3", "furigana": "勉強[べんきょう]の量[りょう]の加減[かげん]を、先生[せんせい]と相談[そうだん]した。", "sentence_source": "generated"}, {"text": "オーブンの加減が弱くて、パンがなかなか焼けない。", "target_word": "加減", "complexity_tier": "T3", "furigana": "オーブンの加減[かげん]が弱[よわ]くて、パンがなかなか焼[や]けない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "加減", "label": "基本形"}], "register": "標準", "sense_fingerprint": "物事の程度・状態・度合いを表す具合、体調や光・機器の調子の加減", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '138c9f88-9d7f-429e-8d2c-7d4fc969fc77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37579, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "加減", "is_correct": true, "explanation": "「体の加減が悪い」は体調を指し、体調不良で会社を休んだ文に合う。"}, {"text": "呼吸", "is_correct": false, "explanation": "息をする働きで、体調が悪いという文脈と意味が合わない。"}, {"text": "歩幅", "is_correct": false, "explanation": "歩く幅で、体の調子を言う文には合わない。"}, {"text": "眼差し", "is_correct": false, "explanation": "目つきで、体調不良の文には合わない。"}], "explanations": {"加減": "「体の加減が悪い」は体調を指し、体調不良で会社を休んだ文に合う。", "呼吸": "息をする働きで、体調が悪いという文脈と意味が合わない。", "歩幅": "歩く幅で、体の調子を言う文には合わない。", "眼差し": "目つきで、体調不良の文には合わない。"}, "sentence_index": 0, "correct_answer": "加減"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は酒を飲む加減が速すぎて、一杯目で酔いつぶれた。", "explanation": "ここは〈速さ〉の意味。飲むペースは速さで言い、加減は程度の具合を表すので合わない。"}, {"text": "彼は酒を飲む加減が高くて、いつも安い店を探している。", "explanation": "ここは〈値段〉の意味。酒の値段は値段で言い、加減は程度の具合を表すので合わない。"}, {"text": "彼は酒を飲む加減が長くて、夜明けまで続いた。", "explanation": "ここは〈時間〉の意味。飲んでいる時間は時間で言い、加減は程度の具合を表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37579, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "加減", "is_correct": true, "explanation": "「冷房の加減が強すぎて寒い」は冷え方の調整具合を表し、文に合う。"}, {"text": "点滅", "is_correct": false, "explanation": "光がついたり消えたりすることで、冷房の強さを言う文には合わない。"}, {"text": "色合い", "is_correct": false, "explanation": "色の調子で、冷房の強さを言う文には合わない。"}, {"text": "寿命", "is_correct": false, "explanation": "もつ期間で、冷房の強さを言う文には合わない。"}], "explanations": {"加減": "「冷房の加減が強すぎて寒い」は冷え方の調整具合を表し、文に合う。", "点滅": "光がついたり消えたりすることで、冷房の強さを言う文には合わない。", "色合い": "色の調子で、冷房の強さを言う文には合わない。", "寿命": "もつ期間で、冷房の強さを言う文には合わない。"}, "sentence_index": 6, "correct_answer": "加減"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "オーブンの加減が焦げくさくて、台所じゅうに広がった。", "explanation": "ここは〈におい〉の意味。焦げくさいにおいはにおいで言い、加減は調整の具合を表すので合わない。"}, {"text": "機械の加減が鮮やかな青色で、目立つ。", "explanation": "ここは〈色〉の意味。機械の色は色で言い、加減は調整の具合を表すので合わない。"}, {"text": "オーブンの加減を入れてから、電源を切った。", "explanation": "ここは〈電源〉の意味。電源は入れるものだが、加減は入れられないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37579, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "照明を加減が変わって、部屋が暗くなった。", "corrected_sentence": "照明の加減が変わって、部屋が暗くなった。", "error_description": "助詞の誤り。「照明の加減」の「の」が「を」になっている。「を」は目的語を示すので、「加減が変わる」の主語として続かない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37579, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "エアコンの風の加減を、少し固めた。", "corrected_sentence": "エアコンの風の加減を、少し弱めた。", "error_description": "連語の誤り。「加減を弱める」が正しい。「固める」は物を硬くする動詞で、加減とは組み合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a50109-9e29-40da-9b72-4da6b5fefbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37580, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "良い", "is_correct": true, "explanation": "「よい」は「よくないこと」の反対の意味で、「悪い」の対義語。"}, {"text": "遅い", "is_correct": false, "explanation": "時間の速さに関わる語で、「悪い」の対義語ではない。"}, {"text": "強い", "is_correct": false, "explanation": "強弱の対義語で、「よくない」の反対にはならない。"}, {"text": "厚い", "is_correct": false, "explanation": "厚さに関わる語で、「悪い」の対義語ではない。"}], "correct_answer": "良い", "explanations": {"良い": "「よい」は「よくないこと」の反対の意味で、「悪い」の対義語。", "遅い": "時間の速さに関わる語で、「悪い」の対義語ではない。", "強い": "強弱の対義語で、「よくない」の反対にはならない。", "厚い": "厚さに関わる語で、「悪い」の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37580, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "良い", "is_correct": true, "explanation": "「よい」は「悪い」の対義語で、ここでの「よくない」の反対にあたる。"}, {"text": "軽い", "is_correct": false, "explanation": "重さに関わる語で、「悪い」の対義語ではない。"}, {"text": "高い", "is_correct": false, "explanation": "高低に関わる語で、「悪い」の対義語ではない。"}, {"text": "太い", "is_correct": false, "explanation": "太さに関わる語で、「悪い」の対義語ではない。"}], "correct_answer": "良い", "explanations": {"良い": "「よい」は「悪い」の対義語で、ここでの「よくない」の反対にあたる。", "軽い": "重さに関わる語で、「悪い」の対義語ではない。", "高い": "高低に関わる語で、「悪い」の対義語ではない。", "太い": "太さに関わる語で、「悪い」の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37580, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "よいの反対の意味。よくないこと。", "primary_collocate": null, "pronunciation": "わるい", "ipa": "waɾɯi", "syllable_count": 3, "sentences": [{"text": "雨が降っているので、道が悪いです。", "target_word": "悪い", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]っているので、道[みち]が悪[わる]いです。", "sentence_source": "generated"}, {"text": "昨日から体の調子が悪くて、学校を休みました。", "target_word": "悪く", "complexity_tier": "T3", "furigana": "昨日[きのう]から体[からだ]の調子[ちょうし]が悪[わる]くて、学校[がっこう]を休[やす]みました。", "sentence_source": "generated"}, {"text": "人の物を勝手に使うのは悪いことです。", "target_word": "悪い", "complexity_tier": "T3", "furigana": "人[ひと]の物[もの]を勝手[かって]に使[つか]うのは悪[わる]いことです。", "sentence_source": "generated"}, {"text": "夜遅くまで起きているのは体に悪い。", "target_word": "悪い", "complexity_tier": "T3", "furigana": "夜遅[よるおそ]くまで起[お]きているのは体[からだ]に悪[わる]い。", "sentence_source": "generated"}, {"text": "今朝は機嫌が悪かったので、誰とも話しませんでした。", "target_word": "悪かった", "complexity_tier": "T3", "furigana": "今朝[けさ]は機嫌[きげん]が悪[わる]かったので、誰[だれ]とも話[はな]しませんでした。", "sentence_source": "generated"}, {"text": "暗い所で本を読むと、目が悪くなります。", "target_word": "悪く", "complexity_tier": "T3", "furigana": "暗[くら]い所[ところ]で本[ほん]を読[よ]むと、目[め]が悪[わる]くなります。", "sentence_source": "generated"}, {"text": "天気が悪かったから、遠足は中止になった。", "target_word": "悪かった", "complexity_tier": "T3", "furigana": "天気[てんき]が悪[わる]かったから、遠足[えんそく]は中止[ちゅうし]になった。", "sentence_source": "generated"}, {"text": "この魚は変な匂いがするので、悪くなっているかもしれない。", "target_word": "悪く", "complexity_tier": "T3", "furigana": "この魚[さかな]は変[へん]な匂[にお]いがするので、悪[わる]くなっているかもしれない。", "sentence_source": "generated"}, {"text": "彼は顔色が悪いけれど、熱はないそうだ。", "target_word": "悪い", "complexity_tier": "T3", "furigana": "彼[かれ]は顔色[かおいろ]が悪[わる]いけれど、熱[ねつ]はないそうだ。", "sentence_source": "generated"}, {"text": "悪いことをした子どもは、先生に叱られた。", "target_word": "悪い", "complexity_tier": "T3", "furigana": "悪[わる]いことをした子[こ]どもは、先生[せんせい]に叱[しか]られた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "悪い", "label": "終止形・連体形"}, {"form": "悪く", "label": "連用形"}, {"form": "悪かった", "label": "過去形"}, {"form": "悪くない", "label": "否定形"}, {"form": "悪ければ", "label": "仮定形"}], "register": "標準（日常語）", "sense_fingerprint": "よいの反対。天気・体調・行いなどが、よくない状態であること。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faa209c7-2535-420e-9dfa-d147d9c97da0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37580, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "悪い", "is_correct": true, "explanation": "「道が悪い」は雨で路面の状態が好ましくないことを表し、文の流れに合う。"}, {"text": "悪く", "is_correct": false, "explanation": "連用形は「です」に続かないため、「道が悪くです」となり不自然。"}, {"text": "悪くない", "is_correct": false, "explanation": "雨が降っている理由と矛盾し、道が悪くないと言うと文脈に合わない。"}, {"text": "悪ければ", "is_correct": false, "explanation": "仮定形は「です」で文を終えられず、この文の形に合わない。"}], "explanations": {"悪い": "「道が悪い」は雨で路面の状態が好ましくないことを表し、文の流れに合う。", "悪く": "連用形は「です」に続かないため、「道が悪くです」となり不自然。", "悪くない": "雨が降っている理由と矛盾し、道が悪くないと言うと文脈に合わない。", "悪ければ": "仮定形は「です」で文を終えられず、この文の形に合わない。"}, "sentence_index": 0, "correct_answer": "悪い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "頭痛が悪くて、一日中寝ていた。", "explanation": "ここは「ひどい」の意味。痛みの激しさは「ひどい」「強い」で言い、「悪い」は使わない。"}, {"text": "チームは数で悪かったが、粘り強く戦った。", "explanation": "ここは「劣る」の意味。数の多さ・少なさの比較は「劣る」「少ない」で言い、「悪い」は合わない。"}, {"text": "この部屋は悪くて、四人では座れない。", "explanation": "ここは「狭い」の意味。部屋の広さは「狭い」で言い、「悪い」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37580, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "悪かった", "is_correct": true, "explanation": "過去の天気が悪かったことを表し、中止の理由として文に合う。"}, {"text": "良かった", "is_correct": false, "explanation": "天気が良かったのでは中止の理由にならず、文の意味が合わない。"}, {"text": "強かった", "is_correct": false, "explanation": "「天気が強かった」では中止の理由にならない。"}, {"text": "遅かった", "is_correct": false, "explanation": "天気の状態を表す語ではなく、中止の理由として合わない。"}], "explanations": {"悪かった": "過去の天気が悪かったことを表し、中止の理由として文に合う。", "良かった": "天気が良かったのでは中止の理由にならず、文の意味が合わない。", "強かった": "「天気が強かった」では中止の理由にならない。", "遅かった": "天気の状態を表す語ではなく、中止の理由として合わない。"}, "sentence_index": 6, "correct_answer": "悪かった"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この部品は強度が悪いので、すぐ壊れる。", "explanation": "ここは「弱い」の意味。強度の程度は「弱い」「強い」で言い、「悪い」は使わない。"}, {"text": "彼は身長が悪いので、背の高い人に囲まれると目立つ。", "explanation": "ここは「低い」の意味。身長の高低は「低い」「高い」で表し、「悪い」は使わない。"}, {"text": "彼は経験が悪いので、まだ慎重だ。", "explanation": "ここは「乏しい」の意味。経験の少なさは「乏しい」で言い、「悪い」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37580, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "空が暗くなって、道が悪いなった。", "corrected_sentence": "空が暗くなって、道が悪くなった。", "error_description": "「悪い」の連用形は「悪く」。「悪いなった」は誤りで、「悪くなった」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "悪く", "is_correct": true, "explanation": "「て」に続く連用形で、この文の形に合う。"}, {"text": "悪い", "is_correct": false, "explanation": "終止形・連体形は「て」に続かないので誤り。"}, {"text": "悪かった", "is_correct": false, "explanation": "過去形は「て」に続かず、文の流れが崩れる。"}, {"text": "悪ければ", "is_correct": false, "explanation": "仮定形は「て」に続かず、文が成り立たない。"}], "correct_form": "悪く", "base_form": "悪い", "form_label": "連用形", "sentence_index": 1, "explanations": {"悪く": "「て」に続く連用形で、この文の形に合う。", "悪い": "終止形・連体形は「て」に続かないので誤り。", "悪かった": "過去形は「て」に続かず、文の流れが崩れる。", "悪ければ": "仮定形は「て」に続かず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37580, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜道は暗いし、体調が悪いを危ない。", "corrected_sentence": "夜道は暗いし、体調が悪いと危ない。", "error_description": "「悪い」は条件の「と」で続ける。「悪いを」は誤りで、「悪いと」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "悪く", "is_correct": true, "explanation": "「なっている」に続く連用形で、この文の形に合う。"}, {"text": "悪すぎる", "is_correct": false, "explanation": "「悪すぎる」は「なる」に続けると形が合わない。"}, {"text": "悪ければ", "is_correct": false, "explanation": "仮定形は「なっている」に続かず、文が成り立たない。"}, {"text": "悪そう", "is_correct": false, "explanation": "様子を表す形で、「なっている」に続けると文が崩れる。"}], "correct_form": "悪く", "base_form": "悪い", "form_label": "連用形", "sentence_index": 7, "explanations": {"悪く": "「なっている」に続く連用形で、この文の形に合う。", "悪すぎる": "「悪すぎる」は「なる」に続けると形が合わない。", "悪ければ": "仮定形は「なっている」に続かず、文が成り立たない。", "悪そう": "様子を表す形で、「なっている」に続けると文が崩れる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
