INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37581, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "状態や性質が好ましくないさま。正しくない、劣っている、不適切だという評価。", "primary_collocate": null, "pronunciation": "わるい", "ipa": "waɾɯi", "syllable_count": 3, "sentences": [{"text": "彼は成績が悪いが、努力はだれよりもしている。", "target_word": "悪い", "complexity_tier": "T3", "furigana": "彼[かれ]は成績[せいせき]が悪[わる]いが、努力[どりょく]はだれよりもしている。", "sentence_source": "generated"}, {"text": "食事のマナーが悪いと、一緒に食べたくなくなる。", "target_word": "悪い", "complexity_tier": "T3", "furigana": "食事[しょくじ]のマナーが悪[わる]いと、一緒[いっしょ]に食[た]べたくなくなる。", "sentence_source": "generated"}, {"text": "部屋の空気が悪いので、窓を開けましょう。", "target_word": "悪い", "complexity_tier": "T3", "furigana": "部屋[へや]の空気[くうき]が悪[わる]いので、窓[まど]を開[あ]けましょう。", "sentence_source": "generated"}, {"text": "この文章は、言い回しが悪くて意味が伝わりにくい。", "target_word": "悪くて", "complexity_tier": "T3", "furigana": "言い回[まわ]しが悪[わる]くて意味[いみ]が伝[つた]わりにくい。", "sentence_source": "generated"}, {"text": "日本語の発音が悪いと言われて、毎日練習している。", "target_word": "悪い", "complexity_tier": "T3", "furigana": "日本語[にほんご]の発音[はつおん]が悪[わる]いと言[い]われて、毎日[まいにち]練習[れんしゅう]している。", "sentence_source": "generated"}, {"text": "姿勢が悪いと、肩がこりやすくなります。", "target_word": "悪い", "complexity_tier": "T3", "furigana": "姿勢[しせい]が悪[わる]いと、肩[かた]がこりやすくなります。", "sentence_source": "generated"}, {"text": "この機械は使い勝手が悪いので、買い替えたい。", "target_word": "悪い", "complexity_tier": "T3", "furigana": "この機械[きかい]は使[つか]い勝手[かって]が悪[わる]いので、買[か]い替[か]えたい。", "sentence_source": "generated"}, {"text": "状況が悪くなる前に、早めに対策を考えよう。", "target_word": "悪く", "complexity_tier": "T3", "furigana": "状況[じょうきょう]が悪[わる]くなる前[まえ]に、早[はや]めに対策[たいさく]を考[かんが]えよう。", "sentence_source": "generated"}, {"text": "話しかける相手を間違えたのは、タイミングが悪かったからだ。", "target_word": "悪かった", "complexity_tier": "T3", "furigana": "話[はな]しかける相手[あいて]を間違[まちが]えたのは、タイミングが悪[わる]かったからだ。", "sentence_source": "generated"}, {"text": "悪い点を直せば、この計画はもっとよくなる。", "target_word": "悪い", "complexity_tier": "T3", "furigana": "悪[わる]い点[てん]を直[なお]せば、この計画[けいかく]はもっとよくなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "悪い", "label": "終止形・連体形"}, {"form": "悪く", "label": "連用形"}, {"form": "悪かった", "label": "過去形"}, {"form": "悪くない", "label": "否定形"}, {"form": "悪ければ", "label": "仮定形"}], "register": "標準（日常語）", "sense_fingerprint": "成績・態度・性能・責任など、基準に照らして劣っている、不適切だ、正しくないと評価すること。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faa209c7-2535-420e-9dfa-d147d9c97da0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37581, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "悪い", "is_correct": true, "explanation": "「成績が悪いが」で、成績が劣っていることを表し、文の流れに合う。"}, {"text": "悪く", "is_correct": false, "explanation": "連用形は「成績が悪くが」となり、「が」に続かず不自然。"}, {"text": "悪ければ", "is_correct": false, "explanation": "仮定形は「成績が悪ければが」となり、文が成り立たない。"}, {"text": "遅い", "is_correct": false, "explanation": "成績の評価には合わず、「成績が遅いが」は意味が通らない。"}], "explanations": {"悪い": "「成績が悪いが」で、成績が劣っていることを表し、文の流れに合う。", "悪く": "連用形は「成績が悪くが」となり、「が」に続かず不自然。", "悪ければ": "仮定形は「成績が悪ければが」となり、文が成り立たない。", "遅い": "成績の評価には合わず、「成績が遅いが」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "悪い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は足が悪いので、階段を使うのが大変だ。", "explanation": "ここは体の不自由（足の具合）の意味。足の障害は「不自由」で言い、基準に照らした劣りの評価ではない。"}, {"text": "その選手は膝が悪くて、今日は試合に出られない。", "explanation": "ここは体の故障の意味。膝の故障は「痛めている」で言い、技量の劣りを表す「悪い」ではない。"}, {"text": "彼は胃が悪いので、脂っこい物を避けている。", "explanation": "ここは体の不調の意味。胃の不調は「弱い」「痛める」で言い、基準に照らした劣りの評価ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37581, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "悪い", "is_correct": true, "explanation": "「使い勝手が悪い」で、買い替えたい理由として文に合う。"}, {"text": "良い", "is_correct": false, "explanation": "使い勝手が良いと買い替えたい理由にならず、文が合わない。"}, {"text": "熱い", "is_correct": false, "explanation": "使い勝手を表す語ではなく、文の意味が通らない。"}, {"text": "重い", "is_correct": false, "explanation": "使い勝手の評価には合わず、文の意味が通らない。"}], "explanations": {"悪い": "「使い勝手が悪い」で、買い替えたい理由として文に合う。", "良い": "使い勝手が良いと買い替えたい理由にならず、文が合わない。", "熱い": "使い勝手を表す語ではなく、文の意味が通らない。", "重い": "使い勝手の評価には合わず、文の意味が通らない。"}, "sentence_index": 6, "correct_answer": "悪い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この時計は時間が悪くて、遅れたことがない。", "explanation": "ここは「正確」の意味。時刻の確かさは「正確」で言い、「悪い」は時間の状態には使わないので合わない。"}, {"text": "この子は昨夜、悪い夢を見て泣き出した。", "explanation": "ここは「不快な・嫌な」の意味。夢の内容の不快さは「嫌な」で言い、基準に照らした劣りの評価ではない。"}, {"text": "この店の店主は耳が悪いので、注文を大声で繰り返す。", "explanation": "ここは体の機能の障害の意味。耳の不自由は「聞こえにくい」で言い、基準に照らした劣りの評価ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37581, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "説明が分かりにくいと、評判が悪いなる。", "corrected_sentence": "説明が分かりにくいと、評判が悪くなる。", "error_description": "「悪くなる」の連用形は「悪く」。「悪いなる」は誤りで、「悪くなる」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "悪い", "is_correct": true, "explanation": "「と」の前に来る終止形・連体形で、この文の形に合う。"}, {"text": "悪く", "is_correct": false, "explanation": "連用形は「と」に続けると文が完結せず、この文に合わない。"}, {"text": "悪かった", "is_correct": false, "explanation": "過去の話になり、習慣を表す文の内容に合わない。"}, {"text": "悪そう", "is_correct": false, "explanation": "様子を表す形で、「と」の前に置くと文が成り立たない。"}], "correct_form": "悪い", "base_form": "悪い", "form_label": "終止形・連体形", "sentence_index": 1, "explanations": {"悪い": "「と」の前に来る終止形・連体形で、この文の形に合う。", "悪く": "連用形は「と」に続けると文が完結せず、この文に合わない。", "悪かった": "過去の話になり、習慣を表す文の内容に合わない。", "悪そう": "様子を表す形で、「と」の前に置くと文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37581, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この機械は使い勝手が悪いを、誰も使わない。", "corrected_sentence": "この機械は使い勝手が悪いと、誰も使わない。", "error_description": "「悪い」は条件の「と」で続ける。「悪いを」は誤りで、「悪いと」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "悪く", "is_correct": true, "explanation": "「なる」に続く連用形で、この文の形に合う。"}, {"text": "悪すぎる", "is_correct": false, "explanation": "「なる」に続けると形が合わず、文が成り立たない。"}, {"text": "悪ければ", "is_correct": false, "explanation": "仮定形は「なる」に続かず、文が崩れる。"}, {"text": "悪そう", "is_correct": false, "explanation": "様子を表す形で、「なる前に」に続けると文が崩れる。"}], "correct_form": "悪く", "base_form": "悪い", "form_label": "連用形", "sentence_index": 7, "explanations": {"悪く": "「なる」に続く連用形で、この文の形に合う。", "悪すぎる": "「なる」に続けると形が合わず、文が成り立たない。", "悪ければ": "仮定形は「なる」に続かず、文が崩れる。", "悪そう": "様子を表す形で、「なる前に」に続けると文が崩れる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
