INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37582, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "「引く」は、ものを自分の方に動かすことです。", "primary_collocate": null, "pronunciation": "ひく", "ipa": "çikɯ", "syllable_count": 2, "sentences": [{"text": "このドアは押さずに、手前に引くと開きます。", "target_word": "引く", "complexity_tier": "T3", "furigana": "このドアは押[お]さずに、手前[てまえ]に引[ひ]くと開[あ]きます。", "sentence_source": "generated"}, {"text": "犬がひもを強く引いたので、転びそうになりました。", "target_word": "引いた", "complexity_tier": "T3", "furigana": "犬[いぬ]がひもを強[つよ]く引[ひ]いたので、転[ころ]びそうになりました。", "sentence_source": "generated"}, {"text": "母は子どもの手を引いて、横断歩道をわたりました。", "target_word": "引いて", "complexity_tier": "T3", "furigana": "母[はは]は子[こ]どもの手[て]を引[ひ]いて、横断歩道[おうだんほどう]をわたりました。", "sentence_source": "generated"}, {"text": "机の引き出しを引いたら、古い写真が出てきました。", "target_word": "引いた", "complexity_tier": "T3", "furigana": "机[つくえ]の引[ひ]き出[だ]しを引[ひ]いたら、古[ふる]い写真[しゃしん]が出[で]てきました。", "sentence_source": "generated"}, {"text": "椅子を後ろに引いて、ゆっくり座りました。", "target_word": "引いて", "complexity_tier": "T3", "furigana": "椅子[いす]を後[うし]ろに引[ひ]いて、ゆっくり座[すわ]りました。", "sentence_source": "generated"}, {"text": "綱を引くと、鐘が大きな音で鳴りました。", "target_word": "引く", "complexity_tier": "T3", "furigana": "綱[つな]を引[ひ]くと、鐘[かね]が大[おお]きな音[おと]で鳴[な]りました。", "sentence_source": "generated"}, {"text": "彼女は私の袖を引いて、小さな声で話しかけました。", "target_word": "引いて", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は私[わたし]の袖[そで]を引[ひ]いて、小[ちい]さな声[こえ]で話[はな]しかけました。", "sentence_source": "generated"}, {"text": "重いかばんを引きながら、駅まで歩きました。", "target_word": "引き", "complexity_tier": "T3", "furigana": "重[おも]いかばんを引[ひ]きながら、駅[えき]まで歩[ある]きました。", "sentence_source": "generated"}, {"text": "赤いひもを引いてください。電気がつきます。", "target_word": "引いて", "complexity_tier": "T3", "furigana": "赤[あか]いひもを引[ひ]いてください。電気[でんき]がつきます。", "sentence_source": "generated"}, {"text": "押すのではなく、ドアを自分の方に引きます。", "target_word": "引きます", "complexity_tier": "T3", "furigana": "押[お]すのではなく、ドアを自分[じぶん]の方[ほう]に引[ひ]きます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "引く", "label": "辞書形"}, {"form": "引きます", "label": "丁寧形"}, {"form": "引いて", "label": "て形"}, {"form": "引いた", "label": "た形"}, {"form": "引かない", "label": "ない形"}, {"form": "引けば", "label": "仮定形"}], "register": "標準", "sense_fingerprint": "ものを自分の方へ動かす（他動詞）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b906860-ce3e-49f4-97db-f10691e443cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37582, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "引く", "is_correct": true, "explanation": "「手前に引くと開く」の動詞。ドアを自分の方に動かす動作を表し、文脈に合う。"}, {"text": "光る", "is_correct": false, "explanation": "「手前に光ると開く」は意味が通らず、動作の方向を示せない。"}, {"text": "眠る", "is_correct": false, "explanation": "「手前に眠ると開く」は成り立たず、ドアを動かす動作と結びつかない。"}, {"text": "歌う", "is_correct": false, "explanation": "「手前に歌うと開く」は動作として不自然で、文脈に合わない。"}], "explanations": {"引く": "「手前に引くと開く」の動詞。ドアを自分の方に動かす動作を表し、文脈に合う。", "光る": "「手前に光ると開く」は意味が通らず、動作の方向を示せない。", "眠る": "「手前に眠ると開く」は成り立たず、ドアを動かす動作と結びつかない。", "歌う": "「手前に歌うと開く」は動作として不自然で、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "引く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "玄関の鍵を引いて、ドアを開けた。", "explanation": "ここは〈回す〉の意味。鍵は回して開けるもので、引く（手前に動かす）では開けられないので合わない。"}, {"text": "エレベーターのボタンを引いて、呼んだ。", "explanation": "ここは〈押す〉の意味。ボタンは押すもので、引く（手前に動かす）は使わないので合わない。"}, {"text": "ノートに定規で直線を引いた。", "explanation": "ここは〈線を描く〉の意味。直線を描くのは「引く」の別の用法で、手前に動かす意味とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37582, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "引いて", "is_correct": true, "explanation": "袖を引いてから話しかける動作を表し、「引いて、話しかけました」と続く文脈に合う。"}, {"text": "笑って", "is_correct": false, "explanation": "袖を笑う対象にはならず、「袖を笑って」は文が成り立たない。"}, {"text": "走って", "is_correct": false, "explanation": "袖を走らせることはできず、「袖を走って」は成り立たない。"}, {"text": "泣いて", "is_correct": false, "explanation": "袖を泣くという動作は成り立たず、文脈に合わない。"}], "explanations": {"引いて": "袖を引いてから話しかける動作を表し、「引いて、話しかけました」と続く文脈に合う。", "笑って": "袖を笑う対象にはならず、「袖を笑って」は文が成り立たない。", "走って": "袖を走らせることはできず、「袖を走って」は成り立たない。", "泣いて": "袖を泣くという動作は成り立たず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "引いて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "お祭りの始まりに、太鼓を引いて合図した。", "explanation": "ここは〈叩く〉の意味。太鼓は叩いて鳴らすもので、引く（手前に動かす）とは合わない。"}, {"text": "ポスターを壁に引いた。", "explanation": "ここは〈貼る〉の意味。ポスターを壁に固定するのは貼るで、引く（手前に動かす）は合わない。"}, {"text": "夏休みの絵を、白い紙に引いた。", "explanation": "ここは〈描く〉の意味。絵は描くもので、引く（手前に動かす）とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37582, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "太いロープに引くと、船が岸へ寄ってきました。", "corrected_sentence": "太いロープを引くと、船が岸へ寄ってきました。", "error_description": "「引く」は他動詞で、引くものを「を」で示す。「ロープに引く」は誤りで、正しくは「ロープを引く」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "引いた", "is_correct": true, "explanation": "過去の動作を表す「た形」。「強く引いたので」の文脈に合う。"}, {"text": "引き", "is_correct": false, "explanation": "連用形は「引きので」となり、「ので」には続けられない。"}, {"text": "引かない", "is_correct": false, "explanation": "否定形は「引いたので」と意味が逆になり、文脈に合わない。"}, {"text": "引けば", "is_correct": false, "explanation": "仮定形は「引いたので」の確定した事柄と合わない。"}], "correct_form": "引いた", "base_form": "引く", "form_label": "た形", "sentence_index": 1, "explanations": {"引いた": "過去の動作を表す「た形」。「強く引いたので」の文脈に合う。", "引き": "連用形は「引きので」となり、「ので」には続けられない。", "引かない": "否定形は「引いたので」と意味が逆になり、文脈に合わない。", "引けば": "仮定形は「引いたので」の確定した事柄と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37582, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "カーテンを静かに引くます。", "corrected_sentence": "カーテンを静かに引きます。", "error_description": "「引く」の丁寧形は「引きます」。「引くます」は活用の誤りで、語幹に「ます」を直接つけることはできない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "引き", "is_correct": true, "explanation": "連用形で、「引きながら」と動作を並行させる文脈に合う。"}, {"text": "引いて", "is_correct": false, "explanation": "て形は「引いてながら」となり、「ながら」と続けられない。"}, {"text": "引きます", "is_correct": false, "explanation": "丁寧形は「ながら」と続かず、「引きますながら」は文が成り立たない。"}, {"text": "引けた", "is_correct": false, "explanation": "可能形の過去は「引けたながら」となり、動作の並行を表せない。"}], "correct_form": "引き", "base_form": "引く", "form_label": "連用形", "sentence_index": 7, "explanations": {"引き": "連用形で、「引きながら」と動作を並行させる文脈に合う。", "引いて": "て形は「引いてながら」となり、「ながら」と続けられない。", "引きます": "丁寧形は「ながら」と続かず、「引きますながら」は文が成り立たない。", "引けた": "可能形の過去は「引けたながら」となり、動作の並行を表せない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
