INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37583, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "「引く」は、物や人を手前に動かす、または力を加えて移動させる動作を表す他動詞です。", "primary_collocate": null, "pronunciation": "ひく", "ipa": "çikɯ", "syllable_count": 2, "sentences": [{"text": "馬が重い荷車を引いて、坂を上っていきます。", "target_word": "引いて", "complexity_tier": "T3", "furigana": "馬[うま]が重[おも]い荷車[にぐるま]を引[ひ]いて、坂[さか]を上[のぼ]っていきます。", "sentence_source": "generated"}, {"text": "子どもたちは力を合わせて、大きな網を引きました。", "target_word": "引きました", "complexity_tier": "T3", "furigana": "子[こ]どもたちは力[ちから]を合[あ]わせて、大[おお]きな網[あみ]を引[ひ]きました。", "sentence_source": "generated"}, {"text": "警察官は、道に迷った老人の腕を引いて安全な場所へ連れて行きました。", "target_word": "引いて", "complexity_tier": "T3", "furigana": "警察官[けいさつかん]は、道[みち]に迷[まよ]った老人[ろうじん]の腕[うで]を引[ひ]いて安全[あんぜん]な場所[ばしょ]へ連[つ]れて行[い]きました。", "sentence_source": "generated"}, {"text": "引っ越しの日、みんなでソファーを手前に引いて運びました。", "target_word": "引いて", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しの日[ひ]、みんなでソファーを手前[てまえ]に引[ひ]いて運[はこ]びました。", "sentence_source": "generated"}, {"text": "魚が強くかかったので、思い切って竿を引きました。", "target_word": "引きました", "complexity_tier": "T3", "furigana": "魚[さかな]が強[つよ]くかかったので、思[おも]い切[き]って竿[さお]を引[ひ]きました。", "sentence_source": "generated"}, {"text": "彼は弓を力いっぱい引いて、矢を放ちました。", "target_word": "引いて", "complexity_tier": "T3", "furigana": "彼[かれ]は弓[ゆみ]を力[ちから]いっぱい引[ひ]いて、矢[や]を放[はな]ちました。", "sentence_source": "generated"}, {"text": "そりを引く犬たちは、雪の上を速く走ります。", "target_word": "引く", "complexity_tier": "T3", "furigana": "そりを引[ひ]く犬[いぬ]たちは、雪[ゆき]の上[うえ]を速[はや]く走[はし]ります。", "sentence_source": "generated"}, {"text": "弟が私のシャツを引いて、早く行こうと言いました。", "target_word": "引いて", "complexity_tier": "T3", "furigana": "弟[おとうと]が私[わたし]のシャツを引[ひ]いて、早[はや]く行[い]こうと言[い]いました。", "sentence_source": "generated"}, {"text": "このタンスは重いので、二人で引かないと動きません。", "target_word": "引かない", "complexity_tier": "T3", "furigana": "このタンスは重[おも]いので、二人[ふたり]で引[ひ]かないと動[うご]きません。", "sentence_source": "generated"}, {"text": "電車が止まったので、非常用のレバーを引きました。", "target_word": "引きました", "complexity_tier": "T3", "furigana": "電車[でんしゃ]が止[と]まったので、非常用[ひじょうよう]のレバーを引[ひ]きました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "引く", "label": "辞書形"}, {"form": "引きます", "label": "丁寧形"}, {"form": "引いて", "label": "て形"}, {"form": "引いた", "label": "た形"}, {"form": "引かない", "label": "ない形"}, {"form": "引けば", "label": "仮定形"}], "register": "標準", "sense_fingerprint": "物や人に力を加えて手前や後ろへ移動させる（他動詞）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b906860-ce3e-49f4-97db-f10691e443cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37583, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "引いて", "is_correct": true, "explanation": "荷車を引いて坂を上るという動作を表し、「引いて、上っていきます」と続く文脈に合う。"}, {"text": "眠って", "is_correct": false, "explanation": "荷車を眠らせる動作は成り立たず、「荷車を眠って」は文が通らない。"}, {"text": "掃いて", "is_correct": false, "explanation": "荷車を掃く対象にはならず、「荷車を掃いて」は不自然で文脈に合わない。"}, {"text": "叫んで", "is_correct": false, "explanation": "荷車を叫ぶことはできず、文脈に合わない。"}], "explanations": {"引いて": "荷車を引いて坂を上るという動作を表し、「引いて、上っていきます」と続く文脈に合う。", "眠って": "荷車を眠らせる動作は成り立たず、「荷車を眠って」は文が通らない。", "掃いて": "荷車を掃く対象にはならず、「荷車を掃いて」は不自然で文脈に合わない。", "叫んで": "荷車を叫ぶことはできず、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "引いて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "エレベーターの行き先ボタンを引いた。", "explanation": "ここは〈押す〉の意味。ボタンは押すもので、ものを手前に引く動作としては合わない。"}, {"text": "ダイヤルを引いて、音量を上げた。", "explanation": "ここは〈回す〉の意味。ダイヤルは回して操作するもので、引く（手前に動かす）とは合わない。"}, {"text": "ボールを遠くへ引いた。", "explanation": "ここは〈投げる〉の意味。ボールを遠くへ飛ばす動作は投げるで、引く（手前に動かす）とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37583, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "引く", "is_correct": true, "explanation": "「そりを引く犬たち」の動詞。そりを引いて走る犬を表し、文脈に合う。"}, {"text": "煮る", "is_correct": false, "explanation": "そりを煮る対象にはならず、「そりを煮る犬たち」は文脈に合わない。"}, {"text": "焼く", "is_correct": false, "explanation": "そりを焼く動作は文脈に合わず、犬の行動として成り立たない。"}, {"text": "飲む", "is_correct": false, "explanation": "そりを飲むことはできず、「そりを飲む犬たち」は意味が通らない。"}], "explanations": {"引く": "「そりを引く犬たち」の動詞。そりを引いて走る犬を表し、文脈に合う。", "煮る": "そりを煮る対象にはならず、「そりを煮る犬たち」は文脈に合わない。", "焼く": "そりを焼く動作は文脈に合わず、犬の行動として成り立たない。", "飲む": "そりを飲むことはできず、「そりを飲む犬たち」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "引く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "お祭りの始まりに、太鼓を引いて合図した。", "explanation": "ここは〈叩く〉の意味。太鼓は叩いて鳴らすもので、引く（手前に動かす）とは合わない。"}, {"text": "手紙を引いた。", "explanation": "ここは〈書く〉の意味。手紙は書くもので、引く（手前に動かす）の意味では使わない。"}, {"text": "冬のために、マフラーを引いた。", "explanation": "ここは〈編む〉の意味。マフラーは編むもので、引く（手前に動かす）とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37583, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大きな網に引いて、魚を岸へ運びました。", "corrected_sentence": "大きな網を引いて、魚を岸へ運びました。", "error_description": "「引く」は他動詞で、引くものを「を」で示す。「網に引く」は誤りで、正しくは「網を引く」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "引きました", "is_correct": true, "explanation": "丁寧な過去の形。「網を引きました」と丁寧に述べる文脈に合う。"}, {"text": "引いて", "is_correct": false, "explanation": "て形は文を言い切れず、「大きな網を引いて。」では文が終わらない。"}, {"text": "引かない", "is_correct": false, "explanation": "否定形で、引いた事実を述べる文と意味が逆になる。"}, {"text": "引けば", "is_correct": false, "explanation": "仮定形は確定した動作を表す文と合わない。"}], "correct_form": "引きました", "base_form": "引く", "form_label": "丁寧形", "sentence_index": 1, "explanations": {"引きました": "丁寧な過去の形。「網を引きました」と丁寧に述べる文脈に合う。", "引いて": "て形は文を言い切れず、「大きな網を引いて。」では文が終わらない。", "引かない": "否定形で、引いた事実を述べる文と意味が逆になる。", "引けば": "仮定形は確定した動作を表す文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37583, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "重い扉を手前に引きて開けた。", "corrected_sentence": "重い扉を手前に引いて開けた。", "error_description": "「引く」のて形は「引いて」。「引きて」は誤った活用で、て形の作り方に合わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "引いて", "is_correct": true, "explanation": "て形で、「引いて、早く行こうと言いました」と続く文脈に合う。"}, {"text": "引く", "is_correct": false, "explanation": "辞書形は「引く、早く行こう」と続けると文の区切りが不自然になる。"}, {"text": "引きます", "is_correct": false, "explanation": "丁寧形は文の途中で使えず、「引きます、早く行こう」は不自然。"}, {"text": "引けた", "is_correct": false, "explanation": "可能形の過去は、シャツを引く動作の文脈に合わない。"}], "correct_form": "引いて", "base_form": "引く", "form_label": "て形", "sentence_index": 7, "explanations": {"引いて": "て形で、「引いて、早く行こうと言いました」と続く文脈に合う。", "引く": "辞書形は「引く、早く行こう」と続けると文の区切りが不自然になる。", "引きます": "丁寧形は文の途中で使えず、「引きます、早く行こう」は不自然。", "引けた": "可能形の過去は、シャツを引く動作の文脈に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
