INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37584, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "えらいことや、よいことをする人のことです。", "primary_collocate": null, "pronunciation": "こうき", "ipa": "koːki", "syllable_count": 3, "sentences": [{"text": "あの方は、困っている人を助ける高貴な人だと言われている。", "target_word": "高貴", "complexity_tier": "T3", "furigana": "あの方[かた]は、困[こま]っている人[ひと]を助[たす]ける高貴[こうき]な人[ひと]だと言[い]われている。", "sentence_source": "generated"}, {"text": "高貴な人は、立場の弱い人にもやさしく話しかける。", "target_word": "高貴", "complexity_tier": "T3", "furigana": "高貴[こうき]な人[ひと]は、立場[たちば]の弱[よわ]い人[ひと]にもやさしく話[はな]しかける。", "sentence_source": "generated"}, {"text": "昔の物語には、国を守った高貴な人がたくさん出てくる。", "target_word": "高貴", "complexity_tier": "T3", "furigana": "昔[むかし]の物語[ものがたり]には、国[くに]を守[まも]った高貴[こうき]な人[ひと]がたくさん出[で]てくる。", "sentence_source": "generated"}, {"text": "彼女は貧しい人に食べ物を配る高貴な人で、みんなに慕われた。", "target_word": "高貴", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は貧[まず]しい人[ひと]に食[た]べ物[もの]を配[くば]る高貴[こうき]な人[ひと]で、みんなに慕[した]われた。", "sentence_source": "generated"}, {"text": "高貴な人とは、お金持ちのことではなく、心が立派な人のことだ。", "target_word": "高貴", "complexity_tier": "T3", "furigana": "高貴[こうき]な人[ひと]とは、お金持[かねも]ちのことではなく、心[こころ]が立派[りっぱ]な人[ひと]のことだ。", "sentence_source": "generated"}, {"text": "祖母は、だれにも親切にする高貴な人だった。", "target_word": "高貴", "complexity_tier": "T3", "furigana": "祖母[そぼ]は、だれにも親切[しんせつ]にする高貴[こうき]な人[ひと]だった。", "sentence_source": "generated"}, {"text": "先生は「人のために働く高貴な人になりなさい」と言った。", "target_word": "高貴", "complexity_tier": "T3", "furigana": "先生[せんせい]は「人[ひと]のために働[はたら]く高貴[こうき]な人[ひと]になりなさい」と言[い]った。", "sentence_source": "generated"}, {"text": "村を救った高貴な人の像が、広場に立っている。", "target_word": "高貴", "complexity_tier": "T3", "furigana": "村[むら]を救[すく]った高貴[こうき]な人[ひと]の像[ぞう]が、広場[ひろば]に立[た]っている。", "sentence_source": "generated"}, {"text": "高貴な人は、ほめられても自慢しないものだ。", "target_word": "高貴", "complexity_tier": "T3", "furigana": "高貴[こうき]な人[ひと]は、ほめられても自慢[じまん]しないものだ。", "sentence_source": "generated"}, {"text": "彼は高貴な人だから、困った人を見れば必ず手を貸す。", "target_word": "高貴", "complexity_tier": "T3", "furigana": "彼[かれ]は高貴[こうき]な人[ひと]だから、困[こま]った人[ひと]を見[み]れば必[かなら]ず手[て]を貸[か]す。", "sentence_source": "generated"}], "morphological_forms": [{"form": "高貴", "label": "語幹・名詞"}, {"form": "高貴な", "label": "連体形"}, {"form": "高貴で", "label": "連用形（中止・接続）"}, {"form": "高貴だ", "label": "終止形"}], "register": "文章語（やや改まった語）", "sense_fingerprint": "立派な行いをし、人のために尽くす心の気高い人。『高貴な人』の形で使う。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faa209c7-2535-420e-9dfa-d147d9c97da0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37584, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高貴", "is_correct": true, "explanation": "「困っている人を助ける高貴な人」で、身分や品格の高さを表し、文に合う。"}, {"text": "貧弱", "is_correct": false, "explanation": "「貧弱な人」では人を助ける人物像と合わない。"}, {"text": "乱暴", "is_correct": false, "explanation": "「乱暴な人」では困っている人を助けるという文の流れに合わない。"}, {"text": "退屈", "is_correct": false, "explanation": "「退屈な人」は人物評価として文脈に合わない。"}], "explanations": {"高貴": "「困っている人を助ける高貴な人」で、身分や品格の高さを表し、文に合う。", "貧弱": "「貧弱な人」では人を助ける人物像と合わない。", "乱暴": "「乱暴な人」では困っている人を助けるという文の流れに合わない。", "退屈": "「退屈な人」は人物評価として文脈に合わない。"}, "sentence_index": 0, "correct_answer": "高貴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このホテルは高貴な値段で、学生には手が出ない。", "explanation": "ここは「高い」の意味。値段の高さには「高い」「高価」を使い、「高貴」は身分や品格を表すので合わない。"}, {"text": "この鉛筆は高貴な書き心地で、字がきれいに書ける。", "explanation": "ここは「上質」の意味。物の質の良さに「高貴」は使わないので合わない。"}, {"text": "この本は高貴な資料で、博物館に保管されている。", "explanation": "ここは「貴重」の意味。得がたい価値のある物には「貴重」を使い、「高貴」は身分や品格を表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37584, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高貴", "is_correct": true, "explanation": "「人のために働く高貴な人になりなさい」で、品格の高い人物像を表し、文に合う。"}, {"text": "凶暴", "is_correct": false, "explanation": "「凶暴な人になりなさい」では、人のために働く人物像と合わない。"}, {"text": "乱雑", "is_correct": false, "explanation": "「乱雑な人」は人物像として文の意味に合わない。"}, {"text": "薄情", "is_correct": false, "explanation": "「薄情な人になりなさい」は人のために働くという文脈と矛盾する。"}], "explanations": {"高貴": "「人のために働く高貴な人になりなさい」で、品格の高い人物像を表し、文に合う。", "凶暴": "「凶暴な人になりなさい」では、人のために働く人物像と合わない。", "乱雑": "「乱雑な人」は人物像として文の意味に合わない。", "薄情": "「薄情な人になりなさい」は人のために働くという文脈と矛盾する。"}, "sentence_index": 6, "correct_answer": "高貴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は高貴な足音で、部屋に入ってきた。", "explanation": "ここは「静か」の意味。足音の静かさに「高貴」は使わないので合わない。"}, {"text": "この犬は高貴な鳴き声で、近所に響いた。", "explanation": "ここは「大きい」の意味。声の大きさには「大きい」を使い、「高貴」は合わない。"}, {"text": "隣の部屋は高貴で、勉強できない。", "explanation": "ここは「騒がしい」の意味。にぎやかな音の多さには「騒がしい」を使い、「高貴」は身分や品格を表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37584, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "高貴だ人は、困った人に手を貸す。", "corrected_sentence": "高貴な人は、困った人に手を貸す。", "error_description": "名詞を修飾するときは連体形「高貴な」を使う。「高貴だ人」は終止形を名詞に続けており誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37584, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は高貴を振る舞うので、みんなに敬われる。", "corrected_sentence": "彼女は高貴に振る舞うので、みんなに敬われる。", "error_description": "「高貴」は副詞として「高貴に振る舞う」と「に」で続ける。「高貴を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
