INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37585, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "地位や身分が上で、立派であること。また、そのさま。", "primary_collocate": null, "pronunciation": "こうき", "ipa": "koːki", "syllable_count": 3, "sentences": [{"text": "彼女は高貴な家に生まれ、小さいころから礼儀を学んだ。", "target_word": "高貴", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は高貴[こうき]な家[いえ]に生[う]まれ、小[ちい]さいころから礼儀[れいぎ]を学[まな]んだ。", "sentence_source": "generated"}, {"text": "高貴な身分の人だけが、その部屋に入ることを許された。", "target_word": "高貴", "complexity_tier": "T3", "furigana": "高貴[こうき]な身分[みぶん]の人[ひと]だけが、その部屋[へや]に入[はい]ることを許[ゆる]された。", "sentence_source": "generated"}, {"text": "高貴な生まれの彼は、庶民の暮らしを知らなかった。", "target_word": "高貴", "complexity_tier": "T3", "furigana": "高貴[こうき]な生[う]まれの彼[かれ]は、庶民[しょみん]の暮[く]らしを知[し]らなかった。", "sentence_source": "generated"}, {"text": "この絵には、高貴な雰囲気の女性がかかれている。", "target_word": "高貴", "complexity_tier": "T3", "furigana": "この絵[え]には、高貴[こうき]な雰囲気[ふんいき]の女性[じょせい]がかかれている。", "sentence_source": "generated"}, {"text": "平安時代の高貴な女性は、顔を人に見せなかった。", "target_word": "高貴", "complexity_tier": "T3", "furigana": "平安時代[へいあんじだい]の高貴[こうき]な女性[じょせい]は、顔[かお]を人[ひと]に見[み]せなかった。", "sentence_source": "generated"}, {"text": "そのドレスは、高貴な身分にふさわしい上品なものだった。", "target_word": "高貴", "complexity_tier": "T3", "furigana": "そのドレスは、高貴[こうき]な身分[みぶん]にふさわしい上品[じょうひん]なものだった。", "sentence_source": "generated"}, {"text": "高貴な人々が集まる舞踏会に、私も招かれた。", "target_word": "高貴", "complexity_tier": "T3", "furigana": "高貴[こうき]な人々[ひとびと]が集[あつ]まる舞踏会[ぶとうかい]に、私[わたし]も招[まね]かれた。", "sentence_source": "generated"}, {"text": "彼の話し方には、高貴な育ちがにじみ出ている。", "target_word": "高貴", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はな]し方[かた]には、高貴[こうき]な育[そだ]ちがにじみ出[で]ている。", "sentence_source": "generated"}, {"text": "高貴な方のお宅なので、玄関で丁寧にあいさつした。", "target_word": "高貴", "complexity_tier": "T3", "furigana": "高貴[こうき]な方[かた]のお宅[たく]なので、玄関[げんかん]で丁寧[ていねい]にあいさつした。", "sentence_source": "generated"}, {"text": "昔は高貴な身分の人だけが、絹の着物を着られた。", "target_word": "高貴", "complexity_tier": "T3", "furigana": "昔[むかし]は高貴[こうき]な身分[みぶん]の人[ひと]だけが、絹[きぬ]の着物[きもの]を着[き]られた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "高貴", "label": "語幹"}, {"form": "高貴な", "label": "連体形"}, {"form": "高貴で", "label": "連用形（中止・接続）"}, {"form": "高貴だ", "label": "終止形"}], "register": "文章語（やや改まった語）", "sense_fingerprint": "生まれや身分が高く、気品があって立派なさま。『高貴な身分・生まれ』の形で使う。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faa209c7-2535-420e-9dfa-d147d9c97da0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37585, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高貴", "is_correct": true, "explanation": "「高貴な家に生まれ」で、身分の高い家柄を表し、文に合う。"}, {"text": "凶暴", "is_correct": false, "explanation": "「凶暴な家に生まれ」は家柄の意味として文に合わない。"}, {"text": "陰湿", "is_correct": false, "explanation": "「陰湿な家に生まれ」は家の雰囲気の評価であり、文の流れに合わない。"}, {"text": "頑丈", "is_correct": false, "explanation": "家の強さを表す語で、生まれ・身分の文脈に合わない。"}], "explanations": {"高貴": "「高貴な家に生まれ」で、身分の高い家柄を表し、文に合う。", "凶暴": "「凶暴な家に生まれ」は家柄の意味として文に合わない。", "陰湿": "「陰湿な家に生まれ」は家の雰囲気の評価であり、文の流れに合わない。", "頑丈": "家の強さを表す語で、生まれ・身分の文脈に合わない。"}, "sentence_index": 0, "correct_answer": "高貴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この絵は高貴な値段で売られ、なかなか買い手がつかない。", "explanation": "ここは「高価」の意味。値段の高さは「高価」で言い、「高貴」は身分や品格を表すので合わない。"}, {"text": "彼は高貴な体格で、毎日ジムに通っている。", "explanation": "ここは「がっしり」の意味。体格には「大柄」「がっしり」を使い、「高貴」は合わない。"}, {"text": "この道は高貴な傾斜で、自転車では上がれない。", "explanation": "ここは「急な」の意味。坂の傾きは「急」で表し、「高貴」は合わないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37585, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高貴", "is_correct": true, "explanation": "「高貴な人々が集まる舞踏会」で、身分の高い人々を表し、文に合う。"}, {"text": "凶悪", "is_correct": false, "explanation": "「凶悪な人々が集まる舞踏会」では文の意味が合わない。"}, {"text": "陰惨", "is_correct": false, "explanation": "「陰惨な人々」は雰囲気や人物の評価が文に合わない。"}, {"text": "粗暴", "is_correct": false, "explanation": "「粗暴な人々」は舞踏会の場に合わず、文の流れに反する。"}], "explanations": {"高貴": "「高貴な人々が集まる舞踏会」で、身分の高い人々を表し、文に合う。", "凶悪": "「凶悪な人々が集まる舞踏会」では文の意味が合わない。", "陰惨": "「陰惨な人々」は雰囲気や人物の評価が文に合わない。", "粗暴": "「粗暴な人々」は舞踏会の場に合わず、文の流れに反する。"}, "sentence_index": 6, "correct_answer": "高貴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この魚は高貴な匂いがするので、食べにくい。", "explanation": "ここは「強い」の意味。匂いの強さには「強い」を使い、「高貴」は身分や品格を表すので合わない。"}, {"text": "彼は高貴な足の速さで、クラスで一番速く走る。", "explanation": "ここは「速い」の意味。走る速さには「速い」を使い、「高貴」は合わない。"}, {"text": "この料理は高貴な辛さなので、子どもには食べられない。", "explanation": "ここは「辛い」の意味。味の辛さには「辛い」を使い、「高貴」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37585, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は高貴に家に生まれた。", "corrected_sentence": "彼女は高貴な家に生まれた。", "error_description": "名詞を修飾するときは連体形「高貴な」を使う。「高貴に家」は副詞形で家を修飾できず誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "高貴", "is_correct": true, "explanation": "語幹の「高貴」が正解。見出し語の形で、語形変化の基本となる。"}, {"text": "高貴で", "is_correct": false, "explanation": "連用形（中止・接続）。「人」を直接修飾できず、ここでは文が続かない。"}, {"text": "高貴だ", "is_correct": false, "explanation": "終止形。名詞「人」の前に置くと修飾できないので、この位置には合わない。"}, {"text": "高貴に", "is_correct": false, "explanation": "副詞形。名詞「人」を修飾できず、「身分の人」の形に合わない。"}], "correct_form": "高貴", "base_form": "高貴", "form_label": "語幹", "sentence_index": 1, "explanations": {"高貴": "語幹の「高貴」が正解。見出し語の形で、語形変化の基本となる。", "高貴で": "連用形（中止・接続）。「人」を直接修飾できず、ここでは文が続かない。", "高貴だ": "終止形。名詞「人」の前に置くと修飾できないので、この位置には合わない。", "高貴に": "副詞形。名詞「人」を修飾できず、「身分の人」の形に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37585, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "高貴で身分の者だけが、宮殿に出入りできた。", "corrected_sentence": "高貴な身分の者だけが、宮殿に出入りできた。", "error_description": "名詞「身分」を修飾するので連体形「高貴な」を使う。「高貴で」は中止形で、「身分」を修飾できず誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "高貴", "is_correct": true, "explanation": "語幹の「高貴」が正解。見出し語の形で、語形変化の基本となる。"}, {"text": "高貴そう", "is_correct": false, "explanation": "様子を表す形で、「育ち」の前に置くと文が崩れる。"}, {"text": "高貴だった", "is_correct": false, "explanation": "過去の形。名詞「育ち」を直接修飾できず、この位置では文が成り立たない。"}, {"text": "高貴である", "is_correct": false, "explanation": "「である」は名詞を直接修飾できないため、「育ち」の前には置けない。"}], "correct_form": "高貴", "base_form": "高貴", "form_label": "語幹", "sentence_index": 7, "explanations": {"高貴": "語幹の「高貴」が正解。見出し語の形で、語形変化の基本となる。", "高貴そう": "様子を表す形で、「育ち」の前に置くと文が崩れる。", "高貴だった": "過去の形。名詞「育ち」を直接修飾できず、この位置では文が成り立たない。", "高貴である": "「である」は名詞を直接修飾できないため、「育ち」の前には置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37586, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「車を止める」の目的語を表す正しい格。"}, {"text": "が", "is_correct": false, "explanation": "「車が止める」では車が止める主体になり、他動詞の「止める」と合わない。"}, {"text": "に", "is_correct": false, "explanation": "「車に止める」は位置や相手を表す形になり、止める対象を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「車と止める」は並列になり、止める対象にならない。"}], "correct_answer": "を", "explanations": {"を": "「車を止める」の目的語を表す正しい格。", "が": "「車が止める」では車が止める主体になり、他動詞の「止める」と合わない。", "に": "「車に止める」は位置や相手を表す形になり、止める対象を示せない。", "と": "「車と止める」は並列になり、止める対象にならない。"}, "error_tags": {"が": "主語の格。止める主体にならない", "に": "位置・相手の格。止める対象を示せない", "と": "並列の格。目的語にならない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37586, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37586, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "くるまなどのしんこうをとめて、停止させます。", "primary_collocate": null, "pronunciation": "とめる", "ipa": "tomeɾɯ", "syllable_count": 3, "sentences": [{"text": "駅の前でタクシーを止めて、荷物をのせた。", "target_word": "止めて", "complexity_tier": "T3", "furigana": "駅(えき)の前(まえ)でタクシーを止(と)めて、荷物(にもつ)をのせた。", "sentence_source": "generated"}, {"text": "父は家の前に車を止めて、エンジンを切った。", "target_word": "止めて", "complexity_tier": "T3", "furigana": "父(ちち)は家(いえ)の前(まえ)に車(くるま)を止(と)めて、エンジンを切(き)った。", "sentence_source": "generated"}, {"text": "雨がひどいので、道のはしに自転車を止めた。", "target_word": "止めた", "complexity_tier": "T3", "furigana": "雨(あめ)がひどいので、道(みち)のはしに自転車(じてんしゃ)を止(と)めた。", "sentence_source": "generated"}, {"text": "運転手はバスを止めて、おばあさんをのせた。", "target_word": "止めて", "complexity_tier": "T3", "furigana": "運転手(うんてんしゅ)はバスを止(と)めて、おばあさんをのせた。", "sentence_source": "generated"}, {"text": "店の前に車を止めないでください。", "target_word": "止めない", "complexity_tier": "T3", "furigana": "店(みせ)の前(まえ)に車(くるま)を止(と)めないでください。", "sentence_source": "generated"}, {"text": "信号が赤になったので、車を止めた。", "target_word": "止めた", "complexity_tier": "T3", "furigana": "信号(しんごう)が赤(あか)になったので、車(くるま)を止(と)めた。", "sentence_source": "generated"}, {"text": "兄は駐車場に車を止めてから、店に入った。", "target_word": "止めて", "complexity_tier": "T3", "furigana": "兄(あに)は駐車場(ちゅうしゃじょう)に車(くるま)を止(と)めてから、店(みせ)に入(はい)った。", "sentence_source": "generated"}, {"text": "手をあげて、通りかかったタクシーを止めた。", "target_word": "止めた", "complexity_tier": "T3", "furigana": "手(て)をあげて、通(とお)りかかったタクシーを止(と)めた。", "sentence_source": "generated"}, {"text": "道がせまいので、広い場所まで行って車を止めます。", "target_word": "止めます", "complexity_tier": "T3", "furigana": "道(みち)がせまいので、広(ひろ)い場所(ばしょ)まで行(い)って車(くるま)を止(と)めます。", "sentence_source": "generated"}, {"text": "雪の日は、坂の下で車を止めて待った。", "target_word": "止めて", "complexity_tier": "T3", "furigana": "雪(ゆき)の日(ひ)は、坂(さか)の下(した)で車(くるま)を止(と)めて待(ま)った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "止める", "label": "終止形"}, {"form": "止めた", "label": "過去形"}, {"form": "止めて", "label": "て形"}, {"form": "止めない", "label": "否定形"}, {"form": "止めます", "label": "丁寧形"}, {"form": "止めれば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "車などの進行を止めて停止させる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T3: contains vocabulary far above tier T3: 坂の下 (Zipf 1.83)']::text[], 'ce891cbc-2525-4fa3-868e-3c2cf3f81b11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37586, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "止めて", "is_correct": true, "explanation": "車などを停めるという動作を表し、「荷物をのせた」へつながる。"}, {"text": "食べて", "is_correct": false, "explanation": "「タクシーを食べて」は意味が成り立たないので合わない。"}, {"text": "笑って", "is_correct": false, "explanation": "「タクシーを笑って」は意味が成り立たないので合わない。"}, {"text": "眠って", "is_correct": false, "explanation": "「タクシーを眠って」は意味が成り立たないので合わない。"}], "explanations": {"止めて": "車などを停めるという動作を表し、「荷物をのせた」へつながる。", "食べて": "「タクシーを食べて」は意味が成り立たないので合わない。", "笑って": "「タクシーを笑って」は意味が成り立たないので合わない。", "眠って": "「タクシーを眠って」は意味が成り立たないので合わない。"}, "sentence_index": 0, "correct_answer": "止めて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寒いので、窓を止めて部屋を暖めた。", "explanation": "ここは〈閉める〉の意味。窓は止めるものではなく閉めるものなので合わない。"}, {"text": "出かける前に、ネクタイを止めて鏡を見た。", "explanation": "ここは〈締める〉の意味。ネクタイは止めるものではなく締めるものなので合わない。"}, {"text": "寝る前に、玄関の鍵を止めた。", "explanation": "ここは〈かける〉の意味。鍵は止めるのではなくかけるものなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37586, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "止めて", "is_correct": true, "explanation": "車を停める動作を表し、「から、店に入った」へ自然につながる。"}, {"text": "歌って", "is_correct": false, "explanation": "「車を歌って」は意味が成り立たないので合わない。"}, {"text": "転んで", "is_correct": false, "explanation": "「車を転んで」は意味が成り立たないので合わない。"}, {"text": "泣いて", "is_correct": false, "explanation": "「車を泣いて」は意味が成り立たないので合わない。"}], "explanations": {"止めて": "車を停める動作を表し、「から、店に入った」へ自然につながる。", "歌って": "「車を歌って」は意味が成り立たないので合わない。", "転んで": "「車を転んで」は意味が成り立たないので合わない。", "泣いて": "「車を泣いて」は意味が成り立たないので合わない。"}, "sentence_index": 6, "correct_answer": "止めて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "読み終えて、本を止めた。", "explanation": "ここは〈閉じる〉の意味。読み終えた本は閉じるもので、止めるとは言わないので合わない。"}, {"text": "雨がひどかったので、友だちを家に止めた。", "explanation": "ここは〈泊める〉の意味。友だちを家に泊めるという別の語で、「止める」とは言わないので合わない。"}, {"text": "夜道で、ヘッドライトを止めた。", "explanation": "ここは〈消す〉か〈つける〉の意味。ライトは止めるものではなく、つけたり消したりするものなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37586, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "坂の下でバスが止めて、乗客が降りた。", "corrected_sentence": "坂の下でバスを止めて、乗客が降りた。", "error_description": "誤りは「バスが」。「止める」は他動詞で目的語が必要なので、「バスを」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "止めて", "is_correct": true, "explanation": "て形。止めた後に「エンジンを切った」へつなぐ形で、文脈に合う。"}, {"text": "止めない", "is_correct": false, "explanation": "否定形。止めなかったという意味になり、実際に止めた事実と合わない。"}, {"text": "止めれば", "is_correct": false, "explanation": "仮定形。条件を表す形になり、過去の動作をつなぐ文脈に合わない。"}, {"text": "止める", "is_correct": false, "explanation": "終止形。文末で言い切る形で、後ろに続く「て」の文脈には合わない。"}], "correct_form": "止めて", "base_form": "止める", "form_label": "て形", "sentence_index": 1, "explanations": {"止めて": "て形。止めた後に「エンジンを切った」へつなぐ形で、文脈に合う。", "止めない": "否定形。止めなかったという意味になり、実際に止めた事実と合わない。", "止めれば": "仮定形。条件を表す形になり、過去の動作をつなぐ文脈に合わない。", "止める": "終止形。文末で言い切る形で、後ろに続く「て」の文脈には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37586, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "駐車場の入口で車を止めるて、係の人に鍵を渡した。", "corrected_sentence": "駐車場の入口で車を止めて、係の人に鍵を渡した。", "error_description": "誤りは「止めるて」。「止める」の連用形は「止めて」なので、「止めるて」は誤り。正しくは「止めて」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "止めた", "is_correct": true, "explanation": "過去形。タクシーを実際に止めた出来事を表し、文の内容と合う。"}, {"text": "止めて", "is_correct": false, "explanation": "て形。後ろに文を続ける形で、出来事を言い切る文末としては合わない。"}, {"text": "止めます", "is_correct": false, "explanation": "丁寧形。現在や未来の丁寧な言い方で、過去の出来事には合わない。"}, {"text": "止めなかった", "is_correct": false, "explanation": "過去否定形。止めなかったという意味になり、実際の出来事と逆になる。"}], "correct_form": "止めた", "base_form": "止める", "form_label": "過去形", "sentence_index": 7, "explanations": {"止めた": "過去形。タクシーを実際に止めた出来事を表し、文の内容と合う。", "止めて": "て形。後ろに文を続ける形で、出来事を言い切る文末としては合わない。", "止めます": "丁寧形。現在や未来の丁寧な言い方で、過去の出来事には合わない。", "止めなかった": "過去否定形。止めなかったという意味になり、実際の出来事と逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37587, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37587, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「人を止めた」の目的語を表す正しい格。"}, {"text": "と", "is_correct": false, "explanation": "「人と止めた」は並列になり、止める対象にならない。"}, {"text": "で", "is_correct": false, "explanation": "「人で止めた」は手段の意味になり、止める対象を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「人より止めた」は比較の意味になり、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「人を止めた」の目的語を表す正しい格。", "と": "「人と止めた」は並列になり、止める対象にならない。", "で": "「人で止めた」は手段の意味になり、止める対象を示せない。", "より": "「人より止めた」は比較の意味になり、文が成り立たない。"}, "error_tags": {"と": "並列の格。止める対象にならない", "で": "手段の格。止める対象を示せない", "より": "比較の格。文が成り立たない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37587, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "動いている人や物などを、動かなくすること。また、行ったり来たりするのをやめること。", "primary_collocate": null, "pronunciation": "とめる", "ipa": "tomeɾɯ", "syllable_count": 3, "sentences": [{"text": "道路に出そうな子どもを、母が急いで止めた。", "target_word": "止めた", "complexity_tier": "T3", "furigana": "道路(どうろ)に出(で)そうな子(こ)どもを、母(はは)が急(いそ)いで止(と)めた。", "sentence_source": "generated"}, {"text": "水道の水を止めるのをわすれて、床がぬれた。", "target_word": "止める", "complexity_tier": "T3", "furigana": "水道(すいどう)の水(みず)を止(と)めるのをわすれて、床(ゆか)がぬれた。", "sentence_source": "generated"}, {"text": "先生は話している生徒を止めて、質問を聞いた。", "target_word": "止めて", "complexity_tier": "T3", "furigana": "先生(せんせい)は話(はな)している生徒(せいと)を止(と)めて、質問(しつもん)を聞(き)いた。", "sentence_source": "generated"}, {"text": "後ろから名前を呼ばれて、彼は歩く足を止めた。", "target_word": "止めた", "complexity_tier": "T3", "furigana": "後(うし)ろから名前(なまえ)を呼(よ)ばれて、彼(かれ)は歩(ある)く足(あし)を止(と)めた。", "sentence_source": "generated"}, {"text": "機械を止めてから、中のそうじをした。", "target_word": "止めて", "complexity_tier": "T3", "furigana": "機械(きかい)を止(と)めてから、中(なか)のそうじをした。", "sentence_source": "generated"}, {"text": "けんかをしている二人を、友だちが止めた。", "target_word": "止めた", "complexity_tier": "T3", "furigana": "けんかをしている二人(ふたり)を、友(とも)だちが止(と)めた。", "sentence_source": "generated"}, {"text": "血が出るのを止めるために、ハンカチで強くおさえた。", "target_word": "止める", "complexity_tier": "T3", "furigana": "血(ち)が出(で)るのを止(と)めるために、ハンカチで強(つよ)くおさえた。", "sentence_source": "generated"}, {"text": "電車が来るので、ふみきりで歩く人を止めた。", "target_word": "止めた", "complexity_tier": "T3", "furigana": "電車(でんしゃ)が来(く)るので、ふみきりで歩(ある)く人(ひと)を止(と)めた。", "sentence_source": "generated"}, {"text": "時計の音が気になって、夜は時計を止めている。", "target_word": "止めている", "complexity_tier": "T3", "furigana": "時計(とけい)の音(おと)が気(き)になって、夜(よる)は時計(とけい)を止(と)めている。", "sentence_source": "generated"}, {"text": "先生は廊下を走る生徒を、声で止めた。", "target_word": "止めた", "complexity_tier": "T3", "furigana": "先生(せんせい)は廊下(ろうか)を走(はし)る生徒(せいと)を、声(こえ)で止(と)めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "止める", "label": "終止形"}, {"form": "止めた", "label": "過去形"}, {"form": "止めて", "label": "て形"}, {"form": "止めない", "label": "否定形"}, {"form": "止めます", "label": "丁寧形"}, {"form": "止めれば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "動いている人や物、流れを動かなくする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T3: contains vocabulary far above tier T3: ふみきり (Zipf 1.36)']::text[], 'ce891cbc-2525-4fa3-868e-3c2cf3f81b11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37587, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "止めた", "is_correct": true, "explanation": "子どもの動きを止める動作を表し、母の行動として自然につながる。"}, {"text": "笑った", "is_correct": false, "explanation": "「子どもを笑った」は意味が成り立たないので合わない。"}, {"text": "眠った", "is_correct": false, "explanation": "「子どもを眠った」は意味が成り立たないので合わない。"}, {"text": "歌った", "is_correct": false, "explanation": "「子どもを歌った」は意味が成り立たないので合わない。"}], "explanations": {"止めた": "子どもの動きを止める動作を表し、母の行動として自然につながる。", "笑った": "「子どもを笑った」は意味が成り立たないので合わない。", "眠った": "「子どもを眠った」は意味が成り立たないので合わない。", "歌った": "「子どもを歌った」は意味が成り立たないので合わない。"}, "sentence_index": 0, "correct_answer": "止めた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "薬を飲んで、足のけがを止めた。", "explanation": "ここは〈治す〉の意味。けがは止めるものではなく治すものなので合わない。"}, {"text": "家族で話し合って、庭の木を止めた。", "explanation": "ここは〈切る〉の意味。木は止めるものではなく切るものなので合わない。"}, {"text": "急に冷えたので、友だちを家に止めた。", "explanation": "ここは〈泊める〉の意味。友だちを泊めるという別の語で、動きを止める意味とは違うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37587, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "止める", "is_correct": true, "explanation": "出血を止める意味で、「止めるために、ハンカチでおさえた」へ自然につながる。"}, {"text": "数える", "is_correct": false, "explanation": "血の出る様子を数える意味になり、ハンカチでおさえる目的として成り立たない。"}, {"text": "比べる", "is_correct": false, "explanation": "血が出るのを比べる意味になり、ハンカチでおさえる目的と合わない。"}, {"text": "喜ぶ", "is_correct": false, "explanation": "血が出るのを喜ぶという意味になり、おさえた理由として成り立たない。"}], "explanations": {"止める": "出血を止める意味で、「止めるために、ハンカチでおさえた」へ自然につながる。", "数える": "血の出る様子を数える意味になり、ハンカチでおさえる目的として成り立たない。", "比べる": "血が出るのを比べる意味になり、ハンカチでおさえる目的と合わない。", "喜ぶ": "血が出るのを喜ぶという意味になり、おさえた理由として成り立たない。"}, "sentence_index": 6, "correct_answer": "止める"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朝起きて、まず体重を止めて、記録に書いた。", "explanation": "ここは〈計る〉の意味。体重は止めるものではなく計るものなので合わない。"}, {"text": "洗濯物を止めて、箱にしまった。", "explanation": "ここは〈たたむ〉の意味。洗濯物は止めるものではなくたたむものなので合わない。"}, {"text": "雨の日、母はかさを止めて、玄関に立てた。", "explanation": "ここは〈立てる〉の意味。かさは止めるものではなく立てるものなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37587, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "お店の前で、走ってきた子どもが止めた。", "corrected_sentence": "お店の前で、走ってきた子どもを止めた。", "error_description": "誤りは「子どもが」。「止める」は他動詞で、止められる対象の「子どもを」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "止める", "is_correct": true, "explanation": "終止形。「止めるのを忘れた」と名詞化の「の」につながる基本の形で、文の内容に合う。"}, {"text": "止めて", "is_correct": false, "explanation": "て形。「止めてのを」と続けると不自然で、ここでは基本の形が必要。"}, {"text": "止めます", "is_correct": false, "explanation": "丁寧形。「止めますの」と名詞に続けられず、文が成り立たない。"}, {"text": "止めれば", "is_correct": false, "explanation": "仮定形。条件を表す形になり、忘れた動作の対象として合わない。"}], "correct_form": "止める", "base_form": "止める", "form_label": "終止形", "sentence_index": 1, "explanations": {"止める": "終止形。「止めるのを忘れた」と名詞化の「の」につながる基本の形で、文の内容に合う。", "止めて": "て形。「止めてのを」と続けると不自然で、ここでは基本の形が必要。", "止めます": "丁寧形。「止めますの」と名詞に続けられず、文が成り立たない。", "止めれば": "仮定形。条件を表す形になり、忘れた動作の対象として合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37587, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "水もれに止めるために、テープをはった。", "corrected_sentence": "水もれを止めるために、テープをはった。", "error_description": "誤りは「水もれに」。「止める」は他動詞で、止める対象は「を」で示すので「水もれを」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "止めた", "is_correct": true, "explanation": "過去形。実際に人を止めた出来事を表し、文の内容と合う。"}, {"text": "止めよう", "is_correct": false, "explanation": "意志を表す形。過去の出来事を述べる文の終わりとして合わず、文が成り立たない。"}, {"text": "止めなかった", "is_correct": false, "explanation": "過去否定形。止めなかったという意味になり、実際の出来事と逆になる。"}, {"text": "止めろ", "is_correct": false, "explanation": "命令の形。出来事を説明する文に合わず、この文脈では成り立たない。"}], "correct_form": "止めた", "base_form": "止める", "form_label": "過去形", "sentence_index": 7, "explanations": {"止めた": "過去形。実際に人を止めた出来事を表し、文の内容と合う。", "止めよう": "意志を表す形。過去の出来事を述べる文の終わりとして合わず、文が成り立たない。", "止めなかった": "過去否定形。止めなかったという意味になり、実際の出来事と逆になる。", "止めろ": "命令の形。出来事を説明する文に合わず、この文脈では成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37588, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「スマホで」の「で」。手段を示す格助詞で、文の流れに合う。"}, {"text": "を", "is_correct": false, "explanation": "「スマホを調べた」は対象を示す形になり、手段を示す文の意味に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「スマホへ調べた」は方向を示す形になり、手段を示す文として不自然。"}, {"text": "に", "is_correct": false, "explanation": "「スマホに調べた」は手段を示せず、「スマホで」の文として合わない。"}], "correct_answer": "で", "explanations": {"で": "「スマホで」の「で」。手段を示す格助詞で、文の流れに合う。", "を": "「スマホを調べた」は対象を示す形になり、手段を示す文の意味に合わない。", "へ": "「スマホへ調べた」は方向を示す形になり、手段を示す文として不自然。", "に": "「スマホに調べた」は手段を示せず、「スマホで」の文として合わない。"}, "error_tags": {"を": "object", "へ": "direction", "に": "location"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37588, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「育て方を」の「を」。調べる対象を示す格助詞で、文の流れに合う。"}, {"text": "が", "is_correct": false, "explanation": "「育て方が調べて」は主語の形になり、調べる対象の文として不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「育て方へ調べて」は方向を示す形になり、対象を示す文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「育て方と調べて」は並列の形になり、対象を示す文として不自然。"}], "correct_answer": "を", "explanations": {"を": "「育て方を」の「を」。調べる対象を示す格助詞で、文の流れに合う。", "が": "「育て方が調べて」は主語の形になり、調べる対象の文として不自然。", "へ": "「育て方へ調べて」は方向を示す形になり、対象を示す文として成り立たない。", "と": "「育て方と調べて」は並列の形になり、対象を示す文として不自然。"}, "error_tags": {"が": "subject", "へ": "direction", "と": "quotation_or_pairing"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37588, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "「しらべる」は、知りたいことを、いろいろな方法で見たり聞いたりして、わかるようにすることです。", "primary_collocate": null, "pronunciation": "しらべる", "ipa": "ɕiɾabeɾɯ", "syllable_count": 4, "sentences": [{"text": "わからない言葉は辞書で調べます。", "target_word": "調べ", "complexity_tier": "T3", "furigana": "わからない言葉[ことば]は辞書[じしょ]で調[しら]べます。", "sentence_source": "generated"}, {"text": "明日の天気をスマホで調べた。", "target_word": "調べた", "complexity_tier": "T3", "furigana": "明日[あした]の天気[てんき]をスマホで調[しら]べた。", "sentence_source": "generated"}, {"text": "電車の時間を調べてから、家を出ましょう。", "target_word": "調べて", "complexity_tier": "T3", "furigana": "電車[でんしゃ]の時間[じかん]を調[しら]べてから、家[いえ]を出[で]ましょう。", "sentence_source": "generated"}, {"text": "駅までの行き方を調べて、地図に印をつけた。", "target_word": "調べて", "complexity_tier": "T3", "furigana": "駅[えき]までの行[い]き方[かた]を調[しら]べて、地図[ちず]に印[しるし]をつけた。", "sentence_source": "generated"}, {"text": "旅行の前に、ホテルの場所をインターネットで調べました。", "target_word": "調べ", "complexity_tier": "T3", "furigana": "旅行[りょこう]の前[まえ]に、ホテルの場所[ばしょ]をインターネットで調[しら]べました。", "sentence_source": "generated"}, {"text": "宿題でわからない漢字を図書館の本で調べる。", "target_word": "調べる", "complexity_tier": "T3", "furigana": "宿題[しゅくだい]でわからない漢字[かんじ]を図書館[としょかん]の本[ほん]で調[しら]べる。", "sentence_source": "generated"}, {"text": "店が何時まで開いているか、電話で調べてみます。", "target_word": "調べて", "complexity_tier": "T3", "furigana": "店[みせ]が何時[なんじ]まで開[あ]いているか、電話[でんわ]で調[しら]べてみます。", "sentence_source": "generated"}, {"text": "彼は犬の育て方を調べて、毎日ノートに書いている。", "target_word": "調べて", "complexity_tier": "T3", "furigana": "彼[かれ]は犬[いぬ]の育[そだ]て方[かた]を調[しら]べて、毎日[まいにち]ノートに書[か]いている。", "sentence_source": "generated"}, {"text": "私は子どものころ、虫の名前を図鑑で調べるのが好きだった。", "target_word": "調べる", "complexity_tier": "T3", "furigana": "私[わたし]は子[こ]どものころ、虫[むし]の名前[なまえ]を図鑑[ずかん]で調[しら]べるのが好[す]きだった。", "sentence_source": "generated"}, {"text": "分からないことがあれば、まず自分で調べなさい。", "target_word": "調べなさい", "complexity_tier": "T3", "furigana": "分[わ]からないことがあれば、まず自分[じぶん]で調[しら]べなさい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "調べる", "label": "終止形"}, {"form": "調べ", "label": "連用形"}, {"form": "調べて", "label": "て形"}, {"form": "調べた", "label": "過去形"}, {"form": "調べない", "label": "否定形"}, {"form": "調べます", "label": "丁寧形"}, {"form": "調べれば", "label": "仮定形"}, {"form": "調べよう", "label": "意志形"}, {"form": "調べなさい", "label": "命令形"}], "register": "中立", "sense_fingerprint": "知りたいことを辞書・本・ネットなどで見聞きして知る（日常の調べもの）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9355037-504a-4712-9844-167042b60a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37588, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "調べ", "is_correct": true, "explanation": "連用形。「辞書で調べます」の「調べ＋ます」の形で、文に合う。"}, {"text": "調べる", "is_correct": false, "explanation": "辞書形に「ます」は続かず、「調べるます」は成り立たない。"}, {"text": "調べなさい", "is_correct": false, "explanation": "命令形に「ます」は続かず、「辞書で調べなさいます」は成り立たない。"}, {"text": "調べた", "is_correct": false, "explanation": "過去形に「ます」は続かず、「調べたます」は成り立たない。"}], "explanations": {"調べ": "連用形。「辞書で調べます」の「調べ＋ます」の形で、文に合う。", "調べる": "辞書形に「ます」は続かず、「調べるます」は成り立たない。", "調べなさい": "命令形に「ます」は続かず、「辞書で調べなさいます」は成り立たない。", "調べた": "過去形に「ます」は続かず、「調べたます」は成り立たない。"}, "sentence_index": 0, "correct_answer": "調べ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先生の話を調べた。", "explanation": "ここは〈聞く〉の意味。調べるは資料や観測で事実を明らかにすることで、人の話を耳で受け取る場面では使わない。"}, {"text": "泣いている子を調べて抱きしめた。", "explanation": "ここは〈抱きしめる〉の意味。調べるは事実を確かめる意味で、腕で包み込む動作には使わない。"}, {"text": "友達の涙を調べて、ハンカチで拭いた。", "explanation": "ここは〈拭く〉の意味。調べるは事実を明らかにする意味で、涙をぬぐう動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37588, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "調べて", "is_correct": true, "explanation": "て形。「電話で調べてみます」の「調べて＋みます」の形で、文に合う。"}, {"text": "調べよう", "is_correct": false, "explanation": "意志形に「みます」は続かず、「調べようみます」は成り立たない。"}, {"text": "調べなさい", "is_correct": false, "explanation": "命令形に「みます」は続かず、文として成り立たない。"}, {"text": "調べれば", "is_correct": false, "explanation": "仮定形に「みます」は続かず、「調べればみます」は文として成り立たない。"}], "explanations": {"調べて": "て形。「電話で調べてみます」の「調べて＋みます」の形で、文に合う。", "調べよう": "意志形に「みます」は続かず、「調べようみます」は成り立たない。", "調べなさい": "命令形に「みます」は続かず、文として成り立たない。", "調べれば": "仮定形に「みます」は続かず、「調べればみます」は文として成り立たない。"}, "sentence_index": 6, "correct_answer": "調べて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "泣いている友達の気持ちを調べなさい。", "explanation": "ここは〈察する〉の意味。調べるは資料などで事実を確かめる意味で、人の気持ちを推し量る場面では使わない。"}, {"text": "部屋の壁に、好きな絵を調べなさい。", "explanation": "ここは〈飾る〉の意味。調べるは事実を明らかにする意味で、絵を壁に並べて見せる場面では使わない。"}, {"text": "読書の時間に、本を一冊、枕にして調べなさい。", "explanation": "ここは〈枕にする〉の意味。調べるは事実を明らかにする意味で、本を枕にする場面では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37588, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大学の入試日程を調べに、申し込んだ。", "corrected_sentence": "大学の入試日程を調べてから、申し込んだ。", "error_description": "「調べてから」を「調べに」にしている。前後の動作を順に続けるには「調べてから」が必要で、「調べに」は文として不自然になる。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "調べた", "is_correct": true, "explanation": "過去形。「スマホで調べた。」と文を終える形で、過去の出来事として合う。"}, {"text": "調べ", "is_correct": false, "explanation": "連用形は文を終えられず、「スマホで調べ。」は文として成り立たない。"}, {"text": "調べて", "is_correct": false, "explanation": "て形は文末で止まれず、「スマホで調べて。」は不完全な文になる。"}, {"text": "調べれば", "is_correct": false, "explanation": "仮定形は「ば」の条件節になり、文を言い切れない。"}], "correct_form": "調べた", "base_form": "調べる", "form_label": "過去形", "sentence_index": 1, "explanations": {"調べた": "過去形。「スマホで調べた。」と文を終える形で、過去の出来事として合う。", "調べ": "連用形は文を終えられず、「スマホで調べ。」は文として成り立たない。", "調べて": "て形は文末で止まれず、「スマホで調べて。」は不完全な文になる。", "調べれば": "仮定形は「ば」の条件節になり、文を言い切れない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37588, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父の住んでいた町の歴史を調べよと、図書館へ行った。", "corrected_sentence": "祖父の住んでいた町の歴史を調べようと、図書館へ行った。", "error_description": "意志形「調べよう」の「う」が抜けて「調べよ」になっている。「調べよ」は命令の形で、「〜と、図書館へ行った」の文脈に合わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "調べて", "is_correct": true, "explanation": "て形。「調べて、毎日ノートに書いている」と文中で続ける形で、文脈に合う。"}, {"text": "調べなさい", "is_correct": false, "explanation": "命令形は文を言い切るので、「調べなさい、毎日…」と続かない。"}, {"text": "調べよう", "is_correct": false, "explanation": "意志形は文を締めくくる形で、「調べよう、毎日…」と続けられない。"}, {"text": "調べます", "is_correct": false, "explanation": "丁寧形は「ます」で言い切るため、「調べます、毎日…」と続けるのは不自然。"}], "correct_form": "調べて", "base_form": "調べる", "form_label": "て形", "sentence_index": 7, "explanations": {"調べて": "て形。「調べて、毎日ノートに書いている」と文中で続ける形で、文脈に合う。", "調べなさい": "命令形は文を言い切るので、「調べなさい、毎日…」と続かない。", "調べよう": "意志形は文を締めくくる形で、「調べよう、毎日…」と続けられない。", "調べます": "丁寧形は「ます」で言い切るため、「調べます、毎日…」と続けるのは不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37589, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「原因を」の「を」。調べる対象を示す格助詞で、文の流れに合う。"}, {"text": "が", "is_correct": false, "explanation": "「原因が調べています」は主語の位置になり、警察が調べる対象としての文の意味に合わない。"}, {"text": "に", "is_correct": false, "explanation": "「原因に調べています」は場所や相手を示す位置になり、対象を示す文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「原因へ調べています」は方向を示す形になり、調べる対象を示す文として不自然。"}], "correct_answer": "を", "explanations": {"を": "「原因を」の「を」。調べる対象を示す格助詞で、文の流れに合う。", "が": "「原因が調べています」は主語の位置になり、警察が調べる対象としての文の意味に合わない。", "に": "「原因に調べています」は場所や相手を示す位置になり、対象を示す文として成り立たない。", "へ": "「原因へ調べています」は方向を示す形になり、調べる対象を示す文として不自然。"}, "error_tags": {"が": "subject", "に": "location", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37589, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「安全を」の「を」。調べる対象を示す格助詞で、文の流れに合う。"}, {"text": "が", "is_correct": false, "explanation": "「安全が調べている」は主語の形になり、専門家が調べる対象を示す文として不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「安全へ調べている」は方向を示す形になり、調べる対象の文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「安全と調べている」は並列や引用を示す形になり、調べる対象を示す文に合わない。"}], "correct_answer": "を", "explanations": {"を": "「安全を」の「を」。調べる対象を示す格助詞で、文の流れに合う。", "が": "「安全が調べている」は主語の形になり、専門家が調べる対象を示す文として不自然。", "へ": "「安全へ調べている」は方向を示す形になり、調べる対象の文として成り立たない。", "と": "「安全と調べている」は並列や引用を示す形になり、調べる対象を示す文に合わない。"}, "error_tags": {"が": "subject", "へ": "direction", "と": "quotation_or_pairing"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37589, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "「調べる」は、疑問や目的のために、資料や観測などを用いて事実や原因などを明らかにすること。", "primary_collocate": null, "pronunciation": "しらべる", "ipa": "ɕiɾabeɾɯ", "syllable_count": 4, "sentences": [{"text": "医者は体を調べて薬を決めます。", "target_word": "調べて", "complexity_tier": "T3", "furigana": "医者[いしゃ]は体[からだ]を調[しら]べて薬[くすり]を決[き]めます。", "sentence_source": "mined"}, {"text": "警察は事故の原因を調べています。", "target_word": "調べて", "complexity_tier": "T3", "furigana": "警察[けいさつ]は事故[じこ]の原因[げんいん]を調[しら]べています。", "sentence_source": "generated"}, {"text": "科学者は川の水を調べて、魚が減った理由を明らかにした。", "target_word": "調べて", "complexity_tier": "T3", "furigana": "科学者[かがくしゃ]は川[かわ]の水[みず]を調[しら]べて、魚[さかな]が減[へ]った理由[りゆう]を明[あき]らかにした。", "sentence_source": "generated"}, {"text": "資料を調べれば、この町の歴史がわかるはずです。", "target_word": "調べれば", "complexity_tier": "T3", "furigana": "資料[しりょう]を調[しら]べれば、この町[まち]の歴史[れきし]がわかるはずです。", "sentence_source": "generated"}, {"text": "駅員が荷物の中身を調べた。", "target_word": "調べた", "complexity_tier": "T3", "furigana": "駅員[えきいん]が荷物[にもつ]の中身[なかみ]を調[しら]べた。", "sentence_source": "generated"}, {"text": "調査の前に、まず過去のデータを調べる必要がある。", "target_word": "調べる", "complexity_tier": "T3", "furigana": "調査[ちょうさ]の前[まえ]に、まず過去[かこ]のデータを調[しら]べる必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "病気の原因を調べるために、血液の検査をした。", "target_word": "調べる", "complexity_tier": "T3", "furigana": "病気[びょうき]の原因[げんいん]を調[しら]べるために、血液[けつえき]の検査[けんさ]をした。", "sentence_source": "generated"}, {"text": "専門家が古い橋の安全を調べている。", "target_word": "調べて", "complexity_tier": "T3", "furigana": "専門家[せんもんか]が古[ふる]い橋[はし]の安全[あんぜん]を調[しら]べている。", "sentence_source": "generated"}, {"text": "会社は売り上げが下がった理由を調べました。", "target_word": "調べ", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は売[う]り上[あ]げが下[さ]がった理由[りゆう]を調[しら]べました。", "sentence_source": "generated"}, {"text": "先生は生徒のノートを調べて、間違いを直した。", "target_word": "調べて", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]のノートを調[しら]べて、間違[まちが]いを直[なお]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "調べる", "label": "終止形"}, {"form": "調べ", "label": "連用形"}, {"form": "調べて", "label": "て形"}, {"form": "調べた", "label": "過去形"}, {"form": "調べない", "label": "否定形"}, {"form": "調べます", "label": "丁寧形"}, {"form": "調べれば", "label": "仮定形"}, {"form": "調べよう", "label": "意志形"}, {"form": "調べられる", "label": "可能形"}], "register": "中立", "sense_fingerprint": "資料や観測で事実や原因を明らかにする（調査・点検）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9355037-504a-4712-9844-167042b60a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37589, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "調べて", "is_correct": true, "explanation": "て形。「体を調べて、薬を決める」と続けるための形で、文中の文脈に合う。"}, {"text": "調べなさい", "is_correct": false, "explanation": "命令形は文を終えるので、「体を調べなさい薬を決めます」と続かず、文として成り立たない。"}, {"text": "調べよう", "is_correct": false, "explanation": "意志形は文を締めくくる形で、「薬を決めます」と続かない。"}, {"text": "調べない", "is_correct": false, "explanation": "否定形にすると「体を調べない薬」となり、検査してから薬を決めるという文脈に合わない。"}], "explanations": {"調べて": "て形。「体を調べて、薬を決める」と続けるための形で、文中の文脈に合う。", "調べなさい": "命令形は文を終えるので、「体を調べなさい薬を決めます」と続かず、文として成り立たない。", "調べよう": "意志形は文を締めくくる形で、「薬を決めます」と続かない。", "調べない": "否定形にすると「体を調べない薬」となり、検査してから薬を決めるという文脈に合わない。"}, "sentence_index": 0, "correct_answer": "調べて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女の横顔を調べた。", "explanation": "ここは〈見つめる〉の意味。調べるは資料や観測で事実を明らかにすることで、人の顔をじっと見る場面では使わない。"}, {"text": "相手の本心を調べた。", "explanation": "ここは〈探る〉の意味。調べるは事実や原因を明らかにすることで、相手の気持ちをさぐる場面では使わない。"}, {"text": "迷子の子どもを町中で調べた。", "explanation": "ここは〈探す〉の意味。人を捜すときは探すを使い、調べるは対象の事実を明らかにする意味になる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37589, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "調べる", "is_correct": true, "explanation": "辞書形。「病気の原因を調べるために」と続けて目的を表す形で、文に合う。"}, {"text": "調べます", "is_correct": false, "explanation": "丁寧形は「ために」に続かず、「調べますために」は成り立たない。"}, {"text": "調べれば", "is_correct": false, "explanation": "仮定形は「ために」に続かず、条件の形になって目的を表せない。"}, {"text": "調べなさい", "is_correct": false, "explanation": "命令形は「ために」に続かず、文の中で目的を表す形にならない。"}], "explanations": {"調べる": "辞書形。「病気の原因を調べるために」と続けて目的を表す形で、文に合う。", "調べます": "丁寧形は「ために」に続かず、「調べますために」は成り立たない。", "調べれば": "仮定形は「ために」に続かず、条件の形になって目的を表せない。", "調べなさい": "命令形は「ために」に続かず、文の中で目的を表す形にならない。"}, "sentence_index": 6, "correct_answer": "調べる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生に道を調べた。", "explanation": "ここは〈尋ねる〉の意味。調べるは資料や観測で事実を明らかにすることで、人に教えてもらう場面では使わない。"}, {"text": "かばんから一冊調べた。", "explanation": "ここは〈取り出す〉の意味。調べるは事実を明らかにする意味で、かばんから物を出す動作には使わない。"}, {"text": "泣いていた友達を、休み時間に調べた。", "explanation": "ここは〈慰める〉の意味。調べるは事実を確かめる意味で、相手の気持ちを和らげる場面では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37589, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "記者は新しい法律の内容を調べに、記事にした。", "corrected_sentence": "記者は新しい法律の内容を調べて、記事にした。", "error_description": "「調べて」を「調べに」にしている。前後の文を続けるには「調べて」が必要で、「調べに」は行くなどの動詞と組むため、ここでは不自然になる。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "調べて", "is_correct": true, "explanation": "て形。「〜ています」に続けて進行を表す形で、アンカー文の「調べています」の一部として合う。"}, {"text": "調べる", "is_correct": false, "explanation": "辞書形のままでは「〜ています」に続かず、「調べるています」は成り立たない。"}, {"text": "調べ", "is_correct": false, "explanation": "連用形の「調べ」には「ています」が直接つながらず、「調べています」の形にならない。"}, {"text": "調べた", "is_correct": false, "explanation": "過去形の「調べた」には「ています」が続かず、進行を表す文の形にならない。"}], "correct_form": "調べて", "base_form": "調べる", "form_label": "て形", "sentence_index": 1, "explanations": {"調べて": "て形。「〜ています」に続けて進行を表す形で、アンカー文の「調べています」の一部として合う。", "調べる": "辞書形のままでは「〜ています」に続かず、「調べるています」は成り立たない。", "調べ": "連用形の「調べ」には「ています」が直接つながらず、「調べています」の形にならない。", "調べた": "過去形の「調べた」には「ています」が続かず、進行を表す文の形にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37589, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "社員は売り上げの数字を調べるに、資料を開いた。", "corrected_sentence": "社員は売り上げの数字を調べるために、資料を開いた。", "error_description": "目的を表す「ために」が「に」になっている。目的は「調べるために」で示すのが自然で、「調べるに」は文として成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "調べて", "is_correct": true, "explanation": "て形。「〜ている」に続けて進行を表す形で、アンカー文の「調べている」と一致する。"}, {"text": "調べます", "is_correct": false, "explanation": "丁寧形の「調べます」には「ている」が続かず、「調べますている」は成り立たない。"}, {"text": "調べれば", "is_correct": false, "explanation": "仮定形の「調べれば」には「ている」が続かず、条件を表す形になって進行の文に合わない。"}, {"text": "調べない", "is_correct": false, "explanation": "否定形の「調べない」には「ている」が続かず、「調べないている」は成り立たない。"}], "correct_form": "調べて", "base_form": "調べる", "form_label": "て形", "sentence_index": 7, "explanations": {"調べて": "て形。「〜ている」に続けて進行を表す形で、アンカー文の「調べている」と一致する。", "調べます": "丁寧形の「調べます」には「ている」が続かず、「調べますている」は成り立たない。", "調べれば": "仮定形の「調べれば」には「ている」が続かず、条件を表す形になって進行の文に合わない。", "調べない": "否定形の「調べない」には「ている」が続かず、「調べないている」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
