INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37590, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "おかねがたくさんかかること。", "primary_collocate": null, "pronunciation": "こうがく", "ipa": "koːɡakɯ", "syllable_count": 4, "sentences": [{"text": "手術には高額な費用がかかるので、保険に入っておいてよかった。", "target_word": "高額", "complexity_tier": "T3", "furigana": "手術[しゅじゅつ]には高額[こうがく]な費用[ひよう]がかかるので、保険[ほけん]に入[はい]っておいてよかった。", "sentence_source": "generated"}, {"text": "留学は高額になるため、家族と何度も相談した。", "target_word": "高額", "complexity_tier": "T3", "furigana": "留学[りゅうがく]は高額[こうがく]になるため、家族[かぞく]と何度[なんど]も相談[そうだん]した。", "sentence_source": "generated"}, {"text": "この大学は学費が高額で、奨学金なしでは通えない。", "target_word": "高額", "complexity_tier": "T3", "furigana": "この大学[だいがく]は学費[がくひ]が高額[こうがく]で、奨学金[しょうがくきん]なしでは通[かよ]えない。", "sentence_source": "generated"}, {"text": "車の修理が高額になり、新しい車を買うか迷っている。", "target_word": "高額", "complexity_tier": "T3", "furigana": "車[くるま]の修理[しゅうり]が高額[こうがく]になり、新[あたら]しい車[くるま]を買[か]うか迷[まよ]っている。", "sentence_source": "generated"}, {"text": "高額な治療を続けるために、父は仕事を増やした。", "target_word": "高額", "complexity_tier": "T3", "furigana": "高額[こうがく]な治療[ちりょう]を続[つづ]けるために、父[ちち]は仕事[しごと]を増[ふ]やした。", "sentence_source": "generated"}, {"text": "結婚式に高額な費用をかけたので、あとで支払いに苦労した。", "target_word": "高額", "complexity_tier": "T3", "furigana": "結婚式[けっこんしき]に高額[こうがく]な費用[ひよう]をかけたので、あとで支払[しはら]いに苦労[くろう]した。", "sentence_source": "generated"}, {"text": "海外旅行は高額だが、一生の思い出になる。", "target_word": "高額", "complexity_tier": "T3", "furigana": "海外旅行[かいがいりょこう]は高額[こうがく]だが、一生[いっしょう]の思[おも]い出[で]になる。", "sentence_source": "generated"}, {"text": "高額な請求書が届いて、母は驚いた。", "target_word": "高額", "complexity_tier": "T3", "furigana": "高額[こうがく]な請求書[せいきゅうしょ]が届[とど]いて、母[はは]は驚[おどろ]いた。", "sentence_source": "generated"}, {"text": "ピアノを習うと、楽器代や月謝が高額になりがちだ。", "target_word": "高額", "complexity_tier": "T3", "furigana": "ピアノを習[なら]うと、楽器代[がっきだい]や月謝[げっしゃ]が高額[こうがく]になりがちだ。", "sentence_source": "generated"}, {"text": "高額の医療費を払うため、家を売ることにした。", "target_word": "高額", "complexity_tier": "T3", "furigana": "高額[こうがく]の医療費[いりょうひ]を払[はら]うため、家[いえ]を売[う]ることにした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "高額", "label": "語幹・名詞"}, {"form": "高額な", "label": "連体形"}, {"form": "高額の", "label": "連体修飾（の）"}, {"form": "高額で", "label": "連用形（中止・接続）"}, {"form": "高額になる", "label": "変化の形"}], "register": "標準（やや改まった語）", "sense_fingerprint": "治療・学費・修理などで、支払う費用が多くかかること。『高額な費用』の形で使う。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faa209c7-2535-420e-9dfa-d147d9c97da0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37590, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高額", "is_correct": true, "explanation": "「手術の費用が多くかかる」という意味に合う。"}, {"text": "高温", "is_correct": false, "explanation": "温度が高いことを表す語。費用の大きさには使えない。"}, {"text": "高速", "is_correct": false, "explanation": "速さに関する語で、費用の大きさには合わない。"}, {"text": "高層", "is_correct": false, "explanation": "建物の高さに関する語。費用には使わない。"}], "explanations": {"高額": "「手術の費用が多くかかる」という意味に合う。", "高温": "温度が高いことを表す語。費用の大きさには使えない。", "高速": "速さに関する語で、費用の大きさには合わない。", "高層": "建物の高さに関する語。費用には使わない。"}, "sentence_index": 0, "correct_answer": "高額"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼はテストで高額な点数を取った。", "explanation": "ここは〈高得点〉の意味。〈高額〉は金額に使うので、点数には合わない。"}, {"text": "彼は会社で高額な地位に就いた。", "explanation": "ここは〈高位〉（地位が高いこと）の意味。〈高額〉は金額の大きさなので、地位には使えない。"}, {"text": "彼女は高額で歌い上げた。", "explanation": "ここは〈高音〉（音が高いこと）の意味。〈高額〉は金額なので、歌い方には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37590, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高額", "is_correct": true, "explanation": "「海外旅行の費用が多くかかる」という意味に合う。"}, {"text": "高熱", "is_correct": false, "explanation": "体温に関する語。旅行の費用には使えない。"}, {"text": "高所", "is_correct": false, "explanation": "場所の高さを表す語。費用には使わない。"}, {"text": "高圧", "is_correct": false, "explanation": "圧力に関する語。金額には合わない。"}], "explanations": {"高額": "「海外旅行の費用が多くかかる」という意味に合う。", "高熱": "体温に関する語。旅行の費用には使えない。", "高所": "場所の高さを表す語。費用には使わない。", "高圧": "圧力に関する語。金額には合わない。"}, "sentence_index": 6, "correct_answer": "高額"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖母は高額で、一人では階段を上がれない。", "explanation": "ここは〈高齢〉（年が多いこと）の意味。〈高額〉は金額に使い、人の年齢には使えない。"}, {"text": "この村は高額で、野菜作りが盛んだ。", "explanation": "ここは〈高地〉（標高が高い場所）の意味。〈高額〉は金額なので、土地の高さには合わない。"}, {"text": "父は高額で、毎日薬を飲んでいる。", "explanation": "ここは〈高血圧〉の意味。〈高額〉は金額なので、体の状態には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
