INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37591, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "金額が大きいこと。値段が高いこと。", "primary_collocate": null, "pronunciation": "こうがく", "ipa": "koːɡakɯ", "syllable_count": 4, "sentences": [{"text": "高額の商品を買うときは、カードより現金で払う人もいる。", "target_word": "高額", "complexity_tier": "T3", "furigana": "高額[こうがく]の商品[しょうひん]を買[か]うときは、カードより現金[げんきん]で払[はら]う人[ひと]もいる。", "sentence_source": "generated"}, {"text": "銀行で高額な現金を引き出すときは、理由を聞かれることがある。", "target_word": "高額", "complexity_tier": "T3", "furigana": "銀行[ぎんこう]で高額[こうがく]な現金[げんきん]を引[ひ]き出[だ]すときは、理由[りゆう]を聞[き]かれることがある。", "sentence_source": "generated"}, {"text": "この絵は高額で取引され、ニュースになった。", "target_word": "高額", "complexity_tier": "T3", "furigana": "この絵[え]は高額[こうがく]で取引[とりひき]され、ニュースになった。", "sentence_source": "generated"}, {"text": "高額の寄付をしてくれた人に、学校は感謝状を贈った。", "target_word": "高額", "complexity_tier": "T3", "furigana": "高額[こうがく]の寄付[きふ]をしてくれた人[ひと]に、学校[がっこう]は感謝状[かんしゃじょう]を贈[おく]った。", "sentence_source": "generated"}, {"text": "店には高額な時計が並び、ガラスケースに入っていた。", "target_word": "高額", "complexity_tier": "T3", "furigana": "店[みせ]には高額[こうがく]な時計[とけい]が並[なら]び、ガラスケースに入[はい]っていた。", "sentence_source": "generated"}, {"text": "高額な買い物をする前に、値段を比べておこう。", "target_word": "高額", "complexity_tier": "T3", "furigana": "高額[こうがく]な買[か]い物[もの]をする前[まえ]に、値段[ねだん]を比[くら]べておこう。", "sentence_source": "generated"}, {"text": "宝くじで高額の賞金が当たり、彼は仕事を辞めた。", "target_word": "高額", "complexity_tier": "T3", "furigana": "宝[たから]くじで高額[こうがく]の賞金[しょうきん]が当[あ]たり、彼[かれ]は仕事[しごと]を辞[や]めた。", "sentence_source": "generated"}, {"text": "高額な品物は、お店が家まで配達してくれる。", "target_word": "高額", "complexity_tier": "T3", "furigana": "高額[こうがく]な品物[しなもの]は、お店[みせ]が家[いえ]まで配達[はいたつ]してくれる。", "sentence_source": "generated"}, {"text": "一度に高額を支払うと、カードの上限を超えてしまうことがある。", "target_word": "高額", "complexity_tier": "T3", "furigana": "一度[いちど]に高額[こうがく]を支払[しはら]うと、カードの上限[じょうげん]を超[こ]えてしまうことがある。", "sentence_source": "generated"}, {"text": "高額な指輪を買うために、兄は三年間お金をためた。", "target_word": "高額", "complexity_tier": "T3", "furigana": "高額[こうがく]な指輪[ゆびわ]を買[か]うために、兄[あに]は三年間[さんねんかん]お金[かね]をためた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "高額", "label": "語幹・名詞"}, {"form": "高額な", "label": "連体形"}, {"form": "高額の", "label": "連体修飾（の）"}, {"form": "高額で", "label": "連用形（中止・接続）"}, {"form": "高額を", "label": "目的語の形"}], "register": "標準（やや改まった語）", "sense_fingerprint": "商品・現金・賞金・寄付などの金額が大きいこと、値段が高いこと。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faa209c7-2535-420e-9dfa-d147d9c97da0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37591, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高額", "is_correct": true, "explanation": "「商品の金額が大きい」という意味に合う。"}, {"text": "高温", "is_correct": false, "explanation": "温度に関する語。商品の値段には使えない。"}, {"text": "高層", "is_correct": false, "explanation": "建物の階数や高さに関する語。商品には使わない。"}, {"text": "高地", "is_correct": false, "explanation": "標高が高い土地を表す語。商品の金額には合わない。"}], "explanations": {"高額": "「商品の金額が大きい」という意味に合う。", "高温": "温度に関する語。商品の値段には使えない。", "高層": "建物の階数や高さに関する語。商品には使わない。", "高地": "標高が高い土地を表す語。商品の金額には合わない。"}, "sentence_index": 0, "correct_answer": "高額"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖父は高額で、耳が少し遠くなった。", "explanation": "ここは〈高齢〉（年が多いこと）の意味。〈高額〉は金額に使うので、人の年齢には使えない。"}, {"text": "新幹線は高額で走るので、とても早く着く。", "explanation": "ここは〈高速〉（速いこと）の意味。〈高額〉は金額の大きさなので、速さには使えない。"}, {"text": "鳥は高額を飛ぶので、遠くまで見渡せる。", "explanation": "ここは〈高空〉（空の高いところ）の意味。〈高額〉は金額なので、空の高さには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37591, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高額", "is_correct": true, "explanation": "「賞金の金額が大きい」という意味に合う。"}, {"text": "高熱", "is_correct": false, "explanation": "体温に関する語。賞金には使えない。"}, {"text": "高圧", "is_correct": false, "explanation": "圧力に関する語。金額には合わない。"}, {"text": "高音", "is_correct": false, "explanation": "音の高さに関する語。賞金には使わない。"}], "explanations": {"高額": "「賞金の金額が大きい」という意味に合う。", "高熱": "体温に関する語。賞金には使えない。", "高圧": "圧力に関する語。金額には合わない。", "高音": "音の高さに関する語。賞金には使わない。"}, "sentence_index": 6, "correct_answer": "高額"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父は高額で、毎日薬を飲んでいる。", "explanation": "ここは〈高血圧〉の意味。〈高額〉は金額なので、体の状態には使えない。"}, {"text": "今日は高額で、真夏日になった。", "explanation": "ここは〈高温〉（気温が高いこと）の意味。〈高額〉は金額なので、気温の高さには使えない。"}, {"text": "この店は高額で来店する客が多い。", "explanation": "ここは〈高頻度〉（回数が多いこと）の意味。〈高額〉は金額なので、来店の回数には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37591, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この絵は高額くて、買えそうにない。", "corrected_sentence": "この絵は高額で、買えそうにない。", "error_description": "「高額」は名詞なので「くて」は付かない。正しくは「高額で」（中止・接続）。誤りは「高額」の活用形。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37591, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "宝くじで高額だの賞金が当たり、彼はすぐに仕事を辞めた。", "corrected_sentence": "宝くじで高額の賞金が当たり、彼はすぐに仕事を辞めた。", "error_description": "「高額」を賞金の修飾に使うときは「の」が正しい。「だの」は並列の形で、ここでは成り立たない。誤りは「高額」の後の「だの」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37592, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「空を飛んでいく」で鳥の通り道を表す「を」になり、正しい。"}, {"text": "が", "is_correct": false, "explanation": "「鳥が空が飛ぶ」は主語が重なり、不自然で文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「空と飛んでいく」は並列の「と」で、鳥の飛ぶ場所や経路にならず不自然。"}, {"text": "の", "is_correct": false, "explanation": "「空の飛んでいく」は連体修飾にならず、不自然な文になる。"}], "correct_answer": "を", "explanations": {"を": "「空を飛んでいく」で鳥の通り道を表す「を」になり、正しい。", "が": "「鳥が空が飛ぶ」は主語が重なり、不自然で文が成り立たない。", "と": "「空と飛んでいく」は並列の「と」で、鳥の飛ぶ場所や経路にならず不自然。", "の": "「空の飛んでいく」は連体修飾にならず、不自然な文になる。"}, "error_tags": {"を": "経路・目的語", "が": "主語", "と": "並列・相手", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37592, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37592, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "空は、鳥や飛行機が飛ぶ、上の方の場所のことです。", "primary_collocate": null, "pronunciation": "そら", "ipa": "soɾa", "syllable_count": 2, "sentences": [{"text": "空を見上げると、白い雲がゆっくり動いていました。", "target_word": "空", "complexity_tier": "T3", "furigana": "空[そら]を見上[みあ]げると、白[しろ]い雲[くも]がゆっくり動[うご]いていました。", "sentence_source": "generated"}, {"text": "鳥が空を飛んでいくのを、子どもたちが見ています。", "target_word": "空", "complexity_tier": "T3", "furigana": "鳥[とり]が空[そら]を飛[と]んでいくのを、子[こ]どもたちが見[み]ています。", "sentence_source": "generated"}, {"text": "夕方になると、空が赤くなります。", "target_word": "空", "complexity_tier": "T3", "furigana": "夕方[ゆうがた]になると、空[そら]が赤[あか]くなります。", "sentence_source": "generated"}, {"text": "飛行機が空に白い線をのこして行きました。", "target_word": "空", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]が空[そら]に白[しろ]い線[せん]をのこして行[い]きました。", "sentence_source": "generated"}, {"text": "今日は空が暗いので、雨が降りそうです。", "target_word": "空", "complexity_tier": "T3", "furigana": "今日[きょう]は空[そら]が暗[くら]いので、雨[あめ]が降[ふ]りそうです。", "sentence_source": "generated"}, {"text": "夜の空には、たくさんの星が光っていました。", "target_word": "空", "complexity_tier": "T3", "furigana": "夜[よる]の空[そら]には、たくさんの星[ほし]が光[ひか]っていました。", "sentence_source": "generated"}, {"text": "窓から空をながめていたら、虹が出ていました。", "target_word": "空", "complexity_tier": "T3", "furigana": "窓[まど]から空[そら]をながめていたら、虹[にじ]が出[で]ていました。", "sentence_source": "generated"}, {"text": "空は広くて、どこまでも続いているように見えます。", "target_word": "空", "complexity_tier": "T3", "furigana": "空[そら]は広[ひろ]くて、どこまでも続[つづ]いているように見[み]えます。", "sentence_source": "generated"}, {"text": "ヘリコプターが空の高いところを飛んでいます。", "target_word": "空", "complexity_tier": "T3", "furigana": "ヘリコプターが空[そら]の高[たか]いところを飛[と]んでいます。", "sentence_source": "generated"}, {"text": "朝、空が明るくなってから、散歩に出かけました。", "target_word": "空", "complexity_tier": "T3", "furigana": "朝[あさ]、空[そら]が明[あか]るくなってから、散歩[さんぽ]に出[で]かけました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "空", "label": "基本形"}], "register": "標準", "sense_fingerprint": "鳥や飛行機が飛ぶ頭上の広い場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T2: contains vocabulary far above tier T2: のこし (Zipf 2.49)']::text[], '3b906860-ce3e-49f4-97db-f10691e443cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37592, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空", "is_correct": true, "explanation": "「空を見上げる」で、白い雲が動くのを仰ぎ見る場面に合う。"}, {"text": "床", "is_correct": false, "explanation": "床は見上げる対象にならず、「床を見上げると」は文脈に合わない。"}, {"text": "海", "is_correct": false, "explanation": "「海を見上げる」は場面に合わず、雲が動く文脈として不自然。"}, {"text": "地面", "is_correct": false, "explanation": "「地面を見上げる」は意味が通らず、雲を見る文脈に合わない。"}], "explanations": {"空": "「空を見上げる」で、白い雲が動くのを仰ぎ見る場面に合う。", "床": "床は見上げる対象にならず、「床を見上げると」は文脈に合わない。", "海": "「海を見上げる」は場面に合わず、雲が動く文脈として不自然。", "地面": "「地面を見上げる」は意味が通らず、雲を見る文脈に合わない。"}, "sentence_index": 0, "correct_answer": "空"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "魚が空の底をゆっくり泳いでいました。", "explanation": "〈海〉の意味。海の底を泳ぐ話で、空に底があるとは言えず、この語とは合わない。"}, {"text": "空にはり付いたトカゲが、ゆっくり動いていました。", "explanation": "〈天井〉の意味。屋内の上面にはり付くものの話で、屋外の空間を表す空とは合わない。"}, {"text": "机の上の空の箱を、ゆっくり動かしました。", "explanation": "ここは〈からっぽ〉の意味。中身のない箱の話で、頭上の空間を表す空とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37592, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空", "is_correct": true, "explanation": "「空をながめる」で、虹が出ていた場面に合う。"}, {"text": "紙", "is_correct": false, "explanation": "「紙をながめる」は虹の場面に合わず、文が通らない。"}, {"text": "電話", "is_correct": false, "explanation": "「電話をながめる」は意味をなさず、窓の外の場面と合わない。"}, {"text": "鍋", "is_correct": false, "explanation": "「鍋をながめる」は場面に合わず、虹が出ていた文脈として不自然。"}], "explanations": {"空": "「空をながめる」で、虹が出ていた場面に合う。", "紙": "「紙をながめる」は虹の場面に合わず、文が通らない。", "電話": "「電話をながめる」は意味をなさず、窓の外の場面と合わない。", "鍋": "「鍋をながめる」は場面に合わず、虹が出ていた文脈として不自然。"}, "sentence_index": 6, "correct_answer": "空"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この部屋は、広い空を使って作品を展示しています。", "explanation": "〈空間〉の意味。展示に使う場所の広がりを指す語で、頭上の空を表す空とは合わない。"}, {"text": "この絵は、白い空にかけてあります。", "explanation": "〈壁〉の意味。絵をかけるのは壁などの面で、頭上の場所を指すこの語では言えない。"}, {"text": "空が雨で濡れて、すべりやすくなりました。", "explanation": "〈屋根〉の意味。建物の上を覆う部分の話で、雨で濡れてすべりやすくなるのは屋根で、空には当てはまらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37592, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもたちは、空が眺めて雲の形を数えていました。", "corrected_sentence": "子どもたちは、空を眺めて雲の形を数えていました。", "error_description": "助詞の誤り。「眺める」は対象を「を」で受ける。「空が」では空が主語になり、眺めるという動作と合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37592, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨日は、空がとても広く見えます。", "corrected_sentence": "昨日は、空がとても広く見えました。", "error_description": "時制の誤り。「昨日」の出来事なので過去形の「見えました」にする。「見えます」は非過去形で誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37593, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「空に」の「に」。雲のない空という場所に月が見えるという存在の場所を表す。"}, {"text": "へ", "is_correct": false, "explanation": "「空へ見えました」は方向を表す「へ」で、見えるものの場所を示す文にはならない。"}, {"text": "の", "is_correct": false, "explanation": "「空の」は名詞に続く形で、「空の、月が…」では文として続かず不自然になる。"}, {"text": "を", "is_correct": false, "explanation": "「空を見えました」の「を」は他動詞の対象用で、見えるという自動詞的な表現には合わない。"}], "correct_answer": "に", "explanations": {"に": "「空に」の「に」。雲のない空という場所に月が見えるという存在の場所を表す。", "へ": "「空へ見えました」は方向を表す「へ」で、見えるものの場所を示す文にはならない。", "の": "「空の」は名詞に続く形で、「空の、月が…」では文として続かず不自然になる。", "を": "「空を見えました」の「を」は他動詞の対象用で、見えるという自動詞的な表現には合わない。"}, "error_tags": {"へ": "方向", "の": "修飾", "を": "対象"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37593, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37593, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "空とは、地上よりも高い、大気で満たされた空間のことです。飛行機や鳥が飛ぶ領域であり、雲や星が存在する場所でもあります。", "primary_collocate": null, "pronunciation": "そら", "ipa": "soɾa", "syllable_count": 2, "sentences": [{"text": "山の上では、空が近く感じられます。", "target_word": "空", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]では、空[そら]が近[ちか]く感[かん]じられます。", "sentence_source": "generated"}, {"text": "雲一つない空に、月がはっきり見えました。", "target_word": "空", "complexity_tier": "T3", "furigana": "雲[くも]一[ひと]つない空[そら]に、月[つき]がはっきり見[み]えました。", "sentence_source": "generated"}, {"text": "台風が去ったあと、空は少しずつ明るくなりました。", "target_word": "空", "complexity_tier": "T3", "furigana": "台風[たいふう]が去[さ]ったあと、空[そら]は少[すこ]しずつ明[あか]るくなりました。", "sentence_source": "generated"}, {"text": "空には鳥だけでなく、飛行機やドローンも飛んでいます。", "target_word": "空", "complexity_tier": "T3", "furigana": "空[そら]には鳥[とり]だけでなく、飛行機[ひこうき]やドローンも飛[と]んでいます。", "sentence_source": "generated"}, {"text": "都会では、ビルが高くて空が狭く見えます。", "target_word": "空", "complexity_tier": "T3", "furigana": "都会[とかい]では、ビルが高[たか]くて空[そら]が狭[せま]く見[み]えます。", "sentence_source": "generated"}, {"text": "星が好きな兄は、夜になると毎日空を観察しています。", "target_word": "空", "complexity_tier": "T3", "furigana": "星[ほし]が好[す]きな兄[あに]は、夜[よる]になると毎日[まいにち]空[そら]を観察[かんさつ]しています。", "sentence_source": "generated"}, {"text": "空に浮かぶ雲の形を見て、天気を予想しました。", "target_word": "空", "complexity_tier": "T3", "furigana": "空[そら]に浮[う]かぶ雲[くも]の形[かたち]を見[み]て、天気[てんき]を予想[よそう]しました。", "sentence_source": "generated"}, {"text": "花火が上がって、夜の空が一瞬明るくなりました。", "target_word": "空", "complexity_tier": "T3", "furigana": "花火[はなび]が上[あ]がって、夜[よる]の空[そら]が一瞬[いっしゅん]明[あか]るくなりました。", "sentence_source": "generated"}, {"text": "海のそばでは、空と海の境目がほとんどわかりません。", "target_word": "空", "complexity_tier": "T3", "furigana": "海[うみ]のそばでは、空[そら]と海[うみ]の境目[さかいめ]がほとんどわかりません。", "sentence_source": "generated"}, {"text": "雨がやむと、空に大きな虹がかかりました。", "target_word": "空", "complexity_tier": "T3", "furigana": "雨[あめ]がやむと、空[そら]に大[おお]きな虹[にじ]がかかりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "空", "label": "基本形"}], "register": "標準", "sense_fingerprint": "地上より高い大気の空間で雲や星のある場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b906860-ce3e-49f4-97db-f10691e443cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37593, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空", "is_correct": true, "explanation": "大気の広がりとしての空を指し、高い所では空が近く感じられるという文脈に合う。"}, {"text": "味", "is_correct": false, "explanation": "味は舌で感じるもので、「山の上では味が近く感じられる」は意味が通らない。"}, {"text": "手", "is_correct": false, "explanation": "手は体の部位で、高さや距離の感覚を表す文脈に入らず、文が成り立たない。"}, {"text": "紙", "is_correct": false, "explanation": "紙は物体で、山の上の高さとは結びつかず、「紙が近く感じられる」は文脈に合わない。"}], "explanations": {"空": "大気の広がりとしての空を指し、高い所では空が近く感じられるという文脈に合う。", "味": "味は舌で感じるもので、「山の上では味が近く感じられる」は意味が通らない。", "手": "手は体の部位で、高さや距離の感覚を表す文脈に入らず、文が成り立たない。", "紙": "紙は物体で、山の上の高さとは結びつかず、「紙が近く感じられる」は文脈に合わない。"}, "sentence_index": 0, "correct_answer": "空"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "草原で、空に寝転がって昼寝をした。", "explanation": "空（そら）は大気の広がりを指し、寝転がれる地面の意味にはならない。寝転がるのは地面であり、空を場所にすることはできない。"}, {"text": "部屋の空にクモの巣が張っている。", "explanation": "室内の天井は「天井」と言い、空（そら）は屋外の大気の広がりを指す。部屋の天井の意味では使えない。"}, {"text": "空の箱を、そのまま捨てました。", "explanation": "ここは〈中が空っぽ〉（から）の読み。中身のない箱を指し、大気の広がりとしての空（そら）ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37593, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空", "is_correct": true, "explanation": "「空に浮かぶ雲」の空。雲が浮かぶ大気の空間を指し、場所として自然に入る。"}, {"text": "椅子", "is_correct": false, "explanation": "椅子に雲が浮かぶ状況は成り立たず、「椅子に浮かぶ雲」は文脈に合わない。"}, {"text": "本", "is_correct": false, "explanation": "本に雲が浮かぶという場面は成り立たず、文の意味が通らない。"}, {"text": "電話", "is_correct": false, "explanation": "電話に雲が浮かぶことはなく、「電話に浮かぶ雲」は意味が通らない。"}], "explanations": {"空": "「空に浮かぶ雲」の空。雲が浮かぶ大気の空間を指し、場所として自然に入る。", "椅子": "椅子に雲が浮かぶ状況は成り立たず、「椅子に浮かぶ雲」は文脈に合わない。", "本": "本に雲が浮かぶという場面は成り立たず、文の意味が通らない。", "電話": "電話に雲が浮かぶことはなく、「電話に浮かぶ雲」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "空"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "窓から空が差し込んで、部屋が明るくなった。", "explanation": "ここは〈光〉の意味。差し込むのは光で、空（そら）は差し込む主語にはならないので合わない。"}, {"text": "空が強くて、帽子が飛ばされた。", "explanation": "ここは〈風〉の意味。強く吹いて帽子を飛ばすのは風で、空はそのような主語にならない。"}, {"text": "空の瓶を、台所でそっと洗いました。", "explanation": "ここは〈中が空っぽ〉（から）の読み。中身のない瓶を指し、大気の広がりとしての空（そら）ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37593, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜の空を、大きな月が浮かんでいました。", "corrected_sentence": "夜の空に、大きな月が浮かんでいました。", "error_description": "「浮かぶ」は場所を表す「に」を取る。「空を」は対象を表す「を」で、空が目的語になる誤り。正しくは「空に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37593, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夕焼けで空が赤く流れました。", "corrected_sentence": "夕焼けで空が赤く染まりました。", "error_description": "空の色の変化には「染まる」を使う。「流れる」は雲などの動きに使う語で、空の色の変化を表す場合は合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37596, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「原理で動く」の手段・根拠を表す「で」。"}, {"text": "を", "is_correct": false, "explanation": "「原理を動いている」は対象の「を」になり、動く主体を表さない。"}, {"text": "へ", "is_correct": false, "explanation": "「原理へ動いている」は方向の意味になり、ここには合わない。"}, {"text": "の", "is_correct": false, "explanation": "「原理の動いている」は名詞修飾になり、文がつながらない。"}], "correct_answer": "で", "explanations": {"で": "「原理で動く」の手段・根拠を表す「で」。", "を": "「原理を動いている」は対象の「を」になり、動く主体を表さない。", "へ": "「原理へ動いている」は方向の意味になり、ここには合わない。", "の": "「原理の動いている」は名詞修飾になり、文がつながらない。"}, "error_tags": {"を": "対象（目的語）", "へ": "方向", "の": "所属・修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37596, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「原理は知られていない」の主題を表す「は」。"}, {"text": "と", "is_correct": false, "explanation": "「原理と知られていない」は共同の意味になり、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「原理より知られていない」は比較の意味になり、ここには合わない。"}, {"text": "に", "is_correct": false, "explanation": "「原理に知られていない」は方向の意味になり、主題にならない。"}], "correct_answer": "は", "explanations": {"は": "「原理は知られていない」の主題を表す「は」。", "と": "「原理と知られていない」は共同の意味になり、文が成り立たない。", "より": "「原理より知られていない」は比較の意味になり、ここには合わない。", "に": "「原理に知られていない」は方向の意味になり、主題にならない。"}, "error_tags": {"と": "共同・相手", "より": "比較・起点", "に": "方向・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37596, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものがどのように動くかや、どうしてそうなるかを説明する、たいせつな考え方です。", "primary_collocate": null, "pronunciation": "げんり", "ipa": "ɡeɴɾi", "syllable_count": 3, "sentences": [{"text": "飛行機が空を飛ぶ原理を、先生が模型を使って説明してくれた。", "target_word": "原理", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]が空[そら]を飛[と]ぶ原理[げんり]を、先生[せんせい]が模型[もけい]を使[つか]って説明[せつめい]してくれた。", "sentence_source": "generated"}, {"text": "この時計は、振り子の原理で動いているので、電池がいらない。", "target_word": "原理", "complexity_tier": "T3", "furigana": "この時計[とけい]は、振[ふ]り子[こ]の原理[げんり]で動[うご]いているので、電池[でんち]がいらない。", "sentence_source": "generated"}, {"text": "原理が分かれば、機械が壊れても自分で直せる。", "target_word": "原理", "complexity_tier": "T3", "furigana": "原理[げんり]が分[わ]かれば、機械[きかい]が壊[こわ]れても自分[じぶん]で直[なお]せる。", "sentence_source": "generated"}, {"text": "電子レンジが食べ物を温める原理を、弟は知りたがっている。", "target_word": "原理", "complexity_tier": "T3", "furigana": "電子[でんし]レンジが食[た]べ物[もの]を温[あたた]める原理[げんり]を、弟[おとうと]は知[し]りたがっている。", "sentence_source": "generated"}, {"text": "てこの原理を使うと、小さな力で重い石も動かせる。", "target_word": "原理", "complexity_tier": "T3", "furigana": "てこの原理[げんり]を使[つか]うと、小[ちい]さな力[ちから]で重[おも]い石[いし]も動[うご]かせる。", "sentence_source": "generated"}, {"text": "仕組みは複雑だが、原理はとても簡単だ。", "target_word": "原理", "complexity_tier": "T3", "furigana": "仕組[しく]みは複雑[ふくざつ]だが、原理[げんり]はとても簡単[かんたん]だ。", "sentence_source": "generated"}, {"text": "彼は原理を理解しないまま、説明書どおりに機械を使っている。", "target_word": "原理", "complexity_tier": "T3", "furigana": "彼[かれ]は原理[げんり]を理解[りかい]しないまま、説明書[せつめいしょ]どおりに機械[きかい]を使[つか]っている。", "sentence_source": "generated"}, {"text": "冷蔵庫が中を冷やす原理は、意外と知られていない。", "target_word": "原理", "complexity_tier": "T3", "furigana": "冷蔵庫[れいぞうこ]が中[なか]を冷[ひ]やす原理[げんり]は、意外[いがい]と知[し]られていない。", "sentence_source": "generated"}, {"text": "この玩具は磁石の原理を利用して、空中に浮いて見える。", "target_word": "原理", "complexity_tier": "T3", "furigana": "この玩具[おもちゃ]は磁石[じしゃく]の原理[げんり]を利用[りよう]して、空中[くうちゅう]に浮[う]いて見[み]える。", "sentence_source": "generated"}, {"text": "原理を知ると、手品は少しもふしぎではなくなる。", "target_word": "原理", "complexity_tier": "T3", "furigana": "原理[げんり]を知[し]ると、手品[てじな]は少[すこ]しもふしぎではなくなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "原理", "label": "基本形"}], "register": "neutral(普通体・標準語)", "sense_fingerprint": "機械や道具が動くわけを説明する基本の考え方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faa209c7-2535-420e-9dfa-d147d9c97da0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37596, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原理", "is_correct": true, "explanation": "「空を飛ぶ仕組みの基本の考え方」を指し、説明の対象に合う。"}, {"text": "原料", "is_correct": false, "explanation": "製品を作る材料のこと。飛ぶ仕組みを説明する文には合わない。"}, {"text": "原野", "is_correct": false, "explanation": "人の手が入っていない広い土地のこと。仕組みの説明には使えない。"}, {"text": "原価", "is_correct": false, "explanation": "商品を作るのにかかる費用のこと。仕組みには使わない。"}], "explanations": {"原理": "「空を飛ぶ仕組みの基本の考え方」を指し、説明の対象に合う。", "原料": "製品を作る材料のこと。飛ぶ仕組みを説明する文には合わない。", "原野": "人の手が入っていない広い土地のこと。仕組みの説明には使えない。", "原価": "商品を作るのにかかる費用のこと。仕組みには使わない。"}, "sentence_index": 0, "correct_answer": "原理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このパンの原理は、小麦粉と水だ。", "explanation": "ここは〈原料〉（製品を作る材料）の意味。〈原理〉は仕組みの法則なので、材料は指さない。"}, {"text": "この原理は、見渡す限り草がはえた広い土地だ。", "explanation": "ここは〈原野〉（人の手が入っていない広い土地）の意味。〈原理〉は法則なので、土地は指さない。"}, {"text": "大切な契約書の原理を、金庫に保管した。", "explanation": "ここは〈原本〉（写しの元になる書類）の意味。〈原理〉は仕組みの法則で、書類には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37596, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原理", "is_correct": true, "explanation": "「機械の仕組みを理解する」の対象として合う。"}, {"text": "原案", "is_correct": false, "explanation": "計画などの元になる案のこと。理解の対象にはならない。"}, {"text": "原題", "is_correct": false, "explanation": "作品の元の題名のこと。機械を理解する文には合わない。"}, {"text": "原石", "is_correct": false, "explanation": "加工前の鉱石のこと。理解の対象としては合わない。"}], "explanations": {"原理": "「機械の仕組みを理解する」の対象として合う。", "原案": "計画などの元になる案のこと。理解の対象にはならない。", "原題": "作品の元の題名のこと。機械を理解する文には合わない。", "原石": "加工前の鉱石のこと。理解の対象としては合わない。"}, "sentence_index": 6, "correct_answer": "原理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ジュースの原理を水で薄めて、飲みやすくした。", "explanation": "ここは〈原液〉（薄めずに使う濃い液）の意味。〈原理〉は仕組みなので、液体の濃さには使えない。"}, {"text": "裁判で原理が訴えを起こし、勝訴した。", "explanation": "ここは〈原告〉（訴えを起こす人）の意味。〈原理〉は人ではないので、訴える主体にはなれない。"}, {"text": "この工場は原理を精製して、ガソリンを作っている。", "explanation": "ここは〈原油〉（精製する前の石油）の意味。〈原理〉は法則なので、精製する対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37596, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この時計の原理を分かれば、電池の入れ方が分かる。", "corrected_sentence": "この時計の原理が分かれば、電池の入れ方が分かる。", "error_description": "「分かる」は「〜が分かる」と言うので、主語を表す「が」が正しい。誤りは「原理」に付いた「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37596, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "兄は磁石の原理に利用して、空中に浮く玩具を作った。", "corrected_sentence": "兄は磁石の原理を利用して、空中に浮く玩具を作った。", "error_description": "「利用する」は「〜を利用する」と言うので、対象を表す「を」が正しい。誤りは「原理」に付いた「に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37597, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「原理が基本になる」の主語を表す「が」。"}, {"text": "を", "is_correct": false, "explanation": "「原理を基本になる」は対象の「を」になり、「なる」の主語にならない。"}, {"text": "で", "is_correct": false, "explanation": "「原理で基本になる」は手段の意味になり、ここでは成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「原理へ基本になる」は方向の意味で、変化の意味に合わない。"}], "correct_answer": "が", "explanations": {"が": "「原理が基本になる」の主語を表す「が」。", "を": "「原理を基本になる」は対象の「を」になり、「なる」の主語にならない。", "で": "「原理で基本になる」は手段の意味になり、ここでは成り立たない。", "へ": "「原理へ基本になる」は方向の意味で、変化の意味に合わない。"}, "error_tags": {"を": "対象（目的語）", "で": "手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37597, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「原理を発見した」の対象を表す「を」。"}, {"text": "と", "is_correct": false, "explanation": "「原理と発見した」は共同の相手の意味になり、対象を表さない。"}, {"text": "より", "is_correct": false, "explanation": "「原理より発見した」は比較の意味になり、ここには合わない。"}, {"text": "に", "is_correct": false, "explanation": "「原理に発見した」は方向の意味になり、対象を表さない。"}], "correct_answer": "を", "explanations": {"を": "「原理を発見した」の対象を表す「を」。", "と": "「原理と発見した」は共同の相手の意味になり、対象を表さない。", "より": "「原理より発見した」は比較の意味になり、ここには合わない。", "に": "「原理に発見した」は方向の意味になり、対象を表さない。"}, "error_tags": {"と": "共同・相手", "より": "比較・起点", "に": "方向・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37597, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "自然や社会の事柄の、しくみや原因を説明するための基本的な規則や法則。", "primary_collocate": null, "pronunciation": "げんり", "ipa": "ɡeɴɾi", "syllable_count": 3, "sentences": [{"text": "市場では、買う人が多いと値段が上がるという原理が働いている。", "target_word": "原理", "complexity_tier": "T3", "furigana": "市場[しじょう]では、買[か]う人[ひと]が多[おお]いと値段[ねだん]が上[あ]がるという原理[げんり]が働[はたら]いている。", "sentence_source": "generated"}, {"text": "物理学では、エネルギーは消えないという原理が基本になる。", "target_word": "原理", "complexity_tier": "T3", "furigana": "物理学[ぶつりがく]では、エネルギーは消[き]えないという原理[げんり]が基本[きほん]になる。", "sentence_source": "generated"}, {"text": "自然界の原理を知るために、科学者は何度も実験をくり返す。", "target_word": "原理", "complexity_tier": "T3", "furigana": "自然界[しぜんかい]の原理[げんり]を知[し]るために、科学者[かがくしゃ]は何度[なんど]も実験[じっけん]をくり返[かえ]す。", "sentence_source": "generated"}, {"text": "需要と供給の原理は、経済を学ぶ人が最初に習う。", "target_word": "原理", "complexity_tier": "T3", "furigana": "需要[じゅよう]と供給[きょうきゅう]の原理[げんり]は、経済[けいざい]を学[まな]ぶ人[ひと]が最初[さいしょ]に習[なら]う。", "sentence_source": "generated"}, {"text": "競争の原理が働くので、店は少しでも安く売ろうとする。", "target_word": "原理", "complexity_tier": "T3", "furigana": "競争[きょうそう]の原理[げんり]が働[はたら]くので、店[みせ]は少[すこ]しでも安[やす]く売[う]ろうとする。", "sentence_source": "generated"}, {"text": "古代の学者は、星が動く原理を考え続けた。", "target_word": "原理", "complexity_tier": "T3", "furigana": "古代[こだい]の学者[がくしゃ]は、星[ほし]が動[うご]く原理[げんり]を考[かんが]え続[つづ]けた。", "sentence_source": "generated"}, {"text": "社会を動かす原理が変われば、人々の暮らしも変わる。", "target_word": "原理", "complexity_tier": "T3", "furigana": "社会[しゃかい]を動[うご]かす原理[げんり]が変[か]われば、人々[ひとびと]の暮[く]らしも変[か]わる。", "sentence_source": "generated"}, {"text": "浮力の原理を発見した人の話は、今でも有名だ。", "target_word": "原理", "complexity_tier": "T3", "furigana": "浮力[ふりょく]の原理[げんり]を発見[はっけん]した人[ひと]の話[はなし]は、今[いま]でも有名[ゆうめい]だ。", "sentence_source": "generated"}, {"text": "生き物が環境に合わせて変わる原理を、進化論は説明する。", "target_word": "原理", "complexity_tier": "T3", "furigana": "生[い]き物[もの]が環境[かんきょう]に合[あ]わせて変[か]わる原理[げんり]を、進化論[しんかろん]は説明[せつめい]する。", "sentence_source": "generated"}, {"text": "民主主義の原理は、国民が政治の主人公だということだ。", "target_word": "原理", "complexity_tier": "T3", "furigana": "民主主義[みんしゅしゅぎ]の原理[げんり]は、国民[こくみん]が政治[せいじ]の主人公[しゅじんこう]だということだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "原理", "label": "基本形"}], "register": "neutral(普通体・標準語)", "sense_fingerprint": "自然や社会を成り立たせる基本の法則・規則", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faa209c7-2535-420e-9dfa-d147d9c97da0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37597, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原理", "is_correct": true, "explanation": "「原理が働く」の形で、市場の値段の仕組みを指す。"}, {"text": "原石", "is_correct": false, "explanation": "加工前の鉱石のこと。働くものではない。"}, {"text": "原題", "is_correct": false, "explanation": "作品の元の題名のこと。「働く」とは結びつかない。"}, {"text": "原料", "is_correct": false, "explanation": "製品を作る材料のこと。「働く」の主語にはならない。"}], "explanations": {"原理": "「原理が働く」の形で、市場の値段の仕組みを指す。", "原石": "加工前の鉱石のこと。働くものではない。", "原題": "作品の元の題名のこと。「働く」とは結びつかない。", "原料": "製品を作る材料のこと。「働く」の主語にはならない。"}, "sentence_index": 0, "correct_answer": "原理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この映画の原理は、英語のままだ。", "explanation": "ここは〈原題〉（もとの題名）の意味。〈原理〉は法則なので、映画の題名には使わない。"}, {"text": "この写真の原理を、博物館に寄付した。", "explanation": "ここは〈原本〉（写しの元になる物）の意味。〈原理〉は法則なので、物や書類を指さない。"}, {"text": "この商品の原理は、千円ほどだ。", "explanation": "ここは〈原価〉（仕入れの金額）の意味。〈原理〉は法則なので、金額の意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37597, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原理", "is_correct": true, "explanation": "「社会を動かす原理」として、社会の基本の法則に合う。"}, {"text": "原野", "is_correct": false, "explanation": "人の手が入っていない広い土地のこと。社会を動かす意味には合わない。"}, {"text": "原案", "is_correct": false, "explanation": "計画などの元になる案のこと。「動かす」の対象にはならない。"}, {"text": "原告", "is_correct": false, "explanation": "訴えを起こす人のこと。社会を動かす主体には合わない。"}], "explanations": {"原理": "「社会を動かす原理」として、社会の基本の法則に合う。", "原野": "人の手が入っていない広い土地のこと。社会を動かす意味には合わない。", "原案": "計画などの元になる案のこと。「動かす」の対象にはならない。", "原告": "訴えを起こす人のこと。社会を動かす主体には合わない。"}, "sentence_index": 6, "correct_answer": "原理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "水は水素と酸素の原理からできている。", "explanation": "ここは〈原子〉（物質の基本の粒）の意味。〈原理〉は法則なので、物質の一部にはならない。"}, {"text": "このCDの原理は、スタジオに保管されている。", "explanation": "ここは〈原盤〉（録音の元になる板）の意味。〈原理〉は法則で、保管される物ではない。"}, {"text": "この酒蔵は原理をそのまま瓶詰めする。", "explanation": "ここは〈原酒〉（水で割らない酒）の意味。〈原理〉は法則なので、酒には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37597, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市場では、買う人が多いと値段が上がるという原理を働くので、店は値下げしにくい。", "corrected_sentence": "市場では、買う人が多いと値段が上がるという原理が働くので、店は値下げしにくい。", "error_description": "「働く」は「〜が働く」と言うので、主語を表す「が」が正しい。誤りは「原理」に付いた「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37597, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "社会を動かす原理を変われば、人々の暮らしも変わるので、みんなで話し合おう。", "corrected_sentence": "社会を動かす原理が変われば、人々の暮らしも変わるので、みんなで話し合おう。", "error_description": "「変わる」は自動詞なので、主語には「が」を使う。「原理を変わる」は誤り。誤りは「原理」に付いた「を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37598, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「工学の知識」の「の」。名詞と名詞をつなぎ、知識の分野を示す。"}, {"text": "が", "is_correct": false, "explanation": "「工学が知識があれば」は主語が重なり、文が自然につながらない。"}, {"text": "を", "is_correct": false, "explanation": "「工学を知識」は目的語として成り立たず、文の意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「工学へ知識」は方向を示し、知識の分野を表せない。"}], "correct_answer": "の", "explanations": {"の": "「工学の知識」の「の」。名詞と名詞をつなぎ、知識の分野を示す。", "が": "「工学が知識があれば」は主語が重なり、文が自然につながらない。", "を": "「工学を知識」は目的語として成り立たず、文の意味が通らない。", "へ": "「工学へ知識」は方向を示し、知識の分野を表せない。"}, "error_tags": {"が": "主語", "を": "目的語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37598, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「工学では」の「で」。工学という分野の範囲を示して、話題を立てる。"}, {"text": "より", "is_correct": false, "explanation": "「工学より」は比較の対象になり、「理論だけでなく」との関係が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「工学を大切だ」は、大切だの主語に「を」は使えず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「工学に」は存在や対象を表し、ここでは話題を示す形にならない。"}], "correct_answer": "で", "explanations": {"で": "「工学では」の「で」。工学という分野の範囲を示して、話題を立てる。", "より": "「工学より」は比較の対象になり、「理論だけでなく」との関係が成り立たない。", "を": "「工学を大切だ」は、大切だの主語に「を」は使えず、文が成り立たない。", "に": "「工学に」は存在や対象を表し、ここでは話題を示す形にならない。"}, "error_tags": {"より": "比較", "を": "目的語", "に": "対象"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37598, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものをつくったり、きかいをうごかしたりするためのべんきょうです。", "primary_collocate": null, "pronunciation": "こうがく", "ipa": "koːɡakɯ", "syllable_count": 4, "sentences": [{"text": "兄は大学で工学を学び、ロボットを作る仕事につきたいと言う。", "target_word": "工学", "complexity_tier": "T3", "furigana": "兄[あに]は大学[だいがく]で工学[こうがく]を学[まな]び、ロボットを作[つく]る仕事[しごと]につきたいと言[い]う。", "sentence_source": "generated"}, {"text": "工学の知識があれば、橋や道路を安全に設計できる。", "target_word": "工学", "complexity_tier": "T3", "furigana": "工学[こうがく]の知識[ちしき]があれば、橋[はし]や道路[どうろ]を安全[あんぜん]に設計[せっけい]できる。", "sentence_source": "generated"}, {"text": "この大学は工学の研究が盛んで、新しい機械を毎年発表している。", "target_word": "工学", "complexity_tier": "T3", "furigana": "この大学[だいがく]は工学[こうがく]の研究[けんきゅう]が盛[さか]んで、新[あたら]しい機械[きかい]を毎年[まいとし]発表[はっぴょう]している。", "sentence_source": "generated"}, {"text": "工学を専門にする人は、数学が得意なことが多い。", "target_word": "工学", "complexity_tier": "T3", "furigana": "工学[こうがく]を専門[せんもん]にする人[ひと]は、数学[すうがく]が得意[とくい]なことが多[おお]い。", "sentence_source": "generated"}, {"text": "地震に強い建物は、工学の研究から生まれた。", "target_word": "工学", "complexity_tier": "T3", "furigana": "地震[じしん]に強[つよ]い建物[たてもの]は、工学[こうがく]の研究[けんきゅう]から生[う]まれた。", "sentence_source": "generated"}, {"text": "医学と工学が協力して、体に使える小さな機械を作った。", "target_word": "工学", "complexity_tier": "T3", "furigana": "医学[いがく]と工学[こうがく]が協力[きょうりょく]して、体[からだ]に使[つか]える小[ちい]さな機械[きかい]を作[つく]った。", "sentence_source": "generated"}, {"text": "姉は工学が好きで、休みの日も電子工作を楽しんでいる。", "target_word": "工学", "complexity_tier": "T3", "furigana": "姉[あね]は工学[こうがく]が好[す]きで、休[やす]みの日[ひ]も電子工作[でんしこうさく]を楽[たの]しんでいる。", "sentence_source": "generated"}, {"text": "工学では、理論だけでなく、実際に作って試すことも大切だ。", "target_word": "工学", "complexity_tier": "T3", "furigana": "工学[こうがく]では、理論[りろん]だけでなく、実際[じっさい]に作[つく]って試[ため]すことも大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "宇宙船を飛ばせるのは、工学が発展したおかげだ。", "target_word": "工学", "complexity_tier": "T3", "furigana": "宇宙船[うちゅうせん]を飛[と]ばせるのは、工学[こうがく]が発展[はってん]したおかげだ。", "sentence_source": "generated"}, {"text": "彼女は文学より工学に興味があるので、理系の大学を選んだ。", "target_word": "工学", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は文学[ぶんがく]より工学[こうがく]に興味[きょうみ]があるので、理系[りけい]の大学[だいがく]を選[えら]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "工学", "label": "基本形"}], "register": "neutral(普通体・標準語)", "sense_fingerprint": "ものづくりや機械・建設の技術を研究する学問", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faa209c7-2535-420e-9dfa-d147d9c97da0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37598, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工学", "is_correct": true, "explanation": "「大学で」「学び」の目的語として合う、学問の名前。"}, {"text": "工事", "is_correct": false, "explanation": "学ぶ対象にはならない。道路や建物などの建設作業を指す。"}, {"text": "工場", "is_correct": false, "explanation": "学ぶ対象にはならない。ものを製造する施設を指す。"}, {"text": "工房", "is_correct": false, "explanation": "学ぶ対象にはならない。職人が作業をする小さな作業場を指す。"}], "explanations": {"工学": "「大学で」「学び」の目的語として合う、学問の名前。", "工事": "学ぶ対象にはならない。道路や建物などの建設作業を指す。", "工場": "学ぶ対象にはならない。ものを製造する施設を指す。", "工房": "学ぶ対象にはならない。職人が作業をする小さな作業場を指す。"}, "sentence_index": 0, "correct_answer": "工学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "宇宙の成り立ちを数式で解き明かすのが工学だ。", "explanation": "ここは〈理学〉の意味。工学は機械や建物などをつくる学問で、自然の仕組みを解明する分野には使わないので合わない。"}, {"text": "この町は工学を大量に生産し、大きな工場が並んでいる。", "explanation": "ここは〈工業〉に当たる誤用。工学は学問の名前で、生産の対象にはならないので合わない。"}, {"text": "祖母は工学で、季節ごとに美しい器を作っている。", "explanation": "ここは〈工芸〉の意味。器や織物などを手で作る営みは工芸と言い、工学では表せないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37598, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工学", "is_correct": true, "explanation": "電子工作と並ぶ好きな分野として自然につながる学問の名前。"}, {"text": "手術", "is_correct": false, "explanation": "「好きで」の対象として不自然。医療の行為を指す。"}, {"text": "倉庫", "is_correct": false, "explanation": "「好きで」の対象として不自然。物をしまう場所を指す。"}, {"text": "製鉄", "is_correct": false, "explanation": "「好きで」の対象になりにくい。金属を作る産業を指す。"}], "explanations": {"工学": "電子工作と並ぶ好きな分野として自然につながる学問の名前。", "手術": "「好きで」の対象として不自然。医療の行為を指す。", "倉庫": "「好きで」の対象として不自然。物をしまう場所を指す。", "製鉄": "「好きで」の対象になりにくい。金属を作る産業を指す。"}, "sentence_index": 6, "correct_answer": "工学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "職人は長年の工学で、一枚の板から椅子を組み立てた。", "explanation": "ここは〈技術〉の意味。腕前や手わざは技術と言い、工学は学問の分野なので合わない。"}, {"text": "彼女は病院で働くため、工学を専攻して患者の病気を治している。", "explanation": "ここは〈医学〉の意味。病気を治す学問は医学と言い、工学は機械や建物をつくる学問なので合わない。"}, {"text": "彼女は毎晩、小説の工学を書いて新人賞に応募している。", "explanation": "ここは〈文学〉の意味。小説や詩などの作品は文学と言い、工学では表せないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37598, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は大学で工学に学んでいる。", "corrected_sentence": "私は大学で工学を学んでいる。", "error_description": "「学ぶ」は学ぶ対象に「を」をつける。「工学に」は誤りで、「工学を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37598, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は工学を学ぶ、ロボットを作っている。", "corrected_sentence": "彼は工学を学び、ロボットを作っている。", "error_description": "「学ぶ」を読点の前で言い切りの形のままにしている。二つの動作を並べるときは連用形の「学び」にする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37600, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「で」は手段を示し、手で支えたと自然につながる。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。手を支えたでは、木を支えるという意味が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ。手の支えたでは文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や共同を示す。手と支えたでは文が成り立たない。"}], "correct_answer": "で", "explanations": {"で": "「で」は手段を示し、手で支えたと自然につながる。", "を": "「を」は目的語を示す。手を支えたでは、木を支えるという意味が成り立たない。", "の": "「の」は名詞をつなぐ。手の支えたでは文が成り立たない。", "と": "「と」は相手や共同を示す。手と支えたでは文が成り立たない。"}, "error_tags": {"を": "目的語", "の": "連体修飾", "と": "相手・共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37600, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「支える」の目的語である荷物を示す「を」で、荷物を支えながらと自然。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。荷物が支えながらでは意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示す。荷物より支えながらは成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示す。荷物から支えながらは意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「支える」の目的語である荷物を示す「を」で、荷物を支えながらと自然。", "が": "「が」は主語を示す。荷物が支えながらでは意味が通らない。", "より": "「より」は比較を示す。荷物より支えながらは成り立たない。", "から": "「から」は起点を示す。荷物から支えながらは意味が通らない。"}, "error_tags": {"が": "主語", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37600, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かが落ちたり倒れたりしないように、下からしっかりと支えること。", "primary_collocate": null, "pronunciation": "ささえる", "ipa": "sasaeɾɯ", "syllable_count": 4, "sentences": [{"text": "柱が屋根を支えている。", "target_word": "支えている", "complexity_tier": "T2", "furigana": "柱[はしら]が屋根[やね]を支[ささ]えている。", "sentence_source": "generated"}, {"text": "倒れないように、木を手で支えた。", "target_word": "支えた", "complexity_tier": "T3", "furigana": "倒[たお]れないように、木[き]を手[て]で支[ささ]えた。", "sentence_source": "generated"}, {"text": "棚の重い本を、細い棒が支えている。", "target_word": "支えている", "complexity_tier": "T3", "furigana": "棚[たな]の重[おも]い本[ほん]を、細[ほそ]い棒[ぼう]が支[ささ]えている。", "sentence_source": "generated"}, {"text": "転びそうな子どもを、父が後ろから支えた。", "target_word": "支えた", "complexity_tier": "T3", "furigana": "転[ころ]びそうな子[こ]どもを、父[ちち]が後[うし]ろから支[ささ]えた。", "sentence_source": "generated"}, {"text": "橋は太い柱で支えられている。", "target_word": "支えられている", "complexity_tier": "T3", "furigana": "橋[はし]は太[ふと]い柱[はしら]で支[ささ]えられている。", "sentence_source": "generated"}, {"text": "私は梯子を支えて、兄が上るのを待った。", "target_word": "支えて", "complexity_tier": "T3", "furigana": "私[わたし]は梯子[はしご]を支[ささ]えて、兄[あに]が上[のぼ]るのを待[ま]った。", "sentence_source": "generated"}, {"text": "壁が弱いので、板で支える必要がある。", "target_word": "支える", "complexity_tier": "T3", "furigana": "壁[かべ]が弱[よわ]いので、板[いた]で支[ささ]える必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "彼は片手で荷物を支えながら、ドアを開けた。", "target_word": "支えながら", "complexity_tier": "T4", "furigana": "彼[かれ]は片手[かたて]で荷物[にもつ]を支[ささ]えながら、ドアを開[あ]けた。", "sentence_source": "generated"}, {"text": "机の足が折れて、本で机を支えている。", "target_word": "支えている", "complexity_tier": "T3", "furigana": "机[つくえ]の足[あし]が折[お]れて、本[ほん]で机[つくえ]を支[ささ]えている。", "sentence_source": "generated"}, {"text": "風で倒れそうな看板を、二人で支えた。", "target_word": "支えた", "complexity_tier": "T3", "furigana": "風[かぜ]で倒[たお]れそうな看板[かんばん]を、二人[ふたり]で支[ささ]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "支える", "label": "終止形"}, {"form": "支えて", "label": "て形"}, {"form": "支えた", "label": "過去形"}, {"form": "支えない", "label": "否定形"}, {"form": "支えられる", "label": "受身形"}, {"form": "支えながら", "label": "ながら形"}], "register": "neutral", "sense_fingerprint": "物が倒れたり落ちたりしないよう下から押さえて持つ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf6ee224-92d2-4127-abed-56d8891d40e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37600, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "支えている", "is_correct": true, "explanation": "柱が屋根の重さを下から受けて支えている様子を表し、定義に合う。"}, {"text": "笑っている", "is_correct": false, "explanation": "柱が屋根を笑うのは意味が通らず、支える動作ではない。"}, {"text": "歌っている", "is_correct": false, "explanation": "柱が屋根を歌うという文は成り立たず、支える意味とは無関係。"}, {"text": "眠っている", "is_correct": false, "explanation": "「屋根を眠る」とは言えず、文法的にも不自然。"}], "explanations": {"支えている": "柱が屋根の重さを下から受けて支えている様子を表し、定義に合う。", "笑っている": "柱が屋根を笑うのは意味が通らず、支える動作ではない。", "歌っている": "柱が屋根を歌うという文は成り立たず、支える意味とは無関係。", "眠っている": "「屋根を眠る」とは言えず、文法的にも不自然。"}, "sentence_index": 0, "correct_answer": "支えている"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は転んだとき、服の汚れを支えてすぐに立ち上がった。", "explanation": "ここは〈落とす〉の意味。「汚れを落として」の落としを支えに替えたもので、汚れを支えるとは言わない。"}, {"text": "彼は散らかった部屋を支えて、すぐに片づけた。", "explanation": "ここは〈整える〉の意味。「部屋を整えて」の整えるを支えに替えたもので、散らかった部屋を支えるとは言わない。"}, {"text": "ポスターを画びょうで壁に支えた。", "explanation": "ここは〈留める〉の意味。「ポスターを画びょうで壁に留めた」の留めを支えに替えたもので、画びょうで固定する動作は下から受けて落ちないようにする支えるとは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37600, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "支える", "is_correct": true, "explanation": "壁が弱いので板で支える必要があるという文脈に合い、定義に沿う。"}, {"text": "泳ぐ", "is_correct": false, "explanation": "板で泳ぐでは意味が通らず、支える動作ではない。"}, {"text": "踊る", "is_correct": false, "explanation": "板で踊る必要とは結びつかず、文が成り立たない。"}, {"text": "叫ぶ", "is_correct": false, "explanation": "板で叫ぶは成り立たず、支える行為と無関係。"}], "explanations": {"支える": "壁が弱いので板で支える必要があるという文脈に合い、定義に沿う。", "泳ぐ": "板で泳ぐでは意味が通らず、支える動作ではない。", "踊る": "板で踊る必要とは結びつかず、文が成り立たない。", "叫ぶ": "板で叫ぶは成り立たず、支える行為と無関係。"}, "sentence_index": 6, "correct_answer": "支える"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "子どもが転ばないように、父が床にマットを支えた。", "explanation": "ここは〈敷く〉の意味。「床にマットを敷いた」の敷くを支えに替えたもので、マットを床に支えるとは言わない。"}, {"text": "辛い時期に、友人の言葉が涙を支えてくれた。", "explanation": "ここは〈止める〉の意味。「涙を止めてくれた」の止めるを支えに替えたもので、涙を支えるとは言わない。"}, {"text": "お菓子を紙で支えた。", "explanation": "ここは〈包む〉の意味。「お菓子を紙で包んだ」の包むを支えに替えたもので、紙で覆う動作は下から受けて落ちないようにする支えるとは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37600, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "太い柱が古い橋に支えている。", "corrected_sentence": "太い柱が古い橋を支えている。", "error_description": "「支える」の対象は「を」で示す。「橋に」の「に」は誤りで、正しくは「橋を」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "支えた", "is_correct": true, "explanation": "過去形で、倒れないように木を支えた過去の動作と合う。"}, {"text": "支えて", "is_correct": false, "explanation": "て形は文末に置くと文が終わらず、完結した文が必要。"}, {"text": "支えながら", "is_correct": false, "explanation": "ながら形も文末に置けず、完結した文にならない。"}, {"text": "支えられ", "is_correct": false, "explanation": "語幹のままでは文が終わらず、完結しない。"}], "correct_form": "支えた", "base_form": "支える", "form_label": "過去形", "sentence_index": 1, "explanations": {"支えた": "過去形で、倒れないように木を支えた過去の動作と合う。", "支えて": "て形は文末に置くと文が終わらず、完結した文が必要。", "支えながら": "ながら形も文末に置けず、完結した文にならない。", "支えられ": "語幹のままでは文が終わらず、完結しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37600, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "崩れそうな崖が、鉄の杭が支えている。", "corrected_sentence": "崩れそうな崖を、鉄の杭が支えている。", "error_description": "「支える」の対象の「崖」には「を」を付ける。「崖が」は主語の形で、支えられる物を示せない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "支えながら", "is_correct": true, "explanation": "ながら形で、荷物を支えつつドアを開けるという同時の動作を表し、文と合う。"}, {"text": "支えられる", "is_correct": false, "explanation": "受身形になり、荷物が誰かに支えられるという意味になって文の動作と合わない。"}, {"text": "支えます", "is_correct": false, "explanation": "丁寧な終止形なので文が終わり、後のドアを開けたに続かない。"}, {"text": "支えている", "is_correct": false, "explanation": "継続の形で、同時にドアを開けたという流れと合わない。"}], "correct_form": "支えながら", "base_form": "支える", "form_label": "ながら形", "sentence_index": 7, "explanations": {"支えながら": "ながら形で、荷物を支えつつドアを開けるという同時の動作を表し、文と合う。", "支えられる": "受身形になり、荷物が誰かに支えられるという意味になって文の動作と合わない。", "支えます": "丁寧な終止形なので文が終わり、後のドアを開けたに続かない。", "支えている": "継続の形で、同時にドアを開けたという流れと合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
