INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37602, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "何かが二つの線の間でどれだけ開いているかを表す。「角度」は、開き具合のこと。", "primary_collocate": null, "pronunciation": "かくど", "ipa": "kakɯdo", "syllable_count": 3, "sentences": [{"text": "写真を撮るとき、カメラの角度を少し変えました。", "target_word": "角度", "complexity_tier": "T3", "furigana": "写真[しゃしん]を撮[と]るとき、カメラの角度[かくど]を少[すこ]し変[か]えました。", "sentence_source": "generated"}, {"text": "見る角度によって、この絵は違って見える。", "target_word": "角度", "complexity_tier": "T3", "furigana": "見[み]る角度[かくど]によって、この絵[え]は違[ちが]って見[み]える。", "sentence_source": "generated"}, {"text": "坂の角度が急なので、自転車では上れません。", "target_word": "角度", "complexity_tier": "T3", "furigana": "坂[さか]の角度[かくど]が急[きゅう]なので、自転車[じてんしゃ]では上[のぼ]れません。", "sentence_source": "generated"}, {"text": "ドアを開ける角度が小さいと、大きな荷物は通らない。", "target_word": "角度", "complexity_tier": "T3", "furigana": "ドアを開[あ]ける角度[かくど]が小[ちい]さいと、大[おお]きな荷物[にもつ]は通[とお]らない。", "sentence_source": "generated"}, {"text": "先生は、三角形の角度の求め方を説明した。", "target_word": "角度", "complexity_tier": "T3", "furigana": "先生[せんせい]は、三角形[さんかっけい]の角度[かくど]の求[もと]め方[かた]を説明[せつめい]した。", "sentence_source": "generated"}, {"text": "ノートに二本の線を引いて、その角度を測った。", "target_word": "角度", "complexity_tier": "T3", "furigana": "ノートに二[に]本[ほん]の線[せん]を引[ひ]いて、その角度[かくど]を測[はか]った。", "sentence_source": "generated"}, {"text": "鏡を置く角度を変えたら、光が壁に当たった。", "target_word": "角度", "complexity_tier": "T3", "furigana": "鏡[かがみ]を置[お]く角度[かくど]を変[か]えたら、光[ひかり]が壁[かべ]に当[あ]たった。", "sentence_source": "generated"}, {"text": "この椅子は、背もたれの角度を自由に調節できる。", "target_word": "角度", "complexity_tier": "T3", "furigana": "この椅子[いす]は、背[せ]もたれの角度[かくど]を自由[じゆう]に調節[ちょうせつ]できる。", "sentence_source": "generated"}, {"text": "屋根の角度が違うと、雪の落ち方も変わる。", "target_word": "角度", "complexity_tier": "T3", "furigana": "屋根[やね]の角度[かくど]が違[ちが]うと、雪[ゆき]の落[お]ち方[かた]も変[か]わる。", "sentence_source": "generated"}, {"text": "彼女は一番きれいに見える角度を知っていて、いつもそこから写真に写る。", "target_word": "角度", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は一番[いちばん]きれいに見[み]える角度[かくど]を知[し]っていて、いつもそこから写真[しゃしん]に写[うつ]る。", "sentence_source": "generated"}], "morphological_forms": [{"form": "角度", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "二つの線や面の間の開き具合、ものを見る向きや傾き", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4e5da86-1411-4fd5-9f5f-e54c321bb1e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37602, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "角度", "is_correct": true, "explanation": "「カメラの角度」は撮る向きや傾きのことで、「少し変えた」と合う。"}, {"text": "体重", "is_correct": false, "explanation": "人や動物の重さを表す語で、カメラの何を変えたかにはならない。"}, {"text": "年齢", "is_correct": false, "explanation": "人や物の年数を表す語で、カメラの調整には使えない。"}, {"text": "寿命", "is_correct": false, "explanation": "物が使える期間を表す語で、「変えた」対象にならない。"}], "explanations": {"角度": "「カメラの角度」は撮る向きや傾きのことで、「少し変えた」と合う。", "体重": "人や動物の重さを表す語で、カメラの何を変えたかにはならない。", "年齢": "人や物の年数を表す語で、カメラの調整には使えない。", "寿命": "物が使える期間を表す語で、「変えた」対象にならない。"}, "sentence_index": 0, "correct_answer": "角度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "駅までの角度は、歩いて十分ほどだ。", "explanation": "ここは〈どれだけ離れているか〉の意味。角度は二つの線の開き具合で、距離は表せない。"}, {"text": "新幹線の角度は、とても速い。", "explanation": "ここは〈動きの速さ〉の意味。角度は開き具合を表し、速さは表さない。"}, {"text": "井戸の角度は、十メートルもある。", "explanation": "ここは〈下までの長さ〉の意味。角度は開きの度合いで、深さは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37602, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "角度", "is_correct": true, "explanation": "「鏡を置く角度」は置き方の傾きを表し、「光が壁に当たった」と合う。"}, {"text": "味", "is_correct": false, "explanation": "食べ物の性質を表す語で、鏡の置き方には使えない。"}, {"text": "歌詞", "is_correct": false, "explanation": "歌の言葉を表す語で、鏡を置く場合には合わない。"}, {"text": "体温", "is_correct": false, "explanation": "人や動物の熱の度合いを表す語で、置き方とは関係ない。"}], "explanations": {"角度": "「鏡を置く角度」は置き方の傾きを表し、「光が壁に当たった」と合う。", "味": "食べ物の性質を表す語で、鏡の置き方には使えない。", "歌詞": "歌の言葉を表す語で、鏡を置く場合には合わない。", "体温": "人や動物の熱の度合いを表す語で、置き方とは関係ない。"}, "sentence_index": 6, "correct_answer": "角度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "机の角度に頭をぶつけた。", "explanation": "ここは〈物の尖った先〉の意味。角度は線や面の開きのことで、物の角は指さない。"}, {"text": "この部屋の角度は、十畳ほどだ。", "explanation": "ここは〈面積の大きさ〉の意味。角度は開き具合で、広さは表さない。"}, {"text": "この店の角度は、かなり大きい。", "explanation": "ここは〈音の大きさ〉の意味。角度は開き具合で、音量には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37602, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この板の角度に、少しずつ大きくしていく。", "corrected_sentence": "この板の角度を、少しずつ大きくしていく。", "error_description": "「大きくする」の対象は目的語になるので「を」。「に」は場所や方向の助詞で、「角度に大きくする」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37602, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この鏡角度を変えると、光が別の場所に当たる。", "corrected_sentence": "この鏡の角度を変えると、光が別の場所に当たる。", "error_description": "「鏡の角度」のように、名詞どうしは「の」でつなぐ。「の」がないと名詞が並んでしまい、文として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37604, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「階段の下で待つ」の「で」。待つ動作が行われる場所を示す。"}, {"text": "が", "is_correct": false, "explanation": "「階段の下が友達が」と主語が重なり、待っていた動作につながらない。"}, {"text": "を", "is_correct": false, "explanation": "「階段の下を待っていた」は成り立たず、待つ場所を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「階段の下より」は比較になり、友達が待っていた場所を示せない。"}], "correct_answer": "で", "explanations": {"で": "「階段の下で待つ」の「で」。待つ動作が行われる場所を示す。", "が": "「階段の下が友達が」と主語が重なり、待っていた動作につながらない。", "を": "「階段の下を待っていた」は成り立たず、待つ場所を示せない。", "より": "「階段の下より」は比較になり、友達が待っていた場所を示せない。"}, "error_tags": {"が": "主語", "を": "対象", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37604, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「ページの下に書いてある」の「に」。文字が書かれている位置を示す。"}, {"text": "で", "is_correct": false, "explanation": "「ページの下で書いてある」は動作の場所を示し、存在する位置の説明にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「ページの下へ書いてある」は方向を示し、書かれている位置の説明にならない。"}, {"text": "と", "is_correct": false, "explanation": "「ページの下と書いてある」は並列になり、名前がどこにあるかが分からない。"}], "correct_answer": "に", "explanations": {"に": "「ページの下に書いてある」の「に」。文字が書かれている位置を示す。", "で": "「ページの下で書いてある」は動作の場所を示し、存在する位置の説明にならない。", "へ": "「ページの下へ書いてある」は方向を示し、書かれている位置の説明にならない。", "と": "「ページの下と書いてある」は並列になり、名前がどこにあるかが分からない。"}, "error_tags": {"で": "動作の場所", "へ": "方向", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37604, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "もののいちばんひくいところ。", "primary_collocate": null, "pronunciation": "した", "ipa": "ɕita", "syllable_count": 2, "sentences": [{"text": "机の下に、ねこが入ってねている。", "target_word": "下", "complexity_tier": "T3", "furigana": "机[つくえ]の下[した]に、ねこが入[はい]ってねている。", "sentence_source": "generated"}, {"text": "階段の下で、友達が私を待っていた。", "target_word": "下", "complexity_tier": "T3", "furigana": "階段[かいだん]の下[した]で、友達[ともだち]が私[わたし]を待[ま]っていた。", "sentence_source": "generated"}, {"text": "木の下は日かげなので、夏でも涼しい。", "target_word": "下", "complexity_tier": "T3", "furigana": "木[き]の下[した]は日[ひ]かげなので、夏[なつ]でも涼[すず]しい。", "sentence_source": "generated"}, {"text": "箱の下にあった本は、水でぬれてしまった。", "target_word": "下", "complexity_tier": "T3", "furigana": "箱[はこ]の下[した]にあった本[ほん]は、水[みず]でぬれてしまった。", "sentence_source": "generated"}, {"text": "橋の下を、大きな川が静かに流れている。", "target_word": "下", "complexity_tier": "T3", "furigana": "橋[はし]の下[した]を、大[おお]きな川[かわ]が静[しず]かに流[なが]れている。", "sentence_source": "generated"}, {"text": "ベッドの下に落ちたペンを、手を伸ばしてひろった。", "target_word": "下", "complexity_tier": "T3", "furigana": "ベッドの下[した]に落[お]ちたペンを、手[て]を伸[の]ばしてひろった。", "sentence_source": "generated"}, {"text": "山の下は暑かったが、上に行くほど寒くなった。", "target_word": "下", "complexity_tier": "T3", "furigana": "山[やま]の下[した]は暑[あつ]かったが、上[うえ]に行[い]くほど寒[さむ]くなった。", "sentence_source": "generated"}, {"text": "ページの下に、小さな字で名前が書いてある。", "target_word": "下", "complexity_tier": "T3", "furigana": "ページの下[した]に、小[ちい]さな字[じ]で名前[なまえ]が書[か]いてある。", "sentence_source": "generated"}, {"text": "重い本を上に積んだので、一番下の本がつぶれた。", "target_word": "下", "complexity_tier": "T3", "furigana": "重[おも]い本[ほん]を上[うえ]に積[つ]んだので、一番下[いちばんした]の本[ほん]がつぶれた。", "sentence_source": "generated"}, {"text": "雨がふってきたので、みんな大きな屋根の下に走った。", "target_word": "下", "complexity_tier": "T3", "furigana": "雨[あめ]がふってきたので、みんな大[おお]きな屋根[やね]の下[した]に走[はし]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "下", "label": "基本形"}], "register": "neutral(普通体・標準語)", "sense_fingerprint": "ものの低い側・下の部分や下の場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T1: contains vocabulary far above tier T1: ひろっ (Zipf 2.25)']::text[], 'faa209c7-2535-420e-9dfa-d147d9c97da0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37604, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下", "is_correct": true, "explanation": "「机の下」で、机の低い側の場所を示す。ねこが入る位置として自然。"}, {"text": "音", "is_correct": false, "explanation": "「机の音に」では場所にならず、ねこが入る位置として成り立たない。"}, {"text": "魚", "is_correct": false, "explanation": "「机の魚に」は不自然で、ねこが入る場所を表せない。"}, {"text": "雨", "is_correct": false, "explanation": "「机の雨に」は場所にならず、ねこが入っている状況に合わない。"}], "explanations": {"下": "「机の下」で、机の低い側の場所を示す。ねこが入る位置として自然。", "音": "「机の音に」では場所にならず、ねこが入る位置として成り立たない。", "魚": "「机の魚に」は不自然で、ねこが入る場所を表せない。", "雨": "「机の雨に」は場所にならず、ねこが入っている状況に合わない。"}, "sentence_index": 0, "correct_answer": "下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の下で三年間、修行を重ねた。", "explanation": "ここは〈指導のもと〉の意味。人の指導や支配のもとにいることは「の下で」と言い、ものの低い所を指す語義では説明できないので合わない。"}, {"text": "借金の下で、毎月の生活が苦しくなった。", "explanation": "ここは〈圧迫のもと〉の意味。重い負担のもとにあることは「の下で」と言い、低い所を指す語義とは別なので合わない。"}, {"text": "この流行は、最近すっかり下になった。", "explanation": "ここは〈下火〉の意味。勢いが衰えることは下火と言い、「下」だけでは流行の衰退を表せないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37604, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下", "is_correct": true, "explanation": "「山の下」で、山のふもとの低い場所を示す。上と対比される場所として自然。"}, {"text": "色", "is_correct": false, "explanation": "「山の色は暑かった」は成り立たず、場所を示せない。"}, {"text": "声", "is_correct": false, "explanation": "「山の声は暑かった」は不自然で、場所の名詞として合わない。"}, {"text": "本", "is_correct": false, "explanation": "「山の本は暑かった」は意味が通らず、場所を示せない。"}], "explanations": {"下": "「山の下」で、山のふもとの低い場所を示す。上と対比される場所として自然。", "色": "「山の色は暑かった」は成り立たず、場所を示せない。", "声": "「山の声は暑かった」は不自然で、場所の名詞として合わない。", "本": "「山の本は暑かった」は意味が通らず、場所を示せない。"}, "sentence_index": 6, "correct_answer": "下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "手紙は先に下を書いてから、ていねいに清書した。", "explanation": "ここは〈下書き〉の意味。文章の草稿は下書きと言い、下は物の低い所を指すので合わない。"}, {"text": "今月の下に、新しい店がオープンする予定だ。", "explanation": "ここは〈下旬〉の意味。月の終わりの十日間は下旬と言い、下は物の低い所を指すので合わない。"}, {"text": "彼は親切を装いながら、下を隠していた。", "explanation": "ここは〈下心〉の意味。隠された本当の意図は下心と言い、「下」だけではその意味を表せないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37604, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ベンチの下で、ボールが落ちている。", "corrected_sentence": "ベンチの下に、ボールが落ちている。", "error_description": "「落ちている」は物の存在する場所を「に」で示す。「で」は動作の場所に使うので誤り。「下に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37604, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "机の下は暗くので、懐中電灯で照らした。", "corrected_sentence": "机の下は暗いので、懐中電灯で照らした。", "error_description": "「暗い」を「暗くので」と誤っている。理由を表す「ので」の前は「暗いので」の形にする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
