INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37606, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「差を計算して」の「を」。差を計算の対象として示す目的語の助詞。"}, {"text": "が", "is_correct": false, "explanation": "「時間の差が計算して」は差を計算する主体のように読め、文の骨組みが成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「時間の差に計算して」は差が計算の相手や場所にならず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「時間の差へ計算して」は方向を示すが、計算は方向に向かう動作ではないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「差を計算して」の「を」。差を計算の対象として示す目的語の助詞。", "が": "「時間の差が計算して」は差を計算する主体のように読め、文の骨組みが成り立たない。", "に": "「時間の差に計算して」は差が計算の相手や場所にならず、文が成り立たない。", "へ": "「時間の差へ計算して」は方向を示すが、計算は方向に向かう動作ではないので合わない。"}, "error_tags": {"が": "主語", "に": "相手", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37606, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "二つのものの間にあって、ちがっているところ。", "primary_collocate": null, "pronunciation": "さ", "ipa": "sa", "syllable_count": 1, "sentences": [{"text": "兄と私は三つ年がはなれているが、背の差はほとんどない。", "target_word": "差", "complexity_tier": "T3", "furigana": "兄[あに]と私[わたし]は三[みっ]つ年[とし]がはなれているが、背[せ]の差[さ]はほとんどない。", "sentence_source": "generated"}, {"text": "二つのチームの点数の差は、たった一点だった。", "target_word": "差", "complexity_tier": "T3", "furigana": "二[ふた]つのチームの点数[てんすう]の差[さ]は、たった一点[いってん]だった。", "sentence_source": "generated"}, {"text": "朝と夜の気温の差が大きいので、上着が必要だ。", "target_word": "差", "complexity_tier": "T3", "furigana": "朝[あさ]と夜[よる]の気温[きおん]の差[さ]が大[おお]きいので、上着[うわぎ]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "二つの箱を持ち比べても、重さの差は分からなかった。", "target_word": "差", "complexity_tier": "T3", "furigana": "二[ふた]つの箱[はこ]を持[も]ち比[くら]べても、重[おも]さの差[さ]は分[わ]からなかった。", "sentence_source": "generated"}, {"text": "この二つの色は、よく見ると明るさに少し差がある。", "target_word": "差", "complexity_tier": "T3", "furigana": "この二[ふた]つの色[いろ]は、よく見[み]ると明[あか]るさに少[すこ]し差[さ]がある。", "sentence_source": "generated"}, {"text": "一位と二位の差は、わずか〇・一秒だった。", "target_word": "差", "complexity_tier": "T3", "furigana": "一位[いちい]と二位[にい]の差[さ]は、わずか〇・一秒[れいてんいちびょう]だった。", "sentence_source": "generated"}, {"text": "値段の差を考えて、安いほうの店で買うことにした。", "target_word": "差", "complexity_tier": "T3", "furigana": "値段[ねだん]の差[さ]を考[かんが]えて、安[やす]いほうの店[みせ]で買[か]うことにした。", "sentence_source": "generated"}, {"text": "日本と外国の時間の差を計算して、電話をかけた。", "target_word": "差", "complexity_tier": "T3", "furigana": "日本[にほん]と外国[がいこく]の時間[じかん]の差[さ]を計算[けいさん]して、電話[でんわ]をかけた。", "sentence_source": "generated"}, {"text": "双子でも、性格に差があることは多い。", "target_word": "差", "complexity_tier": "T3", "furigana": "双子[ふたご]でも、性格[せいかく]に差[さ]があることは多[おお]い。", "sentence_source": "generated"}, {"text": "去年と今年の売り上げの差を、表にまとめた。", "target_word": "差", "complexity_tier": "T3", "furigana": "去年[きょねん]と今年[ことし]の売[う]り上[あ]げの差[さ]を、表[ひょう]にまとめた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "差", "label": "基本形"}], "register": "neutral(普通体・標準語)", "sense_fingerprint": "二つのものを比べたときの数や量のちがい", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faa209c7-2535-420e-9dfa-d147d9c97da0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37606, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "差", "is_correct": true, "explanation": "「背の差はほとんどない」で、身長のちがいを表す。文の意味が通る唯一の語。"}, {"text": "味", "is_correct": false, "explanation": "「背の味はほとんどない」は意味が通らず、身長の違いを表せない。"}, {"text": "理由", "is_correct": false, "explanation": "「背の理由はほとんどない」は不自然で、身長の比較の文に合わない。"}, {"text": "形", "is_correct": false, "explanation": "「背の形はほとんどない」は身長の違いを表さず、文脈に合わない。"}], "explanations": {"差": "「背の差はほとんどない」で、身長のちがいを表す。文の意味が通る唯一の語。", "味": "「背の味はほとんどない」は意味が通らず、身長の違いを表せない。", "理由": "「背の理由はほとんどない」は不自然で、身長の比較の文に合わない。", "形": "「背の形はほとんどない」は身長の違いを表さず、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "差"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "駅までの差が遠いので、毎朝バスに乗っている。", "explanation": "ここは〈距離〉の意味。道のりの遠さは距離と言い、差は二つのものの量や状態のちがいを指すので合わない。"}, {"text": "全体の売り上げに占める差が、今年は三割だった。", "explanation": "ここは〈割合〉の意味。全体に対する部分の比率は割合と言い、差は比べた結果の違いなので合わない。"}, {"text": "この店は駅の差が近いので、よく利用する。", "explanation": "ここは〈位置〉の意味。場所の関係は位置と言い、差は二つのものの違いを指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37606, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "差", "is_correct": true, "explanation": "「値段の差を考えて」で、二つの店の値段のちがいを表す。文の意味が通る唯一の語。"}, {"text": "音", "is_correct": false, "explanation": "「値段の音を考えて」は意味が通らず、比べる対象として合わない。"}, {"text": "色", "is_correct": false, "explanation": "「値段の色を考えて」は不自然で、値段の比較の文に合わない。"}, {"text": "声", "is_correct": false, "explanation": "「値段の声を考えて」は意味が通らず、値段の違いを表せない。"}], "explanations": {"差": "「値段の差を考えて」で、二つの店の値段のちがいを表す。文の意味が通る唯一の語。", "音": "「値段の音を考えて」は意味が通らず、比べる対象として合わない。", "色": "「値段の色を考えて」は不自然で、値段の比較の文に合わない。", "声": "「値段の声を考えて」は意味が通らず、値段の違いを表せない。"}, "sentence_index": 6, "correct_answer": "差"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "去年と今年の売り上げの差を合わせると、千万円になった。", "explanation": "ここは〈合計〉の意味。全部を足した数は合計と言い、差は引いた違いを指すので合わない。"}, {"text": "届いた封筒の裏には、差の名前だけが書いてあった。", "explanation": "ここは〈差出人〉の意味。手紙や荷物の送り主は差出人と言い、差だけでは表せないので合わない。"}, {"text": "部活の仲間に、お菓子の差を持っていった。", "explanation": "ここは〈差し入れ〉の意味。応援や見舞いの品は差し入れと言い、差は違いを指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37606, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹は足の速さの差に感じて、毎日走る練習をしている。", "corrected_sentence": "妹は足の速さの差を感じて、毎日走る練習をしている。", "error_description": "「感じる」の対象は「を」で示す。「差に」は誤りで、「差を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37606, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "男子と女子の成績の差が大きくので、原因を調べることにした。", "corrected_sentence": "男子と女子の成績の差が大きいので、原因を調べることにした。", "error_description": "「大きい」を「大きくので」と誤っている。理由を表す「ので」の前は「大きいので」の形にする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37607, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「実力の差」の「の」。名詞と名詞をつなぎ、何の差かを示す。"}, {"text": "が", "is_correct": false, "explanation": "「実力が差を感じて」と主語が重なり、感じる対象が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「実力を差を感じて」と目的語が重なり、文の意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「実力へ差を感じて」は方向を示し、感じる対象として不自然。"}], "correct_answer": "の", "explanations": {"の": "「実力の差」の「の」。名詞と名詞をつなぎ、何の差かを示す。", "が": "「実力が差を感じて」と主語が重なり、感じる対象が成り立たない。", "を": "「実力を差を感じて」と目的語が重なり、文の意味が通らない。", "へ": "「実力へ差を感じて」は方向を示し、感じる対象として不自然。"}, "error_tags": {"が": "主語", "を": "目的語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37607, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「勝ち負けの差」の「の」。名詞と名詞をつなぎ、何の差かを示す。"}, {"text": "を", "is_correct": false, "explanation": "「勝ち負けを差は小さくても」は目的語の位置に「を」を置けず、文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「勝ち負けから差」は起点になり、差の所在を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「勝ち負けより差」は比較になり、文の意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「勝ち負けの差」の「の」。名詞と名詞をつなぎ、何の差かを示す。", "を": "「勝ち負けを差は小さくても」は目的語の位置に「を」を置けず、文が成り立たない。", "から": "「勝ち負けから差」は起点になり、差の所在を示せない。", "より": "「勝ち負けより差」は比較になり、文の意味が通らない。"}, "error_tags": {"を": "目的語", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37607, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "二つの物事の間に見られる、異なる点や隔たり。", "primary_collocate": null, "pronunciation": "さ", "ipa": "sa", "syllable_count": 1, "sentences": [{"text": "貧しい人と豊かな人の差が、年々広がっている。", "target_word": "差", "complexity_tier": "T3", "furigana": "貧[まず]しい人[ひと]と豊[ゆた]かな人[ひと]の差[さ]が、年々[ねんねん]広[ひろ]がっている。", "sentence_source": "generated"}, {"text": "実力の差を感じて、彼はもっと練習しようと決めた。", "target_word": "差", "complexity_tier": "T3", "furigana": "実力[じつりょく]の差[さ]を感[かん]じて、彼[かれ]はもっと練習[れんしゅう]しようと決[き]めた。", "sentence_source": "generated"}, {"text": "男女の差をなくすために、会社は制度を見直した。", "target_word": "差", "complexity_tier": "T3", "furigana": "男女[だんじょ]の差[さ]をなくすために、会社[かいしゃ]は制度[せいど]を見直[みなお]した。", "sentence_source": "generated"}, {"text": "都市と田舎の差は、昔ほど大きくない。", "target_word": "差", "complexity_tier": "T3", "furigana": "都市[とし]と田舎[いなか]の差[さ]は、昔[むかし]ほど大[おお]きくない。", "sentence_source": "generated"}, {"text": "育った環境の差が、二人の考え方のちがいを生んだ。", "target_word": "差", "complexity_tier": "T3", "furigana": "育[そだ]った環境[かんきょう]の差[さ]が、二人[ふたり]の考[かんが]え方[かた]のちがいを生[う]んだ。", "sentence_source": "generated"}, {"text": "経験の差はあるが、新人も熱心に仕事を覚えている。", "target_word": "差", "complexity_tier": "T3", "furigana": "経験[けいけん]の差[さ]はあるが、新人[しんじん]も熱心[ねっしん]に仕事[しごと]を覚[おぼ]えている。", "sentence_source": "generated"}, {"text": "地域によって、教育の差が出ないようにしたい。", "target_word": "差", "complexity_tier": "T3", "furigana": "地域[ちいき]によって、教育[きょういく]の差[さ]が出[で]ないようにしたい。", "sentence_source": "generated"}, {"text": "勝ち負けの差は小さくても、本人にとっては大きな悔しさだ。", "target_word": "差", "complexity_tier": "T3", "furigana": "勝[か]ち負[ま]けの差[さ]は小[ちい]さくても、本人[ほんにん]にとっては大[おお]きな悔[くや]しさだ。", "sentence_source": "generated"}, {"text": "努力した人としなかった人では、結果に差が出る。", "target_word": "差", "complexity_tier": "T3", "furigana": "努力[どりょく]した人[ひと]としなかった人[ひと]では、結果[けっか]に差[さ]が出[で]る。", "sentence_source": "generated"}, {"text": "世代の差を感じる場面でも、祖父はいつも笑って話を聞いてくれる。", "target_word": "差", "complexity_tier": "T3", "furigana": "世代[せだい]の差[さ]を感[かん]じる場面[ばめん]でも、祖父[そふ]はいつも笑[わら]って話[はなし]を聞[き]いてくれる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "差", "label": "基本形"}], "register": "neutral(普通体・標準語)", "sense_fingerprint": "人や物事の間にある格差・隔たり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faa209c7-2535-420e-9dfa-d147d9c97da0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37607, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "差", "is_correct": true, "explanation": "「貧しい人と豊かな人の差」として、社会の隔たりが広がる文の主語になる。"}, {"text": "順番", "is_correct": false, "explanation": "「順番が年々広がっている」は意味が通らず、隔たりを表せない。"}, {"text": "理由", "is_correct": false, "explanation": "「理由が年々広がっている」は不自然で、隔たりの拡大の文に合わない。"}, {"text": "天気", "is_correct": false, "explanation": "「天気が年々広がっている」は意味が通らず、人の間の隔たりを表せない。"}], "explanations": {"差": "「貧しい人と豊かな人の差」として、社会の隔たりが広がる文の主語になる。", "順番": "「順番が年々広がっている」は意味が通らず、隔たりを表せない。", "理由": "「理由が年々広がっている」は不自然で、隔たりの拡大の文に合わない。", "天気": "「天気が年々広がっている」は意味が通らず、人の間の隔たりを表せない。"}, "sentence_index": 0, "correct_answer": "差"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "荷物の箱に、差の名前が書いてあった。", "explanation": "ここは〈差出人〉の意味。荷物や手紙を送った人は差出人と言い、差だけでは送り主を表せないので合わない。"}, {"text": "都市と田舎の差を地図で計ると、十キロあった。", "explanation": "ここは〈距離〉の意味。地図上の長さは距離と言い、社会の格差は計るものではないので合わない。"}, {"text": "住民は工事の差を求めて、裁判を起こした。", "explanation": "ここは〈差し止め〉の意味。行為をやめさせるよう求めることは差し止めと言い、差は違いや隔たりを表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37607, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "差", "is_correct": true, "explanation": "「教育の差が出ないように」として、地域による格差を表す。文の意味が通る唯一の語。"}, {"text": "音", "is_correct": false, "explanation": "「教育の音が出ないように」は意味が通らず、格差の文に合わない。"}, {"text": "汗", "is_correct": false, "explanation": "「教育の汗が出ないように」は意味が通らず、格差を表せない。"}, {"text": "煙", "is_correct": false, "explanation": "「教育の煙が出ないように」は意味が通らず、教育の不公平を表せない。"}], "explanations": {"差": "「教育の差が出ないように」として、地域による格差を表す。文の意味が通る唯一の語。", "音": "「教育の音が出ないように」は意味が通らず、格差の文に合わない。", "汗": "「教育の汗が出ないように」は意味が通らず、格差を表せない。", "煙": "「教育の煙が出ないように」は意味が通らず、教育の不公平を表せない。"}, "sentence_index": 6, "correct_answer": "差"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "玄関の差に気をつけて、ゆっくり歩いてください。", "explanation": "ここは〈段差〉の意味。床の高低の差は段差と言い、社会の格差には使わないので合わない。"}, {"text": "祖父と私の世代の差を合わせると、ちょうど百歳になる。", "explanation": "ここは〈合計〉の意味。足し合わせた数は合計と言い、世代の隔たりを表す格差とは別なので合わない。"}, {"text": "祖父の病院に、果物の差を届けた。", "explanation": "ここは〈差し入れ〉の意味。見舞いの品物は差し入れと言い、格差の意味では使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37607, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "貧しい地域の子どもたちは、教育の差を苦しんでいる。", "corrected_sentence": "貧しい地域の子どもたちは、教育の差に苦しんでいる。", "error_description": "「苦しむ」は苦しみの原因を「に」で示す。「差を」は誤りで、「差に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37607, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "都市部と地方の所得の差が大きくので、支援を増やした。", "corrected_sentence": "都市部と地方の所得の差が大きいので、支援を増やした。", "error_description": "「大きい」を「大きくので」と誤っている。理由を表す「ので」の前は「大きいので」の形にする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c242d37f-f04a-42f0-af25-e3df121c4c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37608, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「下から」で、押す動作の起点（下の方向）を示す。"}, {"text": "を", "is_correct": false, "explanation": "「蓋を下を押して」と目的語が重なり、文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「下と押して」は並列を表し、動詞を方向づけられず、文が成立しない。"}, {"text": "の", "is_correct": false, "explanation": "「蓋の下押して」と名詞を続けるだけで、動詞に正しくかからない。"}], "correct_answer": "から", "explanations": {"から": "「下から」で、押す動作の起点（下の方向）を示す。", "を": "「蓋を下を押して」と目的語が重なり、文として成り立たない。", "と": "「下と押して」は並列を表し、動詞を方向づけられず、文が成立しない。", "の": "「蓋の下押して」と名詞を続けるだけで、動詞に正しくかからない。"}, "error_tags": {"を": "object marker", "の": "possessive", "と": "companion or quotation"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37608, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「下から押し続けた」で、押す動作の起点を示す。"}, {"text": "が", "is_correct": false, "explanation": "「下が押し続けた」では下が主語になり、人が押す文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「下と押し続けた」は引用や並列を表し、動詞を修飾できない。"}, {"text": "の", "is_correct": false, "explanation": "「下の押し続けた」は名詞修飾で、動詞の文が成立しない。"}], "correct_answer": "から", "explanations": {"から": "「下から押し続けた」で、押す動作の起点を示す。", "が": "「下が押し続けた」では下が主語になり、人が押す文として成り立たない。", "と": "「下と押し続けた」は引用や並列を表し、動詞を修飾できない。", "の": "「下の押し続けた」は名詞修飾で、動詞の文が成立しない。"}, "error_tags": {"が": "subject", "と": "quotation or companion", "の": "possessive"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37608, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものを、手で下から上に働きかける。", "primary_collocate": null, "pronunciation": "おす", "ipa": "osɯ", "syllable_count": 2, "sentences": [{"text": "兄は重い箱を下から押して、棚の上にのせた。", "target_word": "押して", "complexity_tier": "T3", "furigana": "兄[あに]は重[おも]い箱[はこ]を下[した]から押[お]して、棚[たな]の上[うえ]にのせた。", "sentence_source": "generated"}, {"text": "父は重いマンホールの蓋を下から押して、少しずつ持ち上げた。", "target_word": "押して", "complexity_tier": "T3", "furigana": "父[ちち]は重[おも]いマンホールの蓋[ふた]を下[した]から押[お]して、少[すこ]しずつ持[も]ち上[あ]げた。", "sentence_source": "generated"}, {"text": "天井の板を下から押すと、少し持ち上がった。", "target_word": "押す", "complexity_tier": "T3", "furigana": "天井[てんじょう]の板[いた]を下[した]から押[お]すと、少[すこ]し持[も]ち上[あ]がった。", "sentence_source": "generated"}, {"text": "手のひらでふたを下から押すと、ぱっと開いた。", "target_word": "押す", "complexity_tier": "T3", "furigana": "手[て]のひらでふたを下[した]から押[お]すと、ぱっと開[ひら]いた。", "sentence_source": "generated"}, {"text": "先生は生徒の腕を下から押して、手を高く上げさせた。", "target_word": "押して", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]の腕[うで]を下[した]から押[お]して、手[て]を高[たか]く上[あ]げさせた。", "sentence_source": "generated"}, {"text": "窓が固くて、下から押しても上がらなかった。", "target_word": "押しても", "complexity_tier": "T3", "furigana": "窓[まど]が固[かた]くて、下[した]から押[お]しても上[あ]がらなかった。", "sentence_source": "generated"}, {"text": "天井裏の点検口は、下から押すと外れる。", "target_word": "押す", "complexity_tier": "T3", "furigana": "天井裏[てんじょううら]の点検口[てんけんこう]は、下[した]から押[お]すと外[はず]れる。", "sentence_source": "generated"}, {"text": "風船が落ちないように、手で下から押し続けた。", "target_word": "押し続けた", "complexity_tier": "T3", "furigana": "風船[ふうせん]が落[お]ちないように、手[て]で下[した]から押[お]し続[つづ]けた。", "sentence_source": "generated"}, {"text": "巣箱のふたを下から押したが、びくともしなかった。", "target_word": "押した", "complexity_tier": "T3", "furigana": "巣箱[すばこ]のふたを下[した]から押[お]したが、びくともしなかった。", "sentence_source": "generated"}, {"text": "彼女は荷物を下から押して、網棚の奥に入れた。", "target_word": "押して", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は荷物[にもつ]を下[した]から押[お]して、網棚[あみだな]の奥[おく]に入[い]れた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "押さない", "label": "否定形"}, {"form": "押します", "label": "丁寧形"}, {"form": "押して", "label": "て形"}, {"form": "押した", "label": "た形"}, {"form": "押せば", "label": "仮定形"}, {"form": "押される", "label": "受身形"}], "register": "中立（常体）", "sense_fingerprint": "手で物を下から上へ押し上げるように力を加える", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0e12dd3-c77b-4d9e-9498-0161804d2652') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37608, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "押して", "is_correct": true, "explanation": "「下から押して」は下から力を加えて持ち上げる動作で、「棚の上にのせた」と続く。"}, {"text": "食べて", "is_correct": false, "explanation": "箱を下から食べるという意味になり、文脈と合わない。"}, {"text": "乗って", "is_correct": false, "explanation": "箱の下から乗るのは不自然で、持ち上げる動作と合わない。"}, {"text": "笑って", "is_correct": false, "explanation": "箱を笑っても棚にのせる動作にならず、意味が通らない。"}], "explanations": {"押して": "「下から押して」は下から力を加えて持ち上げる動作で、「棚の上にのせた」と続く。", "食べて": "箱を下から食べるという意味になり、文脈と合わない。", "乗って": "箱の下から乗るのは不自然で、持ち上げる動作と合わない。", "笑って": "箱を笑っても棚にのせる動作にならず、意味が通らない。"}, "sentence_index": 0, "correct_answer": "押して"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は新しい案を会議で押して、全員に採用させた。", "explanation": "ここは〈推す〉（すすめる）の意味。〈押す〉は物に手で力を加える意味で、案を人に勧める場面には合わない。"}, {"text": "彼は怒りを押して、冷静に話した。", "explanation": "ここは〈押さえる〉（感情を抑える）の意味。〈押す〉は物に力を加える意味で、感情には使わない。"}, {"text": "書類に判を押して、提出した。", "explanation": "ここは〈捺印する〉（判を付ける）の意味。〈押す〉の下から上へ力を加える意味とは別。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37608, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "押す", "is_correct": true, "explanation": "「下から押すと外れる」は下から力を加えると外れるという意味で、文脈に合う。"}, {"text": "眺める", "is_correct": false, "explanation": "下から眺めても外れる動作にはならず、意味が通らない。"}, {"text": "寝る", "is_correct": false, "explanation": "下から寝ると外れるという文は意味をなさない。"}, {"text": "噛む", "is_correct": false, "explanation": "点検口を下から噛むと外れるという内容は不自然で、文脈に合わない。"}], "explanations": {"押す": "「下から押すと外れる」は下から力を加えると外れるという意味で、文脈に合う。", "眺める": "下から眺めても外れる動作にはならず、意味が通らない。", "寝る": "下から寝ると外れるという文は意味をなさない。", "噛む": "点検口を下から噛むと外れるという内容は不自然で、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "押す"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ふたを手前に押して、ぱっと開いた。", "explanation": "向きが違う（手前へ押す）。定義の「下から上へ」とは合わない。"}, {"text": "彼女は初対面の人を押して、すぐに打ち解けた。", "explanation": "ここは〈打ち解ける〉（親しくなる）の意味。〈押す〉は物や相手に力を加える動作で、親しくなる過程には使わない。"}, {"text": "帳簿に判を押して、確認を終えた。", "explanation": "ここは〈捺印する〉（判を付ける）の意味。〈押す〉の下から上へ力を加える意味とは別。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37608, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "木箱のふたを下を押すと、ぱっと開いた。", "corrected_sentence": "木箱のふたを下から押すと、ぱっと開いた。", "error_description": "正しくは「下から押す」（起点の「から」）。「下を押す」は「下」を直接の対象にしてしまい、不自然。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "押して", "is_correct": true, "explanation": "て形。「押して、持ち上げた」と動作を順に並べている。"}, {"text": "押さ", "is_correct": false, "explanation": "未然形。「て」に直接つながらず、文が成立しない。"}, {"text": "押せ", "is_correct": false, "explanation": "命令形。過去の動作を述べる文では使えない。"}, {"text": "押される", "is_correct": false, "explanation": "受身形。動作の主体が父ではなく蓋になり、文の意味が変わる。"}], "correct_form": "押して", "base_form": "押す", "form_label": "て形", "sentence_index": 1, "explanations": {"押して": "て形。「押して、持ち上げた」と動作を順に並べている。", "押さ": "未然形。「て」に直接つながらず、文が成立しない。", "押せ": "命令形。過去の動作を述べる文では使えない。", "押される": "受身形。動作の主体が父ではなく蓋になり、文の意味が変わる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37608, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "物置の戸を下を押して、ぱっと開いた。", "corrected_sentence": "物置の戸を下から押して、ぱっと開いた。", "error_description": "正しくは「下から押して」（起点の「から」）。「下を押して」は「下」を直接の対象にしてしまい、不自然。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "押し続けた", "is_correct": true, "explanation": "た形。過去の継続した動作を述べ、「落ちないように」の文脈に合う。"}, {"text": "押し続け", "is_correct": false, "explanation": "連用形。文末に置けず、文が成立しない。"}, {"text": "押し続けたり", "is_correct": false, "explanation": "「たり」の形。文末では完結せず、文が成立しない。"}, {"text": "押し続けられ", "is_correct": false, "explanation": "連用形。文末に置けず、文が成立しない。"}], "correct_form": "押し続けた", "base_form": "押し続ける", "form_label": "た形", "sentence_index": 7, "explanations": {"押し続けた": "た形。過去の継続した動作を述べ、「落ちないように」の文脈に合う。", "押し続け": "連用形。文末に置けず、文が成立しない。", "押し続けたり": "「たり」の形。文末では完結せず、文が成立しない。", "押し続けられ": "連用形。文末に置けず、文が成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37609, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「押さないと」で、押さないことを条件として示す。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は「押さないへ」と続かず、文が成立しない。"}, {"text": "を", "is_correct": false, "explanation": "「押さないを開かない」は目的語を示せず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「押さないに開かない」は接続が成立せず、不自然。"}], "correct_answer": "と", "explanations": {"と": "「押さないと」で、押さないことを条件として示す。", "へ": "方向を表す「へ」は「押さないへ」と続かず、文が成立しない。", "を": "「押さないを開かない」は目的語を示せず、文が成り立たない。", "に": "「押さないに開かない」は接続が成立せず、不自然。"}, "error_tags": {"を": "object marker", "に": "direction or target", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "引く", "is_correct": true, "explanation": "「押す」の対義語。押す向きに対して引く向きを表す。"}, {"text": "叩く", "is_correct": false, "explanation": "打つ動作を表し、押すの対義語ではない。"}, {"text": "撫でる", "is_correct": false, "explanation": "軽く触れる動作を表し、押すの対義語ではない。"}, {"text": "触る", "is_correct": false, "explanation": "接触を表すが、押すの対義語ではない。"}], "correct_answer": "引く", "explanations": {"引く": "「押す」の対義語。押す向きに対して引く向きを表す。", "叩く": "打つ動作を表し、押すの対義語ではない。", "撫でる": "軽く触れる動作を表し、押すの対義語ではない。", "触る": "接触を表すが、押すの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37609, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「後ろから押した」で、押す動作の起点（後方）を示す。"}, {"text": "と", "is_correct": false, "explanation": "「後ろと押した」は引用や並列を表し、動詞を修飾できない。"}, {"text": "の", "is_correct": false, "explanation": "「後ろの押した」は名詞修飾で、動詞の文が成立しない。"}, {"text": "が", "is_correct": false, "explanation": "「後ろが押した」は主語を示すが、車を押す文の主語にならず、不自然。"}], "correct_answer": "から", "explanations": {"から": "「後ろから押した」で、押す動作の起点（後方）を示す。", "と": "「後ろと押した」は引用や並列を表し、動詞を修飾できない。", "の": "「後ろの押した」は名詞修飾で、動詞の文が成立しない。", "が": "「後ろが押した」は主語を示すが、車を押す文の主語にならず、不自然。"}, "error_tags": {"と": "quotation or companion", "の": "possessive", "が": "subject"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "引く", "is_correct": true, "explanation": "「押す」の対義語。ふすまを押す向きに対して、引く向きを表す。"}, {"text": "蹴る", "is_correct": false, "explanation": "足で強く打つ動作で、押すの対義語ではない。"}, {"text": "握る", "is_correct": false, "explanation": "手で掴む動作で、押すの対義語ではない。"}, {"text": "掴む", "is_correct": false, "explanation": "しっかり持つ動作で、押すの対義語ではない。"}], "correct_answer": "引く", "explanations": {"引く": "「押す」の対義語。ふすまを押す向きに対して、引く向きを表す。", "蹴る": "足で強く打つ動作で、押すの対義語ではない。", "握る": "手で掴む動作で、押すの対義語ではない。", "掴む": "しっかり持つ動作で、押すの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37609, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物の表面に手や指を当てて、前や後ろ、上や下などに力を加える。", "primary_collocate": null, "pronunciation": "おす", "ipa": "osɯ", "syllable_count": 2, "sentences": [{"text": "エレベーターのボタンを押すと、すぐにドアが開いた。", "target_word": "押す", "complexity_tier": "T3", "furigana": "エレベーターのボタンを押[お]すと、すぐにドアが開[あ]いた。", "sentence_source": "generated"}, {"text": "重いドアは、体全体で押さないと開かない。", "target_word": "押さ", "complexity_tier": "T3", "furigana": "重[おも]いドアは、体全体[からだぜんたい]で押[お]さないと開[あ]かない。", "sentence_source": "generated"}, {"text": "蓋を手で強く押して、瓶をしっかり閉めた。", "target_word": "押して", "complexity_tier": "T3", "furigana": "蓋[ふた]を手[て]で強[つよ]く押[お]して、瓶[びん]をしっかり閉[し]めた。", "sentence_source": "generated"}, {"text": "ベルを押したのに、だれも出てこなかった。", "target_word": "押した", "complexity_tier": "T3", "furigana": "ベルを押[お]したのに、だれも出[で]てこなかった。", "sentence_source": "generated"}, {"text": "後ろから背中を押されて、前に進んだ。", "target_word": "押されて", "complexity_tier": "T3", "furigana": "後[うし]ろから背中[せなか]を押[お]されて、前[まえ]に進[すす]んだ。", "sentence_source": "generated"}, {"text": "スマホの画面を指で強く押すと、メニューが出る。", "target_word": "押す", "complexity_tier": "T3", "furigana": "スマホの画面[がめん]を指[ゆび]で強[つよ]く押[お]すと、メニューが出[で]る。", "sentence_source": "generated"}, {"text": "荷物を乗せたカートを押して、店の中を歩いた。", "target_word": "押して", "complexity_tier": "T3", "furigana": "荷物[にもつ]を乗[の]せたカートを押[お]して、店[みせ]の中[なか]を歩[ある]いた。", "sentence_source": "generated"}, {"text": "故障した車を、みんなで後ろから押した。", "target_word": "押した", "complexity_tier": "T3", "furigana": "故障[こしょう]した車[くるま]を、みんなで後[うし]ろから押[お]した。", "sentence_source": "generated"}, {"text": "キーボードのエンターキーを押してください。", "target_word": "押して", "complexity_tier": "T3", "furigana": "キーボードのエンターキーを押[お]してください。", "sentence_source": "generated"}, {"text": "ふすまを横に押すと、静かに開いた。", "target_word": "押す", "complexity_tier": "T3", "furigana": "ふすまを横[よこ]に押[お]すと、静[しず]かに開[ひら]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "押さない", "label": "否定形"}, {"form": "押します", "label": "丁寧形"}, {"form": "押して", "label": "て形"}, {"form": "押した", "label": "た形"}, {"form": "押せば", "label": "仮定形"}, {"form": "押される", "label": "受身形"}], "register": "中立（常体）", "sense_fingerprint": "手や指を物の表面に当てて力を加え、動かしたり作動させたりする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0e12dd3-c77b-4d9e-9498-0161804d2652') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37609, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "押す", "is_correct": true, "explanation": "「ボタンを押すと、ドアが開いた」は指で押して操作する意味で、文脈に合う。"}, {"text": "眺める", "is_correct": false, "explanation": "ボタンを眺めてもドアは開かず、意味が通らない。"}, {"text": "閉める", "is_correct": false, "explanation": "ボタンを閉めるという組み合わせは不自然で、操作の文脈に合わない。"}, {"text": "食べる", "is_correct": false, "explanation": "ボタンを食べるという文は意味をなさない。"}], "explanations": {"押す": "「ボタンを押すと、ドアが開いた」は指で押して操作する意味で、文脈に合う。", "眺める": "ボタンを眺めてもドアは開かず、意味が通らない。", "閉める": "ボタンを閉めるという組み合わせは不自然で、操作の文脈に合わない。", "食べる": "ボタンを食べるという文は意味をなさない。"}, "sentence_index": 0, "correct_answer": "押す"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は友人の意見を強く押して、全員の賛成を得た。", "explanation": "ここは〈推す〉（支持する）の意味。〈押す〉は物の表面に手や指で力を加える意味で、意見の支持には使わない。"}, {"text": "彼は新製品を店先で押して、客に売り込んだ。", "explanation": "ここは〈売り込む〉（積極的に勧める）の意味。〈押す〉は物の表面に手や指を当てる意味で、勧める行為とは別。"}, {"text": "彼は怒りを押して、冷静に話した。", "explanation": "ここは〈押さえる〉（感情を抑える）の意味。〈押す〉は物の表面に力を加える意味で、感情には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37609, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "押して", "is_correct": true, "explanation": "「カートを押して、店の中を歩いた」は手で押して移動させる意味で、文脈に合う。"}, {"text": "噛んで", "is_correct": false, "explanation": "カートを噛むという意味になり、文脈と合わない。"}, {"text": "笑って", "is_correct": false, "explanation": "カートを笑うという組み合わせは意味が通らない。"}, {"text": "眠って", "is_correct": false, "explanation": "カートを眠らせるという意味になり、文脈に合わない。"}], "explanations": {"押して": "「カートを押して、店の中を歩いた」は手で押して移動させる意味で、文脈に合う。", "噛んで": "カートを噛むという意味になり、文脈と合わない。", "笑って": "カートを笑うという組み合わせは意味が通らない。", "眠って": "カートを眠らせるという意味になり、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "押して"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は新しい企画を強く押して、部長の承認を取りつけた。", "explanation": "ここは〈推す〉（支持する）の意味。〈押す〉は物の表面に手や指で力を加える意味で、企画の支持には使わない。"}, {"text": "ボールを足で押し返して、ゴールを決めた。", "explanation": "足で押し返す動作で、定義の「手や指を当てる」に合わない。"}, {"text": "契約書に判を押して、返送した。", "explanation": "ここは〈捺印する〉（判を付ける）の意味。〈押す〉の物に手や指で力を加える意味とは別。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37609, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "カードリーダーの画面に押すと、すぐにドアが開いた。", "corrected_sentence": "カードリーダーの画面を押すと、すぐにドアが開いた。", "error_description": "正しくは「画面を押す」（直接の対象を示す「を」）。「に」では押す対象を示せない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "押さ", "is_correct": true, "explanation": "未然形。「ないと」に続き、「押さないと〜ない」という条件を作る。"}, {"text": "押し", "is_correct": false, "explanation": "連用形。「ないと」には続かず、文が成立しない。"}, {"text": "押した", "is_correct": false, "explanation": "た形。「ないと」には続かず、文が成立しない。"}, {"text": "押された", "is_correct": false, "explanation": "受身過去。動作の主体と向きが合わず、文脈に合わない。"}], "correct_form": "押さ", "base_form": "押す", "form_label": "未然形", "sentence_index": 1, "explanations": {"押さ": "未然形。「ないと」に続き、「押さないと〜ない」という条件を作る。", "押し": "連用形。「ないと」には続かず、文が成立しない。", "押した": "た形。「ないと」には続かず、文が成立しない。", "押された": "受身過去。動作の主体と向きが合わず、文脈に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37609, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "障子を横で押すと、静かに開いた。", "corrected_sentence": "障子を横に押すと、静かに開いた。", "error_description": "正しくは「横に押す」（方向を示す「に」）。「で」は手段や場所を示し、押す方向には使えない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "押した", "is_correct": true, "explanation": "た形。過去の出来事として車を押した動作を述べている。"}, {"text": "押さ", "is_correct": false, "explanation": "未然形。単独では文が完結せず、過去の出来事を述べられない。"}, {"text": "押される", "is_correct": false, "explanation": "受身形。車が押される形になり、みんなで押す文脈と合わない。"}, {"text": "押し", "is_correct": false, "explanation": "連用形。文末に置けず、文が成立しない。"}], "correct_form": "押した", "base_form": "押す", "form_label": "た形", "sentence_index": 7, "explanations": {"押した": "た形。過去の出来事として車を押した動作を述べている。", "押さ": "未然形。単独では文が完結せず、過去の出来事を述べられない。", "押される": "受身形。車が押される形になり、みんなで押す文脈と合わない。", "押し": "連用形。文末に置けず、文が成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37610, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "も", "options": [{"text": "も", "is_correct": true, "explanation": "「揚力も大きくなる」で、翼の大きさに加えて揚力も大きくなることを示す。"}, {"text": "を", "is_correct": false, "explanation": "「揚力を大きくなる」は自動詞に目的語が付き、不自然。"}, {"text": "に", "is_correct": false, "explanation": "「揚力に大きくなる」は方向や対象を示し、成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を表し、「大きくなる」と続かず、文が成立しない。"}], "correct_answer": "も", "explanations": {"も": "「揚力も大きくなる」で、翼の大きさに加えて揚力も大きくなることを示す。", "を": "「揚力を大きくなる」は自動詞に目的語が付き、不自然。", "に": "「揚力に大きくなる」は方向や対象を示し、成り立たない。", "と": "「と」は並列を表し、「大きくなる」と続かず、文が成立しない。"}, "error_tags": {"を": "object marker", "に": "direction or target", "と": "companion"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37610, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「揚力のおかげで」で、揚力を名詞として「おかげ」に結びつける。"}, {"text": "が", "is_correct": false, "explanation": "「揚力がおかげで」は主語を示すが、「おかげで」の前に名詞を続ける形として不自然。"}, {"text": "と", "is_correct": false, "explanation": "「揚力とおかげで」は並列を示し、「おかげで」の修飾にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「揚力へおかげで」は方向を示し、理由の文脈に合わない。"}], "correct_answer": "の", "explanations": {"の": "「揚力のおかげで」で、揚力を名詞として「おかげ」に結びつける。", "が": "「揚力がおかげで」は主語を示すが、「おかげで」の前に名詞を続ける形として不自然。", "と": "「揚力とおかげで」は並列を示し、「おかげで」の修飾にならない。", "へ": "「揚力へおかげで」は方向を示し、理由の文脈に合わない。"}, "error_tags": {"が": "subject", "と": "quotation or companion", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37610, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "飛行機が空を飛ぶための力。", "primary_collocate": null, "pronunciation": "ようりょく", "ipa": "joːɾʲokɯ", "syllable_count": 3, "sentences": [{"text": "飛行機は揚力があるから、空を飛ぶことができる。", "target_word": "揚力", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]は揚力[ようりょく]があるから、空[そら]を飛[と]ぶことができる。", "sentence_source": "generated"}, {"text": "翼が大きいと、揚力も大きくなる。", "target_word": "揚力", "complexity_tier": "T3", "furigana": "翼[つばさ]が大[おお]きいと、揚力[ようりょく]も大[おお]きくなる。", "sentence_source": "generated"}, {"text": "揚力が足りなくて、飛行機は上がれなかった。", "target_word": "揚力", "complexity_tier": "T3", "furigana": "揚力[ようりょく]が足[た]りなくて、飛行機[ひこうき]は上[あ]がれなかった。", "sentence_source": "generated"}, {"text": "紙飛行機にも揚力が働いている。", "target_word": "揚力", "complexity_tier": "T3", "furigana": "紙飛行機[かみひこうき]にも揚力[ようりょく]が働[はたら]いている。", "sentence_source": "generated"}, {"text": "鳥は翼を広げて、揚力を得て飛ぶ。", "target_word": "揚力", "complexity_tier": "T3", "furigana": "鳥[とり]は翼[つばさ]を広[ひろ]げて、揚力[ようりょく]を得[え]て飛[と]ぶ。", "sentence_source": "generated"}, {"text": "飛行機は速く走ると、翼に揚力が生まれる。", "target_word": "揚力", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]は速[はや]く走[はし]ると、翼[つばさ]に揚力[ようりょく]が生[う]まれる。", "sentence_source": "generated"}, {"text": "この模型の飛行機は揚力が弱く、すぐ落ちてしまう。", "target_word": "揚力", "complexity_tier": "T3", "furigana": "この模型[もけい]の飛行機[ひこうき]は揚力[ようりょく]が弱[よわ]く、すぐ落[お]ちてしまう。", "sentence_source": "generated"}, {"text": "揚力のおかげで、重い飛行機も空に浮かぶ。", "target_word": "揚力", "complexity_tier": "T3", "furigana": "揚力[ようりょく]のおかげで、重[おも]い飛行機[ひこうき]も空[そら]に浮[う]かぶ。", "sentence_source": "generated"}, {"text": "翼の形を変えると、揚力が変わる。", "target_word": "揚力", "complexity_tier": "T3", "furigana": "翼[つばさ]の形[かたち]を変[か]えると、揚力[ようりょく]が変[か]わる。", "sentence_source": "generated"}, {"text": "向かい風のとき、飛行機の翼に大きな揚力が生まれる。", "target_word": "揚力", "complexity_tier": "T3", "furigana": "向[む]かい風[かぜ]のとき、飛行機[ひこうき]の翼[つばさ]に大[おお]きな揚力[ようりょく]が生[う]まれる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "揚力", "label": "基本形"}], "register": "中立（常体）", "sense_fingerprint": "飛行機や鳥を空に浮かせて飛ばす上向きの力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0e12dd3-c77b-4d9e-9498-0161804d2652') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37610, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "揚力", "is_correct": true, "explanation": "「揚力があるから、空を飛ぶことができる」は飛行機が空を飛ぶ力を表し、文脈に合う。"}, {"text": "料金", "is_correct": false, "explanation": "料金があっても空を飛ぶ理由にならず、文が成立しない。"}, {"text": "温度", "is_correct": false, "explanation": "温度があるから空を飛ぶという因果関係は成り立たない。"}, {"text": "名簿", "is_correct": false, "explanation": "名簿があるから空を飛ぶという関係は成り立たない。"}], "explanations": {"揚力": "「揚力があるから、空を飛ぶことができる」は飛行機が空を飛ぶ力を表し、文脈に合う。", "料金": "料金があっても空を飛ぶ理由にならず、文が成立しない。", "温度": "温度があるから空を飛ぶという因果関係は成り立たない。", "名簿": "名簿があるから空を飛ぶという関係は成り立たない。"}, "sentence_index": 0, "correct_answer": "揚力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ロケットは揚力で宇宙へ飛んでいく。", "explanation": "ここは前に進ませる推力の意味。揚力は翼に働く上向きの力で、推力とは別の力。"}, {"text": "リンゴは揚力で木から落ちる。", "explanation": "ここは重力の意味。揚力は上向きに働く力で、下に落ちる現象とは別の力。"}, {"text": "金属の揚力を測るために、重い箱を天井まで運んだ。", "explanation": "ここは〈重さ〉（重力）の意味。揚力は翼に働く上向きの力で、物の重さを表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37610, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "揚力", "is_correct": true, "explanation": "「揚力が弱く、すぐ落ちてしまう」は模型の飛行機の上向きの力が弱いことを表し、文脈に合う。"}, {"text": "交通費", "is_correct": false, "explanation": "交通費が弱いという表現は意味をなさず、文脈に合わない。"}, {"text": "寝具", "is_correct": false, "explanation": "寝具が弱いという表現は飛行機の性質と合わない。"}, {"text": "湿度", "is_correct": false, "explanation": "湿度が弱いという表現は飛行機の飛行力を示せず、文脈に合わない。"}], "explanations": {"揚力": "「揚力が弱く、すぐ落ちてしまう」は模型の飛行機の上向きの力が弱いことを表し、文脈に合う。", "交通費": "交通費が弱いという表現は意味をなさず、文脈に合わない。", "寝具": "寝具が弱いという表現は飛行機の性質と合わない。", "湿度": "湿度が弱いという表現は飛行機の飛行力を示せず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "揚力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "空気の揚力が大きいと、飛行機は遅くなる。", "explanation": "ここは進行方向の抵抗を表す抗力の意味。揚力は翼に働く上向きの力で、速度を落とす力ではない。"}, {"text": "道路の揚力が少ないと、車が滑りやすい。", "explanation": "ここは摩擦の意味。揚力は流れに垂直に翼へ働く力で、路面の摩擦とは別の力。"}, {"text": "ロープの揚力が大きいと、切れやすい。", "explanation": "ここは張力の意味。揚力は翼に働く上向きの力で、ロープを引く張力とは別の力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37610, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "翼が大きいと、揚力を大きくなる。", "corrected_sentence": "翼が大きいと、揚力が大きくなる。", "error_description": "正しくは「揚力が大きくなる」（主語を示す「が」）。「を」は他動詞の目的語を示すが、「大きくなる」は自動詞なので合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37610, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "プロペラ機は、回転する羽根で揚力に得ている。", "corrected_sentence": "プロペラ機は、回転する羽根で揚力を得ている。", "error_description": "正しくは「揚力を得ている」（目的語を示す「を」）。「に」では得る対象を示せない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37611, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「揚力は、流れと垂直な方向に働く力である」で、揚力を主題として示す。"}, {"text": "を", "is_correct": false, "explanation": "「揚力を、流れと垂直な方向に働く力である」は目的語を示し、主題の文にならない。"}, {"text": "で", "is_correct": false, "explanation": "「揚力で、流れと垂直な方向に働く力である」は手段を示し、定義文として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「揚力の、流れと垂直な方向に働く力である」は名詞の修飾を示し、文の主語にならない。"}], "correct_answer": "は", "explanations": {"は": "「揚力は、流れと垂直な方向に働く力である」で、揚力を主題として示す。", "を": "「揚力を、流れと垂直な方向に働く力である」は目的語を示し、主題の文にならない。", "で": "「揚力で、流れと垂直な方向に働く力である」は手段を示し、定義文として成り立たない。", "の": "「揚力の、流れと垂直な方向に働く力である」は名詞の修飾を示し、文の主語にならない。"}, "error_tags": {"を": "object marker", "で": "means", "の": "possessive"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37611, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「揚力を得ている」で、得る対象（目的語）を示す。"}, {"text": "が", "is_correct": false, "explanation": "「揚力が得ている」は主語を示し、得る対象の文として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「揚力に得ている」は方向や対象を示し、得るの目的語にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「揚力と得ている」は並列を示し、得る対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「揚力を得ている」で、得る対象（目的語）を示す。", "が": "「揚力が得ている」は主語を示し、得る対象の文として成り立たない。", "に": "「揚力に得ている」は方向や対象を示し、得るの目的語にはならない。", "と": "「揚力と得ている」は並列を示し、得る対象を示せない。"}, "error_tags": {"が": "subject", "に": "direction or target", "と": "quotation or companion"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37611, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "流体中を移動する物体に、流れと垂直な方向に働く力。特に、飛行機の翼が受ける上向きの力を指す。", "primary_collocate": null, "pronunciation": "ようりょく", "ipa": "joːɾʲokɯ", "syllable_count": 3, "sentences": [{"text": "迎え角を大きくすると、翼の揚力は増える。", "target_word": "揚力", "complexity_tier": "T3", "furigana": "迎[むか]え角[かく]を大[おお]きくすると、翼[つばさ]の揚力[ようりょく]は増[ふ]える。", "sentence_source": "generated"}, {"text": "揚力は、流れと垂直な方向に働く力である。", "target_word": "揚力", "complexity_tier": "T3", "furigana": "揚力[ようりょく]は、流[なが]れと垂直[すいちょく]な方向[ほうこう]に働[はたら]く力[ちから]である。", "sentence_source": "generated"}, {"text": "水中の翼にも、揚力は生じる。", "target_word": "揚力", "complexity_tier": "T3", "furigana": "水中[すいちゅう]の翼[つばさ]にも、揚力[ようりょく]は生[しょう]じる。", "sentence_source": "generated"}, {"text": "揚力が重力より大きければ、機体は上昇する。", "target_word": "揚力", "complexity_tier": "T3", "furigana": "揚力[ようりょく]が重力[じゅうりょく]より大[おお]きければ、機体[きたい]は上昇[じょうしょう]する。", "sentence_source": "generated"}, {"text": "風洞実験で、翼にかかる揚力を測定した。", "target_word": "揚力", "complexity_tier": "T3", "furigana": "風洞実験[ふうどうじっけん]で、翼[つばさ]にかかる揚力[ようりょく]を測定[そくてい]した。", "sentence_source": "generated"}, {"text": "速度が上がると、揚力は速度の二乗に比例して大きくなる。", "target_word": "揚力", "complexity_tier": "T3", "furigana": "速度[そくど]が上[あ]がると、揚力[ようりょく]は速度[そくど]の二乗[にじょう]に比例[ひれい]して大[おお]きくなる。", "sentence_source": "generated"}, {"text": "翼の上面の流れが速いと、上向きの揚力が生じる。", "target_word": "揚力", "complexity_tier": "T3", "furigana": "翼[つばさ]の上面[じょうめん]の流[なが]れが速[はや]いと、上向[うわむ]きの揚力[ようりょく]が生[しょう]じる。", "sentence_source": "generated"}, {"text": "ヘリコプターは、回転する翼で揚力を得ている。", "target_word": "揚力", "complexity_tier": "T3", "furigana": "ヘリコプターは、回転[かいてん]する翼[つばさ]で揚力[ようりょく]を得[え]ている。", "sentence_source": "generated"}, {"text": "失速すると、翼の揚力は急に小さくなる。", "target_word": "揚力", "complexity_tier": "T3", "furigana": "失速[しっそく]すると、翼[つばさ]の揚力[ようりょく]は急[きゅう]に小[ちい]さくなる。", "sentence_source": "generated"}, {"text": "揚力と抗力の比を揚抗比という。", "target_word": "揚力", "complexity_tier": "T3", "furigana": "揚力[ようりょく]と抗力[こうりょく]の比[ひ]を揚抗比[ようこうひ]という。", "sentence_source": "generated"}], "morphological_forms": [{"form": "揚力", "label": "基本形"}], "register": "専門的（常体）", "sense_fingerprint": "流体力学で、流れに垂直に物体へ働く力。翼が受ける上向きの力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0e12dd3-c77b-4d9e-9498-0161804d2652') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37611, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "揚力", "is_correct": true, "explanation": "「迎え角を大きくすると、翼の揚力は増える」は流体力学で翼が受ける上向きの力を表し、文脈に合う。"}, {"text": "料金", "is_correct": false, "explanation": "翼の料金が増えるという表現は、流体力学の文脈と合わない。"}, {"text": "名簿", "is_correct": false, "explanation": "翼の名簿が増えるという表現は意味をなさない。"}, {"text": "音色", "is_correct": false, "explanation": "翼の音色が増えるという表現は、力の変化を述べる文に合わない。"}], "explanations": {"揚力": "「迎え角を大きくすると、翼の揚力は増える」は流体力学で翼が受ける上向きの力を表し、文脈に合う。", "料金": "翼の料金が増えるという表現は、流体力学の文脈と合わない。", "名簿": "翼の名簿が増えるという表現は意味をなさない。", "音色": "翼の音色が増えるという表現は、力の変化を述べる文に合わない。"}, "sentence_index": 0, "correct_answer": "揚力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "揚力が大きいと、ロケットは速く進む。", "explanation": "ここは前に進ませる推力の意味。揚力は流れに垂直に翼へ働く力で、推進力とは別。"}, {"text": "揚力が大きいと、荷物の重さが増す。", "explanation": "ここは〈重さ〉の意味。揚力は流れに垂直に働く力で、物の重さとは別。"}, {"text": "揚力が大きいと、床の摩擦が増す。", "explanation": "ここは〈摩擦〉の意味。揚力は翼に働く力で、接触面の摩擦とは別。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37611, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "揚力", "is_correct": true, "explanation": "「上向きの揚力が生じる」は流れの速さによって翼に生じる力の意味で、文脈に合う。"}, {"text": "体温", "is_correct": false, "explanation": "上向きの体温が生じるという表現は、流体力学の文脈と合わない。"}, {"text": "怒り", "is_correct": false, "explanation": "上向きの怒りが生じるという表現は、物理現象の説明に合わない。"}, {"text": "湿度", "is_correct": false, "explanation": "上向きの湿度が生じるという表現は意味をなさない。"}], "explanations": {"揚力": "「上向きの揚力が生じる」は流れの速さによって翼に生じる力の意味で、文脈に合う。", "体温": "上向きの体温が生じるという表現は、流体力学の文脈と合わない。", "怒り": "上向きの怒りが生じるという表現は、物理現象の説明に合わない。", "湿度": "上向きの湿度が生じるという表現は意味をなさない。"}, "sentence_index": 6, "correct_answer": "揚力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "揚力が高いと、天気は安定する。", "explanation": "ここは気圧の意味。揚力は翼が受ける力で、天気の安定を表す量ではない。"}, {"text": "床の揚力が大きいと、物がずれにくい。", "explanation": "ここは摩擦の意味。揚力は流れに垂直に翼へ働く力で、床と物の接触面で働く摩擦とは別。"}, {"text": "ロープの揚力が大きいと、切れやすい。", "explanation": "ここは張力の意味。揚力は翼に働く上向きの力で、ロープを引く張力とは別。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37611, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "迎え角を小さくすると、翼の揚力を減る。", "corrected_sentence": "迎え角を小さくすると、翼の揚力は減る。", "error_description": "正しくは「揚力は減る」（主題を示す「は」）。「を」は他動詞の目的語を示すが、「減る」は自動詞なので合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37611, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "翼の上面の流れを速いと、上向きの揚力が生じた。", "corrected_sentence": "翼の上面の流れが速いと、上向きの揚力が生じた。", "error_description": "正しくは「流れが速い」（主語の「が」）。形容詞「速い」は「を」を取れず、不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37612, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "軽い", "is_correct": true, "explanation": "〈重い〉の対義語で、重さが小さいことを表す。"}, {"text": "高い", "is_correct": false, "explanation": "位置や値の大きさを表し、重さの反対語ではない。"}, {"text": "暗い", "is_correct": false, "explanation": "明るさの反対で、重さとは関係がない。"}, {"text": "固い", "is_correct": false, "explanation": "硬さを表す語で、重さの反対語ではない。"}], "correct_answer": "軽い", "explanations": {"軽い": "〈重い〉の対義語で、重さが小さいことを表す。", "高い": "位置や値の大きさを表し、重さの反対語ではない。", "暗い": "明るさの反対で、重さとは関係がない。", "固い": "硬さを表す語で、重さの反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37612, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "軽い", "is_correct": true, "explanation": "〈重い〉の対義語で、重さが小さいことを表す。"}, {"text": "浅い", "is_correct": false, "explanation": "深さの反対で、重さの対義語ではない。"}, {"text": "遅い", "is_correct": false, "explanation": "速さの反対で、重さとは関係がない。"}, {"text": "狭い", "is_correct": false, "explanation": "広さの反対で、重さの対義語ではない。"}], "correct_answer": "軽い", "explanations": {"軽い": "〈重い〉の対義語で、重さが小さいことを表す。", "浅い": "深さの反対で、重さの対義語ではない。", "遅い": "速さの反対で、重さとは関係がない。", "狭い": "広さの反対で、重さの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37612, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "ものが重たいということは、持ったり動かしたりするのが大変なことです。", "primary_collocate": null, "pronunciation": "おもい", "ipa": "omoi", "syllable_count": 3, "sentences": [{"text": "このかばんは重い。", "target_word": "重い", "complexity_tier": "T2", "furigana": "このかばんは重[おも]い。", "sentence_source": "generated"}, {"text": "重い荷物を持って、駅まで歩いた。", "target_word": "重い", "complexity_tier": "T3", "furigana": "重[おも]い荷物[にもつ]を持[も]って、駅[えき]まで歩[ある]いた。", "sentence_source": "generated"}, {"text": "石が重くて、一人では動かせない。", "target_word": "重くて", "complexity_tier": "T3", "furigana": "石[いし]が重[おも]くて、一人[ひとり]では動[うご]かせない。", "sentence_source": "generated"}, {"text": "箱は重かったので、二人で運んだ。", "target_word": "重かった", "complexity_tier": "T3", "furigana": "箱[はこ]は重[おも]かったので、二人[ふたり]で運[はこ]んだ。", "sentence_source": "generated"}, {"text": "本をたくさん入れたら、袋が重くなった。", "target_word": "重くなった", "complexity_tier": "T3", "furigana": "本[ほん]をたくさん入[い]れたら、袋[ふくろ]が重[おも]くなった。", "sentence_source": "generated"}, {"text": "重い扉を、力いっぱい押した。", "target_word": "重い", "complexity_tier": "T3", "furigana": "重[おも]い扉[とびら]を、力[ちから]いっぱい押[お]した。", "sentence_source": "generated"}, {"text": "子どもには重いので、私が持ちます。", "target_word": "重い", "complexity_tier": "T3", "furigana": "子[こ]どもには重[おも]いので、私[わたし]が持[も]ちます。", "sentence_source": "generated"}, {"text": "鉄は木より重い。", "target_word": "重い", "complexity_tier": "T2", "furigana": "鉄[てつ]は木[き]より重[おも]い。", "sentence_source": "generated"}, {"text": "荷物が重すぎて、手が痛くなった。", "target_word": "重すぎて", "complexity_tier": "T3", "furigana": "荷物[にもつ]が重[おも]すぎて、手[て]が痛[いた]くなった。", "sentence_source": "generated"}, {"text": "この机は重いから、動かすのが大変だ。", "target_word": "重い", "complexity_tier": "T3", "furigana": "この机[つくえ]は重[おも]いから、動[うご]かすのが大変[たいへん]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "重い", "label": "終止形"}, {"form": "重く", "label": "連用形"}, {"form": "重かった", "label": "過去形"}, {"form": "重くない", "label": "否定形"}, {"form": "重ければ", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "物の重さが大きく、持ったり動かしたりするのが大変", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T2: contains vocabulary far above tier T2: 力いっぱい (Zipf 2.43)']::text[], 'cf6ee224-92d2-4127-abed-56d8891d40e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37612, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重い", "is_correct": true, "explanation": "「このかばんは重い」で物の重さを述べる文として自然。"}, {"text": "甘い", "is_correct": false, "explanation": "「かばんが甘い」は意味をなさず、重さの話と合わない。"}, {"text": "眠い", "is_correct": false, "explanation": "「かばんが眠い」は成り立たず、物の重さを表さない。"}, {"text": "苦い", "is_correct": false, "explanation": "味を表す形容詞で、かばんの重さを述べる文に入らない。"}], "explanations": {"重い": "「このかばんは重い」で物の重さを述べる文として自然。", "甘い": "「かばんが甘い」は意味をなさず、重さの話と合わない。", "眠い": "「かばんが眠い」は成り立たず、物の重さを表さない。", "苦い": "味を表す形容詞で、かばんの重さを述べる文に入らない。"}, "sentence_index": 0, "correct_answer": "重い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "参加者の数が重くて、会場が混んだ。", "explanation": "ここは〈多い〉の意味。数の多さは「多い」で表し、「数が重い」とは言わない。"}, {"text": "この選手の走りは重くて、タイムが縮んだ。", "explanation": "ここは〈速い〉の意味。速さは「速い」で表し、「走りが重い」とは言わない。"}, {"text": "彼は性格が重くて、誰とも仲良くなれなかった。", "explanation": "ここは〈暗くて付き合いにくい〉の意味。性格は「暗い」「とっつきにくい」で表し、「性格が重い」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37612, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重い", "is_correct": true, "explanation": "子どもには重いので私が持つという理由の文として自然。"}, {"text": "白い", "is_correct": false, "explanation": "子どもには白いので、という理由の文が意味をなさない。"}, {"text": "四角い", "is_correct": false, "explanation": "形の話になり、子どもが持てない理由として成り立たない。"}, {"text": "丸い", "is_correct": false, "explanation": "丸いことは持つ理由にならず、文が通らない。"}], "explanations": {"重い": "子どもには重いので私が持つという理由の文として自然。", "白い": "子どもには白いので、という理由の文が意味をなさない。", "四角い": "形の話になり、子どもが持てない理由として成り立たない。", "丸い": "丸いことは持つ理由にならず、文が通らない。"}, "sentence_index": 6, "correct_answer": "重い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この授業は時間が重くて、二時間も続いた。", "explanation": "ここは〈長い〉の意味。時間の長さは「長い」で表し、「時間が重い」とは言わない。"}, {"text": "この会社の社員は重くて、会議で意見が出ない。", "explanation": "ここは〈無口〉の意味。口数の少なさは「口が重い」で表し、「社員が重い」とは言わない。"}, {"text": "彼は説明が重くて、聞いている人が眠くなった。", "explanation": "ここは〈話が長い〉の意味。話の長さは「長い」で表し、「説明が重い」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37612, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この箱は重くので、一人では運べない。", "corrected_sentence": "この箱は重いので、一人では運べない。", "error_description": "「ので」の前は終止形（重い）を使う。「重くので」は連用形を使った誤りで、正しくは「重いので」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "重い", "is_correct": true, "explanation": "連体形で、名詞「荷物」を修飾している。ここに入る正しい形。"}, {"text": "重く", "is_correct": false, "explanation": "連用形は名詞に直接続けられず、荷物を修飾できない。"}, {"text": "重ければ", "is_correct": false, "explanation": "仮定形は名詞を修飾できず、文が成り立たない。"}, {"text": "重さ", "is_correct": false, "explanation": "名詞で、直後に「荷物」を続けると文が成り立たない。"}], "correct_form": "重い", "base_form": "重い", "form_label": "連体形", "sentence_index": 1, "explanations": {"重い": "連体形で、名詞「荷物」を修飾している。ここに入る正しい形。", "重く": "連用形は名詞に直接続けられず、荷物を修飾できない。", "重ければ": "仮定形は名詞を修飾できず、文が成り立たない。", "重さ": "名詞で、直後に「荷物」を続けると文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37612, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このスーツケースは重いて、階段で運べなかった。", "corrected_sentence": "このスーツケースは重くて、階段で運べなかった。", "error_description": "形容詞「重い」のて形は「重くて」。「重いて」は活用の誤りで、正しくは「重くて」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "重い", "is_correct": true, "explanation": "終止形で、文末の述語として鉄は木より重いと言い切る。"}, {"text": "重かったら", "is_correct": false, "explanation": "条件の形で、文末に置くと言い切れず不完全になる。"}, {"text": "重くて", "is_correct": false, "explanation": "て形は文末に置くと文が完結せず、不自然になる。"}, {"text": "重くても", "is_correct": false, "explanation": "逆接の条件を表す形で、文末に置くと言い切れず不完全になる。"}], "correct_form": "重い", "base_form": "重い", "form_label": "終止形", "sentence_index": 7, "explanations": {"重い": "終止形で、文末の述語として鉄は木より重いと言い切る。", "重かったら": "条件の形で、文末に置くと言い切れず不完全になる。", "重くて": "て形は文末に置くと文が完結せず、不自然になる。", "重くても": "逆接の条件を表す形で、文末に置くと言い切れず不完全になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37613, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "軽い", "is_correct": true, "explanation": "〈重い〉の対義語で、重さが小さいことを表す。"}, {"text": "低い", "is_correct": false, "explanation": "高さの反対語で、重さの反対語ではない。"}, {"text": "薄い", "is_correct": false, "explanation": "厚さの反対語で、重さとは関係がない。"}, {"text": "柔らかい", "is_correct": false, "explanation": "硬さの反対語で、重さの反対語ではない。"}], "correct_answer": "軽い", "explanations": {"軽い": "〈重い〉の対義語で、重さが小さいことを表す。", "低い": "高さの反対語で、重さの反対語ではない。", "薄い": "厚さの反対語で、重さとは関係がない。", "柔らかい": "硬さの反対語で、重さの反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
