INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37613, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "「重い」は、物体の質量が大きく、持ち上げたり動かしたりするのに力が必要であることを表す形容詞です。", "primary_collocate": null, "pronunciation": "おもい", "ipa": "omoi", "syllable_count": 3, "sentences": [{"text": "重い鍋を持ち上げるには、両手が必要だ。", "target_word": "重い", "complexity_tier": "T3", "furigana": "重[おも]い鍋[なべ]を持[も]ち上[あ]げるには、両手[りょうて]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "その石は重く、女の人の力では持ち上がらない。", "target_word": "重く", "complexity_tier": "T4", "furigana": "その石[いし]は重[おも]く、女[おんな]の人[ひと]の力[ちから]では持[も]ち上[あ]がらない。", "sentence_source": "generated"}, {"text": "重い机を動かすために、みんなで力を合わせた。", "target_word": "重い", "complexity_tier": "T3", "furigana": "重[おも]い机[つくえ]を動[うご]かすために、みんなで力[ちから]を合[あ]わせた。", "sentence_source": "generated"}, {"text": "荷物が重いので、タクシーに乗ることにした。", "target_word": "重い", "complexity_tier": "T3", "furigana": "荷物[にもつ]が重[おも]いので、タクシーに乗[の]ることにした。", "sentence_source": "generated"}, {"text": "水を入れたバケツは思ったより重かった。", "target_word": "重かった", "complexity_tier": "T3", "furigana": "水[みず]を入[い]れたバケツは思[おも]ったより重[おも]かった。", "sentence_source": "generated"}, {"text": "重い本ばかり持つと、肩が疲れる。", "target_word": "重い", "complexity_tier": "T3", "furigana": "重[おも]い本[ほん]ばかり持[も]つと、肩[かた]が疲[つか]れる。", "sentence_source": "generated"}, {"text": "この自転車は重くて、坂を上るのがつらい。", "target_word": "重くて", "complexity_tier": "T3", "furigana": "この自転車[じてんしゃ]は重[おも]くて、坂[さか]を上[のぼ]るのがつらい。", "sentence_source": "generated"}, {"text": "小さな箱なのに、とても重いので驚いた。", "target_word": "重い", "complexity_tier": "T3", "furigana": "小[ちい]さな箱[はこ]なのに、とても重[おも]いので驚[おどろ]いた。", "sentence_source": "generated"}, {"text": "重い荷物は、下の棚に置いてください。", "target_word": "重い", "complexity_tier": "T3", "furigana": "重[おも]い荷物[にもつ]は、下[した]の棚[たな]に置[お]いてください。", "sentence_source": "generated"}, {"text": "鉄の板は重いので、機械で運ぶ。", "target_word": "重い", "complexity_tier": "T3", "furigana": "鉄[てつ]の板[いた]は重[おも]いので、機械[きかい]で運[はこ]ぶ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "重い", "label": "終止形"}, {"form": "重く", "label": "連用形"}, {"form": "重かった", "label": "過去形"}, {"form": "重くない", "label": "否定形"}, {"form": "重ければ", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "物体の質量が大きく、持ち上げたり動かしたりするのに力が要る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: contains vocabulary far above tier T2: 持ち上がら (Zipf 1.86)']::text[], 'cf6ee224-92d2-4127-abed-56d8891d40e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37613, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重い", "is_correct": true, "explanation": "鍋を修飾する形で、重い鍋の持ち上げには両手が必要という意味になる。"}, {"text": "眠い", "is_correct": false, "explanation": "「眠い鍋」は意味が通らず、持ち上げる文と結びつかない。"}, {"text": "苦い", "is_correct": false, "explanation": "味を表す語で、「苦い鍋」は持ち上げる話と合わない。"}, {"text": "寂しい", "is_correct": false, "explanation": "「寂しい鍋」は物の性質として成り立たず、文が不自然。"}], "explanations": {"重い": "鍋を修飾する形で、重い鍋の持ち上げには両手が必要という意味になる。", "眠い": "「眠い鍋」は意味が通らず、持ち上げる文と結びつかない。", "苦い": "味を表す語で、「苦い鍋」は持ち上げる話と合わない。", "寂しい": "「寂しい鍋」は物の性質として成り立たず、文が不自然。"}, "sentence_index": 0, "correct_answer": "重い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "参加者の数が重くて、会場が混んだ。", "explanation": "ここは〈多い〉の意味。数の多さは「多い」で表し、「数が重い」とは言わない。"}, {"text": "この選手の走りは重くて、タイムが縮んだ。", "explanation": "ここは〈速い〉の意味。速さは「速い」で表し、「走りが重い」とは言わない。"}, {"text": "彼は性格が重くて、誰とも仲良くなれなかった。", "explanation": "ここは〈暗くて付き合いにくい〉の意味。性格は「暗い」「とっつきにくい」で表し、「性格が重い」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37613, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重くて", "is_correct": true, "explanation": "理由を表す形で、重いので坂を上るのがつらいという因果が自然。"}, {"text": "甘くて", "is_correct": false, "explanation": "味の形容詞で、自転車の性質として成り立たず、坂の話と合わない。"}, {"text": "白くて", "is_correct": false, "explanation": "色の形容詞で、坂を上るつらさの理由にならない。"}, {"text": "赤くて", "is_correct": false, "explanation": "色の形容詞で、坂を上るつらさの理由にならない。"}], "explanations": {"重くて": "理由を表す形で、重いので坂を上るのがつらいという因果が自然。", "甘くて": "味の形容詞で、自転車の性質として成り立たず、坂の話と合わない。", "白くて": "色の形容詞で、坂を上るつらさの理由にならない。", "赤くて": "色の形容詞で、坂を上るつらさの理由にならない。"}, "sentence_index": 6, "correct_answer": "重くて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この授業は時間が重くて、二時間も続いた。", "explanation": "ここは〈長い〉の意味。時間の長さは「長い」で表し、「時間が重い」とは言わない。"}, {"text": "この会社の社員は重くて、会議で意見が出ない。", "explanation": "ここは〈無口〉の意味。口数の少なさは「口が重い」で表し、「社員が重い」とは言わない。"}, {"text": "彼は説明が重くて、聞いている人が眠くなった。", "explanation": "ここは〈話が長い〉の意味。話の長さは「長い」で表し、「説明が重い」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37613, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "重く鍋を、両手で持ち上げた。", "corrected_sentence": "重い鍋を、両手で持ち上げた。", "error_description": "名詞を修飾するには連体形「重い」を使う。「重く鍋」は連用形で、名詞に直接続けられない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "重く", "is_correct": true, "explanation": "連用形で、後ろの「持ち上がらない」へ続けて状態を述べており、ここに入る正しい形。"}, {"text": "重かろう", "is_correct": false, "explanation": "推量形は文の途中で続けられず、「、持ち上がらない」につながらない。"}, {"text": "重さ", "is_correct": false, "explanation": "名詞で、動詞「持ち上がらない」へ直接続く形ではない。"}, {"text": "重み", "is_correct": false, "explanation": "名詞で、述語の位置に置くと文が成り立たない。"}], "correct_form": "重く", "base_form": "重い", "form_label": "連用形", "sentence_index": 1, "explanations": {"重く": "連用形で、後ろの「持ち上がらない」へ続けて状態を述べており、ここに入る正しい形。", "重かろう": "推量形は文の途中で続けられず、「、持ち上がらない」につながらない。", "重さ": "名詞で、動詞「持ち上がらない」へ直接続く形ではない。", "重み": "名詞で、述語の位置に置くと文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37613, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この段ボールは重いて、一人では持てなかった。", "corrected_sentence": "この段ボールは重くて、一人では持てなかった。", "error_description": "形容詞「重い」のて形は「重くて」。「重いて」は活用の誤りで、正しくは「重くて」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "重い", "is_correct": true, "explanation": "終止形で、「ので」の前に置き、小さな箱なのに重いという理由を述べる。"}, {"text": "重ければ", "is_correct": false, "explanation": "仮定形は「ので」と合わず、条件の文になってしまう。"}, {"text": "重くて", "is_correct": false, "explanation": "て形は「ので」に続けられず、文が成り立たない。"}, {"text": "重かろう", "is_correct": false, "explanation": "推量形は「ので」の前に置けず、文が成り立たない。"}], "correct_form": "重い", "base_form": "重い", "form_label": "終止形", "sentence_index": 7, "explanations": {"重い": "終止形で、「ので」の前に置き、小さな箱なのに重いという理由を述べる。", "重ければ": "仮定形は「ので」と合わず、条件の文になってしまう。", "重くて": "て形は「ので」に続けられず、文が成り立たない。", "重かろう": "推量形は「ので」の前に置けず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37614, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「抵抗が」は「ある」の主語になり、文が成立する。"}, {"text": "を", "is_correct": false, "explanation": "「抵抗を」だと「ある」の主語にならず、文が成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、「抵抗へある」は成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す助詞で、「抵抗からある」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「抵抗が」は「ある」の主語になり、文が成立する。", "を": "「抵抗を」だと「ある」の主語にならず、文が成立しない。", "へ": "方向を表す助詞で、「抵抗へある」は成り立たない。", "から": "起点を表す助詞で、「抵抗からある」は意味が通らない。"}, "error_tags": {"を": "対象", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37614, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「抵抗を加える」で、抵抗が目的語になる。"}, {"text": "が", "is_correct": false, "explanation": "「抵抗が加えて」では主語になり、「加える」の目的語にならない。"}, {"text": "で", "is_correct": false, "explanation": "手段を表す助詞で、「抵抗で加えて」は文が成立しない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の助詞で、「抵抗の加えて」は文が成立しない。"}], "correct_answer": "を", "explanations": {"を": "「抵抗を加える」で、抵抗が目的語になる。", "が": "「抵抗が加えて」では主語になり、「加える」の目的語にならない。", "で": "手段を表す助詞で、「抵抗で加えて」は文が成立しない。", "の": "連体修飾の助詞で、「抵抗の加えて」は文が成立しない。"}, "error_tags": {"が": "主語", "で": "手段", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37614, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物が動くのをじゃまする力。", "primary_collocate": null, "pronunciation": "ていこう", "ipa": "teːkoː", "syllable_count": 4, "sentences": [{"text": "坂道では、自転車を押す手に大きな抵抗を感じた。", "target_word": "抵抗", "complexity_tier": "T3", "furigana": "坂道[さかみち]では、自転車[じてんしゃ]を押[お]す手[て]に大[おお]きな抵抗[ていこう]を感[かん]じた。", "sentence_source": "generated"}, {"text": "水の中では、歩くときに抵抗があるので、体が重く感じる。", "target_word": "抵抗", "complexity_tier": "T3", "furigana": "水[みず]の中[なか]では、歩[ある]くときに抵抗[ていこう]があるので、体[からだ]が重[おも]く感[かん]じる。", "sentence_source": "generated"}, {"text": "摩擦が大きいと、ものが動くときの抵抗も大きくなる。", "target_word": "抵抗", "complexity_tier": "T3", "furigana": "摩擦[まさつ]が大[おお]きいと、ものが動[うご]くときの抵抗[ていこう]も大[おお]きくなる。", "sentence_source": "generated"}, {"text": "氷の上は抵抗が小さいので、石はよくすべる。", "target_word": "抵抗", "complexity_tier": "T3", "furigana": "氷[こおり]の上[うえ]は抵抗[ていこう]が小[ちい]さいので、石[いし]はよくすべる。", "sentence_source": "generated"}, {"text": "重いドアは、押しても抵抗が強くて、なかなか開かない。", "target_word": "抵抗", "complexity_tier": "T3", "furigana": "重[おも]いドアは、押[お]しても抵抗[ていこう]が強[つよ]くて、なかなか開[あ]かない。", "sentence_source": "generated"}, {"text": "砂の上を走ると、足への抵抗が大きく、すぐ疲れる。", "target_word": "抵抗", "complexity_tier": "T3", "furigana": "砂[すな]の上[うえ]を走[はし]ると、足[あし]への抵抗[ていこう]が大[おお]きく、すぐ疲[つか]れる。", "sentence_source": "generated"}, {"text": "油をさしたら、車輪の回るときの抵抗が少なくなった。", "target_word": "抵抗", "complexity_tier": "T3", "furigana": "油[あぶら]をさしたら、車輪[しゃりん]の回[まわ]るときの抵抗[ていこう]が少[すく]なくなった。", "sentence_source": "generated"}, {"text": "ブレーキは、車輪に抵抗を加えて、車を止める。", "target_word": "抵抗", "complexity_tier": "T3", "furigana": "ブレーキは、車輪[しゃりん]に抵抗[ていこう]を加[くわ]えて、車[くるま]を止[と]める。", "sentence_source": "generated"}, {"text": "刃がうすいと、土に入るときの抵抗が少ない。", "target_word": "抵抗", "complexity_tier": "T3", "furigana": "刃[は]がうすいと、土[つち]に入[はい]るときの抵抗[ていこう]が少[すく]ない。", "sentence_source": "generated"}, {"text": "泥の中では足が進みにくい。抵抗が大きいからだ。", "target_word": "抵抗", "complexity_tier": "T3", "furigana": "泥[どろ]の中[なか]では足[あし]が進[すす]みにくい。抵抗[ていこう]が大[おお]きいからだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "抵抗", "label": "基本形"}, {"form": "抵抗が", "label": "主格"}, {"form": "抵抗を", "label": "目的格"}], "register": "普通体（日常）", "sense_fingerprint": "物が動くときにそれをじゃまする力（摩擦や重さなどによる）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd744feb5-cce0-45db-a3b7-f31e2c301cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37614, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抵抗", "is_correct": true, "explanation": "物の動きを妨げる力を表し、押す手にかかる重さの感覚に合う。"}, {"text": "天井", "is_correct": false, "explanation": "場所を表す名詞で、「大きな天井を感じた」は成り立たない。"}, {"text": "会議", "is_correct": false, "explanation": "出来事を表す名詞で、「大きな会議を感じた」は意味をなさない。"}, {"text": "手紙", "is_correct": false, "explanation": "書いた物を表す名詞で、「大きな手紙を感じた」は成り立たない。"}], "explanations": {"抵抗": "物の動きを妨げる力を表し、押す手にかかる重さの感覚に合う。", "天井": "場所を表す名詞で、「大きな天井を感じた」は成り立たない。", "会議": "出来事を表す名詞で、「大きな会議を感じた」は意味をなさない。", "手紙": "書いた物を表す名詞で、「大きな手紙を感じた」は成り立たない。"}, "sentence_index": 0, "correct_answer": "抵抗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大型ロケットは、大きな抵抗を生んで、空へ勢いよく上がっていった。", "explanation": "ここは〈推進力〉の意味。機体を押し進める力は推進力で、〈抵抗〉は動きを妨げる力なので、押し上げる働きには使わない。"}, {"text": "急ブレーキをかけると、抵抗が働いて体が前に投げ出される。", "explanation": "ここは〈慣性〉の意味。動き続けようとする性質は慣性で、〈抵抗〉は動きを妨げる力なので、体を前へ投げ出す原因にはならない。"}, {"text": "祖父は、占領に対する人々の抵抗の歴史を語った。", "explanation": "ここは〈抵抗運動〉の意味。権力や占領に逆らう運動は抵抗運動で、〈抵抗〉は物の動きを妨げる力を表すので、この意味には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37614, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抵抗", "is_correct": true, "explanation": "車輪の回転を妨げる力を指し、「少なくなった」と合う。"}, {"text": "天気", "is_correct": false, "explanation": "空模様を表す語で、「車輪の回るときの天気が少なくなった」は成り立たない。"}, {"text": "名前", "is_correct": false, "explanation": "呼び名を表す語で、「車輪の回るときの名前が少なくなった」は意味をなさない。"}, {"text": "季節", "is_correct": false, "explanation": "時期を表す語で、「車輪の回るときの季節が少なくなった」は合わない。"}], "explanations": {"抵抗": "車輪の回転を妨げる力を指し、「少なくなった」と合う。", "天気": "空模様を表す語で、「車輪の回るときの天気が少なくなった」は成り立たない。", "名前": "呼び名を表す語で、「車輪の回るときの名前が少なくなった」は意味をなさない。", "季節": "時期を表す語で、「車輪の回るときの季節が少なくなった」は合わない。"}, "sentence_index": 6, "correct_answer": "抵抗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地球の抵抗で、ボールは地面へ落ちていく。", "explanation": "ここは〈引力〉の意味。物を地球の中心へ引く力は引力で、〈抵抗〉は動きを妨げる力なので、引き下げる働きには使わない。"}, {"text": "湯船の中では、抵抗で体がふわりと浮く。", "explanation": "ここは〈浮力〉の意味。水中で物を押し上げる力は浮力で、〈抵抗〉は動きを妨げる力なので、体を浮かせる働きには使わない。"}, {"text": "ひもでボールを回すと、抵抗で手が外へ引っぱられる。", "explanation": "ここは〈遠心力〉の意味。回る物を外へ引っぱる力は遠心力で、〈抵抗〉は動きを妨げる力なので、外へ引く働きには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37614, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "風の強い日は、傘の抵抗が大きなって、自転車がふらつく。", "corrected_sentence": "風の強い日は、傘の抵抗が大きくなって、自転車がふらつく。", "error_description": "形容詞「大きい」は連用形「大きく」＋「なって」が正しい。「大きなって」は活用の誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37614, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "坂道でブレーキを強くかけると、車輪に大きな抵抗を生じて、車が止まる。", "corrected_sentence": "坂道でブレーキを強くかけると、車輪に大きな抵抗が生じて、車が止まる。", "error_description": "「生じる」は自動詞なので、主語の「抵抗」には「が」を使う。「抵抗を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37615, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「抵抗が大きい」で、抵抗が主語になる。"}, {"text": "を", "is_correct": false, "explanation": "「抵抗を大きいので」は形容詞の主語にならず、文が成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、「抵抗へ大きいので」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列や引用の助詞で、「抵抗と大きいので」は文が成立しない。"}], "correct_answer": "が", "explanations": {"が": "「抵抗が大きい」で、抵抗が主語になる。", "を": "「抵抗を大きいので」は形容詞の主語にならず、文が成立しない。", "へ": "方向を表す助詞で、「抵抗へ大きいので」は成り立たない。", "と": "並列や引用の助詞で、「抵抗と大きいので」は文が成立しない。"}, "error_tags": {"を": "対象", "へ": "方向", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37615, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「抵抗を減らす」で、抵抗が目的語になる。"}, {"text": "が", "is_correct": false, "explanation": "「抵抗が減らす」では主語になり、「減らす」の目的語にならない。"}, {"text": "で", "is_correct": false, "explanation": "手段を表す助詞で、「抵抗で減らすために」は文として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "位置や相手を表す助詞で、「抵抗に減らすために」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「抵抗を減らす」で、抵抗が目的語になる。", "が": "「抵抗が減らす」では主語になり、「減らす」の目的語にならない。", "で": "手段を表す助詞で、「抵抗で減らすために」は文として成り立たない。", "に": "位置や相手を表す助詞で、「抵抗に減らすために」は文として成り立たない。"}, "error_tags": {"が": "主語", "で": "手段", "に": "位置"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37615, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物体の動きを妨げようとする力。特に、空気や水などの流体中を物体が進むときに受ける、進行方向とは逆向きの力。", "primary_collocate": null, "pronunciation": "ていこう", "ipa": "teːkoː", "syllable_count": 4, "sentences": [{"text": "速く走る電車は、空気の抵抗を小さくする形をしている。", "target_word": "抵抗", "complexity_tier": "T3", "furigana": "速[はや]く走[はし]る電車[でんしゃ]は、空気[くうき]の抵抗[ていこう]を小[ちい]さくする形[かたち]をしている。", "sentence_source": "generated"}, {"text": "水の抵抗が大きいので、プールの中では速く歩けない。", "target_word": "抵抗", "complexity_tier": "T3", "furigana": "水[みず]の抵抗[ていこう]が大[おお]きいので、プールの中[なか]では速[はや]く歩[ある]けない。", "sentence_source": "generated"}, {"text": "車の形を工夫して、風の抵抗を減らした。", "target_word": "抵抗", "complexity_tier": "T3", "furigana": "車[くるま]の形[かたち]を工夫[くふう]して、風[かぜ]の抵抗[ていこう]を減[へ]らした。", "sentence_source": "generated"}, {"text": "自転車で向かい風の中を走ると、空気の抵抗が強い。", "target_word": "抵抗", "complexity_tier": "T3", "furigana": "自転車[じてんしゃ]で向[む]かい風[かぜ]の中[なか]を走[はし]ると、空気[くうき]の抵抗[ていこう]が強[つよ]い。", "sentence_source": "generated"}, {"text": "魚の体は細長く、水の抵抗を受けにくい。", "target_word": "抵抗", "complexity_tier": "T3", "furigana": "魚[さかな]の体[からだ]は細長[ほそなが]く、水[みず]の抵抗[ていこう]を受[う]けにくい。", "sentence_source": "generated"}, {"text": "パラシュートは、空気の抵抗を大きくして、ゆっくり落ちる。", "target_word": "抵抗", "complexity_tier": "T3", "furigana": "パラシュートは、空気[くうき]の抵抗[ていこう]を大[おお]きくして、ゆっくり落[お]ちる。", "sentence_source": "generated"}, {"text": "飛行機の翼は、空気の抵抗を考えて作られている。", "target_word": "抵抗", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]の翼[つばさ]は、空気[くうき]の抵抗[ていこう]を考[かんが]えて作[つく]られている。", "sentence_source": "generated"}, {"text": "水泳選手は、水の抵抗を減らすために、特別な水着を着る。", "target_word": "抵抗", "complexity_tier": "T3", "furigana": "水泳[すいえい]選手[せんしゅ]は、水[みず]の抵抗[ていこう]を減[へ]らすために、特別[とくべつ]な水着[みずぎ]を着[き]る。", "sentence_source": "generated"}, {"text": "スピードが上がるほど、空気の抵抗も急に大きくなる。", "target_word": "抵抗", "complexity_tier": "T3", "furigana": "スピードが上[あ]がるほど、空気[くうき]の抵抗[ていこう]も急[きゅう]に大[おお]きくなる。", "sentence_source": "generated"}, {"text": "傘を広げて走ると、風から強い抵抗を受ける。", "target_word": "抵抗", "complexity_tier": "T3", "furigana": "傘[かさ]を広[ひろ]げて走[はし]ると、風[かぜ]から強[つよ]い抵抗[ていこう]を受[う]ける。", "sentence_source": "generated"}], "morphological_forms": [{"form": "抵抗", "label": "基本形"}, {"form": "抵抗が", "label": "主格"}, {"form": "抵抗を", "label": "目的格"}], "register": "普通体（説明的）", "sense_fingerprint": "空気や水の中を進む物体が受ける、進行方向と逆向きの力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd744feb5-cce0-45db-a3b7-f31e2c301cc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37615, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抵抗", "is_correct": true, "explanation": "進む物体が空気から受ける力を指し、小さくする形の文脈に合う。"}, {"text": "色", "is_correct": false, "explanation": "見た目の性質で、「空気の色を小さくする」は意味をなさない。"}, {"text": "名前", "is_correct": false, "explanation": "呼び名で、「空気の名前を小さくする」は成り立たない。"}, {"text": "季節", "is_correct": false, "explanation": "時期を表す語で、「空気の季節を小さくする」は合わない。"}], "explanations": {"抵抗": "進む物体が空気から受ける力を指し、小さくする形の文脈に合う。", "色": "見た目の性質で、「空気の色を小さくする」は意味をなさない。", "名前": "呼び名で、「空気の名前を小さくする」は成り立たない。", "季節": "時期を表す語で、「空気の季節を小さくする」は合わない。"}, "sentence_index": 0, "correct_answer": "抵抗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "強い追い風を帆に受けると、船は抵抗で前へ進む。", "explanation": "ここは〈推進力〉の意味。前へ進ませる力は推進力で、〈抵抗〉は進行方向と逆向きに働く力なので、船を前へ進める力には使わない。"}, {"text": "水の中では、抵抗で体が浮く。", "explanation": "ここは〈浮力〉の意味。水中で物を押し上げる力は浮力で、〈抵抗〉は進行方向と逆向きに働く力なので、体を浮かせる働きとは合わない。"}, {"text": "水中で物を離すと、抵抗で下へ沈んでいく。", "explanation": "ここは〈重力〉の意味。物を下へ引く力は重力で、〈抵抗〉は進行方向と逆向きに働く力なので、沈ませる働きには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37615, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抵抗", "is_correct": true, "explanation": "進む物体が空気から受ける力を指し、考えて作られる対象として合う。"}, {"text": "身長", "is_correct": false, "explanation": "人の体の長さで、「空気の身長を考えて作られている」は意味をなさない。"}, {"text": "年齢", "is_correct": false, "explanation": "人の年数で、「空気の年齢を考えて作られている」は成り立たない。"}, {"text": "誕生日", "is_correct": false, "explanation": "人の記念日で、「空気の誕生日を考えて作られている」は意味をなさない。"}], "explanations": {"抵抗": "進む物体が空気から受ける力を指し、考えて作られる対象として合う。", "身長": "人の体の長さで、「空気の身長を考えて作られている」は意味をなさない。", "年齢": "人の年数で、「空気の年齢を考えて作られている」は成り立たない。", "誕生日": "人の記念日で、「空気の誕生日を考えて作られている」は意味をなさない。"}, "sentence_index": 6, "correct_answer": "抵抗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このまな板は抵抗加工で、菌が増えにくい。", "explanation": "ここは〈抗菌〉の意味。菌の増殖を抑える加工は抗菌で、〈抵抗〉は動きを妨げる力を指すので、菌への働きには使わない。"}, {"text": "動いている物は、抵抗でしばらく進み続ける。", "explanation": "ここは〈慣性〉の意味。動き続けようとする性質は慣性で、〈抵抗〉は動きを妨げる力なので、進み続ける理由にはならない。"}, {"text": "この橋は、重い抵抗に耐えられるように作られている。", "explanation": "元の言い方は〈荷重〉。橋が支えるのは荷重で、〈抵抗〉は物の動きを妨げる力を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37615, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この車は、空気の抵抗を小さなするために、先端を細くしてある。", "corrected_sentence": "この車は、空気の抵抗を小さくするために、先端を細くしてある。", "error_description": "「小さくする」は形容詞の連用形「小さく」が必要。「小さなする」は活用の誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37615, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "向かい風が強いと、空気の抵抗に受けて、自転車のスピードが落ちる。", "corrected_sentence": "向かい風が強いと、空気の抵抗を受けて、自転車のスピードが落ちる。", "error_description": "「受ける」の目的語には「を」が必要。「抵抗に受ける」は助詞の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e8f94a-57eb-4070-a427-4784d52d32e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37616, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『日光』を受けるという、受ける動作の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "『が』は主語を示すため、『日光が受けて』は主語と動詞がかみ合わない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を表し、受けるの目的語にはならない。"}, {"text": "で", "is_correct": false, "explanation": "『で』は場所や手段を表し、目的語の『日光』を示せないので不自然。"}], "correct_answer": "を", "explanations": {"を": "『日光』を受けるという、受ける動作の目的語を示す。", "が": "『が』は主語を示すため、『日光が受けて』は主語と動詞がかみ合わない。", "へ": "『へ』は方向を表し、受けるの目的語にはならない。", "で": "『で』は場所や手段を表し、目的語の『日光』を示せないので不自然。"}, "error_tags": {"が": "主格（主語）", "へ": "方向", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37616, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『波』を受けるという、受ける動作の目的語を示す。"}, {"text": "に", "is_correct": false, "explanation": "『に』は帰着や相手を表し、『波に受けた』では受ける対象を示せず不自然。"}, {"text": "と", "is_correct": false, "explanation": "『と』は並列や相手を表し、受けるの目的語にはならない。"}, {"text": "の", "is_correct": false, "explanation": "『の』は所有や修飾を表し、『波の受けた船』は文の意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "『波』を受けるという、受ける動作の目的語を示す。", "に": "『に』は帰着や相手を表し、『波に受けた』では受ける対象を示せず不自然。", "と": "『と』は並列や相手を表し、受けるの目的語にはならない。", "の": "『の』は所有や修飾を表し、『波の受けた船』は文の意味が通らない。"}, "error_tags": {"に": "相手・位置", "と": "並列・相手", "の": "所有・修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37616, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かが自分に来たり、当たったりすることを言う。", "primary_collocate": null, "pronunciation": "うける", "ipa": "ɯkeɾɯ", "syllable_count": 3, "sentences": [{"text": "帆は風を受けて、大きくふくらんだ。", "target_word": "受けて", "complexity_tier": "T3", "furigana": "帆[ほ]は風[かぜ]を受[う]けて、大[おお]きくふくらんだ。", "sentence_source": "generated"}, {"text": "ひまわりは日光を受けて、大きく育つ。", "target_word": "受けて", "complexity_tier": "T3", "furigana": "ひまわりは日光[にっこう]を受[う]けて、大[おお]きく育[そだ]つ。", "sentence_source": "generated"}, {"text": "キーパーは強いボールを両手で受けた。", "target_word": "受けた", "complexity_tier": "T3", "furigana": "キーパーは強[つよ]いボールを両手[りょうて]で受[う]けた。", "sentence_source": "generated"}, {"text": "雨どいは屋根の雨水を受けて、タンクに流す。", "target_word": "受けて", "complexity_tier": "T3", "furigana": "雨[あま]どいは屋根[やね]の雨水[あまみず]を受[う]けて、タンクに流[なが]す。", "sentence_source": "generated"}, {"text": "彼は後ろからの衝撃を受けて、前に倒れた。", "target_word": "受けて", "complexity_tier": "T3", "furigana": "彼[かれ]は後[うし]ろからの衝撃[しょうげき]を受[う]けて、前[まえ]に倒[たお]れた。", "sentence_source": "generated"}, {"text": "窓ガラスが朝日を受けて、きらきら光っている。", "target_word": "受けて", "complexity_tier": "T3", "furigana": "窓[まど]ガラスが朝日[あさひ]を受[う]けて、きらきら光[ひか]っている。", "sentence_source": "generated"}, {"text": "バケツで天井から落ちる水を受けた。", "target_word": "受けた", "complexity_tier": "T3", "furigana": "バケツで天井[てんじょう]から落[お]ちる水[みず]を受[う]けた。", "sentence_source": "generated"}, {"text": "大きな波を受けた船が、激しくゆれた。", "target_word": "受けた", "complexity_tier": "T3", "furigana": "大[おお]きな波[なみ]を受[う]けた船[ふね]が、激[はげ]しくゆれた。", "sentence_source": "generated"}, {"text": "ボールを受ける前に、まわりをよく見た。", "target_word": "受ける", "complexity_tier": "T3", "furigana": "ボールを受[う]ける前[まえ]に、まわりをよく見[み]た。", "sentence_source": "generated"}, {"text": "坂の上の家は、夏の強い西日を受ける。", "target_word": "受ける", "complexity_tier": "T3", "furigana": "坂[さか]の上[うえ]の家[いえ]は、夏[なつ]の強[つよ]い西日[にしび]を受[う]ける。", "sentence_source": "generated"}], "morphological_forms": [{"form": "受けない", "label": "否定形"}, {"form": "受けます", "label": "丁寧形"}, {"form": "受けて", "label": "て形"}, {"form": "受けた", "label": "た形"}, {"form": "受ければ", "label": "仮定形"}, {"form": "受けられる", "label": "可能形"}], "register": "中立（常体）", "sense_fingerprint": "飛んで来たり当たったりするものを、物や体で受け止める", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: ふくらん (Zipf 2.47)','sentence 9 above tier T2: contains vocabulary far above tier T2: 西日 (Zipf 2.34)']::text[], 'e0e12dd3-c77b-4d9e-9498-0161804d2652') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37616, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "受けて", "is_correct": true, "explanation": "「風を受け止めて帆がふくらむ」という文脈に合う、正しい形。"}, {"text": "嫌って", "is_correct": false, "explanation": "「風を嫌う」は帆の動きとしてつながらず、ふくらむ結果の説明にならない。"}, {"text": "数えて", "is_correct": false, "explanation": "「風を数える」は物理的にも文脈にも合わない。"}, {"text": "断って", "is_correct": false, "explanation": "「風を断る」は帆の動きとして不自然で、ふくらむ理由にならない。"}], "explanations": {"受けて": "「風を受け止めて帆がふくらむ」という文脈に合う、正しい形。", "嫌って": "「風を嫌う」は帆の動きとしてつながらず、ふくらむ結果の説明にならない。", "数えて": "「風を数える」は物理的にも文脈にも合わない。", "断って": "「風を断る」は帆の動きとして不自然で、ふくらむ理由にならない。"}, "sentence_index": 0, "correct_answer": "受けて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "台所でガスを受けて、湯をわかした。", "explanation": "ここは〈使う〉の意味。受けるは外から来るものを受け止める語で、ガスのような資源を使う意味では使わない。"}, {"text": "重いドアを受けて、そっと中へ入った。", "explanation": "ここは〈押す〉の意味。受けるは外から来るものを受け止める語で、ドアを押し開ける動作には使わない。"}, {"text": "机を受けて、教室の端へ寄せた。", "explanation": "ここは〈動かす〉の意味。受けるは外から来るものを受け止める語で、机を自分で移動させる動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37616, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "受けた", "is_correct": true, "explanation": "『天井から落ちる水を受け止めた』という動作として、文が完結する正しい形。"}, {"text": "洗った", "is_correct": false, "explanation": "『水を洗う』は動作として成立せず、文脈とも合わない。"}, {"text": "煮た", "is_correct": false, "explanation": "天井から落ちる水を煮ることはできず、文として意味が通らない。"}, {"text": "叩いた", "is_correct": false, "explanation": "水を叩くという動作は、落ちてくる水を受け止めるという文脈と合わない。"}], "explanations": {"受けた": "『天井から落ちる水を受け止めた』という動作として、文が完結する正しい形。", "洗った": "『水を洗う』は動作として成立せず、文脈とも合わない。", "煮た": "天井から落ちる水を煮ることはできず、文として意味が通らない。", "叩いた": "水を叩くという動作は、落ちてくる水を受け止めるという文脈と合わない。"}, "sentence_index": 6, "correct_answer": "受けた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "念願の子どもを受けて、夫婦で喜んだ。", "explanation": "ここは〈授かる〉の意味。受けるは外から来るものを受け止める語で、人を授かる意味では使わない。"}, {"text": "社長の話を受けて、契約書に判を押した。", "explanation": "ここは〈承諾する〉の意味。持ちかけられた話に応じる意味で、物や体に当たる意味とは別。"}, {"text": "雨の日は帽子を受けて出かけた。", "explanation": "ここは〈かぶる〉の意味。頭に身につけるものには『受ける』は使わず、外から来るものを受け止める語として合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37616, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "船は風に受けて、大きく進んだ。", "corrected_sentence": "船は風を受けて、大きく進んだ。", "error_description": "『受ける』の対象は『を』で示す。『風に』は誤りで、正しくは『風を受けて』。『に』は場所や方向を表す助詞なので目的語には使えない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "受けて", "is_correct": true, "explanation": "文をつなぐ『て形』。『日光を受けて、大きく育つ』と後ろの文に続く形として正しい。"}, {"text": "受けない", "is_correct": false, "explanation": "否定形なので、日光を受けて育つという肯定の流れと合わない。"}, {"text": "受けた", "is_correct": false, "explanation": "た形は完了・過去を表し、後半の現在の『育つ』の流れに合わない。"}, {"text": "受けます", "is_correct": false, "explanation": "丁寧形で、常体の文の中では浮いてしまう。"}], "correct_form": "受けて", "base_form": "受ける", "form_label": "て形", "sentence_index": 1, "explanations": {"受けて": "文をつなぐ『て形』。『日光を受けて、大きく育つ』と後ろの文に続く形として正しい。", "受けない": "否定形なので、日光を受けて育つという肯定の流れと合わない。", "受けた": "た形は完了・過去を表し、後半の現在の『育つ』の流れに合わない。", "受けます": "丁寧形で、常体の文の中では浮いてしまう。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37616, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "鍋で天井から落ちる水に受けた。", "corrected_sentence": "鍋で天井から落ちる水を受けた。", "error_description": "『受ける』の目的語は『を』で示す。『水に』は誤りで、正しくは『水を受けた』。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "受けた", "is_correct": true, "explanation": "過去の出来事を表すた形で、後ろの『ゆれた』と時制がそろう。"}, {"text": "受けたい", "is_correct": false, "explanation": "願望形なので、波を受けたがる船が揺れたという内容になり、実際の出来事と合わない。"}, {"text": "受ければ", "is_correct": false, "explanation": "仮定形なので、もしも波を受けたら、という仮定の文になり、実際に起きた出来事と合わない。"}, {"text": "受けよう", "is_correct": false, "explanation": "意志形なので、船が自分から波を受けようとしたという意味になり、事実の描写と合わない。"}], "correct_form": "受けた", "base_form": "受ける", "form_label": "た形", "sentence_index": 7, "explanations": {"受けた": "過去の出来事を表すた形で、後ろの『ゆれた』と時制がそろう。", "受けたい": "願望形なので、波を受けたがる船が揺れたという内容になり、実際の出来事と合わない。", "受ければ": "仮定形なので、もしも波を受けたら、という仮定の文になり、実際に起きた出来事と合わない。", "受けよう": "意志形なので、船が自分から波を受けようとしたという意味になり、事実の描写と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37617, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『検査』を受けるという、受ける動作の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "『検査が受けた』では主語と動詞の関係が合わず、不自然。"}, {"text": "に", "is_correct": false, "explanation": "『に』は帰着や相手を表し、『検査に受けた』は受ける対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を表し、『検査へ受けた』は目的語として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "『検査』を受けるという、受ける動作の目的語を示す。", "が": "『検査が受けた』では主語と動詞の関係が合わず、不自然。", "に": "『に』は帰着や相手を表し、『検査に受けた』は受ける対象を示せない。", "へ": "『へ』は方向を表し、『検査へ受けた』は目的語として成り立たない。"}, "error_tags": {"が": "主格（主語）", "に": "相手・位置", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "与える", "is_correct": true, "explanation": "『指導を受ける』の対義語。先輩が与える側、新入社員が受ける側という関係になる。"}, {"text": "眠る", "is_correct": false, "explanation": "休息を表す語で、受けるとは対義関係にない。"}, {"text": "歩く", "is_correct": false, "explanation": "移動を表す語で、受けるの対義語にはならない。"}, {"text": "泣く", "is_correct": false, "explanation": "感情の表出を表す語で、受けるとは対義関係にない。"}], "correct_answer": "与える", "explanations": {"与える": "『指導を受ける』の対義語。先輩が与える側、新入社員が受ける側という関係になる。", "眠る": "休息を表す語で、受けるとは対義関係にない。", "歩く": "移動を表す語で、受けるの対義語にはならない。", "泣く": "感情の表出を表す語で、受けるとは対義関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37617, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『注意』を受けるという、受ける動作の目的語を示す。"}, {"text": "で", "is_correct": false, "explanation": "『で』は場所や手段を表し、『注意で受けた』は目的語として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "『と』は並列や相手を表し、『注意と受けた』は意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "『の』は所有や修飾を表し、『注意の受けた』は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "『注意』を受けるという、受ける動作の目的語を示す。", "で": "『で』は場所や手段を表し、『注意で受けた』は目的語として成り立たない。", "と": "『と』は並列や相手を表し、『注意と受けた』は意味が通らない。", "の": "『の』は所有や修飾を表し、『注意の受けた』は文として成り立たない。"}, "error_tags": {"で": "場所・手段", "と": "並列・相手", "の": "所有・修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37617, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "外部から何か作用や影響が自分に向かって来て、それを体に感じたり、自分に向けて得たりすること。", "primary_collocate": null, "pronunciation": "うける", "ipa": "ɯkeɾɯ", "syllable_count": 3, "sentences": [{"text": "兄の影響を受けて、私もギターを始めた。", "target_word": "受けて", "complexity_tier": "T3", "furigana": "兄[あに]の影響[えいきょう]を受[う]けて、私[わたし]もギターを始[はじ]めた。", "sentence_source": "generated"}, {"text": "母は病院で検査を受けた。", "target_word": "受けた", "complexity_tier": "T3", "furigana": "母[はは]は病院[びょういん]で検査[けんさ]を受[う]けた。", "sentence_source": "generated"}, {"text": "台風の被害を受けた町に、支援が届いた。", "target_word": "受けた", "complexity_tier": "T3", "furigana": "台風[たいふう]の被害[ひがい]を受[う]けた町[まち]に、支援[しえん]が届[とど]いた。", "sentence_source": "generated"}, {"text": "新入社員は先輩から指導を受ける。", "target_word": "受ける", "complexity_tier": "T3", "furigana": "新入社員[しんにゅうしゃいん]は先輩[せんぱい]から指導[しどう]を受[う]ける。", "sentence_source": "generated"}, {"text": "彼の話を聞いて、強い刺激を受けた。", "target_word": "受けた", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はなし]を聞[き]いて、強[つよ]い刺激[しげき]を受[う]けた。", "sentence_source": "generated"}, {"text": "祖父は来月、手術を受ける予定だ。", "target_word": "受ける", "complexity_tier": "T3", "furigana": "祖父[そふ]は来月[らいげつ]、手術[しゅじゅつ]を受[う]ける予定[よてい]だ。", "sentence_source": "generated"}, {"text": "この国では、子どもたちは無料で教育を受けられる。", "target_word": "受けられる", "complexity_tier": "T3", "furigana": "この国[くに]では、子[こ]どもたちは無料[むりょう]で教育[きょういく]を受[う]けられる。", "sentence_source": "generated"}, {"text": "その店は先月、保健所から注意を受けた。", "target_word": "受けた", "complexity_tier": "T3", "furigana": "その店[みせ]は先月[せんげつ]、保健所[ほけんじょ]から注意[ちゅうい]を受[う]けた。", "sentence_source": "generated"}, {"text": "この作品は国内外で高い評価を受けている。", "target_word": "受けている", "complexity_tier": "T3", "furigana": "この作品[さくひん]は国内外[こくないがい]で高[たか]い評価[ひょうか]を受[う]けている。", "sentence_source": "generated"}, {"text": "私は毎週、ピアノのレッスンを受けている。", "target_word": "受けている", "complexity_tier": "T3", "furigana": "私[わたし]は毎週[まいしゅう]、ピアノのレッスンを受[う]けている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "受けない", "label": "否定形"}, {"form": "受けます", "label": "丁寧形"}, {"form": "受けて", "label": "て形"}, {"form": "受けた", "label": "た形"}, {"form": "受ければ", "label": "仮定形"}, {"form": "受けられる", "label": "可能形"}], "register": "中立（常体）", "sense_fingerprint": "影響・刺激・治療・指導などを外から自分に向けて得たり感じたりする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0e12dd3-c77b-4d9e-9498-0161804d2652') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37617, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "受けて", "is_correct": true, "explanation": "影響を受けて行動が変わる、という文脈に合う正しい形。"}, {"text": "数えて", "is_correct": false, "explanation": "『影響を数える』とは言えず、文の流れが合わない。"}, {"text": "運んで", "is_correct": false, "explanation": "『影響を運ぶ』は文脈に合わず、ギターを始める理由にならない。"}, {"text": "磨いて", "is_correct": false, "explanation": "『影響を磨く』は不自然で、ギターを始めた理由の説明にならない。"}], "explanations": {"受けて": "影響を受けて行動が変わる、という文脈に合う正しい形。", "数えて": "『影響を数える』とは言えず、文の流れが合わない。", "運んで": "『影響を運ぶ』は文脈に合わず、ギターを始める理由にならない。", "磨いて": "『影響を磨く』は不自然で、ギターを始めた理由の説明にならない。"}, "sentence_index": 0, "correct_answer": "受けて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "前の車を受けて、速度を上げた。", "explanation": "ここは〈追い越す〉の意味。受けるは外から来るものを受け止める語で、前の車を抜く動作には使わない。"}, {"text": "ボタンを受けて、エレベーターを呼んだ。", "explanation": "ここは〈押す〉の意味。受けるは外から来るものを受け止める語で、ボタンを押して操作する動作には使わない。"}, {"text": "空を受けて、ぼんやり眺めた。", "explanation": "ここは〈眺める〉の意味。受けるは外から来るものを受け止める語で、景色を見渡す動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37617, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "受けられる", "is_correct": true, "explanation": "可能形で、無料で教育を受ける機会があるという文脈に合う。"}, {"text": "建てられる", "is_correct": false, "explanation": "『教育を建てる』とは言えず、意味が通らない。"}, {"text": "割られる", "is_correct": false, "explanation": "『教育を割る』という動作は文脈に合わない。"}, {"text": "焼かれる", "is_correct": false, "explanation": "『教育を焼く』という表現はなく、文として成立しない。"}], "explanations": {"受けられる": "可能形で、無料で教育を受ける機会があるという文脈に合う。", "建てられる": "『教育を建てる』とは言えず、意味が通らない。", "割られる": "『教育を割る』という動作は文脈に合わない。", "焼かれる": "『教育を焼く』という表現はなく、文として成立しない。"}, "sentence_index": 6, "correct_answer": "受けられる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父は会社の転勤の話を受けた。", "explanation": "ここは〈承諾する〉の意味。持ちかけられた話に応じる意味で、外から作用を受ける意味とは別。"}, {"text": "先生は来年度の学年主任を受けた。", "explanation": "ここは〈引き受ける〉の意味。役目を引き受ける意味で、外からの作用を感じる意味とは別。"}, {"text": "祖父はテストで百点を受けた。", "explanation": "ここは〈取る〉の意味。受けるは外から来るものを受け止める語で、点数を獲得する意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37617, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姉の影響に受けて、私もピアノを始めた。", "corrected_sentence": "姉の影響を受けて、私もピアノを始めた。", "error_description": "『受ける』の対象である『影響』は『を』で示す。『影響に』は誤りで、正しくは『影響を受けて』。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "受けた", "is_correct": true, "explanation": "過去の完了を表すた形で、『病院で検査を受けた』という出来事と合う。"}, {"text": "受けない", "is_correct": false, "explanation": "否定形なので、検査を受けなかったという逆の内容になり合わない。"}, {"text": "受けます", "is_correct": false, "explanation": "丁寧形で、常体の文の中では浮いてしまう。"}, {"text": "受けて", "is_correct": false, "explanation": "て形は文を続ける形なので、文末の『た』がなく文が終わらない。"}], "correct_form": "受けた", "base_form": "受ける", "form_label": "た形", "sentence_index": 1, "explanations": {"受けた": "過去の完了を表すた形で、『病院で検査を受けた』という出来事と合う。", "受けない": "否定形なので、検査を受けなかったという逆の内容になり合わない。", "受けます": "丁寧形で、常体の文の中では浮いてしまう。", "受けて": "て形は文を続ける形なので、文末の『た』がなく文が終わらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37617, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その店は先週、保健所から注意に受けた。", "corrected_sentence": "その店は先週、保健所から注意を受けた。", "error_description": "『受ける』の目的語である『注意』は『を』で示す。『注意に』は誤りで、正しくは『注意を受けた』。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "受けた", "is_correct": true, "explanation": "過去の出来事を表すた形で、保健所から注意があったという事実と合う。"}, {"text": "受けられる", "is_correct": false, "explanation": "可能形なので、注意を受ける力や機会の話になり、事実の報告と合わない。"}, {"text": "受ければ", "is_correct": false, "explanation": "仮定形なので、事実を述べる文には合わない。"}, {"text": "受けよう", "is_correct": false, "explanation": "意志形なので、店が自分から注意を受けようとする意味になり、報告の内容と合わない。"}], "correct_form": "受けた", "base_form": "受ける", "form_label": "た形", "sentence_index": 7, "explanations": {"受けた": "過去の出来事を表すた形で、保健所から注意があったという事実と合う。", "受けられる": "可能形なので、注意を受ける力や機会の話になり、事実の報告と合わない。", "受ければ": "仮定形なので、事実を述べる文には合わない。", "受けよう": "意志形なので、店が自分から注意を受けようとする意味になり、報告の内容と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37618, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『抗力』を小さくするという、動作の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "『抗力が小さくする』は目的語を示せず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "『抗力に小さくする』は不自然で、動作の対象を示せない。"}, {"text": "で", "is_correct": false, "explanation": "『で』は手段を表し、『抗力で小さくする』は目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "『抗力』を小さくするという、動作の目的語を示す。", "が": "『抗力が小さくする』は目的語を示せず、文が成り立たない。", "に": "『抗力に小さくする』は不自然で、動作の対象を示せない。", "で": "『で』は手段を表し、『抗力で小さくする』は目的語にならない。"}, "error_tags": {"が": "主格（主語）", "に": "相手・位置", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37618, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『抗力』を減らすという、動作の目的語を示す。"}, {"text": "と", "is_correct": false, "explanation": "『と』は並列や相手を表し、減らす対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を表し、『抗力へ減らす』は目的語として成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "『より』は比較や起点を表し、『抗力より減らす』は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "『抗力』を減らすという、動作の目的語を示す。", "と": "『と』は並列や相手を表し、減らす対象を示せない。", "へ": "『へ』は方向を表し、『抗力へ減らす』は目的語として成り立たない。", "より": "『より』は比較や起点を表し、『抗力より減らす』は意味が通らない。"}, "error_tags": {"と": "並列・相手", "へ": "方向", "より": "比較・起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37618, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物が空気や水の中を動くときに、進むのをじゃまする力のことです。", "primary_collocate": null, "pronunciation": "こうりょく", "ipa": "koːɾʲokɯ", "syllable_count": 4, "sentences": [{"text": "水の中を走ると、空気の中より抗力が大きいので、速く進めない。", "target_word": "抗力", "complexity_tier": "T3", "furigana": "水[みず]の中[なか]を走[はし]ると、空気[くうき]の中[なか]より抗力[こうりょく]が大[おお]きいので、速[はや]く進[すす]めない。", "sentence_source": "generated"}, {"text": "飛行機は、抗力を小さくするために、細長い形をしている。", "target_word": "抗力", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]は、抗力[こうりょく]を小[ちい]さくするために、細長[ほそなが]い形[かたち]をしている。", "sentence_source": "generated"}, {"text": "自転車で風に向かって走ると、抗力を強く感じて、足が重くなる。", "target_word": "抗力", "complexity_tier": "T3", "furigana": "自転車[じてんしゃ]で風[かぜ]に向[む]かって走[はし]ると、抗力[こうりょく]を強[つよ]く感[かん]じて、足[あし]が重[おも]くなる。", "sentence_source": "generated"}, {"text": "傘を開いて落とすと、空気の抗力が大きいので、ゆっくり落ちる。", "target_word": "抗力", "complexity_tier": "T3", "furigana": "傘[かさ]を開[ひら]いて落[お]とすと、空気[くうき]の抗力[こうりょく]が大[おお]きいので、ゆっくり落[お]ちる。", "sentence_source": "generated"}, {"text": "魚の体は、水の抗力を受けにくい形になっている。", "target_word": "抗力", "complexity_tier": "T3", "furigana": "魚[さかな]の体[からだ]は、水[みず]の抗力[こうりょく]を受[う]けにくい形[かたち]になっている。", "sentence_source": "generated"}, {"text": "プールで手を広げて歩くと、水の抗力で前に進みにくい。", "target_word": "抗力", "complexity_tier": "T3", "furigana": "プールで手[て]を広[ひろ]げて歩[ある]くと、水[みず]の抗力[こうりょく]で前[まえ]に進[すす]みにくい。", "sentence_source": "generated"}, {"text": "速く走る車ほど、空気から受ける抗力は大きくなる。", "target_word": "抗力", "complexity_tier": "T3", "furigana": "速[はや]く走[はし]る車[くるま]ほど、空気[くうき]から受[う]ける抗力[こうりょく]は大[おお]きくなる。", "sentence_source": "generated"}, {"text": "水泳選手は、抗力を減らすために、体をまっすぐにして泳ぐ。", "target_word": "抗力", "complexity_tier": "T3", "furigana": "水泳[すいえい]選手[せんしゅ]は、抗力[こうりょく]を減[へ]らすために、体[からだ]をまっすぐにして泳[およ]ぐ。", "sentence_source": "generated"}, {"text": "パラシュートは、空気の抗力を利用して落ちる速さを抑える。", "target_word": "抗力", "complexity_tier": "T3", "furigana": "パラシュートは、空気[くうき]の抗力[こうりょく]を利用[りよう]して落[お]ちる速[はや]さを抑[おさ]える。", "sentence_source": "generated"}, {"text": "球が速く飛ぶほど、空気の抗力も大きくなり、だんだん遅くなる。", "target_word": "抗力", "complexity_tier": "T3", "furigana": "球[たま]が速[はや]く飛[と]ぶほど、空気[くうき]の抗力[こうりょく]も大[おお]きくなり、だんだん遅[おそ]くなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "抗力", "label": "基本形"}], "register": "平易な書き言葉（常体）", "sense_fingerprint": "空気や水の中で、動く物の進みをじゃまする力（日常的な説明）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0e12dd3-c77b-4d9e-9498-0161804d2652') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37618, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抗力", "is_correct": true, "explanation": "流体の中で進むのをじゃまする力で、速く進めない理由として正しい語。"}, {"text": "速さ", "is_correct": false, "explanation": "速さは動く速度で、大きいと進みにくくなるという因果関係に合わない。"}, {"text": "電圧", "is_correct": false, "explanation": "電圧は電気の強さで、水や空気の中での進みにくさを表せない。"}, {"text": "温度", "is_correct": false, "explanation": "温度は熱さの程度で、進みにくさの原因として使える語ではない。"}], "explanations": {"抗力": "流体の中で進むのをじゃまする力で、速く進めない理由として正しい語。", "速さ": "速さは動く速度で、大きいと進みにくくなるという因果関係に合わない。", "電圧": "電圧は電気の強さで、水や空気の中での進みにくさを表せない。", "温度": "温度は熱さの程度で、進みにくさの原因として使える語ではない。"}, "sentence_index": 0, "correct_answer": "抗力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "電流を流すと、導線の抗力で熱が出る。", "explanation": "ここは〈電気抵抗〉の意味。抗力は流体中で進みを妨げる力で、電流の流れには使わない。"}, {"text": "ブレーキの抗力で、車がだんだん止まった。", "explanation": "ここは〈摩擦〉の意味。接触面で生じる力は摩擦で、流体中の抵抗を表す抗力とは区別する。"}, {"text": "水中に沈めた物体には、上向きの抗力がはたらく。", "explanation": "ここは〈浮力〉の意味。上向きに押す力は浮力で、進行方向と逆向きにはたらく抗力とは別。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37618, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抗力", "is_correct": true, "explanation": "流体の中で進むのをじゃまする力で、速く走るほど大きくなるという内容に合う。"}, {"text": "出力", "is_correct": false, "explanation": "出力は機械が出す仕事の量で、空気から受ける力の大きさには使えない。"}, {"text": "音量", "is_correct": false, "explanation": "音量は音の大きさで、空気から受ける力を表す語ではない。"}, {"text": "体積", "is_correct": false, "explanation": "体積は物の占める大きさで、受ける力が大きくなる理由にならない。"}], "explanations": {"抗力": "流体の中で進むのをじゃまする力で、速く走るほど大きくなるという内容に合う。", "出力": "出力は機械が出す仕事の量で、空気から受ける力の大きさには使えない。", "音量": "音量は音の大きさで、空気から受ける力を表す語ではない。", "体積": "体積は物の占める大きさで、受ける力が大きくなる理由にならない。"}, "sentence_index": 6, "correct_answer": "抗力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寝不足が続いて、体の抗力が落ちた。", "explanation": "ここは〈免疫力〉の意味。病気に負けない体の力は免疫力で、流体中の抵抗を表す抗力とは別。"}, {"text": "長い階段で、すっかり抗力を使い果たした。", "explanation": "ここは〈体力〉の意味。体を動かす力は体力で、抗力は流体中で進むのを妨げる力を指す。"}, {"text": "試験中は抗力が切れて、ミスが増えた。", "explanation": "ここは〈集中力〉の意味。注意を保つ力は集中力で、抗力の語義とは関係ない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37618, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "船は水の中で抗力に大きくなり、進みにくい。", "corrected_sentence": "船は水の中で抗力が大きくなり、進みにくい。", "error_description": "『大きくなる』の主語は『抗力が』。『抗力に』は誤りで、正しくは『抗力が大きくなり』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37618, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "スキーヤーは、抗力で減らすために、姿勢を低くして滑る。", "corrected_sentence": "スキーヤーは、抗力を減らすために、姿勢を低くして滑る。", "error_description": "『減らす』の目的語である『抗力』は『を』で示す。『抗力で』は誤りで、正しくは『抗力を減らすために』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37619, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "も", "options": [{"text": "も", "is_correct": true, "explanation": "『抗力』も大きくなるという、加えて言う意味を示す。"}, {"text": "を", "is_correct": false, "explanation": "『抗力を大きくなる』は目的語を取れない自動詞の形で、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "『抗力に大きくなる』は不自然で、帰着を表す形として合わない。"}, {"text": "で", "is_correct": false, "explanation": "『で』は手段を表し、『抗力で大きくなる』は意味が通らない。"}], "correct_answer": "も", "explanations": {"も": "『抗力』も大きくなるという、加えて言う意味を示す。", "を": "『抗力を大きくなる』は目的語を取れない自動詞の形で、文が成り立たない。", "に": "『抗力に大きくなる』は不自然で、帰着を表す形として合わない。", "で": "『で』は手段を表し、『抗力で大きくなる』は意味が通らない。"}, "error_tags": {"を": "目的語（対象）", "に": "相手・位置", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37619, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "『抗力』について小さいと述べる主題を示す。"}, {"text": "と", "is_correct": false, "explanation": "『と』は並列や相手を表し、『抗力と小さい』は文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を表し、『抗力へ小さい』は不自然で意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "『から』は起点を表し、『抗力から小さい』は意味が通らない。"}], "correct_answer": "は", "explanations": {"は": "『抗力』について小さいと述べる主題を示す。", "と": "『と』は並列や相手を表し、『抗力と小さい』は文が成り立たない。", "へ": "『へ』は方向を表し、『抗力へ小さい』は不自然で意味が通らない。", "から": "『から』は起点を表し、『抗力から小さい』は意味が通らない。"}, "error_tags": {"と": "並列・相手", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37619, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物体が流体（空気や水）の中を移動する際に、進行方向と逆向きに働く抵抗力。", "primary_collocate": null, "pronunciation": "こうりょく", "ipa": "koːɾʲokɯ", "syllable_count": 4, "sentences": [{"text": "流体中を動く物体には、進行方向と逆向きの抗力がはたらく。", "target_word": "抗力", "complexity_tier": "T3", "furigana": "流体[りゅうたい]中[ちゅう]を動[うご]く物体[ぶったい]には、進行[しんこう]方向[ほうこう]と逆[ぎゃく]向[む]きの抗力[こうりょく]がはたらく。", "sentence_source": "generated"}, {"text": "物体の速さが増すと、受ける抗力も大きくなる。", "target_word": "抗力", "complexity_tier": "T3", "furigana": "物体[ぶったい]の速[はや]さが増[ま]すと、受[う]ける抗力[こうりょく]も大[おお]きくなる。", "sentence_source": "generated"}, {"text": "新幹線の先頭車両は、抗力を減らすために流線形に設計されている。", "target_word": "抗力", "complexity_tier": "T3", "furigana": "新幹線[しんかんせん]の先頭[せんとう]車両[しゃりょう]は、抗力[こうりょく]を減[へ]らすために流線形[りゅうせんけい]に設計[せっけい]されている。", "sentence_source": "generated"}, {"text": "雨粒は、重力と空気の抗力がつり合うと、一定の速さで落下する。", "target_word": "抗力", "complexity_tier": "T3", "furigana": "雨粒[あめつぶ]は、重力[じゅうりょく]と空気[くうき]の抗力[こうりょく]がつり合[あ]うと、一定[いってい]の速[はや]さで落下[らっか]する。", "sentence_source": "generated"}, {"text": "抗力は、物体の形や表面の状態によって大きく変わる。", "target_word": "抗力", "complexity_tier": "T3", "furigana": "抗力[こうりょく]は、物体[ぶったい]の形[かたち]や表面[ひょうめん]の状態[じょうたい]によって大[おお]きく変[か]わる。", "sentence_source": "generated"}, {"text": "潜水艦は、水の抗力に打ち勝つだけの推進力を必要とする。", "target_word": "抗力", "complexity_tier": "T3", "furigana": "潜水艦[せんすいかん]は、水[みず]の抗力[こうりょく]に打[う]ち勝[か]つだけの推進力[すいしんりょく]を必要[ひつよう]とする。", "sentence_source": "generated"}, {"text": "実験では、風洞に模型を置いて抗力を測定した。", "target_word": "抗力", "complexity_tier": "T3", "furigana": "実験[じっけん]では、風洞[ふうどう]に模型[もけい]を置[お]いて抗力[こうりょく]を測定[そくてい]した。", "sentence_source": "generated"}, {"text": "球体より流線形のほうが、受ける抗力は小さい。", "target_word": "抗力", "complexity_tier": "T3", "furigana": "球体[きゅうたい]より流線形[りゅうせんけい]のほうが、受[う]ける抗力[こうりょく]は小[ちい]さい。", "sentence_source": "generated"}, {"text": "空気の密度が低い高所では、航空機が受ける抗力も小さくなる。", "target_word": "抗力", "complexity_tier": "T3", "furigana": "空気[くうき]の密度[みつど]が低[ひく]い高所[こうしょ]では、航空機[こうくうき]が受[う]ける抗力[こうりょく]も小[ちい]さくなる。", "sentence_source": "generated"}, {"text": "設計者は、燃費を改善するため、車体の抗力を二割下げた。", "target_word": "抗力", "complexity_tier": "T3", "furigana": "設計者[せっけいしゃ]は、燃費[ねんぴ]を改善[かいぜん]するため、車体[しゃたい]の抗力[こうりょく]を二割[にわり]下[さ]げた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "抗力", "label": "基本形"}], "register": "学術的な書き言葉（常体）", "sense_fingerprint": "流体中を動く物体が受ける、進行方向と逆向きの抵抗力（物理・工学の用語）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0e12dd3-c77b-4d9e-9498-0161804d2652') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37619, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抗力", "is_correct": true, "explanation": "進行方向と逆向きにはたらく抵抗力を指す、正しい物理用語。"}, {"text": "推力", "is_correct": false, "explanation": "推力は進行方向に押す力で、『逆向き』という条件と矛盾する。"}, {"text": "慣性", "is_correct": false, "explanation": "慣性は物体が動き続けようとする性質で、はたらく力ではないので合わない。"}, {"text": "電圧", "is_correct": false, "explanation": "電圧は電気の押す力で、物体の運動に逆らう力としては使えない。"}], "explanations": {"抗力": "進行方向と逆向きにはたらく抵抗力を指す、正しい物理用語。", "推力": "推力は進行方向に押す力で、『逆向き』という条件と矛盾する。", "慣性": "慣性は物体が動き続けようとする性質で、はたらく力ではないので合わない。", "電圧": "電圧は電気の押す力で、物体の運動に逆らう力としては使えない。"}, "sentence_index": 0, "correct_answer": "抗力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "エンジンの抗力で、飛行機が前へ進んだ。", "explanation": "ここは〈推力〉の意味。抗力は進行方向と逆向きにはたらく力で、前へ進める力を指す語ではない。"}, {"text": "ロープの抗力で、荷物を引き上げた。", "explanation": "ここは〈張力〉の意味。ロープ内を伝わる引っ張りの力は張力で、抗力ではない。"}, {"text": "水の抗力が、船体の側面を押した。", "explanation": "ここは〈圧力〉の意味。面に垂直にかかる押す力は圧力で、進行方向と逆向きの抗力とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37619, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抗力", "is_correct": true, "explanation": "風洞で模型にはたらく抵抗力を測定する文脈に合う正しい物理用語。"}, {"text": "味", "is_correct": false, "explanation": "味は感覚の対象で、風洞の模型に対して測る量ではない。"}, {"text": "電圧", "is_correct": false, "explanation": "電圧は電気の強さで、風洞の模型実験で測る対象にはならない。"}, {"text": "香り", "is_correct": false, "explanation": "香りは嗅覚の対象で、模型に働く力を測る語ではない。"}], "explanations": {"抗力": "風洞で模型にはたらく抵抗力を測定する文脈に合う正しい物理用語。", "味": "味は感覚の対象で、風洞の模型に対して測る量ではない。", "電圧": "電圧は電気の強さで、風洞の模型実験で測る対象にはならない。", "香り": "香りは嗅覚の対象で、模型に働く力を測る語ではない。"}, "sentence_index": 6, "correct_answer": "抗力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この布は抗力が高く、菌の増殖を防ぐ。", "explanation": "ここは〈抗菌力〉の意味。抗力は流体中で進むのを妨げる力を指し、菌への作用には使わない。"}, {"text": "長時間の試験で、抗力が限界に近づいた。", "explanation": "ここは〈忍耐力〉の意味。こらえる心の力は忍耐力で、抗力の語義とは関係ない。"}, {"text": "毎日の暗記で、抗力が落ちた。", "explanation": "ここは〈記憶力〉の意味。覚えておく力は記憶力で、流体中の抵抗を表す抗力とは別物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37619, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "流線形の車体は抗力が小さくするために設計されている。", "corrected_sentence": "流線形の車体は抗力を小さくするために設計されている。", "error_description": "『小さくする』の目的語は『を』で示す。『抗力が』は誤りで、正しくは『抗力を小さくするために』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37619, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究所では、風洞に模型を置いて抗力に測定した。", "corrected_sentence": "研究所では、風洞に模型を置いて抗力を測定した。", "error_description": "『測定した』の目的語は『を』で示す。『抗力に』は誤りで、正しくは『抗力を測定した』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37620, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「エンジンで空を飛ぶ」は、エンジンを手段として空を飛ぶという意味になり自然。"}, {"text": "に", "is_correct": false, "explanation": "「エンジンに空を飛ぶ」では手段を表せず、不自然になる。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は行き先を表す。「エンジンへ空を飛ぶ」は成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の対象を表す。「エンジンを空を飛ぶ」は、飛ぶの目的語にならず不自然。"}], "correct_answer": "で", "explanations": {"で": "「エンジンで空を飛ぶ」は、エンジンを手段として空を飛ぶという意味になり自然。", "に": "「エンジンに空を飛ぶ」では手段を表せず、不自然になる。", "へ": "「へ」は行き先を表す。「エンジンへ空を飛ぶ」は成り立たない。", "を": "「を」は動作の対象を表す。「エンジンを空を飛ぶ」は、飛ぶの目的語にならず不自然。"}, "error_tags": {"に": "位置・相手", "へ": "方向", "を": "対象"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37620, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「船のエンジンが壊れて」で、壊れる主体を表す主語になり自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を表す。「エンジンと壊れて」では壊れる主語にならない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は比べる文脈がないと使えない。「エンジンより壊れて」は不自然。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐ。「エンジンの壊れて」では動詞「壊れて」の主語にならない。"}], "correct_answer": "が", "explanations": {"が": "「船のエンジンが壊れて」で、壊れる主体を表す主語になり自然。", "と": "「と」は並列や相手を表す。「エンジンと壊れて」では壊れる主語にならない。", "より": "比較の「より」は比べる文脈がないと使えない。「エンジンより壊れて」は不自然。", "の": "「の」は名詞どうしをつなぐ。「エンジンの壊れて」では動詞「壊れて」の主語にならない。"}, "error_tags": {"と": "相手・並列", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37620, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "車や飛行機などを動かす力を作る機械のことです。", "primary_collocate": null, "pronunciation": "えんじん", "ipa": "eɲdʑiɴ", "syllable_count": 4, "sentences": [{"text": "朝、寒くて車のエンジンがなかなかかからなかった。", "target_word": "エンジン", "complexity_tier": "T3", "furigana": "朝[あさ]、寒[さむ]くて車[くるま]のエンジンがなかなかかからなかった。", "sentence_source": "generated"}, {"text": "この飛行機は四つのエンジンで空を飛ぶ。", "target_word": "エンジン", "complexity_tier": "T3", "furigana": "この飛行機[ひこうき]は四[よっ]つのエンジンで空[そら]を飛[と]ぶ。", "sentence_source": "generated"}, {"text": "父は車のエンジンの音を聞いて、調子が悪いと分かった。", "target_word": "エンジン", "complexity_tier": "T3", "furigana": "父[ちち]は車[くるま]のエンジンの音[おと]を聞[き]いて、調子[ちょうし]が悪[わる]いと分[わ]かった。", "sentence_source": "generated"}, {"text": "バイクのエンジンを止めてから、荷物を下ろした。", "target_word": "エンジン", "complexity_tier": "T3", "furigana": "バイクのエンジンを止[と]めてから、荷物[にもつ]を下[お]ろした。", "sentence_source": "generated"}, {"text": "エンジンが熱くなったので、少し休ませた。", "target_word": "エンジン", "complexity_tier": "T3", "furigana": "エンジンが熱[あつ]くなったので、少[すこ]し休[やす]ませた。", "sentence_source": "generated"}, {"text": "新しいエンジンは古いものより静かで、燃料もあまり使わない。", "target_word": "エンジン", "complexity_tier": "T3", "furigana": "新[あたら]しいエンジンは古[ふる]いものより静[しず]かで、燃料[ねんりょう]もあまり使[つか]わない。", "sentence_source": "generated"}, {"text": "坂道でエンジンの力が足りず、車が進まなかった。", "target_word": "エンジン", "complexity_tier": "T3", "furigana": "坂道[さかみち]でエンジンの力[ちから]が足[た]りず、車[くるま]が進[すす]まなかった。", "sentence_source": "generated"}, {"text": "船のエンジンが壊れて、港まで戻れなかった。", "target_word": "エンジン", "complexity_tier": "T3", "furigana": "船[ふね]のエンジンが壊[こわ]れて、港[みなと]まで戻[もど]れなかった。", "sentence_source": "generated"}, {"text": "修理工場で、車のエンジンを新しいものに替えた。", "target_word": "エンジン", "complexity_tier": "T3", "furigana": "修理[しゅうり]工場[こうじょう]で、車[くるま]のエンジンを新[あたら]しいものに替[か]えた。", "sentence_source": "generated"}, {"text": "信号で止まるときは、エンジンを切ると燃料が節約できる。", "target_word": "エンジン", "complexity_tier": "T3", "furigana": "信号[しんごう]で止[と]まるときは、エンジンを切[き]ると燃料[ねんりょう]が節約[せつやく]できる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "エンジン", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "車・バイク・飛行機・船などの中にある、動かす力を作る機械", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6594844-572f-479f-92a0-dc80fd5f0199') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37620, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "エンジン", "is_correct": true, "explanation": "車を動かす機械のエンジンが寒さでかからなかった、という文になる。「かかる」はエンジンの始動に使う。"}, {"text": "タイヤ", "is_correct": false, "explanation": "「車のタイヤがなかなかかからなかった」は成り立たない。タイヤは「かかる」で始動を表さない。"}, {"text": "ワイパー", "is_correct": false, "explanation": "ワイパーは雨の日に窓を拭く部品で、「かからなかった」という始動の状態とは結びつかない。"}, {"text": "ミラー", "is_correct": false, "explanation": "ミラーは後方を見るための鏡で、「なかなかかからなかった」という文の主語にはならない。"}], "explanations": {"エンジン": "車を動かす機械のエンジンが寒さでかからなかった、という文になる。「かかる」はエンジンの始動に使う。", "タイヤ": "「車のタイヤがなかなかかからなかった」は成り立たない。タイヤは「かかる」で始動を表さない。", "ワイパー": "ワイパーは雨の日に窓を拭く部品で、「かからなかった」という始動の状態とは結びつかない。", "ミラー": "ミラーは後方を見るための鏡で、「なかなかかからなかった」という文の主語にはならない。"}, "sentence_index": 0, "correct_answer": "エンジン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "坂道でエンジンが滑って、車が止まった。", "explanation": "ここは〈車輪〉の意味。地面に接して滑るのは車輪で、エンジンは地面に触れないので合わない。"}, {"text": "扇風機のエンジンが回って、部屋に風が届く。", "explanation": "ここは〈モーター〉の意味。扇風機は電気で回す装置なので、乗り物を動かす機械のエンジンとは言わない。"}, {"text": "懐中電灯のエンジンを替えたら、明るくなった。", "explanation": "ここは〈電池〉の意味。懐中電灯は電池で光る器具で、動力を作る機械のエンジンは使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37620, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "エンジン", "is_correct": true, "explanation": "坂道で力が足りず車が進まなかったのは、動力を作るエンジンの力が足りないという意味になる。"}, {"text": "シート", "is_correct": false, "explanation": "シートは座る部分で、動かす力を作らないので「〇〇の力が足りず」の主語にはならない。"}, {"text": "ヘッドライト", "is_correct": false, "explanation": "ヘッドライトは光を出す部品で、車を進ませる力とは関係ないので合わない。"}, {"text": "ドア", "is_correct": false, "explanation": "ドアは開け閉めする部分で、進む力の主体として文が成り立たない。"}], "explanations": {"エンジン": "坂道で力が足りず車が進まなかったのは、動力を作るエンジンの力が足りないという意味になる。", "シート": "シートは座る部分で、動かす力を作らないので「〇〇の力が足りず」の主語にはならない。", "ヘッドライト": "ヘッドライトは光を出す部品で、車を進ませる力とは関係ないので合わない。", "ドア": "ドアは開け閉めする部分で、進む力の主体として文が成り立たない。"}, "sentence_index": 6, "correct_answer": "エンジン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "事故でエンジンがへこみ、修理に出した。", "explanation": "ここは〈車体〉の意味。車体は外から見えて、へこむ部分を指す。エンジンは内部の機械なので、へこむものとしては使わない。"}, {"text": "急カーブでエンジンを強く握った。", "explanation": "ここは〈ハンドル〉の意味。曲がるときに握るのはハンドルで、エンジンは握る対象にならない。"}, {"text": "通学路で、子どもがエンジンを鳴らして人に知らせた。", "explanation": "ここは〈警笛〉の意味。鳴らして知らせるのは警笛で、動力を作る機械のエンジンは鳴らさない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37620, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "船はエンジンを海を進む。", "corrected_sentence": "船はエンジンで海を進む。", "error_description": "「エンジンを」の「を」は手段を表せないので誤り。手段を表すのは「で」。「海を進む」の「を」は正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37620, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寒い朝は、まずエンジンをかかってから出発する。", "corrected_sentence": "寒い朝は、まずエンジンをかけてから出発する。", "error_description": "「エンジンを」に続く動詞は他動詞の「かける」が正しい。自動詞の「かかる」は「エンジンが」の形で使うため、「を」と合わず誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37621, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「ガソリンのエンジンと電気の力」で、二つのものを並べる「と」になり自然。"}, {"text": "を", "is_correct": false, "explanation": "「を」だと「エンジンを電気の力を合わせて」となり、目的語が二つ並んで不自然。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表す。「エンジンから電気の力を合わせて」は起点として不自然で、合わせる相手にもならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表す。「エンジンへ電気の力を合わせて」は不自然。"}], "correct_answer": "と", "explanations": {"と": "「ガソリンのエンジンと電気の力」で、二つのものを並べる「と」になり自然。", "を": "「を」だと「エンジンを電気の力を合わせて」となり、目的語が二つ並んで不自然。", "から": "「から」は起点を表す。「エンジンから電気の力を合わせて」は起点として不自然で、合わせる相手にもならない。", "へ": "「へ」は方向を表す。「エンジンへ電気の力を合わせて」は不自然。"}, "error_tags": {"を": "対象", "から": "起点", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37621, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「小さなエンジンが付いている」で、付いている主体を表す主語になり自然。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は比べる文脈がないと使えない。「エンジンより付いている」は不自然。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表す。「エンジンから付いている」は付く主体を示さず不自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を表す。「エンジンで付いている」は不自然。"}], "correct_answer": "が", "explanations": {"が": "「小さなエンジンが付いている」で、付いている主体を表す主語になり自然。", "より": "比較の「より」は比べる文脈がないと使えない。「エンジンより付いている」は不自然。", "から": "「から」は起点を表す。「エンジンから付いている」は付く主体を示さず不自然。", "で": "「で」は手段や場所を表す。「エンジンで付いている」は不自然。"}, "error_tags": {"より": "比較", "から": "起点", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37621, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "燃料を燃やしたり電気を使ったりして、回転する力や押し出す力を作り出す機械。車や飛行機、船などに使われ、動くためのもとになる力を生み出す。", "primary_collocate": null, "pronunciation": "えんじん", "ipa": "eɲdʑiɴ", "syllable_count": 4, "sentences": [{"text": "ガソリンを燃やして動くエンジンは、排気ガスを出す。", "target_word": "エンジン", "complexity_tier": "T3", "furigana": "ガソリンを燃[も]やして動[うご]くエンジンは、排気[はいき]ガスを出[だ]す。", "sentence_source": "generated"}, {"text": "ハイブリッド車は、ガソリンのエンジンと電気の力を合わせて走る。", "target_word": "エンジン", "complexity_tier": "T3", "furigana": "ハイブリッド車[しゃ]は、ガソリンのエンジンと電気[でんき]の力[ちから]を合[あ]わせて走[はし]る。", "sentence_source": "generated"}, {"text": "ロケットのエンジンは、大きな炎を出して機体を押し出す。", "target_word": "エンジン", "complexity_tier": "T3", "furigana": "ロケットのエンジンは、大[おお]きな炎[ほのお]を出[だ]して機体[きたい]を押[お]し出[だ]す。", "sentence_source": "generated"}, {"text": "エンジンの回転が上がると、車の速度も上がる。", "target_word": "エンジン", "complexity_tier": "T3", "furigana": "エンジンの回転[かいてん]が上[あ]がると、車[くるま]の速度[そくど]も上[あ]がる。", "sentence_source": "generated"}, {"text": "船のエンジンが生む力で、大きな船も海を進む。", "target_word": "エンジン", "complexity_tier": "T3", "furigana": "船[ふね]のエンジンが生[う]む力[ちから]で、大[おお]きな船[ふね]も海[うみ]を進[すす]む。", "sentence_source": "generated"}, {"text": "この飛行機のエンジンは、空気を後ろに強く押し出して進む。", "target_word": "エンジン", "complexity_tier": "T3", "furigana": "この飛行機[ひこうき]のエンジンは、空気[くうき]を後[うし]ろに強[つよ]く押[お]し出[だ]して進[すす]む。", "sentence_source": "generated"}, {"text": "燃料が切れると、エンジンは力を作れず止まってしまう。", "target_word": "エンジン", "complexity_tier": "T3", "furigana": "燃料[ねんりょう]が切[き]れると、エンジンは力[ちから]を作[つく]れず止[と]まってしまう。", "sentence_source": "generated"}, {"text": "小さな草刈り機にも、小さなエンジンが付いている。", "target_word": "エンジン", "complexity_tier": "T3", "furigana": "小[ちい]さな草刈[くさか]り機[き]にも、小[ちい]さなエンジンが付[つ]いている。", "sentence_source": "generated"}, {"text": "エンジンの中で燃料が燃え、その力で車輪が回る。", "target_word": "エンジン", "complexity_tier": "T3", "furigana": "エンジンの中[なか]で燃料[ねんりょう]が燃[も]え、その力[ちから]で車輪[しゃりん]が回[まわ]る。", "sentence_source": "generated"}, {"text": "力が強いエンジンほど、たくさんの燃料を使う。", "target_word": "エンジン", "complexity_tier": "T3", "furigana": "力[ちから]が強[つよ]いエンジンほど、たくさんの燃料[ねんりょう]を使[つか]う。", "sentence_source": "generated"}], "morphological_forms": [{"form": "エンジン", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "燃料を燃やすなどして回転力や推進力を生み出す動力機械という仕組みの面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T2: contains vocabulary far above tier T2: 草刈り機 (Zipf 2.27)']::text[], 'c6594844-572f-479f-92a0-dc80fd5f0199') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37621, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "エンジン", "is_correct": true, "explanation": "ガソリンを燃やして動く機械で、排気ガスを出すのはエンジン。"}, {"text": "電池", "is_correct": false, "explanation": "電池は燃やして動くものではなく、排気ガスも出さないので、この文の主語に合わない。"}, {"text": "タンク", "is_correct": false, "explanation": "タンクは燃料を入れる容器で、燃やして動く機械ではない。"}, {"text": "燃料", "is_correct": false, "explanation": "燃料は燃やされる側のもので、燃やして動く主体にはならない。"}], "explanations": {"エンジン": "ガソリンを燃やして動く機械で、排気ガスを出すのはエンジン。", "電池": "電池は燃やして動くものではなく、排気ガスも出さないので、この文の主語に合わない。", "タンク": "タンクは燃料を入れる容器で、燃やして動く機械ではない。", "燃料": "燃料は燃やされる側のもので、燃やして動く主体にはならない。"}, "sentence_index": 0, "correct_answer": "エンジン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "車のエンジンが残り少なくなったので、ガソリンスタンドで補給した。", "explanation": "ここは〈燃料〉の意味。残り少なくなって補給するのは燃料で、回転や押し出しの力を作る機械のエンジンは補給しない。"}, {"text": "懐中電灯のエンジンを替えたら、明るくなった。", "explanation": "ここは〈電池〉の意味。懐中電灯は光を出す器具で、回転や押し出しの力を作らないので、エンジンは使わない。"}, {"text": "急カーブでエンジンを強く握った。", "explanation": "ここは〈ハンドル〉の意味。曲がるときに握るのはハンドルで、エンジンは握る対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37621, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "エンジン", "is_correct": true, "explanation": "燃料が切れると力を作れなくなり止まる機械で、ここではエンジンを指す。"}, {"text": "排気管", "is_correct": false, "explanation": "排気管は排ガスを外へ出す管で、力を作る主体ではないので、この文の主語に合わない。"}, {"text": "冷却器", "is_correct": false, "explanation": "冷却器は熱を逃がす装置で、燃料が切れて力を作れなくなる主語としては不自然。"}, {"text": "ホース", "is_correct": false, "explanation": "ホースは液体を運ぶ管で、力を作れずに止まる主語としては合わない。"}], "explanations": {"エンジン": "燃料が切れると力を作れなくなり止まる機械で、ここではエンジンを指す。", "排気管": "排気管は排ガスを外へ出す管で、力を作る主体ではないので、この文の主語に合わない。", "冷却器": "冷却器は熱を逃がす装置で、燃料が切れて力を作れなくなる主語としては不自然。", "ホース": "ホースは液体を運ぶ管で、力を作れずに止まる主語としては合わない。"}, "sentence_index": 6, "correct_answer": "エンジン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "事故でエンジンがへこみ、修理に出した。", "explanation": "ここは〈車体〉の意味。外からへこむ部分を指す語で、車の内部の機械であるエンジンはへこむものとして使わない。"}, {"text": "坂道でエンジンが滑って、車が止まった。", "explanation": "ここは〈車輪〉の意味。地面に接して滑るのは車輪で、エンジンは地面に触れないので合わない。"}, {"text": "エンジンを踏むと、車が速く走る。", "explanation": "ここは〈アクセル〉の意味。踏んで速さを調整するのはアクセルで、エンジンは踏む対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37621, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この船は小さなエンジンに、ゆっくり進む。", "corrected_sentence": "この船は小さなエンジンで、ゆっくり進む。", "error_description": "エンジンを手段として表す助詞は「で」が正しい。「に」は方向や相手を表すので、「進む」の手段としては不自然で誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37621, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "朝の準備で、エンジンがあたためて、車を出した。", "corrected_sentence": "朝の準備で、エンジンをあたためて、車を出した。", "error_description": "「あたためる」は他動詞なので、目的語は「を」で示す。「エンジンが」の「が」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37622, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "勝負の場を表し、「じゃんけんに負けた」と自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "「負ける」は目的語を取らないので、「じゃんけんを負けた」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、勝負の場を示す文には合わない。"}, {"text": "と", "is_correct": false, "explanation": "共同や相手を表す助詞で、「じゃんけんと負けた」は文にならない。"}], "correct_answer": "に", "explanations": {"に": "勝負の場を表し、「じゃんけんに負けた」と自然に続く。", "を": "「負ける」は目的語を取らないので、「じゃんけんを負けた」は不自然。", "へ": "方向を表す助詞で、勝負の場を示す文には合わない。", "と": "共同や相手を表す助詞で、「じゃんけんと負けた」は文にならない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "共同"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "勝つ", "is_correct": true, "explanation": "勝負の結果で「負ける」と反対の意味を表す対義語。"}, {"text": "引き分ける", "is_correct": false, "explanation": "勝ちも負けも決まらない結果で、負けの反対ではない。"}, {"text": "参加する", "is_correct": false, "explanation": "試合に加わる行為で、勝敗の結果を表さない。"}, {"text": "走る", "is_correct": false, "explanation": "動作を表すだけで、勝敗とは関係しない。"}], "correct_answer": "勝つ", "explanations": {"勝つ": "勝負の結果で「負ける」と反対の意味を表す対義語。", "引き分ける": "勝ちも負けも決まらない結果で、負けの反対ではない。", "参加する": "試合に加わる行為で、勝敗の結果を表さない。", "走る": "動作を表すだけで、勝敗とは関係しない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fde1bf3-eb38-48d7-91f7-2154a83f42d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
